// data/companions-extra.ts
// ============================================================================
// Full-depth (≈1500-2500 word) Arabic + English transcripts for the 21
// companions defined in app/companions.tsx. The brief card-level paragraphs in
// app/companions.tsx remain untouched (they are still used in cards and
// previews); this file extends them with full biographical narratives,
// matching the depth used for prophet stories in religious-story-complete.ts.
//
// Wired through data/full-story-texts.ts → expandCompanionStory(): if a
// companion's id has an entry here, the extended transcript replaces the
// generic template paragraphs.
//
// Sources: Sira Ibn Hisham, Sahih al-Bukhari, Sahih Muslim, Siyar A'lam
// al-Nubala' (al-Dhahabi), al-Isaba (Ibn Hajar), al-Tabaqat (Ibn Sa'd).
// ============================================================================

function P(parts: string[]): string {
  return parts.join('\n\n');
}

export interface CompanionExtendedTranscript {
  ar: string;
  en: string;
}

// Per-companion citation list. Mirrors StorySource in lib/content-api.ts.
// `note` is used to flag ikhtilaf, weak chains, or disputed historical details
// so readers see when a named source is reporting something contested.
export interface CompanionSourceEntry {
  reference: string;
  url?: string;
  note?: string;
}

// Sources shared by every companion biography in this file. The biographies
// pull from the same core hadith collections and classical companion-
// biography works; we list them once here and append per-companion specific
// citations below.
export const COMMON_COMPANION_SOURCES: CompanionSourceEntry[] = [
  { reference: 'صحيح البخاري', url: 'https://sunnah.com/bukhari' },
  { reference: 'صحيح مسلم', url: 'https://sunnah.com/muslim' },
  { reference: 'سير أعلام النبلاء للذهبي' },
  { reference: 'الإصابة في تمييز الصحابة لابن حجر' },
  { reference: 'الطبقات الكبرى لابن سعد' },
  { reference: 'السيرة النبوية لابن هشام' },
  { reference: 'البداية والنهاية لابن كثير' },
];

export const COMPANIONS_EXTENDED_TRANSCRIPTS: Record<string, CompanionExtendedTranscript> = {
  // ──────────────────────────────────────────────────────────────────────
  // 1. أبو بكر الصديق رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'abu-bakr': {
    ar: P([
      'هو عبد الله بن عثمان بن عامر بن عمرو بن كعب بن سعد بن تيم بن مرة، القرشي التيمي. وُلد بمكة سنة 573م، بعد عام الفيل بنحو ثلاث سنين. كانت أمه أم الخير سلمى بنت صخر، وأبوه أبو قحافة. عرف بين قومه بالصدق والاستقامة قبل الإسلام، وكان من سادة قريش وأنسابها، يُرجع إليه في علم الأنساب.',
      'كان أبو بكر تاجرًا ميسورًا، له تجارة واسعة بين الشام واليمن، تقدّر ثروته يوم أسلم بأربعين ألف درهم. لكنه أنفقها كلها على الإسلام في سنوات قليلة، حتى مات وما عنده إلا قميص يلبسه. كان من القلائل في الجاهلية الذين حرّموا الخمر على أنفسهم، ترفّعًا لا تديّنًا، لما رأوا فيها من فساد العقول.',
      'دعاه النبي ﷺ إلى الإسلام في أول البعثة، فأسلم في الحال دون تردد. قال النبي ﷺ: ما دعوتُ أحدًا إلى الإسلام إلا كانت له كبوة ونظر وتردد، إلا ما كان من أبي بكر، ما عَكَم — أي ما تأخر — حين ذكرته به. كانت هذه السرعة في القبول لأن قلبه كان مهيأ للحق قبل أن يأتيه.',
      'صار أبو بكر بعد إسلامه يدعو الناس إلى الله، فأسلم على يديه كثير من سادات قريش الذين كانوا فيما بعد عماد الإسلام: عثمان بن عفان، والزبير بن العوام، وعبد الرحمن بن عوف، وسعد بن أبي وقاص، وطلحة بن عبيد الله. خمسة من العشرة المبشرين بالجنة دخلوا الإسلام بسببه.',
      'لما اشتدّ الإيذاء على المستضعفين، أنفق أبو بكر ماله في عتق العبيد المعذبين. اشترى بلال بن رباح من سيده أمية بن خلف بسبع أواق من الفضة. واشترى عامر بن فهيرة وأم عبيس وزنّيرة والنهدية وابنتها وجارية بني المؤمل، كلهم من المعذبين في الله. قال له أبوه: يا بني، أراك تعتق رقابًا ضعافًا، فلو أنك عتقت رجالًا جلدًا يقومون معك! فقال: يا أبت، إنما أريد ما أريد لله.',
      'لما هاجر النبي ﷺ، اختار أبا بكر صاحبًا في الهجرة. خرجا من مكة ليلًا، ودخلا غار ثور. وقفت قريش على باب الغار، وكاد أبو بكر يُكشف من شدّة قربهم. قال: يا رسول الله، لو نظر أحدهم تحت قدميه لرآنا. قال النبي ﷺ: ما ظنّك يا أبا بكر باثنين الله ثالثهما؟ فأنزل الله: إذ يقول لصاحبه لا تحزن إن الله معنا. هذه الآية وحدها كافية بتشريف أبي بكر إلى آخر الزمان.',
      'في المدينة، شارك أبو بكر في كل غزوات النبي ﷺ. كان رضي الله عنه يضحّي بنفسه دون النبي. في بدر استشار النبي ﷺ الصحابة، فقام أبو بكر يتكلم فأحسن. وفي أحد وحنين ثبت مع النبي حين انفض الناس. كان وزيره وصاحب رأيه في كل أمر.',
      'حين مات النبي ﷺ، اضطرب المسلمون اضطرابًا شديدًا. ظنّ كثير منهم أنه لم يمت، وخرج عمر بن الخطاب يقول: من قال إن محمدًا مات قتلته. جاء أبو بكر، كشف عن وجه النبي ﷺ وقبّله، ثم خرج إلى الناس فقال كلمته الخالدة: من كان يعبد محمدًا فإن محمدًا قد مات، ومن كان يعبد الله فإن الله حي لا يموت. ثم تلا: وما محمد إلا رسول قد خلت من قبله الرسل، أفإن مات أو قُتل انقلبتم على أعقابكم. قال عمر بعد ذلك: والله لكأنّي ما سمعت بهذه الآية حتى تلاها أبو بكر.',
      'بايعه المسلمون خليفة في سقيفة بني ساعدة. أول خطبة له بعد البيعة كانت من أعظم خطب الإسلام: قال: أيها الناس، إني وُلّيت عليكم ولست بخيركم، فإن أحسنت فأعينوني، وإن أسأت فقوّموني. الصدق أمانة، والكذب خيانة. القوي فيكم ضعيف عندي حتى آخذ الحق منه، والضعيف فيكم قوي عندي حتى آخذ الحق له. أطيعوني ما أطعت الله ورسوله، فإن عصيت الله ورسوله فلا طاعة لي عليكم.',
      'كانت خلافته سنتين وثلاثة أشهر فقط، لكنها من أعظم سنوات الإسلام. واجه فيها حروب الردة — حركة هائلة من القبائل التي ارتدت عن الإسلام أو منعت الزكاة. وقف وحده ضد رأي عمر ومعظم الصحابة، وقال: والله لو منعوني عناقًا — وفي رواية عقالًا — كانوا يؤدّونه إلى رسول الله لقاتلتهم على منعه. ثم جهّز الجيوش، فعاد العرب جميعًا إلى الإسلام.',
      'وفي عهده جُمع القرآن الكريم في مصحف واحد لأول مرة. كان السبب أن كثيرًا من حُفّاظ القرآن استُشهدوا في معركة اليمامة ضد مسيلمة الكذاب. خاف عمر أن يضيع القرآن بموت حملته، فاقترح على أبي بكر جمعه. تردّد أبو بكر أول الأمر، ثم شرح الله صدره فأمر زيد بن ثابت أن يجمعه. هذا الجمع الأول كان حجر الزاوية لكل مصاحف العالم بعد ذلك.',
      'كان أبو بكر زاهدًا في الدنيا حتى في الخلافة. كان لما تولّى يأخذ من بيت المال ما يكفيه يومه فقط. وحين مرض مرض الموت، أوصى عائشة أن تردّ كل ما أخذه إلى بيت المال. قالت عائشة: لم نجد إلا عبدًا حبشيًا كان يخدمه وناضحًا — جملًا يستقي عليه — فردّتهما إلى عمر فبكى عمر وقال: لقد أتعبت من بعدك يا أبا بكر.',
      'مرض رضي الله عنه في جمادى الآخرة سنة 13 هـ، ومات بعد خمسة عشر يومًا من مرضه. كان عمره ثلاثًا وستين سنة، كعمر النبي ﷺ. غسلته زوجته أسماء بنت عميس، ودفن إلى جنب النبي ﷺ في حجرة عائشة. ترك من الأولاد عبد الله وعبد الرحمن ومحمد، ومن البنات أسماء — ذات النطاقين — وعائشة وأم كلثوم.',
      'يبقى أبو بكر الصديق في تاريخ الإسلام أعظم رجل بعد الأنبياء، كما قال ابن عمر: كنا نخيّر بين الناس في زمن النبي ﷺ، فنخيّر أبا بكر ثم عمر ثم عثمان. سيرته دروس لا تنتهي: في الصدق، وفي الصحبة، وفي الإنفاق، وفي الثبات، وفي العدل، وفي التواضع. ومن يقرأها بقلبه، يفهم لماذا اختاره الله صاحبًا لخاتم الأنبياء، وخليفة لأول دولة إسلامية.',
    ]),
    en: P([
      'He is Abdullah ibn Uthman ibn Amir ibn Amr ibn Ka\'b ibn Sa\'d ibn Taym ibn Murrah al-Qurashi al-Taymi. He was born in Makkah in 573 CE, about three years after the Year of the Elephant. His mother was Umm al-Khayr Salma bint Sakhr, and his father was Abu Quhafah. Among his people he was known for truthfulness and uprightness before Islam, and was one of the nobles and genealogists of Quraysh.',
      'Abu Bakr was a well-off merchant with a vast trade between Sham and Yemen. His wealth on the day he embraced Islam was estimated at forty thousand dirhams. He spent it all on Islam in a few years, until he died with only a single shirt to his name. He was among the few in the Jahiliyyah who forbade themselves wine, out of nobility rather than religion, seeing the corruption of intellect it caused.',
      'The Prophet ﷺ called him to Islam at the very start of the mission. He accepted at once, without hesitation. The Prophet ﷺ said: "I did not call anyone to Islam except that he had hesitation and reflection — except Abu Bakr, who did not delay when I mentioned it to him." This swiftness came from a heart prepared for the truth before it arrived.',
      'After his conversion he began calling people to Allah. Through him many of the nobles of Quraysh who became the pillars of Islam embraced the faith: Uthman ibn Affan, Zubayr ibn al-Awwam, Abd al-Rahman ibn Awf, Sa\'d ibn Abi Waqqas, and Talha ibn Ubaydillah — five of the ten promised Paradise entered Islam by his hand.',
      'When the harm against the weak intensified, Abu Bakr spent his wealth freeing tortured slaves. He bought Bilal ibn Rabah from his master Umayyah ibn Khalaf for seven ounces of silver. He bought Amir ibn Fuhayra, Umm Ubays, Zinnira, al-Nahdiyya and her daughter, and the slave-girl of Banu al-Mu\'ammil — all of them tortured for Allah\'s sake. His father said: "My son, I see you freeing weak necks; if only you would free strong men who would stand with you!" He replied: "Father, I want what I want for Allah."',
      'When the Prophet ﷺ migrated, he chose Abu Bakr as his companion in the Hijrah. They left Makkah by night and entered the cave of Thawr. Quraysh stood at the mouth of the cave, and Abu Bakr was almost exposed by their nearness. He said: "O Messenger of Allah, if one of them looked beneath his feet he would see us." The Prophet ﷺ said: "What do you think, O Abu Bakr, of two whose third is Allah?" Allah revealed: "When he said to his companion, ‘Do not grieve; indeed Allah is with us.’" This verse alone is enough honour for Abu Bakr until the end of time.',
      'In Madinah, Abu Bakr took part in every campaign of the Prophet ﷺ. He used to risk himself before the Prophet. At Badr the Prophet ﷺ consulted his Companions, and Abu Bakr stood and spoke well. At Uhud and Hunayn he stood firm with the Prophet when others scattered. He was his minister and counsellor in every matter.',
      'When the Prophet ﷺ died, the Muslims were severely shaken. Many thought he had not died, and Umar ibn al-Khattab went out saying: "Whoever says Muhammad has died, I will kill him." Abu Bakr came, uncovered the Prophet\'s face and kissed him, then went out to the people and said his immortal words: "Whoever used to worship Muhammad — Muhammad has died. Whoever worships Allah — Allah is Ever-Living and never dies." He then recited: "Muhammad is no more than a messenger; messengers have passed before him. If he died or was killed, would you turn back on your heels?" Umar said afterwards: "By Allah, it was as if I had never heard this verse until Abu Bakr recited it."',
      'The Muslims pledged allegiance to him as caliph in the Saqifah of Banu Sa\'idah. His first sermon after the pledge was among the greatest of Islam: "O people, I have been appointed over you and I am not the best of you. If I do well, support me; if I do wrong, correct me. Truthfulness is a trust, and lying is a betrayal. The strong among you is weak before me until I take the right from him, and the weak among you is strong before me until I take the right for him. Obey me as long as I obey Allah and His Messenger; if I disobey Allah and His Messenger, you owe me no obedience."',
      'His caliphate lasted only two years and three months, but they were among the greatest years of Islam. He faced the Wars of Apostasy — a vast movement of tribes that left Islam or withheld zakat. He stood alone against Umar and most of the Companions, saying: "By Allah, if they withhold from me a young goat — or in a narration, a tether — they used to pay to the Messenger of Allah, I will fight them for withholding it." He sent the armies, and all the Arabs returned to Islam.',
      'In his era the Qur\'an was compiled into a single Mushaf for the first time. The reason: many memorisers were martyred in the Battle of Yamamah against Musaylimah the Liar. Umar feared the Qur\'an would be lost with the death of its bearers, and proposed its collection to Abu Bakr. Abu Bakr hesitated at first, then Allah expanded his chest and he ordered Zayd ibn Thabit to collect it. This first compilation was the cornerstone of every Mushaf in the world afterwards.',
      'Abu Bakr was ascetic in the world even in the caliphate. When he took office he would take from the public treasury only what sufficed his day. When he fell into his final illness he instructed A\'isha to return everything he had taken to the public treasury. A\'isha said: "We found only an Abyssinian slave who served him and a camel he used to draw water with." She returned them to Umar, who wept and said: "You have tired whoever comes after you, O Abu Bakr."',
      'He fell ill in Jumada al-Akhirah of 13 AH, and died fifteen days later. He was sixty-three years old, the age of the Prophet ﷺ. His wife Asma\' bint Umays washed him, and he was buried beside the Prophet ﷺ in A\'isha\'s chamber. He left as sons Abdullah, Abd al-Rahman, and Muhammad, and as daughters Asma\' — of the two girdles — A\'isha, and Umm Kulthum.',
      'Abu Bakr al-Siddiq remains in the history of Islam the greatest man after the prophets. Ibn Umar said: "We used to choose among people in the time of the Prophet ﷺ, and we would choose Abu Bakr, then Umar, then Uthman." His life is a teaching that does not end: in truthfulness, in companionship, in spending, in steadfastness, in justice, and in humility. Whoever reads it with the heart understands why Allah chose him as the companion of the seal of the prophets and the caliph of the first Islamic state.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 2. عمر بن الخطاب رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'umar': {
    ar: P([
      'هو عمر بن الخطاب بن نُفيل بن عبد العزى بن رياح بن قُرط بن رزاح بن عدي بن كعب، القرشي العدوي. وُلد بمكة بعد عام الفيل بثلاث عشرة سنة. أمه حنتمة بنت هاشم بن المغيرة المخزومية. تربى في بيت متوسط الحال، عمل في صغره برعي الإبل لأبيه. اشتُهر منذ شبابه بقوة البدن وصراحة الكلمة وذكاء العقل.',
      'كان عمر في الجاهلية من أشد الناس عداوة للإسلام. لما رأى أخته فاطمة وزوجها قد أسلما، ضربهما ضربًا شديدًا. ثم رأى الدم في وجه أخته فلانت قلبه. سألها أن تريه ما كانا يقرآن، فأعطته صحيفة فيها سورة طه. لما قرأها قال: ما أحسن هذا الكلام وأكرمه! وذهب إلى دار الأرقم حيث كان النبي ﷺ مع أصحابه، فأعلن إسلامه. كان إسلامه في السنة السادسة من البعثة، فأعزّ الله به الإسلام.',
      'قال النبي ﷺ قبل إسلامه: اللهم أعزّ الإسلام بأحب الرجلين إليك: عمر بن الخطاب أو أبي جهل بن هشام. فاستجاب الله فأسلم عمر. قال ابن مسعود: ما زلنا أعزّة منذ أسلم عمر. صار المسلمون يصلّون عند الكعبة جهرًا لأول مرة، وكسر عمر الحاجز النفسي الذي حال بينهم وبين إظهار دينهم.',
      'هاجر عمر إلى المدينة جهرًا. لم يهرب كما هرب غيره. خرج متقلّدًا سيفه، حاملًا قوسه، آخذًا بيده الحربة، فطاف بالبيت سبعًا، ثم صلى ركعتين، ثم أتى مجالس قريش فقال: من أراد أن تثكله أمه، وييتم ولده، وترمل زوجه، فليلقني وراء هذا الوادي. فما تبعه أحد.',
      'في المدينة شارك في كل المعارك مع النبي ﷺ. كان من أبرز الصحابة في كل قضية، يُؤخذ برأيه في الشورى. وحدث في حياته أن الوحي وافق رأيه في مسائل عديدة: في أسارى بدر، وفي حجاب نساء النبي، وفي مقام إبراهيم، وفي تحريم الخمر. قال عمر: وافقت ربي في ثلاث. وكان هذا فضلًا عظيمًا.',
      'لما تولى الخلافة بعد أبي بكر سنة 13 هـ، بدأ عصرًا جديدًا في تاريخ الإسلام. كانت الدولة الإسلامية لا تتجاوز شبه الجزيرة العربية. في عشر سنوات من خلافته، فتح العراق وفارس والشام ومصر وأرمينيا وأذربيجان وأجزاء من ليبيا. تضاعفت رقعة الإسلام عشرات المرات في عشر سنوات فقط.',
      'لكن عمر لم يكن مجرد فاتح. كان مؤسس النظام الإداري للدولة. هو أول من دوّن الدواوين — أي السجلات الحكومية لتوزيع العطايا. وأول من اتخذ التقويم الهجري بداية للتاريخ الإسلامي. وأول من جعل الجمع للتراويح في رمضان جماعة. وأول من حدّ الناس في الخمر ثمانين جلدة. وأول من سُمّي أمير المؤمنين.',
      'كان فتحه لبيت المقدس سنة 15 هـ من أعظم أحداث خلافته. جاء بنفسه من المدينة، يتناوب مع غلامه على الراحلة — يركب مرة ويمشي مرة. دخل القدس في ثوب فيه أربع عشرة رقعة. لما عرض عليه البطريرك صفرونيوس أن يصلي في كنيسة القيامة، رفض وقال: لو صلّيت فيها لاتخذها المسلمون مسجدًا من بعدي. فصلى خارج الكنيسة، وما زال المكان يسمى مسجد عمر إلى اليوم.',
      'كان عدله ضرب المثل. قصة بنيّ مصر أنّ ابن عمرو بن العاص — والي مصر — ضرب رجلًا قبطيًا، فجاء القبطي إلى عمر في المدينة شاكيًا. استدعى عمر عمرو بن العاص وابنه، وأعطى السوط للقبطي وقال: اضرب ابن الأكرمين. ثم قال كلمته المشهورة لعمرو: متى استعبدتم الناس وقد ولدتهم أمهاتهم أحرارًا؟',
      'كان زهده عجيبًا. لم يبنِ قصرًا، ولم يلبس ناعم الثياب، ولم يأكل ناعم الطعام. كان يطوف ليلًا بنفسه يتفقد رعيته. ذات ليلة سمع امرأة تبكي أطفالها وتطبخ لهم حجارة في القدر تشغلهم حتى يناموا. عاد عمر فحمل الطعام بنفسه على ظهره، وقال لخادمه أسلم: دعني، فإن الله لا يسألك عن حمل عمر، ولكن يسألني أنا.',
      'كان يحاسب نفسه أشد محاسبة. قال يومًا: لو ضاعت بغلة في العراق لخشيت أن يسألني الله عنها يوم القيامة. وقال: حاسبوا أنفسكم قبل أن تحاسبوا، وزنوا أعمالكم قبل أن توزن عليكم. كانت قاعدته في الحكم أن الحاكم خادم لرعيته لا سيد عليها.',
      'استشهد سنة 23 هـ على يد أبي لؤلؤة فيروز المجوسي، عبد للمغيرة بن شعبة. طعنه بخنجر مسموم في الفجر وهو يصلي بالناس. قتل بسبب فارسيته وحقده على الإسلام بعد فتح فارس. حُمل عمر إلى بيته، وعاش ثلاثة أيام. عيّن في وفاته شورى من ستة من الصحابة ليختاروا الخليفة بعده: عثمان، علي، عبد الرحمن بن عوف، طلحة، الزبير، سعد بن أبي وقاص.',
      'لما طلب أن يدفن إلى جنب النبي ﷺ وأبي بكر، أرسل ابنه عبد الله إلى عائشة يستأذنها. كانت عائشة قد جهّزت هذا المكان لنفسها، لكنها قالت: كنت أردته لنفسي، ولأوثرنّ به عمر اليوم على نفسي. لما رجع ابنه بالخبر، قال عمر: ما كان شيء أهم إلي من ذلك المضجع، فإذا قبضتُ فاحملوني، ثم استأذنوا، فإن أذنت فادفنوني، وإن ردّت فردّوني إلى مقابر المسلمين. ما زال متخوّفًا حتى آخر لحظة من تجاوز إذنها.',
      'دفن مع النبي ﷺ وأبي بكر، فاكتمل الثالوث المبارك في الحجرة المباركة في المسجد النبوي. كان عمره 63 سنة، نفس عمر النبي ﷺ وأبي بكر. ترك في تاريخ الإسلام بصمة لا تُمحى: في الإدارة، في القضاء، في الفتوحات، في الزهد، في العدل. ولا يمر يوم اليوم إلا ويذكر اسمه في خطبة جمعة أو درس حديث.',
      'يبقى عمر بن الخطاب الفاروق الذي فرّق الله به بين الحق والباطل. مدرسة في كل شيء: في الإيمان القوي، وفي القيادة الحازمة، وفي العدل الذي لا يحابي، وفي الزهد الصادق، وفي التواضع رغم العظمة. وكلما ضعفت الأمة احتاجت إلى عمر جديد. والأمل أن يبعث الله في كل جيل من يحمل بعض خصاله.',
    ]),
    en: P([
      'He is Umar ibn al-Khattab ibn Nufayl ibn Abd al-Uzza ibn Rabah ibn Qurt ibn Razah ibn Adi ibn Ka\'b, al-Qurashi al-Adawi. He was born in Makkah thirteen years after the Year of the Elephant. His mother was Hantamah bint Hashim ibn al-Mughirah al-Makhzumiyyah. He was raised in a household of modest means and worked in his youth herding his father\'s camels. From his youth he was known for physical strength, candid speech, and sharp intellect.',
      'In the Jahiliyyah Umar was among the bitterest enemies of Islam. When he saw his sister Fatimah and her husband had embraced Islam, he beat them severely. Then he saw the blood on his sister\'s face and his heart softened. He asked her to show him what they had been reading; she gave him a sheet with Surah Ta-Ha. When he read it he said: "How fine and noble this speech is!" He went to the house of al-Arqam where the Prophet ﷺ was with his Companions and announced his Islam. His conversion was in the sixth year of the mission, and Allah honoured Islam through him.',
      'Before his conversion the Prophet ﷺ said: "O Allah, honour Islam with the dearest of the two men to You: Umar ibn al-Khattab or Abu Jahl ibn Hisham." Allah answered, and Umar embraced Islam. Ibn Mas\'ud said: "We have remained honoured since Umar embraced Islam." The Muslims began to pray openly at the Ka\'bah for the first time, and Umar broke the psychological barrier between them and showing their religion.',
      'Umar emigrated to Madinah openly. He did not flee as others did. He went out with his sword strapped on, his bow on his shoulder, and his spear in his hand. He circumambulated the House seven times, prayed two rak\'ahs, then came to the gatherings of Quraysh and said: "Whoever wants his mother to mourn him, his children to be orphaned, his wife to be widowed — let him meet me behind this valley." None of them followed.',
      'In Madinah he took part in every battle with the Prophet ﷺ. He was prominent in every matter, his opinion sought in consultation. Revelation accorded with his view in several matters: the prisoners of Badr, the veiling of the Prophet\'s wives, the station of Ibrahim, and the prohibition of wine. Umar said: "I agreed with my Lord in three." This was a tremendous merit.',
      'When he took the caliphate after Abu Bakr in 13 AH, a new era began in the history of Islam. The Islamic state then did not extend beyond the Arabian Peninsula. In ten years of his caliphate, Iraq, Persia, Sham, Egypt, Armenia, Azerbaijan, and parts of Libya were conquered. The reach of Islam multiplied many times over in only ten years.',
      'But Umar was not merely a conqueror. He was the founder of the administrative system of the state. He was the first to establish the diwans — the government registers for distributing stipends. The first to take the Hijrah as the start of the Islamic calendar. The first to institute the Tarawih prayer in congregation in Ramadan. The first to set the legal punishment for wine at eighty lashes. The first to be called Commander of the Believers.',
      'His conquest of Jerusalem in 15 AH was among the greatest events of his caliphate. He came in person from Madinah, alternating with his servant on the mount — riding once and walking once. He entered Jerusalem in a garment with fourteen patches. When Patriarch Sophronius offered him to pray inside the Church of the Holy Sepulchre, he refused, saying: "If I prayed inside it, the Muslims would take it as a mosque after me." So he prayed outside the church, and the place is still called the Mosque of Umar to this day.',
      'His justice was proverbial. There is the story of the Egyptian boy: the son of Amr ibn al-As — governor of Egypt — struck a Coptic man, who came to Umar in Madinah complaining. Umar summoned Amr ibn al-As and his son and gave the whip to the Copt, saying: "Strike the son of the noble." Then he said his famous words to Amr: "Since when have you enslaved people, when their mothers gave birth to them free?"',
      'His asceticism was extraordinary. He built no palace, did not wear soft clothing, did not eat fine food. He used to patrol at night to inspect his subjects. One night he heard a woman weeping over her children and cooking stones in the pot to occupy them until they slept. Umar returned and carried the food himself on his back. He said to his servant Aslam: "Leave me; Allah will not ask you about Umar\'s burden, but He will ask me."',
      'He held himself to the most severe accounting. He said one day: "If a she-mule were lost in Iraq, I would fear that Allah would ask me about it on the Day of Resurrection." He said: "Hold yourselves to account before you are held to account, and weigh your deeds before they are weighed against you." His rule was that the ruler is a servant of his people, not a master over them.',
      'He was martyred in 23 AH at the hand of Abu Lu\'lu\'ah Firuz al-Majusi, a slave of al-Mughirah ibn Shu\'bah. He stabbed him with a poisoned dagger at Fajr while he was leading the prayer. He killed him because of his Persian origin and his hatred of Islam after the conquest of Persia. Umar was carried to his house and lived three days. At his death he appointed a council of six Companions to choose the next caliph: Uthman, Ali, Abd al-Rahman ibn Awf, Talha, Zubayr, and Sa\'d ibn Abi Waqqas.',
      'When he asked to be buried beside the Prophet ﷺ and Abu Bakr, he sent his son Abdullah to A\'isha to seek her permission. She had prepared that place for herself, but said: "I wanted it for myself, but I shall prefer Umar over myself today." When his son returned with the news, Umar said: "Nothing was more important to me than that resting place. When I die, carry me, then ask permission. If she agrees, bury me; if she refuses, return me to the Muslim cemeteries." He remained anxious until the last moment about overstepping her permission.',
      'He was buried with the Prophet ﷺ and Abu Bakr, completing the blessed triad in the blessed chamber in the Prophet\'s Mosque. He was sixty-three years old, the same age as the Prophet ﷺ and Abu Bakr. He left an indelible mark on the history of Islam: in administration, in judiciary, in conquest, in asceticism, in justice. Not a day passes today without his name being mentioned in a Friday sermon or a lesson of hadith.',
      'Umar ibn al-Khattab remains al-Faruq — by whom Allah distinguished truth from falsehood. A school in everything: in strong faith, in firm leadership, in justice that shows no favour, in true asceticism, and in humility despite greatness. Whenever the Ummah grows weak it needs a new Umar. The hope is that in every generation Allah raises someone bearing some of his qualities.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 3. عثمان بن عفان رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'uthman': {
    ar: P([
      'هو عثمان بن عفان بن أبي العاص بن أمية بن عبد شمس بن عبد مناف، القرشي الأموي. وُلد بمكة بعد عام الفيل بست سنين، فهو أصغر من النبي ﷺ بست سنوات. أمه أروى بنت كريز بن ربيعة. كان من أشراف قريش وأغنياءها، ومن أصحاب التجارة الواسعة بين الشام والحجاز.',
      'لُقّب بذي النورين لأنه تزوّج اثنتين من بنات النبي ﷺ: رقية، فلما توفيت زوّجه أم كلثوم. قال النبي ﷺ: لو كان عندي ثالثة لزوّجتها عثمان. لم يحظَ بهذا الشرف أحد قبله ولا بعده — أن يتزوج ابنتين من نبي واحد بعد وفاة الأولى.',
      'أسلم على يد أبي بكر الصديق في أوائل البعثة، وهو من السابقين الأولين. كان عمره يومئذ نحو أربع وثلاثين سنة. لما علم به عمه الحكم بن أبي العاص — وكان من المشركين — أوثقه بالحبال وقال: ترغب عن دين آبائك إلى دين محدث؟ فقال عثمان: والله لا أدعه أبدًا. فلما رأى عمه ثباته أطلقه.',
      'هاجر عثمان الهجرتين: إلى الحبشة مرتين، ثم إلى المدينة. كان ممن خرجوا أول مرة إلى الحبشة فرارًا بدينهم من أذى قريش، ومعه زوجته رقية. قال النبي ﷺ لما ودّعهم: إنهما لأول من هاجر بأهله في سبيل الله بعد لوط. هذه شهادة عظيمة من النبي ﷺ، تربط عثمان بأنبياء سابقين.',
      'لم يشهد عثمان غزوة بدر، لأن النبي ﷺ خلّفه على زوجته رقية حين مرضت. ماتت رقية أثناء الغزوة، فعاد عثمان حزينًا، لكن النبي ﷺ ضرب له بسهم من غنائم بدر وأجر، فكان ممن شهدها حكمًا. هذه أيضًا منزلة فريدة.',
      'عُرف بالكرم العجيب. اشترى بئر رومة من يهودي بعشرين ألف درهم — وكان اليهودي يبيع ماءها للمسلمين — وجعلها وقفًا للمسلمين، تشرب منها كل ساكن المدينة. وفي غزوة تبوك جهّز جيش العسرة بأكمله. أحضر ألف بعير وخمسين فرسًا وعشرة آلاف دينار، حملها في حجر النبي ﷺ. كان النبي ﷺ يقلّبها ويقول: ما ضرّ عثمان ما عمل بعد اليوم. ما ضرّ عثمان ما عمل بعد اليوم.',
      'بايعه المسلمون خليفة بعد عمر سنة 23 هـ، عن طريق الشورى التي عيّنها عمر. كان عمره يومئذ سبعين سنة. تولّى في وقت كانت فيه الدولة الإسلامية في أوج فتوحاتها. في خلافته فُتحت أرمينيا وأذربيجان وخراسان وكرمان وسجستان وقبرص وأفريقيا. وصار الأسطول الإسلامي يجوب البحر المتوسط — أول أسطول بحري في تاريخ المسلمين.',
      'أعظم إنجاز في خلافته كان جمع المصحف وتوحيد قراءته. كان المسلمون قد تفرّقوا في الأمصار، وكل بلد يقرأ بقراءة مختلفة، حتى بدأت الخلافات. اقترح حذيفة بن اليمان على عثمان أن يجمع الناس على مصحف واحد قبل أن يختلفوا اختلاف اليهود والنصارى. فأمر عثمان بنسخ المصحف الذي عند حفصة على ستة مصاحف، أرسلها إلى الأمصار، وأمر بإحراق ما عداها. هذا المصحف العثماني هو الذي يقرأ منه المسلمون اليوم في كل أنحاء العالم.',
      'في أواخر خلافته بدأت فتنة عظيمة. كان قد عيّن أقاربه من بني أمية على بعض الأمصار، فاتهمه أعداؤه بالمحاباة. اجتمع جماعة من أهل مصر والكوفة والبصرة وحاصروا بيته في المدينة. كان يستطيع أن يدافع عن نفسه بالسلاح — كان عنده عبيد كثيرون ورجال من الصحابة جاؤوا للدفاع عنه — لكنه رفض. قال: لا أكون أول من يخلف رسول الله في أمته بسفك الدم.',
      'حاصره الثائرون أيامًا، منعوه من الماء حتى في رمضان. ظل صابرًا يقرأ القرآن. قال لمن حوله: من كان حقّه قِبلي فليأخذه ولا يأخذه عند الله. وأعتق عشرين عبدًا في تلك الأيام. اقتحم الثائرون داره وعثمان قاعد يقرأ القرآن. ضربوه ضربات في وجهه ورأسه، فسال دمه على المصحف الشريف، على آية: فسيكفيكهم الله وهو السميع العليم. كانت آخر آية رآها بعينه.',
      'استشهد رضي الله عنه في يوم الجمعة 18 ذي الحجة سنة 35 هـ، وعمره 82 سنة. صلّى عليه جبير بن مطعم ومعه نفر قليل من قرابته، ودفن بـ حش كوكب — مقبرة قرب البقيع — لأن الثوار منعوا دفنه في البقيع. أم المؤمنين عائشة بكت لما سمعت بقتله، وقالت: قتلوه والله مظلومًا.',
      'مقتل عثمان كان نقطة فاصلة في تاريخ الإسلام. فُتح بمقتله باب الفتنة بين المسلمين. وقعت معركة الجمل، ثم معركة صفين، ثم الخوارج، ثم تكوّن النواة الأولى لما سُمّي بعد ذلك بالشيعة والسنة. كل هذا تفرع من قتل خليفة المسلمين الثالث ظلمًا. ولذلك قال علي بن أبي طالب: هذه فتنة ما تكاد تنتهي إلا بكل دار وكل بلد.',
      'كان عثمان رضي الله عنه شديد الحياء. قال النبي ﷺ: ألا أستحيي من رجل تستحيي منه الملائكة؟ كان ﷺ مضطجعًا فدخل أبو بكر فلم يتغير، ودخل عمر فلم يتغير، فلما دخل عثمان سوّى ﷺ ثيابه وقال هذه الكلمة. كان قيام الليل عليه دائمًا، يختم القرآن في ليلة، ويتصدّق في السرّ والعلانية.',
      'يبقى عثمان بن عفان في تاريخ الإسلام رمزًا للحياء والكرم والصبر. ذو النورين الذي زوّجه النبي ﷺ ابنتيه، وجامع القرآن الذي على مصحفه يقرأ المسلمون. مات شهيدًا والمصحف بين يديه، وآية فسيكفيكهم الله على صفحته. اللهم ارضَ عن عثمان وارفع درجته، فما ضرّه ما عمل بعد جيش العسرة، وما ضرّه ما لاقاه من فتنة آخر خلافته.',
    ]),
    en: P([
      'He is Uthman ibn Affan ibn Abi al-As ibn Umayyah ibn Abd Shams ibn Abd Manaf, al-Qurashi al-Umawi. He was born in Makkah six years after the Year of the Elephant, six years younger than the Prophet ﷺ. His mother was Arwa bint Kurayz ibn Rabi\'ah. He was among the nobles and wealthy of Quraysh, with vast trade between Sham and the Hijaz.',
      'He was nicknamed Dhu al-Nurayn (Possessor of the Two Lights) because he married two of the daughters of the Prophet ﷺ: Ruqayyah, and when she died the Prophet married him to Umm Kulthum. The Prophet ﷺ said: "If I had a third I would have married her to Uthman." No one before or after him had this honour — to marry two daughters of a single prophet after the death of the first.',
      'He embraced Islam at the hand of Abu Bakr al-Siddiq at the start of the mission, among the very earliest. He was about thirty-four years old. When his uncle al-Hakam ibn Abi al-As — a polytheist — learned of it, he tied him up and said: "Do you abandon the religion of your fathers for an invented religion?" Uthman said: "By Allah, I shall never leave it." When his uncle saw his steadfastness he released him.',
      'Uthman made the two emigrations: twice to Abyssinia, then to Madinah. He was among those who went first to Abyssinia fleeing with their religion from Quraysh\'s harm, with his wife Ruqayyah. The Prophet ﷺ said when he saw them off: "These are the first to emigrate with their families in Allah\'s cause after Lot." A tremendous testimony from the Prophet ﷺ, linking Uthman with earlier prophets.',
      'Uthman did not attend the Battle of Badr, because the Prophet ﷺ left him with his wife Ruqayyah when she fell ill. Ruqayyah died during the battle, and Uthman returned grieving, but the Prophet ﷺ allotted him a share of Badr\'s spoils and counted his reward, so he was considered as having witnessed it. This too is a unique station.',
      'He was known for remarkable generosity. He bought the Well of Ruma from a Jew for twenty thousand dirhams — and the Jew had been selling its water to the Muslims — and made it a charitable endowment for the Muslims so that everyone in Madinah could drink from it. In the Tabuk campaign he equipped the entire Army of Hardship. He brought a thousand camels, fifty horses, and ten thousand dinars, placing them in the Prophet\'s lap. The Prophet ﷺ would turn them over and say: "Nothing Uthman does after today can harm him. Nothing Uthman does after today can harm him."',
      'The Muslims pledged allegiance to him as caliph after Umar in 23 AH, through the council Umar had appointed. He was seventy years old. He took office when the Islamic state was at the peak of its conquests. In his caliphate Armenia, Azerbaijan, Khurasan, Kerman, Sijistan, Cyprus, and parts of Africa were conquered. The Islamic fleet began to traverse the Mediterranean — the first naval force in Muslim history.',
      'The greatest achievement of his caliphate was the compilation of the Mushaf and the unification of its recitation. The Muslims had dispersed across the lands, each region reciting in a different way, until disputes began. Hudhayfah ibn al-Yaman proposed to Uthman to gather the people on a single Mushaf before they differed as the Jews and Christians had differed. Uthman ordered Hafsah\'s Mushaf copied into six Mushafs, sent them to the regions, and ordered everything else burned. This Uthmanic Mushaf is the one Muslims recite from today all over the world.',
      'In the latter part of his caliphate a great trial began. He had appointed his Umayyad relatives over some regions, and his enemies accused him of nepotism. A group from Egypt, Kufa, and Basra gathered and besieged his house in Madinah. He could have defended himself with arms — he had many slaves and Companions who came to defend him — but he refused. He said: "I will not be the first to succeed the Messenger of Allah in his Ummah by shedding blood."',
      'The rebels besieged him for days, preventing him from water even in Ramadan. He remained patient, reciting the Qur\'an. He said to those around him: "Whoever has a right with me, let him take it, and not take it on the Day of Judgement." He freed twenty slaves in those days. The rebels stormed his house while Uthman sat reciting the Qur\'an. They struck him blows to the face and head, and his blood spilled on the noble Mushaf, on the verse: "Allah will suffice you against them, and He is the All-Hearing, the All-Knowing." It was the last verse his eyes saw.',
      'He was martyred on Friday 18 Dhu al-Hijjah of 35 AH, at the age of 82. Jubayr ibn Mut\'im prayed over him with a small group of his relatives, and he was buried in Hashsh Kawkab — a cemetery near al-Baqi\' — because the rebels prevented his burial in al-Baqi\'. The Mother of the Believers A\'isha wept when she heard of his killing and said: "By Allah, they killed him unjustly."',
      'Uthman\'s killing was a turning point in the history of Islam. His killing opened the door of fitnah among the Muslims. The Battle of the Camel followed, then Siffin, then the Khawarij, then the first nucleus of what was later called Shi\'a and Sunni. All this branched out from the unjust killing of the third caliph of the Muslims. That is why Ali ibn Abi Talib said: "This is a trial that will hardly end except by being in every house and every city."',
      'Uthman was intensely shy. The Prophet ﷺ said: "Should I not be shy of a man whom the angels are shy of?" The Prophet was reclining and Abu Bakr entered and he did not change his position; Umar entered and he did not change. When Uthman entered, the Prophet ﷺ straightened his clothes and said these words. He stood at night always, completing the Qur\'an in a single night, and giving charity in private and in public.',
      'Uthman ibn Affan remains in the history of Islam a symbol of modesty, generosity, and patience. Dhu al-Nurayn whom the Prophet ﷺ married to his two daughters, and the compiler of the Qur\'an whose Mushaf the Muslims still recite from. He died a martyr with the Mushaf in his hands, the verse "Allah will suffice you against them" on its page. O Allah, be pleased with Uthman and raise his rank, for nothing he did after the Army of Hardship harmed him, and nothing he met in the trial at the end of his caliphate harmed him.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 4. علي بن أبي طالب رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'ali': {
    ar: P([
      'هو علي بن أبي طالب بن عبد المطلب بن هاشم بن عبد مناف، القرشي الهاشمي. وُلد في جوف الكعبة قبل البعثة بعشر سنوات — وهذا شرف لم يحظَ به أحد قبله ولا بعده. أمه فاطمة بنت أسد بن هاشم، وأبوه أبو طالب عم النبي ﷺ. نشأ في بيت النبي ﷺ منذ صغره، لما كفله النبي عن أبيه تخفيفًا عنه بعد أن أصابته قحط.',
      'كان أول من أسلم من الصبيان. لما رأى النبي ﷺ وخديجة يصليان، سأل: ما هذا يا محمد؟ فأخبره النبي بدعوته. تأمل علي ليلة، ثم رجع وأعلن إسلامه. كان عمره يومئذ نحو عشر سنين، فصار أول من آمن من الصبيان كما كانت خديجة أول من آمن من النساء، وأبو بكر أول من آمن من الرجال.',
      'في ليلة الهجرة، كانت قريش قد اجتمعت لقتل النبي ﷺ. اختار النبي عليًا أن ينام في فراشه ويتغطّى ببرده الأخضر. كان النبي ﷺ بحاجة إلى من يثق به في أحرج لحظة في تاريخ الإسلام، فاختار عليًا. نام علي مكانه، فلما اقتحموا الفراش وجدوه. قال له المشركون: أين محمد؟ قال: لا أدري. أوصاه النبي ﷺ قبل خروجه أن يردّ الودائع التي كانت عنده للناس، فمكث ثلاثة أيام يردّها ثم لحق به في المدينة.',
      'تزوج فاطمة الزهراء بنت النبي ﷺ في السنة الثانية من الهجرة. كان مهرها درعه الذي باعه. عاشا حياة فقر وعفاف. كانت فاطمة تطحن القمح بيدها حتى مجلت يداها، وكان علي يحطب ويستقي. لكنّ حياتهما كانت من أعظم بيوت الإسلام في الصدق والإيمان. أنجبت له الحسن والحسين وزينب وأم كلثوم. والحسن والحسين سيدا شباب أهل الجنة.',
      'شارك في كل غزوات النبي ﷺ إلا تبوك، حيث استخلفه النبي على المدينة. حزن علي على عدم خروجه، فقال له النبي ﷺ: أما ترضى أن تكون مني بمنزلة هارون من موسى، إلا أنه لا نبي بعدي؟ كانت كلمة عظيمة تقرنه بنبي الله هارون.',
      'كان فارسًا شجاعًا. في غزوة بدر قتل عددًا من كبار قريش في المبارزة. في أحد، صبر مع النبي حين انفض الناس. في الخندق، تطوّع لمبارزة عمرو بن ودّ العامري — أعظم فرسان العرب — وقتله في مبارزة شهدتها الأمة. وفي خيبر، أعطاه النبي ﷺ الراية وقال: لأعطين الراية غدًا رجلًا يحب الله ورسوله، ويحبه الله ورسوله. ففتح الله على يديه.',
      'كان من أعلم الصحابة بالعلوم. قال عمر بن الخطاب: لا بقيتُ لمعضلة ليس فيها أبو الحسن. كان مرجعًا في القضاء والفتوى في زمن الخلفاء الثلاثة قبله. قال النبي ﷺ: أنا مدينة العلم وعلي بابها. فمن أراد العلم فليأت الباب. لكن العلماء حذّروا من الغلو في علي، فالعلم النبوي عام لكل الصحابة، وعلي أوّلهم في كثير منه لا في كله.',
      'تولى الخلافة بعد مقتل عثمان رضي الله عنه سنة 35 هـ. كانت خلافته من أصعب فترات تاريخ الإسلام. ورث فتنة عظيمة بدأت بقتل عثمان، فلم يلبث أن واجه ثلاث حروب أهلية: معركة الجمل ضد عائشة وطلحة والزبير، ومعركة صفين ضد معاوية ومن معه، ومعركة النهروان ضد الخوارج. لم يهنأ بحكمه يومًا واحدًا.',
      'كان في فقهه يقدم العدل المطلق على المصالح السياسية. لما قيل له: أعطِ هؤلاء الأمراء عطاء كثيرًا حتى لا ينقسموا عنك، رفض وقال: لا أبيع الحق بشيء. وكان يأخذ من بيت المال ما يكفيه فقط، وكان يقطع الخبز اليابس بنفسه. كانت ثيابه مرقّعة، وكان يقول: إن الله فرض على أئمة العدل أن يقدّروا أنفسهم بضعفة الناس كي لا يتبيّغ بالفقير فقره.',
      'حروبه ضد معاوية وأهل الشام كانت من أصعب ما واجه. لم تكن حروبًا للدنيا ولا للسلطة، إنما اختلاف في تفسير حق الإمامة بعد قتل عثمان. كل من الطرفين كان يرى نفسه على الحق. وقعت معركة صفين سنة 37 هـ، فلما كاد علي ينتصر، رفع جيش معاوية المصاحف على الرماح ودعوا إلى التحكيم. قبل علي على إكراه من جيشه. تم التحكيم ولم ينجح، فانقسم جيش علي وخرج منه الخوارج.',
      'الخوارج كانوا أصعب على علي من معاوية. قاتلهم في معركة النهروان سنة 38 هـ، فقتل منهم نحو أربعة آلاف. لكن بقايا منهم استمروا في التآمر. عبد الرحمن بن ملجم — أحد الخوارج — تقاسم مع رفيقين له أن يقتلوا في يوم واحد عليًا في الكوفة، ومعاوية في الشام، وعمرو بن العاص في مصر. نجح ابن ملجم وحده.',
      'في فجر السابع عشر من رمضان سنة 40 هـ، خرج علي إلى المسجد للصلاة. كان ابن ملجم قد كمن له، فضربه بسيف مسموم على رأسه وهو ساجد. قال علي: فزتُ ورب الكعبة. حُمل إلى بيته، وعاش يومين. أوصى الحسن أن يقتصّ من ابن ملجم بضربة واحدة كما ضرب، ولا يتجاوز ذلك. ومات رضي الله عنه عن عمر 63 سنة — كعمر النبي ﷺ وأبي بكر وعمر — وهي صدفة ربانية لافتة.',
      'مكان دفنه اختلف فيه. الراجح عند أهل العلم أنه دفن في الكوفة بقرب من مسجدها. لكن المشهور عند العامة أنه دُفن في النجف. الله أعلم بالمكان الحقيقي. لكن المهم أن يبقى ذكره في القلوب، لا في حجارة قبر.',
      'يبقى علي بن أبي طالب في تاريخ الإسلام رابع الخلفاء الراشدين، وأبا الحسن والحسين، وزوج فاطمة بنت رسول الله. رجل جمع العلم والشجاعة والورع والزهد. ابن عم النبي ﷺ، وأخوه يوم المؤاخاة، وصهره. سيرته دروس في الإيمان والثبات. ولا يجوز لمسلم أن يكره عليًا، فمن أبغضه فقد أبغض من أحب رسول الله. اللهم ارضَ عن علي وارفع درجته، وارزقنا الاقتداء بإيمانه.',
    ]),
    en: P([
      'He is Ali ibn Abi Talib ibn Abd al-Muttalib ibn Hashim ibn Abd Manaf, al-Qurashi al-Hashimi. He was born inside the Ka\'bah ten years before the mission — an honour no one before or after him received. His mother was Fatimah bint Asad ibn Hashim, and his father Abu Talib was the uncle of the Prophet ﷺ. He grew up in the Prophet\'s ﷺ house from his early childhood, when the Prophet undertook his care from his father to relieve him after a drought struck him.',
      'He was the first of the boys to embrace Islam. When he saw the Prophet ﷺ and Khadijah praying, he asked: "What is this, O Muhammad?" The Prophet told him of his call. Ali reflected for a night, then returned and announced his Islam. He was about ten years old, so he became the first boy to believe, as Khadijah was the first woman to believe and Abu Bakr the first man.',
      'On the night of the Hijrah, Quraysh had gathered to kill the Prophet ﷺ. The Prophet chose Ali to sleep in his bed and cover himself with his green cloak. The Prophet needed someone he trusted at the most critical moment in the history of Islam, and he chose Ali. Ali slept in his place. When the polytheists stormed the bed they found him. They said to him: "Where is Muhammad?" He said: "I do not know." The Prophet ﷺ had instructed him before leaving to return the deposits people had entrusted to him, so he stayed three days returning them and then followed to Madinah.',
      'He married Fatimah al-Zahra, daughter of the Prophet ﷺ, in the second year of the Hijrah. Her dowry was his coat of mail which he sold. They lived a life of poverty and chastity. Fatimah ground wheat with her hand until her hands blistered, and Ali gathered firewood and drew water. But their life was among the greatest households of Islam in truthfulness and faith. She bore him Hasan, Husayn, Zaynab, and Umm Kulthum. Hasan and Husayn are the leaders of the youth of Paradise.',
      'He took part in every battle of the Prophet ﷺ except Tabuk, where the Prophet left him in charge of Madinah. Ali was sad at not going out, so the Prophet ﷺ said: "Are you not pleased to be to me what Harun was to Musa, except that there is no prophet after me?" A great statement linking him with Allah\'s prophet Harun.',
      'He was a brave knight. At Badr he killed several of Quraysh\'s leading men in duels. At Uhud he stood firm with the Prophet when others scattered. At the Trench he volunteered to duel Amr ibn Wadd al-Amiri — the greatest knight of the Arabs — and killed him in a duel the Ummah witnessed. At Khaybar the Prophet ﷺ gave him the banner and said: "Tomorrow I shall give the banner to a man who loves Allah and His Messenger, and Allah and His Messenger love him." And Allah granted victory through him.',
      'He was among the most knowledgeable Companions. Umar ibn al-Khattab said: "May I not remain for a difficult matter in which Abu al-Hasan is not present." He was a reference in judicial rulings and fatwa during the reigns of the three caliphs before him. The Prophet ﷺ said: "I am the city of knowledge and Ali is its gate. Whoever wants knowledge, let him come to the gate." But scholars warned against extremism in Ali; prophetic knowledge is general to all the Companions, and Ali was foremost in much of it, not all.',
      'He took the caliphate after the martyrdom of Uthman in 35 AH. His caliphate was among the hardest periods in Islamic history. He inherited a great trial that had begun with Uthman\'s killing and soon faced three civil wars: the Battle of the Camel against A\'isha, Talha, and Zubayr; the Battle of Siffin against Mu\'awiyah and those with him; and the Battle of Nahrawan against the Khawarij. He did not enjoy a single day of his rule in peace.',
      'In his jurisprudence he put absolute justice above political interests. When he was told: "Give these leaders abundant gifts so they do not split from you," he refused and said: "I will not sell the truth for anything." He took from the treasury only what sufficed him, and would cut dry bread himself. His clothes were patched, and he used to say: "Allah obliges just imams to measure themselves by the weak of people, so that the poor man is not consumed by his poverty."',
      'His wars against Mu\'awiyah and the people of Sham were among the hardest things he faced. They were not wars for worldly gain or power, but a disagreement in interpreting the right of leadership after Uthman\'s killing. Each side saw itself as on the truth. The Battle of Siffin took place in 37 AH; when Ali was about to win, Mu\'awiyah\'s army raised the Mushafs on spears and called for arbitration. Ali accepted under pressure from his army. The arbitration did not succeed, his army split, and the Khawarij emerged from it.',
      'The Khawarij were harder on Ali than Mu\'awiyah. He fought them at the Battle of Nahrawan in 38 AH, killing about four thousand of them. But remnants continued to plot. Abd al-Rahman ibn Muljam — one of the Khawarij — agreed with two companions to kill, on a single day, Ali in Kufa, Mu\'awiyah in Sham, and Amr ibn al-As in Egypt. Only Ibn Muljam succeeded.',
      'At dawn of the seventeenth of Ramadan in 40 AH, Ali went out to the mosque for prayer. Ibn Muljam had lain in wait for him and struck him with a poisoned sword on his head while he was in prostration. Ali said: "By the Lord of the Ka\'bah, I have succeeded." He was carried to his house and lived two days. He instructed Hasan to take retribution from Ibn Muljam with a single blow as he had struck and not exceed that. He died, may Allah be pleased with him, at the age of 63 — the same age as the Prophet ﷺ, Abu Bakr, and Umar — a striking divine coincidence.',
      'The place of his burial is disputed. The strongest view among scholars is that he was buried in Kufa near its mosque. But it is famously held among the common people that he was buried in Najaf. Allah knows best the real place. But what matters is that his memory remains in hearts, not in tombstones.',
      'Ali ibn Abi Talib remains in the history of Islam the fourth of the Rightly Guided Caliphs, the father of Hasan and Husayn, and the husband of Fatimah, daughter of the Messenger of Allah. A man who combined knowledge, courage, piety, and asceticism. The cousin of the Prophet ﷺ, his brother on the day of the brotherhood, and his son-in-law. His life history is a lesson in faith and steadfastness. It is not permissible for a Muslim to dislike Ali; whoever hates him has hated one whom the Messenger of Allah loved. O Allah, be pleased with Ali and raise his rank, and grant us to follow his faith.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 5. طلحة بن عبيد الله رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'talha': {
    ar: P([
      'هو طلحة بن عبيد الله بن عثمان بن عمرو بن كعب بن سعد بن تيم بن مرة، القرشي التيمي، من قبيلة أبي بكر الصديق. وُلد بمكة قبل الهجرة بنحو ثلاثين سنة. كان من سادات قريش وأغنيائها، تاجرًا ذا ثروة كبيرة، يكثر السفر إلى الشام في تجارة الأقمشة والحرير.',
      'قصة إسلامه بدأت في الشام. كان في رحلة تجارية ببُصرى — مدينة في جنوب الشام — فمر براهب يخطب في الناس. سمعه يقول: إن نبيًا من العرب قد خرج في هذا الزمان، اسمه أحمد، فعليكم بالإيمان به. سأله طلحة: من أي قبيلة؟ قال: من قريش. عاد طلحة سريعًا إلى مكة يبحث عن هذا النبي.',
      'وصل مكة فوجد أن النبي ﷺ قد بُعث، وأن أبا بكر قد أسلم. ذهب إلى أبي بكر — وكان صديقه — فأخبره أبو بكر بالنبي ﷺ ودعوته. ذهبا معًا إلى النبي ﷺ، فأسلم طلحة. كان من السابقين الأولين، من الثمانية الأوائل الذين أسلموا قبل دخول النبي دار الأرقم.',
      'لما علم به عمه نوفل بن خويلد — وكان من رجال قريش الأشداء — قبض عليه هو وأبا بكر، وأوثقهما في حبل واحد، وألقاهما في ساحة الكعبة ليُعذَّبا. صار يُذكر طلحة وأبو بكر بـ القرينين بسبب هذه الحادثة، فقد رُبطا في حبل واحد كأنهما توأمان في الدعوة.',
      'لم يشهد طلحة غزوة بدر، لأنه كان في مهمة في الشام بأمر النبي ﷺ. لكنه شارك في أحد، وكان فيها أعظم بلاء. في أحد، انكشف المسلمون لما خالف الرماة أمر النبي ﷺ. اقتربت قريش من النبي وأرادت قتله. وقف طلحة بنفسه دروعًا أمام النبي. اعترضت السهام جسده، حتى قطعت أصابعه وضربت رأسه بعدة جراح.',
      'في تلك اللحظة، رفع النبي ﷺ يده يضرب، فمسك طلحة بالسيف وجعل يدفع به السهام. أحد السهام جاء إلى وجه النبي ﷺ، فاستقبله طلحة بكفه. شُلّت أصابعه من تلك الضربة، لكنه حفظ وجه النبي من الإصابة. أصيب يومئذ بأربع وعشرين ضربة. سقط على الأرض من شدة الجراح، وظنّ النبي ﷺ أنه استشهد. ثم رفع رأسه فلما رآه النبي قال: أوجب طلحة. أي وجبت له الجنة.',
      'سُمّي بعد أحد: طلحة الخير، طلحة الفياض، طلحة الجود، طلحة الشهيد الحي. قال النبي ﷺ: من سرّه أن ينظر إلى شهيد يمشي على وجه الأرض فلينظر إلى طلحة بن عبيد الله. عاش بعد أحد سنوات طويلة، لكن جراحه شاهدة على ما لاقاه دفاعًا عن النبي ﷺ. كانت يده شلاء، وعلى رأسه ندوب الجراح، وفي جسده آثار السهام التي قبضت دونه.',
      'كان من أكثر الصحابة كرمًا. كان النبي ﷺ يأكل أحيانًا من بيته. قال له النبي يومًا: لو شئت يا طلحة لكنتَ أغنى أهل مكة. وكان طلحة يفرّق ماله في سبيل الله بمناسبة وغير مناسبة. باع مرة أرضًا بسبعمئة ألف، فلم ينم تلك الليلة من خوف أن يموت ولم ينفقها، حتى فرّقها في الفقراء.',
      'شارك في الشورى التي عيّنها عمر بن الخطاب لاختيار الخليفة بعده. كان من الستة الذين أوصى عمر بأن يختار الخليفة من بينهم. وقع الاختيار على عثمان بن عفان، وبايع طلحة بإخلاص. كان من المتبادلين الذكر مع علي وعثمان، وبيوتهم متجاورة في المدينة.',
      'حين قتل عثمان، اضطربت الأمة. طلحة كان في المدينة لما حدث القتل، فحزن حزنًا شديدًا. اتهمه بعض المؤرخين أنه شارك في الحصار، والصحيح أنه كان معترضًا على بعض ولاة عثمان، لكنه لم يرضَ بقتله. بل بكى عليه بكاءً شديدًا، وقال: ما حسبت يومًا أن يحدث هذا.',
      'تولى علي بن أبي طالب الخلافة بعد عثمان. بايع له طلحة في البداية، لكنه طلب منه الاقتصاص من قتلة عثمان فورًا. علي كان يرى أن الأمر يحتاج إلى تحقيق وأن قتلة عثمان متفرّقون في الأمصار. اختلفا في التوقيت لا في المبدأ. خرج طلحة والزبير وعائشة إلى البصرة يطلبون الانتقام لعثمان.',
      'وقعت معركة الجمل سنة 36 هـ بين علي وأصحاب الجمل. حاول علي قبل المعركة أن يصلح. قابل طلحة والزبير وذكّرهما بأحاديث للنبي ﷺ، فتراجع الزبير. لكن المعركة وقعت بعد ذلك بسبب فتنة دبّرها المنافقون من الفريقين. قُتل طلحة في تلك المعركة بسهم أصابه في ركبته، فمات نزفًا.',
      'يقال إن السهم الذي قتل طلحة جاء من مروان بن الحكم — الذي كان في صفّ طلحة! اتهم مروان طلحة بأنه كان من المحرّضين على قتل عثمان (لما اختلف معه في بعض الأمور)، فانتهز فرصة المعركة وأطلق عليه السهم. هذه آفة الفتن: الصديق يصير عدوًا، والعدو يصير قاتلًا، وكل شيء يضطرب.',
      'مات طلحة عن عمر نحو 64 سنة. صلى عليه علي بن أبي طالب بنفسه، وبكى وقال: ليتني متُّ قبل هذا اليوم. ودفن قرب البصرة. كان من أعظم خسارة وقعت يومئذ — رجل من العشرة المبشرين بالجنة، الذي وقى النبي ﷺ بجسده في أحد، يقتل في فتنة بين المسلمين. مأساة من مآسي التاريخ.',
      'يبقى طلحة بن عبيد الله في التاريخ الإسلامي شهيدًا حيًا ميتًا. وقى النبي ﷺ بصدره، فضمن له الجنة وهو يمشي. ومات شهيدًا في فتنة بين أصحاب رسول الله. الواجب على المسلم أن يترضى عنه وعن جميع الصحابة، وأن لا يخوض في خلافاتهم، فقد قال علي بعد المعركة: إني لأرجو أن أكون أنا وطلحة وعثمان من الذين قال الله فيهم: ونزعنا ما في صدورهم من غل إخوانًا على سرر متقابلين.',
    ]),
    en: P([
      'He is Talhah ibn Ubaydillah ibn Uthman ibn Amr ibn Ka\'b ibn Sa\'d ibn Taym ibn Murrah, al-Qurashi al-Taymi, of the tribe of Abu Bakr al-Siddiq. He was born in Makkah about thirty years before the Hijrah. He was among the nobles and wealthy of Quraysh, a merchant of great wealth, frequently travelling to Sham in the trade of cloth and silk.',
      'The story of his Islam began in Sham. He was on a trading journey at Busra — a city in southern Sham — and passed a monk preaching to people. He heard him say: a prophet of the Arabs has emerged in this time, named Ahmad; you must believe in him. Talhah asked: from which tribe? He said: from Quraysh. Talhah returned quickly to Makkah seeking this prophet.',
      'He reached Makkah and found that the Prophet ﷺ had been sent, and Abu Bakr had embraced Islam. He went to Abu Bakr — who was his friend — and Abu Bakr told him of the Prophet ﷺ and his call. They went together to the Prophet ﷺ, and Talhah embraced Islam. He was among the very first, among the first eight who embraced Islam before the Prophet entered the house of al-Arqam.',
      'When his uncle Nawfal ibn Khuwaylid — one of the strong men of Quraysh — learned of him, he seized him with Abu Bakr, tied them both in one rope, and cast them in the courtyard of the Ka\'bah to be tortured. Talhah and Abu Bakr came to be called "the Two Bound Together" because of this incident, having been tied in one rope as if twins in the call.',
      'Talhah did not attend the Battle of Badr because he was on a mission to Sham by the Prophet\'s ﷺ order. But he participated in Uhud and showed there the greatest trial. At Uhud, the Muslims were exposed when the archers disobeyed the Prophet\'s ﷺ command. Quraysh approached the Prophet and tried to kill him. Talhah stood himself as a shield before the Prophet. The arrows intercepted his body until they cut his fingers and struck his head with several wounds.',
      'At that moment, the Prophet ﷺ raised his hand to strike. Talhah grasped a sword and began deflecting arrows with it. An arrow came toward the Prophet\'s ﷺ face, and Talhah caught it with his palm. His fingers were paralysed by that blow, but he protected the Prophet\'s face from injury. He was struck that day with twenty-four blows. He fell to the ground from severe wounds, and the Prophet ﷺ thought he had been martyred. When he lifted his head and the Prophet saw him he said: "Talhah is assured" — meaning Paradise has become obligatory for him.',
      'After Uhud he was named: Talhah the Good, Talhah the Generous, Talhah the Bounteous, Talhah the Living Martyr. The Prophet ﷺ said: "Whoever wishes to look at a martyr walking on the face of the earth, let him look at Talhah ibn Ubaydillah." He lived years after Uhud, but his wounds bore witness to what he met defending the Prophet ﷺ. His hand was paralysed, his head bore the scars of wounds, and his body bore the marks of arrows that struck him in his place.',
      'He was among the most generous of the Companions. The Prophet ﷺ would sometimes eat from his house. The Prophet said to him one day: "If you wished, O Talhah, you would have been the wealthiest of Makkah." Talhah used to distribute his wealth in Allah\'s cause on occasion and without occasion. He once sold a piece of land for seven hundred thousand and did not sleep that night for fear of dying without distributing it, until he had distributed it among the poor.',
      'He took part in the council that Umar ibn al-Khattab appointed to choose the caliph after him. He was among the six whom Umar instructed to choose the caliph from among them. The choice fell upon Uthman ibn Affan, and Talhah pledged allegiance with sincerity. He was among those of close mutual remembrance with Ali and Uthman, and their houses were adjacent in Madinah.',
      'When Uthman was killed, the Ummah was thrown into turmoil. Talhah was in Madinah when the killing occurred and grieved severely. Some historians accused him of participating in the siege; the truth is that he objected to some of Uthman\'s governors but did not consent to his killing. Rather, he wept over him deeply and said: "I never thought a day would come that this would happen."',
      'Ali ibn Abi Talib took the caliphate after Uthman. Talhah pledged allegiance to him at first, but asked him to immediately take retribution from Uthman\'s killers. Ali held that the matter required investigation and that the killers were dispersed across the regions. They differed in timing, not in principle. Talhah, Zubayr, and A\'isha went out to Basra seeking vengeance for Uthman.',
      'The Battle of the Camel took place in 36 AH between Ali and the people of the camel. Ali tried before the battle to reconcile. He met Talhah and Zubayr and reminded them of hadiths of the Prophet ﷺ, and Zubayr withdrew. But the battle occurred afterward because of a sedition contrived by hypocrites from both sides. Talhah was killed in that battle by an arrow that struck him in the knee, and he died of bleeding.',
      'It is said that the arrow that killed Talhah came from Marwan ibn al-Hakam — who was in Talhah\'s ranks! Marwan accused Talhah of having been among those who incited the killing of Uthman (when he disagreed with him in certain matters), and seized the chance of the battle to fire the arrow at him. This is the disease of trials: a friend becomes an enemy, the enemy becomes a killer, and everything is thrown into confusion.',
      'Talhah died at about 64 years of age. Ali ibn Abi Talib prayed over him personally and wept, saying: "I wish I had died before this day." He was buried near Basra. It was among the greatest losses of that day — a man of the ten promised Paradise, who shielded the Prophet ﷺ with his body at Uhud, killed in a sedition among the Muslims. A tragedy among the tragedies of history.',
      'Talhah ibn Ubaydillah remains in Islamic history a living-dead martyr. He shielded the Prophet ﷺ with his chest, and Paradise was guaranteed to him while he walked. He died a martyr in a sedition among the Companions of the Messenger of Allah. The Muslim\'s duty is to be pleased with him and with all the Companions, and not to delve into their disputes. Ali said after the battle: "I hope that I, Talhah, and Uthman shall be among those of whom Allah said: ‘And We will remove whatever is in their breasts of resentment, [so they will be] brothers, on couches facing each other.’"',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 6. الزبير بن العوام رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'zubayr': {
    ar: P([
      'هو الزبير بن العوام بن خويلد بن أسد بن عبد العزى، القرشي الأسدي. ابن أخي خديجة بنت خويلد أم المؤمنين، فهو ابن عمة النبي ﷺ. وُلد بمكة قبل الهجرة بنحو ثمان وعشرين سنة. أمه صفية بنت عبد المطلب — عمة النبي ﷺ. فهو ابن عمة النبي من جهة الأم، وابن أخي زوجته من جهة الأب. قرابة مضاعفة.',
      'أسلم وهو ابن خمس عشرة سنة، رابعًا أو خامسًا من السابقين. كان أول من سلّ سيفه في الإسلام. سمع شائعة كاذبة أن النبي ﷺ قد قُتل، فاستلّ سيفه وخرج يطلب القاتل في شوارع مكة. عمره خمس عشرة سنة وقد سلّ السيف! لما رآه النبي ﷺ، دعا له بالخير ولسيفه، فكان سيفه يلازمه طوال حياته.',
      'لاقى أذى شديدًا من عمه نوفل بن خويلد. كان نوفل يربطه على حصير ويدخّن عليه بنار شديدة، يقول له: ارجع إلى دين آبائك. كان الزبير صبيًا في الخامسة عشرة، فثبت ولم يرجع. قال له عمه يومًا: ترجع إلى ديننا أم تموت؟ قال: لا، والله لا أكفر أبدًا. وكلما زاد عليه الأذى زاد ثباته.',
      'هاجر الهجرتين: إلى الحبشة، ثم إلى المدينة. كان من السباقين في كل المعارك. شهد بدرًا وأحدًا والخندق والحديبية وخيبر وفتح مكة وحنينًا والطائف وتبوك. كان فارسًا شجاعًا، يقاتل بسيفه وبرمحه. أصيب في أحد بعدة جراح، وفي الخندق ضرب عمرو بن عبد ودّ — أعظم فرسان قريش — حتى أعان عليّ بن أبي طالب على قتله.',
      'قال النبي ﷺ: لكل نبي حواري، وحواريّ الزبير. الحواري في اللغة هو الناصر المخلص. هذا اللقب فريد، لم ينله غيره من الصحابة. وفي البخاري حديث آخر: إن طلحة والزبير جاراي في الجنة. أي جيراني. وفي الترمذي: من سرّه أن ينظر إلى رجل من أهل الجنة، فلينظر إلى الزبير.',
      'في غزوة الأحزاب، نام النبي ﷺ مع أصحابه، ثم استيقظ وأراد أن يعرف ماذا فعل المشركون، فقال: من يأتيني بخبر القوم؟ تطوّع الزبير. عاد بأخبارهم. ثم قال النبي ﷺ مرة أخرى: من يأتيني بخبر القوم؟ تطوع الزبير. ثم ثالثة، تطوع الزبير. فقال النبي ﷺ في تلك الليلة كلمته: إن لكل نبي حواريًا، وإن حواريّ الزبير.',
      'كان من أغنياء الصحابة. اشترى كثيرًا من الأراضي في المدينة. لما مات، خلّف ثروة هائلة، لكنها كانت كلها مرهونة بديون عليه. أوصى ابنه عبد الله بأن يقضي ديونه، وقال له: إن عجزت عن قضاء شيء فاستعن بمولاي. سأله عبد الله: من مولاك؟ قال: الله. قال عبد الله: فما وقعت في كربة من ديونه إلا قلت: يا مولى الزبير، اقضِ عنه دينه. فيقضي.',
      'كان من الستة الذين عيّنهم عمر بن الخطاب للشورى. شارك في الفتوحات في مصر، وكان له بلاء حسن في معركة بابليون التي فُتحت بها مصر. وُلد له ابنه عبد الله في المدينة، وكان أول مولود للمهاجرين في المدينة بعد الهجرة، فكبّر له النبي ﷺ وحنّكه بتمرة. عاش عبد الله بعد ذلك ليكون أحد أعلام الصحابة.',
      'لما قُتل عثمان، حصل خلاف بينه وبين علي بن أبي طالب. كان الزبير يطالب بالاقتصاص من القتلة فورًا، وعلي يرى التأني. خرج الزبير مع طلحة وعائشة إلى البصرة. في معركة الجمل، قابله علي وذكّره بحديث للنبي ﷺ. كان النبي قد قال يومًا: لتقاتلنّ عليًا وأنت ظالم له. تذكّر الزبير الحديث، فبكى وانسحب من المعركة قبل بدئها.',
      'انسحب الزبير من المعركة وذهب يصلي في وادي السباع — مكان قريب من البصرة. لحقه رجل اسمه عمرو بن جرموز، وكان من أحد الفريقين. غدر به وهو ساجد، فقتله غدرًا. كان عمر الزبير ستًا وستين سنة. حُمل سيفه إلى علي، فلما رآه قال: سيف طالما فرّج الكرب عن وجه رسول الله ﷺ. وبكى علي عليه.',
      'قال علي لقاتله: من قتل ابن صفية، فبشره بالنار. سمع عمرو بن جرموز هذه الكلمة، فأيقن أنه دخل النار. مات بعد ذلك ولم يعرف له خاتمة طيبة. قتل الزبير لم ينفعه شيئًا، إنما جلب عليه لعنة الأمة بأكملها.',
      'ترك الزبير من الأولاد: عبد الله، عروة، المنذر، عاصم، المهاجر، خديجة الكبرى، أم الحسن، عائشة، وعبد الله. كل أولاده كانوا من علماء الصحابة والتابعين. عبد الله صار خليفة في الحجاز وحكم اثنتي عشرة سنة. عروة بن الزبير صار من فقهاء المدينة السبعة، أحد أعظم علماء التابعين.',
      'دفن الزبير في وادي السباع قرب البصرة. ولا يزال قبره معروفًا هناك إلى اليوم، يزوره الناس. وقد بُنيت قرب قبره مدينة سُمّيت باسمه: مدينة الزبير في جنوب العراق، ما زالت قائمة إلى اليوم.',
      'يبقى الزبير بن العوام في تاريخ الإسلام حواريّ النبي ﷺ، أحد العشرة المبشرين بالجنة، الذي سلّ سيفه أول الإسلام ولم يقبضه إلى آخر يوم في حياته. مات شهيدًا بقتل غادر، فاحتسبه عند الله. اللهم ارضَ عن الزبير، واجمعنا به وبأصحاب النبي ﷺ في جنات النعيم.',
    ]),
    en: P([
      'He is al-Zubayr ibn al-Awwam ibn Khuwaylid ibn Asad ibn Abd al-Uzza, al-Qurashi al-Asadi. He was the nephew of Khadijah bint Khuwaylid, Mother of the Believers, so he was the cousin of the Prophet ﷺ through his aunt. He was born in Makkah about twenty-eight years before the Hijrah. His mother was Safiyyah bint Abd al-Muttalib — the aunt of the Prophet ﷺ. He was thus the Prophet\'s cousin through his mother and the nephew of his wife through his father. Doubled kinship.',
      'He embraced Islam at fifteen, fourth or fifth among the very early ones. He was the first to draw his sword in Islam. He heard a false rumour that the Prophet ﷺ had been killed, drew his sword, and went out searching for the killer in the streets of Makkah. Fifteen years old and he had drawn the sword! When the Prophet ﷺ saw him he prayed for him and his sword, and his sword accompanied him his entire life.',
      'He suffered severe harm from his uncle Nawfal ibn Khuwaylid. Nawfal would tie him on a mat and smoke fire over him, saying: return to the religion of your fathers. He was a boy of fifteen, yet he stood firm and did not return. His uncle said to him one day: do you return to our religion or do you die? He said: no, by Allah, I shall never disbelieve. The more harm increased, the more his steadfastness increased.',
      'He made the two emigrations: to Abyssinia, then to Madinah. He was foremost in every battle. He witnessed Badr, Uhud, the Trench, Hudaybiyyah, Khaybar, the Conquest of Makkah, Hunayn, Ta\'if, and Tabuk. He was a brave knight, fighting with his sword and spear. He was wounded several times at Uhud, and at the Trench struck Amr ibn Abd Wadd — the greatest knight of Quraysh — until Ali ibn Abi Talib helped finish him.',
      'The Prophet ﷺ said: "Every prophet has a disciple, and my disciple is al-Zubayr." The disciple (hawari) in the language is the sincere supporter. This title is unique; no other Companion received it. In Bukhari is another hadith: "Talhah and al-Zubayr are my neighbours in Paradise." In Tirmidhi: "Whoever wishes to look at a man of the people of Paradise, let him look at al-Zubayr."',
      'In the Battle of the Confederates, the Prophet ﷺ and his Companions slept and then he woke, wanting to know what the polytheists were doing. He said: "Who will bring me news of the people?" Al-Zubayr volunteered. He returned with their news. The Prophet ﷺ said again: "Who will bring me news of the people?" Al-Zubayr volunteered. Then a third time, and al-Zubayr volunteered. The Prophet ﷺ said that night his words: "Every prophet has a disciple, and my disciple is al-Zubayr."',
      'He was among the wealthy Companions. He bought much land in Madinah. When he died he left a vast fortune, but it was all mortgaged with debts upon him. He instructed his son Abdullah to pay his debts and said: "If you are unable to discharge anything, seek help from my Patron." Abdullah asked: "Who is your Patron?" He said: "Allah." Abdullah said: "I never fell into difficulty over his debts but I said: O Patron of al-Zubayr, pay his debt for him. And it would be paid."',
      'He was among the six Umar ibn al-Khattab appointed for the council. He participated in the conquests in Egypt and showed great trial at the Battle of Babylon, by which Egypt was conquered. His son Abdullah was born in Madinah, the first child born to the Muhajirun in Madinah after the Hijrah. The Prophet ﷺ said takbir for him and tasted dates and put them in his mouth. Abdullah lived to become one of the foremost Companions.',
      'When Uthman was killed, a disagreement arose between him and Ali ibn Abi Talib. Al-Zubayr demanded immediate retribution from the killers, while Ali held that hesitation was needed. Al-Zubayr went out with Talhah and A\'isha to Basra. At the Battle of the Camel, Ali met him and reminded him of a hadith of the Prophet ﷺ. The Prophet had said one day: "You will fight Ali while wronging him." Al-Zubayr remembered the hadith, wept, and withdrew from the battle before it began.',
      'Al-Zubayr withdrew from the battle and went to pray in Wadi al-Siba\' — a place near Basra. A man named Amr ibn Jurmuz, of one of the two parties, followed him. He betrayed him while he was in prostration and killed him treacherously. Al-Zubayr was sixty-six years old. His sword was brought to Ali, and when he saw it he said: "A sword that long relieved distress from the face of the Messenger of Allah ﷺ." Ali wept over him.',
      'Ali said to his killer: "Whoever killed Ibn Safiyyah, give him glad tidings of the Fire." Amr ibn Jurmuz heard these words and became certain he had entered the Fire. He died afterward and no good ending was known for him. Killing al-Zubayr did not benefit him in anything, but brought upon him the curse of the entire Ummah.',
      'Al-Zubayr left as children: Abdullah, Urwah, al-Mundhir, Asim, al-Muhajir, Khadijah al-Kubra, Umm al-Hasan, A\'isha, and Abdullah. All his children were among the scholars of the Companions and Successors. Abdullah became caliph in the Hijaz and ruled for twelve years. Urwah ibn al-Zubayr became one of the seven jurists of Madinah, one of the greatest scholars of the Successors.',
      'Al-Zubayr was buried in Wadi al-Siba\' near Basra. His grave is still known there to this day, visited by people. A city was built near his grave named after him: the city of al-Zubayr in southern Iraq, still standing today.',
      'al-Zubayr ibn al-Awwam remains in the history of Islam the disciple of the Prophet ﷺ, one of the ten promised Paradise, who drew his sword at the start of Islam and did not sheathe it until his last day. He died a martyr by treacherous killing, and counted his reward with Allah. O Allah, be pleased with al-Zubayr, and gather us with him and with the Companions of the Prophet ﷺ in the Gardens of Bliss.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 7. سعد بن أبي وقاص رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'saad': {
    ar: P([
      'هو سعد بن مالك بن أُهيب بن عبد مناف بن زهرة، القرشي الزهري. ابن خال النبي ﷺ، لأن أم النبي ﷺ آمنة بنت وهب من بني زهرة. وُلد بمكة قبل البعثة بنحو ثلاث وعشرين سنة. أبوه أبو وقاص مالك بن أهيب، فعُرف بكنية أبيه: سعد بن أبي وقاص. كان من الفتيان الأشداء، ماهرًا بالرمي والقتال.',
      'أسلم وعمره سبع عشرة سنة. كان من السابقين الأولين، السابع في الإسلام. لما أسلم، شعرت أمه حمنة بنت سفيان بحزن شديد. قالت له: تترك دين آبائك إلى دين محدث؟ ثم قالت: لأمتنعن من الطعام والشراب حتى أموت أو ترجع. كانت تعتقد أن إصرارها على الإضراب سيكسره. صمدت ثلاثة أيام، فبلغت من الجوع ما اختلطت عقلها.',
      'فقال سعد كلمته الخالدة: يا أمه، لو كانت لكِ مئة نفس، فخرجت نفسًا نفسًا، ما تركت ديني هذا لشيء. فإن شئت فكلي، وإن شئت فلا تأكلي. لما رأت ثباته أكلت. وأنزل الله في هذه الحادثة آية: ووصينا الإنسان بوالديه حسنًا، وإن جاهداك لتشرك بي ما ليس لك به علم فلا تطعهما.',
      'كان أول من رمى بسهم في الإسلام. كان في سرية لرسول الله ﷺ، فلاقوا المشركين، فرمى سعد بسهم. هذا أول سهم رُمي في سبيل الله. كان قبل غزوة بدر. صار يفتخر بهذه السبقة، ويقول: لقد كنت أول رجل في الإسلام رمى بسهم في سبيل الله.',
      'شارك في بدر وأحد وكل الغزوات مع النبي ﷺ. في أحد، كان أحد الذين ثبتوا حول النبي ﷺ حين انفض الناس. كان يرمي السهام بين يدي النبي. والنبي ﷺ يقول له: ارمِ سعد، فداك أبي وأمي. لم يفد النبي ﷺ بأبويه أحدًا غير سعد. هذه شهادة عظيمة.',
      'كان النبي ﷺ يحبه حبًا شديدًا. قال له يومًا: اللهم استجب لسعد إذا دعاك. فكان سعد بعد ذلك إذا دعا الله، أُستجيب له. روي أن رجلًا أساء إليه، فقال سعد: اللهم إن كان هذا كاذبًا فلا تمته حتى تطيل عمره وتشدد فقره وتعرضه للفتن. فعاش الرجل عمرًا طويلًا في فقر، يتعرض لفتنة بعد فتنة، حتى تمنى الموت.',
      'تولى قيادة الجيش الإسلامي في فتح فارس في عهد عمر بن الخطاب. كانت معركة القادسية سنة 15 هـ من أعظم المعارك في تاريخ الإسلام. واجه فيها الجيش الفارسي بقيادة رستم بأكثر من مئة وعشرين ألف مقاتل. وجيش سعد سبعة آلاف فقط. لكن الله نصره. قُتل رستم، وتحطّمت دولة فارس، ودخل سعد المدائن — عاصمة كسرى — في موكب النصر.',
      'دخل سعد المدائن وصلى في إيوان كسرى. كان موقفًا تاريخيًا — قائد مسلم يصلي في قصر أعظم ملك في زمنه. أمر بتحويل الإيوان إلى مسجد، وأقام في المدائن أربع سنوات يدير شؤون العراق. ثم بنى مدينة الكوفة لتكون عاصمة للمسلمين في العراق، بدل المدائن — لأن المدائن لم تكن صالحة لسكنى العرب في حرّها وغبارها.',
      'كان من ستة الشورى الذين عيّنهم عمر بن الخطاب لاختيار الخليفة بعده. حضر الاختيار، وبايع لعثمان. ثم اعتزل الفتن بعد قتل عثمان. لم يشارك في معركة الجمل ولا صفين ولا أي قتال بين المسلمين. كان يقول: أعتزل الفتنة، لو دخل أحدكم بسيفه في رقبتي ما تركت سلمي.',
      'عاش بعد ذلك في قصره بالعقيق قرب المدينة. كان قد بنى بيتًا بسيطًا، فجاءه ابنه عمر بن سعد يومًا فقال: يا أبتِ لو ابتعدت عن الناس في هذا البيت. فدعا سعد عليه: اللهم اقطع رحم عمر، وارم خط أصحابه عليه. واستجاب الله، فإن عمر بن سعد هو الذي شارك بعد ذلك في قتل الحسين بن علي. مأساة من مآسي التاريخ.',
      'كان آخر من توفي من العشرة المبشرين بالجنة. مات في قصره بالعقيق قرب المدينة سنة 55 هـ، وعمره نحو ثمانين سنة. أوصى أن يكفّن بجبّة كان قد لبسها في معركة بدر — كان قد احتفظ بها كل هذه السنين. قال: كنت ألقى بها العدو في بدر، فأحب أن ألقى بها ربي. وكفّن بها.',
      'حُمل في جنازة عظيمة من العقيق إلى المدينة. صلى عليه الناس في المسجد النبوي ودفن بالبقيع. كانت عائشة أم المؤمنين قد طلبت أن تصلي عليه، فأدخلوا جنازته إلى حجرتها وصلّت عليه — فضل لم ينله إلا قليلون من الصحابة.',
      'يبقى سعد بن أبي وقاص في تاريخ الإسلام: ابن خال النبي ﷺ، السابع في الإسلام، أول من رمى بسهم في سبيل الله، فاتح فارس، صاحب الدعوة المستجابة، آخر العشرة وفاة. اللهم ارضَ عن سعد، واجمعنا به في الفردوس الأعلى.',
    ]),
    en: P([
      'He is Sa\'d ibn Malik ibn Uhayb ibn Abd Manaf ibn Zuhrah, al-Qurashi al-Zuhri. The maternal cousin of the Prophet ﷺ, because the Prophet\'s mother Aminah bint Wahb was from Banu Zuhrah. He was born in Makkah about twenty-three years before the mission. His father was Abu Waqqas Malik ibn Uhayb, so he was known by his father\'s kunya: Sa\'d ibn Abi Waqqas. He was among the strong youth, skilled in archery and combat.',
      'He embraced Islam at seventeen. He was among the very first, seventh in Islam. When he embraced Islam, his mother Hamnah bint Sufyan was deeply grieved. She said to him: "Do you leave the religion of your fathers for an invented religion?" Then she said: "I shall refuse food and drink until I die or you return." She believed her insistence on the hunger strike would break him. She held out three days, until hunger so weakened her that her mind became confused.',
      'Sa\'d said his immortal words: "Mother, if you had a hundred souls and they departed one by one, I would not leave this religion of mine for anything. If you wish, eat; if you wish, do not eat." When she saw his steadfastness she ate. Allah revealed in this incident the verse: "And We have enjoined upon man kindness to parents; but if they exert pressure on you to associate with Me that of which you have no knowledge, do not obey them."',
      'He was the first to shoot an arrow in Islam. He was in an expedition of the Messenger of Allah ﷺ; they met the polytheists, and Sa\'d shot an arrow. This was the first arrow shot in Allah\'s cause. It was before the Battle of Badr. He used to take pride in this precedence and say: "I was the first man in Islam to shoot an arrow in the cause of Allah."',
      'He participated in Badr, Uhud, and every battle with the Prophet ﷺ. At Uhud, he was among those who stood firm around the Prophet ﷺ when others scattered. He would shoot arrows in front of the Prophet, and the Prophet ﷺ would say to him: "Shoot, Sa\'d; may my father and mother be ransomed for you." The Prophet ﷺ did not ransom anyone with both his parents but Sa\'d. A tremendous testimony.',
      'The Prophet ﷺ loved him deeply. He said to him one day: "O Allah, answer Sa\'d when he supplicates You." After that, whenever Sa\'d supplicated Allah, he was answered. It is narrated that a man wronged him, and Sa\'d said: "O Allah, if this man is lying, do not let him die until You prolong his life, intensify his poverty, and expose him to trials." The man lived a long life in poverty, exposed to trial after trial, until he longed for death.',
      'He took command of the Islamic army in the conquest of Persia during the reign of Umar ibn al-Khattab. The Battle of al-Qadisiyyah in 15 AH was among the greatest battles in Islamic history. He faced the Persian army under Rustam with more than one hundred and twenty thousand fighters; Sa\'d\'s army was only seven thousand. But Allah granted him victory. Rustam was killed, the Persian state shattered, and Sa\'d entered al-Mada\'in — the capital of Khusrow — in a procession of victory.',
      'Sa\'d entered al-Mada\'in and prayed in the Iwan of Khusrow. A historic stand — a Muslim commander praying in the palace of the greatest king of his time. He ordered the Iwan converted into a mosque and stayed in al-Mada\'in four years administering the affairs of Iraq. Then he built the city of Kufa to be a capital for the Muslims in Iraq, in place of al-Mada\'in — because al-Mada\'in was not suitable for Arabs in its heat and dust.',
      'He was among the six of the council that Umar ibn al-Khattab appointed to choose the caliph after him. He attended the choosing and pledged allegiance to Uthman. Then he withdrew from the trials after the killing of Uthman. He did not participate in the Battle of the Camel or Siffin or any fighting between the Muslims. He used to say: "I withdraw from the trial. If one of you enters with his sword in my neck I will not leave my peace."',
      'He afterward lived in his estate in al-Aqiq near Madinah. He had built a simple house. His son Umar ibn Sa\'d came to him one day and said: "Father, would you not move further from people to this house?" Sa\'d supplicated against him: "O Allah, sever the kinship of Umar, and turn his companions\' approach upon him." Allah answered. For Umar ibn Sa\'d was the one who later participated in killing al-Husayn ibn Ali. A tragedy among the tragedies of history.',
      'He was the last of the ten promised Paradise to die. He died in his estate at al-Aqiq near Madinah in 55 AH at about eighty years of age. He instructed that he be shrouded in a robe he had worn at the Battle of Badr — he had kept it all these years. He said: "I would meet the enemy with it at Badr, and I love to meet my Lord with it." He was shrouded in it.',
      'He was carried in a great funeral procession from al-Aqiq to Madinah. The people prayed over him in the Prophet\'s Mosque and he was buried in al-Baqi\'. A\'isha, Mother of the Believers, had asked to pray over him, so his funeral was brought into her chamber and she prayed over him — a privilege only a few of the Companions had.',
      'Sa\'d ibn Abi Waqqas remains in the history of Islam: the maternal cousin of the Prophet ﷺ, seventh in Islam, first to shoot an arrow in Allah\'s cause, conqueror of Persia, possessor of answered supplication, the last of the ten to die. O Allah, be pleased with Sa\'d and gather us with him in the Highest Paradise.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 8. سعيد بن زيد رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'said': {
    ar: P([
      'هو سعيد بن زيد بن عمرو بن نُفيل، القرشي العدوي. ابن عم عمر بن الخطاب رضي الله عنه، وزوج أخت عمر — فاطمة بنت الخطاب. وُلد بمكة قبل البعثة بنحو اثنتين وعشرين سنة. أبوه زيد بن عمرو بن نفيل — من أحناف الجاهلية الذين رفضوا الشرك واعتنقوا الحنيفية، بحثًا عن دين إبراهيم عليه السلام.',
      'تربى سعيد في بيت موحّد. أبوه زيد رفض عبادة الأصنام، ورفض الذبائح التي تُذبح لها، ورفض وأد البنات. كان يقول: لا أعبد إلا الإله الذي خلق هذه الأشجار وأنبت لها هذا العشب. مات زيد قبل البعثة، فلما بُعث النبي ﷺ، شهد له بالخير وقال: يبعث أمة وحده يوم القيامة.',
      'أسلم سعيد في أوائل البعثة، من السابقين الأولين. كان من العشرة الأوائل الذين أسلموا قبل دخول النبي ﷺ دار الأرقم. وتزوج فاطمة بنت الخطاب — أخت عمر بن الخطاب — وأسلمت معه. كانا من أوائل من جهر بالإسلام في مكة، رغم خطورة ذلك.',
      'الحادثة التي غيّرت مجرى تاريخ الإسلام هي حادثة إسلام عمر، وكانت في بيت سعيد وفاطمة. عمر خرج يومًا متقلّدًا سيفه يريد قتل النبي ﷺ. لقيه رجل من بني زهرة فقال له: يا عمر، لا تكفك أمر بيتك حتى تذهب إلى محمد؟ قال: ما الذي في بيتي؟ قال: أختك وزوجها قد أسلما. غضب عمر غضبًا شديدًا، ورجع إلى بيت أخته فاطمة.',
      'كان عند فاطمة وسعيد قارئ يقرأ عليهما من سورة طه — قبل أن يحفظا الكثير من القرآن. سمع عمر القراءة من خارج الباب، فدخل غاضبًا. ضرب سعيدًا، ثم ضرب أخته فاطمة ضربًا شديدًا حتى سال الدم من وجهها. فقالت: نعم، أسلمنا، فاصنع ما شئت. ولانت قلب عمر منظر الدم في وجه أخته.',
      'قال لها: أرنيني الصحيفة. قالت: لا، أنت رجس، ولا يمس القرآن إلا طاهر. قم فاغتسل. فقام عمر فاغتسل، ثم أعطته الصحيفة. قرأ عمر سورة طه، فقال: ما أحسن هذا الكلام وأكرمه! فذهب من البيت إلى النبي ﷺ في دار الأرقم وأعلن إسلامه. كل هذا حدث في بيت سعيد وفاطمة.',
      'هاجر سعيد إلى المدينة. لم يشهد بدرًا لأنه كان في مهمة في الشام بأمر النبي ﷺ مع طلحة بن عبيد الله. لكن النبي ﷺ ضرب لهما بسهم من غنائم بدر وأجر، فكأنهما شهداها. ثم شارك في أحد والخندق وسائر الغزوات.',
      'كان من الستة الذين عيّنهم عمر بن الخطاب للشورى لاختيار الخليفة بعده. شهد فتوح الشام. وقاد بنفسه فتح دمشق في عهد عمر. ولاه عمر دمشق بعد فتحها، فحكمها مدة، ثم استعفى وعاد إلى المدينة. كان يرفض الولاية ويفضّل الخدمة بدل القيادة.',
      'كان زاهدًا في الدنيا. اعتزل الفتن كلها بعد قتل عثمان. لم يشارك في معركة الجمل ولا صفين. كان يحب العزلة، ويقول: ما تركتُ شيئًا من أمر الدنيا إلا وكان خيرًا لي. وكان كثير الصلاة والصيام، يقوم الليل ويختم القرآن في الأسبوع.',
      'قصة مشهورة عن دعوته المستجابة: ادّعت امرأة من العقيق اسمها أروى بنت أويس أن سعيدًا أخذ شيئًا من أرضها. شكته إلى مروان بن الحكم — والي المدينة. سمع سعيد بالشكوى، فقال: يا أروى، إن كنت تكذبين عليّ فعمى الله بصرك، واجعل قبرك في الأرض التي ادّعيت. ثم تركها. ما هي إلا أيام حتى عميت أروى، ووقعت في بئر في الأرض نفسها التي ادّعت ملكيتها، فماتت غرقًا. كانت دعوة مستجابة فورًا.',
      'تتوفي سعيد بن زيد في العقيق سنة 51 هـ، عن عمر يناهز سبعين سنة. جاء أبو هريرة وعبد الله بن عمر وبكوا عليه. حُمل من العقيق إلى المدينة لدفنه في البقيع. صلى عليه عبد الله بن عمر، ودفن بالبقيع.',
      'سعيد بن زيد كان من القلائل الذين شهد لهم النبي ﷺ بالجنة في حديث: عشرة في الجنة: أبو بكر، عمر، عثمان، علي، طلحة، الزبير، سعد، سعيد، عبد الرحمن بن عوف، أبو عبيدة. كان متواضعًا، إذا سمع من يثني عليه، قال: ما رأيت رسول الله ﷺ يلعن ولا يطعن. يحاول أن يصرف الناس عن مدحه.',
      'كان آخر السبعة الأوائل في الإسلام وفاة. الذين سبقوا الناس إلى الإيمان لم يبقَ منهم في وقت موته إلا قليل. كأن جيلًا كاملًا من جيل الصحابة الأوائل قد ذهب، وسعيد كان آخر شاهد على ذلك العصر.',
      'يبقى سعيد بن زيد في تاريخ الإسلام نموذجًا للصحابي المتواضع، الذي لم يطلب جاهًا ولم يتنافس على رياسة، وإنما اكتفى بنصرة الدين والقعود عن الفتن. وبيته كان شاهدًا على إسلام عمر، أعظم لحظة في تاريخ الدعوة المكية. اللهم ارضَ عن سعيد، وتقبّل دعاءه المستجاب، وارفع درجته في الجنة.',
    ]),
    en: P([
      'He is Sa\'id ibn Zayd ibn Amr ibn Nufayl, al-Qurashi al-Adawi. The cousin of Umar ibn al-Khattab, may Allah be pleased with him, and the husband of Umar\'s sister — Fatimah bint al-Khattab. He was born in Makkah about twenty-two years before the mission. His father Zayd ibn Amr ibn Nufayl was one of the Hanifs of the Jahiliyyah who rejected polytheism and embraced the Hanifiyyah, seeking the religion of Ibrahim.',
      'Sa\'id was raised in a monotheist household. His father Zayd rejected the worship of idols, rejected sacrifices offered to them, and rejected the burial of infant girls. He used to say: "I worship none but the God who created these trees and brought forth this grass for them." Zayd died before the mission. When the Prophet ﷺ was sent, he bore him witness with good and said: "He will be raised as a single nation on the Day of Resurrection."',
      'Sa\'id embraced Islam in the early mission, among the very first. He was among the first ten who embraced Islam before the Prophet ﷺ entered the house of al-Arqam. He married Fatimah bint al-Khattab — Umar ibn al-Khattab\'s sister — and she embraced Islam with him. They were among the first to declare Islam openly in Makkah, despite the danger.',
      'The incident that changed the course of Islamic history is the incident of Umar\'s Islam, which took place in the house of Sa\'id and Fatimah. Umar went out one day with his sword on, wanting to kill the Prophet ﷺ. A man of Banu Zuhrah met him and said: "O Umar, does the matter of your own house not concern you that you go to Muhammad?" He said: "What is in my house?" He said: "Your sister and her husband have embraced Islam." Umar grew severely angry and returned to his sister Fatimah\'s house.',
      'A reader was reciting to Fatimah and Sa\'id from Surah Ta-Ha — before they had memorised much of the Qur\'an. Umar heard the recitation from outside the door and entered in fury. He struck Sa\'id, then struck his sister Fatimah severely until blood flowed from her face. She said: "Yes, we have embraced Islam; do what you will." The sight of blood on his sister\'s face softened Umar\'s heart.',
      'He said to her: "Show me the sheet." She said: "No, you are impure; only the pure may touch the Qur\'an. Get up and perform ghusl." Umar got up and performed ghusl, then she gave him the sheet. Umar read Surah Ta-Ha and said: "How fine and noble this speech is!" He went from the house to the Prophet ﷺ in the house of al-Arqam and announced his Islam. All this took place in the house of Sa\'id and Fatimah.',
      'Sa\'id emigrated to Madinah. He did not witness Badr because he was on a mission to Sham by the Prophet\'s ﷺ order with Talhah ibn Ubaydillah. But the Prophet ﷺ allotted them a share of Badr\'s spoils and counted their reward, so it was as if they had witnessed it. He then participated in Uhud, the Trench, and the rest of the battles.',
      'He was among the six Umar ibn al-Khattab appointed for the council to choose the caliph after him. He witnessed the conquests of Sham. He personally led the conquest of Damascus during Umar\'s reign. Umar appointed him over Damascus after its conquest, and he ruled there for a time, then requested to be relieved and returned to Madinah. He refused governorship and preferred service over leadership.',
      'He was an ascetic in this world. He withdrew from all trials after the killing of Uthman. He did not participate in the Battle of the Camel or Siffin. He loved seclusion and would say: "I have not left anything of worldly matter except it was better for me." He prayed and fasted much, stood the night and would complete the Qur\'an in a week.',
      'A famous story of his answered supplication: a woman from al-Aqiq named Arwa bint Uways claimed that Sa\'id had taken something from her land. She complained against him to Marwan ibn al-Hakam — the governor of Madinah. Sa\'id heard of the complaint and said: "O Arwa, if you are lying about me, may Allah blind your sight and make your grave in the very land you claimed." Then he left her. Only days passed before Arwa became blind, fell into a well in the very land she had claimed ownership of, and died by drowning. It was an immediately answered supplication.',
      'Sa\'id ibn Zayd died at al-Aqiq in 51 AH, at about seventy years of age. Abu Hurayrah and Abdullah ibn Umar came and wept for him. He was carried from al-Aqiq to Madinah for burial in al-Baqi\'. Abdullah ibn Umar prayed over him, and he was buried in al-Baqi\'.',
      'Sa\'id ibn Zayd was among the few to whom the Prophet ﷺ testified Paradise in the hadith: "Ten are in Paradise: Abu Bakr, Umar, Uthman, Ali, Talhah, al-Zubayr, Sa\'d, Sa\'id, Abd al-Rahman ibn Awf, and Abu Ubaydah." He was humble; when he heard someone praise him, he would say: "I never saw the Messenger of Allah ﷺ cursing or denouncing." He tried to turn people away from praising him.',
      'He was the last of the first seven in Islam to die. Those who preceded the people to faith — only a few of them remained at the time of his death. As if an entire generation of the first Companions had passed, and Sa\'id was the last witness of that era.',
      'Sa\'id ibn Zayd remains in the history of Islam a model of the humble Companion, who did not seek status or compete for leadership, but contented himself with supporting the religion and abstaining from trials. His house witnessed the Islam of Umar, the greatest moment in the history of the Makkan call. O Allah, be pleased with Sa\'id, accept his answered supplication, and raise his rank in Paradise.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 9. عبد الرحمن بن عوف رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'abdulrahman': {
    ar: P([
      'هو عبد الرحمن بن عوف بن عبد عوف بن عبد بن الحارث بن زهرة، القرشي الزهري. وُلد بمكة قبل البعثة بنحو عشر سنين. أمه الشفاء بنت عوف من بني زهرة. كان من سادات قريش، ذا تجارة واسعة قبل الإسلام. اسمه في الجاهلية عبد عمرو، فلما أسلم سماه النبي ﷺ عبد الرحمن.',
      'أسلم على يد أبي بكر الصديق في الأيام الأولى للبعثة. كان ثامن الذين أسلموا، فهو من السابقين الأولين. لم يلق من قريش الأذى الشديد الذي لاقاه غيره من المستضعفين، لأنه كان من سادتها، لكنه فضّل الهجرة على البقاء، ليكون مع النبي ﷺ.',
      'هاجر الهجرتين: إلى الحبشة، ثم إلى المدينة. في الحبشة، لقي النجاشي بنفسه، وكان من أبرز المسلمين الذين دافعوا عن الإسلام أمام النجاشي حين أرادت قريش رد المسلمين. ثم رجع إلى المدينة بعد سنوات.',
      'في المدينة، آخى النبي ﷺ بينه وبين سعد بن الربيع الأنصاري. عرض عليه سعد نصف ماله وأن يطلّق إحدى زوجتيه ليتزوجها عبد الرحمن. كان عرضًا كريمًا من أنصاري لمهاجر فقير. لكن عبد الرحمن رفض. قال: بارك الله لك في مالك وأهلك، دلّني على السوق. فدلّه على سوق قينقاع.',
      'بدأ عبد الرحمن من الصفر في المدينة. ذهب إلى السوق، اشترى وباع، ربح. ثم زاد رأس ماله. في وقت قصير صار من أغنى الناس في المدينة. كان يقول: لقد رأيتني وما ألقي حجرًا إلا أصبت تحته ذهبًا أو فضة. أي بارك الله في تجارته بركة عجيبة، حتى صار كل ما يعمل فيه يربح.',
      'شارك في كل غزوات النبي ﷺ. في غزوة بدر قاتل ببسالة. في أحد، كان من الذين ثبتوا وأصيب بأكثر من عشرين جراحة، وكُسرت أسنانه. في غزوة دومة الجندل، أمّره النبي ﷺ على سرية، وعمّمه بيده الشريفة، وقال: امضِ باسم الله وفي سبيل الله. تزوج بعد هذه السرية من تماضر بنت الأصبغ، ابنة ملك دومة الجندل، فدخل بها في الإسلام.',
      'في غزوة تبوك، حدثت قصة فريدة. كان النبي ﷺ يصلي الصبح، وتأخر قليلًا في الخروج. فصلى الناس وعبد الرحمن إمامهم. ركع وسجد ركعة، ثم جاء النبي ﷺ ودخل في الصف خلف عبد الرحمن. حاول عبد الرحمن أن يتنحى ليقدّم النبي ﷺ، لكن النبي ﷺ أشار إليه أن يكمل. صلى النبي ﷺ بإمامة عبد الرحمن. هذا شرف لم يحظ به أحد قبله ولا بعده — أن يأتمّ النبي ﷺ بأحد من أمته.',
      'كان من أغنى الصحابة. لكن غناه لم يفسده. كان ينفق في سبيل الله بسخاء. روي أنه باع أرضًا له بأربعين ألف دينار، وتصدّق بها كلها على فقراء المهاجرين وأمهات المؤمنين. وأرسل في غزوة تبوك سبعمئة بعير محمّلة بالبرّ والشعير لجيش المسلمين. وأعتق ثلاثين ألف عبد طوال حياته.',
      'لما كان عمر بن الخطاب على فراش الموت بعد أن طُعن، عيّن ستة من الصحابة للشورى. كان عبد الرحمن منهم. ولأن عبد الرحمن كان أقدمهم وأكبرهم سنًا، كلّفه عمر بإدارة الشورى. تنازل عبد الرحمن عن حقه في الترشّح، وأخذ يستشير الناس من حوله: من تختارون من الخمسة الباقين؟ في ثلاثة أيام، استشار رجال المدينة ونساءها وأطفالها وعبيدها. ثم بايع لعثمان. كانت أول انتخابات شعبية حقيقية في تاريخ الإسلام.',
      'كان زاهدًا في الدنيا رغم غناه. قال: لقد رأيتنا مع رسول الله ﷺ وما لنا طعام نأكله إلا الأسود — أي التمر — فأصبنا الدنيا فقد خشيت أن تكون حسناتنا قد عُجِّلت لنا. كان يبكي من الخوف أن يكون كثرة ماله عقوبة لا نعمة. ولما يأكل أحيانًا الطعام الطيب، يبكي ويتذكر فقر الصحابة الأوائل.',
      'بشّره النبي ﷺ بالجنة. قال له: عبد الرحمن من العشرة في الجنة، يدخلها حبوًا. ولما سُئل لماذا يدخلها حبوًا (أي بطيئًا)؟ قيل: من ثقل الحساب على المال الكثير. هذا تنبيه أن المال نعمة ومسؤولية، يحاسب صاحبه على كل دينار من أين اكتسبه وفيم أنفقه. عبد الرحمن سيدخل الجنة، لكنه سيؤخّر للحساب الطويل على ماله.',
      'لما وقعت فتنة قتل عثمان، اعتزل عبد الرحمن. لم يشارك في الجمل ولا صفين. توفي قبل الفتنة الكبرى. مرض في المدينة سنة 31 هـ، ومات وعمره خمس وسبعون سنة. كان قد طلب أن يدفن بقرب قبر النبي ﷺ، لكن عثمان أبى ذلك واحترم وصية أم المؤمنين عائشة. دفن في البقيع.',
      'وصى رضي الله عنه بمال كثير. خلّف ألف بعير، ومئة فرس، وعشرة آلاف شاة، وفي بيته أربع أزواج. أوصى لكل من بقي من أهل بدر بأربعمئة دينار، فأخذ كل واحد منهم. واشتُري بمالها بستان وقف على المسلمين. تصدّق بثلث ماله في وصيته.',
      'يبقى عبد الرحمن بن عوف في تاريخ الإسلام نموذج التاجر الزاهد المنفق. أغنى الصحابة، وأكثرهم تواضعًا، وأكثرهم إنفاقًا. ابتدأ في المدينة من الصفر، فجعله الله مليارديرًا في عصره. ومع ذلك ظل خائفًا من الله، باكيًا من خشيته. اللهم ارضَ عن عبد الرحمن، وارزقنا الإيمان والزهد كما رزقته.',
    ]),
    en: P([
      'He is Abd al-Rahman ibn Awf ibn Abd Awf ibn Abd ibn al-Harith ibn Zuhrah, al-Qurashi al-Zuhri. He was born in Makkah about ten years before the mission. His mother al-Shifa\' bint Awf was from Banu Zuhrah. He was among the nobles of Quraysh, with vast trade before Islam. His name in the Jahiliyyah was Abd Amr; when he embraced Islam the Prophet ﷺ named him Abd al-Rahman.',
      'He embraced Islam at the hand of Abu Bakr al-Siddiq in the early days of the mission. He was the eighth to embrace Islam, among the very first. He did not suffer the severe harm of others from Quraysh\'s weak ones because he was of its nobles, but he preferred emigration over staying, to be with the Prophet ﷺ.',
      'He made the two emigrations: to Abyssinia, then to Madinah. In Abyssinia he met the Negus himself, and was among the prominent Muslims who defended Islam before the Negus when Quraysh sought to return the Muslims. He then returned to Madinah years later.',
      'In Madinah, the Prophet ﷺ joined him in brotherhood with Sa\'d ibn al-Rabi\' al-Ansari. Sa\'d offered him half of his wealth and to divorce one of his two wives so Abd al-Rahman could marry her. It was a generous offer from an Ansari to a poor Muhajir. But Abd al-Rahman refused. He said: "May Allah bless you in your wealth and family; direct me to the market." Sa\'d directed him to the market of Qaynuqa\'.',
      'Abd al-Rahman started from zero in Madinah. He went to the market, bought and sold, profited. Then increased his capital. In a short time he became among the wealthiest in Madinah. He used to say: "I have seen myself, and I would not throw a stone but I would find under it gold or silver." Allah blessed his trade with a marvellous blessing, until everything he worked on profited.',
      'He took part in every campaign of the Prophet ﷺ. At Badr he fought valiantly. At Uhud he was among those who stood firm and was wounded with more than twenty wounds; his teeth were broken. At the campaign of Dumat al-Jandal, the Prophet ﷺ appointed him over a raiding party, wrapped his turban with his noble hand, and said: "Go in the name of Allah and in the cause of Allah." After this raid he married Tumadir bint al-Asbagh, daughter of the king of Dumat al-Jandal, entering her into Islam.',
      'In the Tabuk campaign a unique story occurred. The Prophet ﷺ was praying Fajr and was a little late coming out. The people prayed, and Abd al-Rahman was their imam. He bowed and prostrated one rak\'ah, and then the Prophet ﷺ came and entered the row behind Abd al-Rahman. Abd al-Rahman tried to step aside to allow the Prophet ﷺ to lead, but the Prophet ﷺ gestured for him to complete. The Prophet ﷺ prayed under Abd al-Rahman\'s imamate. An honour no one before or after has received — that the Prophet ﷺ should follow one of his Ummah in prayer.',
      'He was among the wealthiest Companions. But his wealth did not corrupt him. He spent in Allah\'s cause generously. It is narrated that he sold a piece of land for forty thousand dinars and gave it all in charity to the poor Muhajirun and the Mothers of the Believers. In the Tabuk campaign he sent seven hundred camels loaded with wheat and barley for the Muslim army. He freed thirty thousand slaves throughout his life.',
      'When Umar ibn al-Khattab was on his deathbed after being stabbed, he appointed six Companions for the council. Abd al-Rahman was among them. Because Abd al-Rahman was the oldest and most senior of them, Umar charged him with managing the council. Abd al-Rahman renounced his right to be a candidate and began consulting the people around him: "Whom do you choose of the five remaining?" Over three days he consulted the men, women, children, and slaves of Madinah. Then he pledged allegiance to Uthman. It was the first true popular election in the history of Islam.',
      'He was an ascetic in this world despite his wealth. He said: "I have seen us with the Messenger of Allah ﷺ when we had no food to eat but the black — meaning dates — and we have attained worldly things, so I fear our good deeds may have been hastened for us." He wept from fear that his abundant wealth might be a punishment rather than a blessing. When he sometimes ate good food, he wept and remembered the poverty of the early Companions.',
      'The Prophet ﷺ gave him glad tidings of Paradise. He said about him: "Abd al-Rahman is of the ten in Paradise; he enters it crawling." When asked why he enters crawling (i.e. slowly), it was said: from the weight of the reckoning over abundant wealth. This is a warning that wealth is a blessing and a responsibility; its owner is held to account for every dinar — where he earned it and what he spent it on. Abd al-Rahman will enter Paradise, but he will be delayed for the long reckoning over his wealth.',
      'When the trial of Uthman\'s killing occurred, Abd al-Rahman had already withdrawn. He did not participate in the Camel or Siffin. He died before the great trial. He fell ill in Madinah in 31 AH and died at seventy-five years of age. He had asked to be buried near the grave of the Prophet ﷺ, but Uthman refused that and respected the wish of A\'isha, Mother of the Believers. He was buried in al-Baqi\'.',
      'He bequeathed great wealth. He left a thousand camels, a hundred horses, ten thousand sheep, and four wives in his house. He bequeathed to every remaining man of Badr four hundred dinars, and each one took it. With its proceeds an orchard was bought and made a charitable endowment for the Muslims. He gave a third of his wealth in charity in his will.',
      'Abd al-Rahman ibn Awf remains in the history of Islam the model of the ascetic, spending merchant. The wealthiest of the Companions, the most humble, and the most spending. He started in Madinah from zero, and Allah made him a billionaire in his era. With all that, he remained fearful of Allah, weeping from awe of Him. O Allah, be pleased with Abd al-Rahman, and grant us faith and asceticism as You granted him.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 10. أبو عبيدة بن الجراح رضي الله عنه — أمين هذه الأمة
  // ──────────────────────────────────────────────────────────────────────
  'abu-ubayda': {
    ar: P([
      'هو عامر بن عبد الله بن الجراح بن هلال بن أهيب، القرشي الفهري. عرف بكنيته أبو عبيدة ولُقب بـ أمين هذه الأمة. وُلد بمكة قبل البعثة بنحو إحدى وأربعين سنة. كان من قبيلة فهر، من قبائل قريش المعروفة بالشجاعة والكرم.',
      'أسلم على يد أبي بكر الصديق في الأيام الأولى للبعثة، فهو من السابقين الأولين. ثامن أو تاسع من أسلم. لقي أذى شديدًا من قريش بعد إسلامه، لكنه ثبت. وكان ممن هاجر إلى الحبشة الهجرة الأولى مع جماعة من المسلمين فرارًا من الأذى.',
      'لما هاجر إلى المدينة، آخى النبي ﷺ بينه وبين سعد بن معاذ سيد الأنصار، أو محمد بن مسلمة في رواية أخرى. كان يحمل من قبل أبا عبيدة في الحالات الصعبة. شارك في كل غزوات النبي ﷺ ابتداءً من بدر.',
      'في غزوة بدر، حدثت قصة عجيبة. كان أبو عبيدة في صف المسلمين، وأبوه عبد الله بن الجراح في صف المشركين. التقيا في المعركة، فحاول أبو عبيدة أن يتجنّب أباه. لكن أبا أبي عبيدة بدأ يطلبه ويحاول قتله. لم يجد أبو عبيدة بدًا من قتاله، فقتله. أنزل الله في هذه الحادثة آية: لا تجد قومًا يؤمنون بالله واليوم الآخر يوادّون من حادّ الله ورسوله ولو كانوا آباءهم.',
      'في غزوة أحد، حدثت أصعب لحظات حياة أبي عبيدة. كان النبي ﷺ قد أصيب في وجهه الشريف، ودخلت حلقتان من حلقات المغفر — البيضة — في خده. كانت الحلقتان متعمّقتين، لا يقدر أحد على إخراجهما من غير أذى. تقدم أبو عبيدة، أمسك بحلقة المغفر بأسنانه، وشدّ بقوة حتى خرجت الحلقة. لكن سقطت ثنيّتاه — أسنان أمامه — بسبب القوة. ثم أمسك الحلقة الثانية بأسنانه أيضًا، فشدّ حتى خرجت، فسقطت سنّ أخرى. ضحى بثلاثة أسنان ليخفف من ألم النبي ﷺ. صار من الناس يقولون: ما رأينا هتمًا قط أحسن من هتم أبي عبيدة.',
      'قال النبي ﷺ في حقّه: لكل أمة أمين، وأمين هذه الأمة أبو عبيدة بن الجراح. هذا اللقب الخاص لم يطلق على غيره. الأمانة فضيلة عظيمة، وأن يكون الإنسان أمين أمة كاملة شرف لا يدانيه شرف.',
      'وفي حديث آخر: أبو بكر في الجنة، وعمر في الجنة، وأبو عبيدة بن الجراح في الجنة. عدّه النبي ﷺ من العشرة المبشرين بالجنة وذكره بشكل خاص في غير ما حديث.',
      'لما حضرت أبا بكر الوفاة، استشار من حوله: من يخلفني؟ اقترح بعض الصحابة عمر، وآخرون أبا عبيدة. كاد أبو بكر يختار أبا عبيدة لولا أن أبا عبيدة نفسه قال: يا أبا بكر، ما أحب أن أتقدّم على رجل قال له النبي ﷺ: مرّ أبا بكر يصلّي بالناس. كان زاهدًا في القيادة كما كان زاهدًا في الدنيا.',
      'في عهد عمر بن الخطاب، تولّى أبو عبيدة قيادة الجيش الإسلامي في فتح الشام. كان من أعظم القادة العسكريين في تاريخ الإسلام. فتح دمشق وحمص وحلب وحماة وقنسرين وجبلة، وقاتل في معركة اليرموك التي حُسم بها مصير الشام.',
      'في فتح دمشق، حدثت قصة عجيبة. كان خالد بن الوليد يحاصر باب شرق دمشق وأبو عبيدة يحاصر باب الجابية. الباب الذي دخل منه خالد كان عن طريق القتال. الباب الذي دخل منه أبو عبيدة كان عن طريق الصلح والأمان. لما دخل الجيشان وتقابلا في وسط دمشق، أمضى أبو عبيدة الصلح حتى على الناحية التي فتحها خالد بالقوة، رحمة بأهل دمشق.',
      'في طاعون عمواس سنة 18 هـ، انتشر الطاعون في جيش الشام وأهله. مات منه نحو خمسة وعشرين ألف. كان أبو عبيدة أمير الشام يومئذ. كتب إليه عمر أن يخرج من المنطقة الموبوءة. اعتذر أبو عبيدة وقال: لقد عرفت حاجتك إلي، ولكنا في جند من أجناد المسلمين، فما كنت لأرغب بنفسي عنهم.',
      'مات أبو عبيدة في الطاعون نفسه في قرية اسمها فحل قرب الأردن، سنة 18 هـ، عن عمر ثمان وخمسين سنة. كان قبل موته يعزّي الناس ويذكّرهم بالله. لما حضرته الوفاة، التفت إلى أصحابه وقال: إني موصيكم بوصية إن قبلتموها لم تزالوا بخير: أقيموا الصلاة، وآتوا الزكاة، وصوموا رمضان، وتصدّقوا، وحجّوا، واعتمروا، وتواصوا، وانصحوا لأمرائكم، ولا تغشوهم.',
      'صلّى عليه معاذ بن جبل ودفنه. كان معاذ بن جبل بعده على إمارة الشام، ثم مات في الطاعون نفسه. كأن الله جمع الصحابة الأبرار في طاعون واحد ورفعهم إلى جنّاته. أبو عبيدة دُفن في فحل، ولا يزال قبره معروفًا إلى اليوم.',
      'يبقى أبو عبيدة بن الجراح في تاريخ الإسلام أمين هذه الأمة، فاتح الشام، الزاهد في القيادة، المضحّي بأسنانه لأجل النبي ﷺ، الميت بطاعون في صفّ جنوده ولم يتركهم. مثال على القائد الذي لا يفصل نفسه عن جنده، والأمين الذي لا يكذب، والصحابي الذي عاش لخدمة الإسلام لا لذاته. اللهم ارضَ عن أبي عبيدة، واجعلنا من ورثة الأمانة كما كان أمين هذه الأمة.',
    ]),
    en: P([
      'He is Amir ibn Abdullah ibn al-Jarrah ibn Hilal ibn Uhayb, al-Qurashi al-Fihri. Known by his kunya Abu Ubaydah and nicknamed "the Trustee of this Ummah." He was born in Makkah about forty-one years before the mission. He was of the tribe of Fihr, one of the Qurashi tribes known for courage and generosity.',
      'He embraced Islam at the hand of Abu Bakr al-Siddiq in the early days of the mission, among the very first. The eighth or ninth to embrace Islam. He suffered severe harm from Quraysh after his Islam, but he stood firm. He was among those who emigrated to Abyssinia in the first emigration with a group of Muslims fleeing harm.',
      'When he emigrated to Madinah, the Prophet ﷺ joined him in brotherhood with Sa\'d ibn Mu\'adh, chief of the Ansar, or Muhammad ibn Maslamah in another narration. He used to volunteer in difficult situations. He participated in every campaign of the Prophet ﷺ starting from Badr.',
      'At the Battle of Badr a striking story occurred. Abu Ubaydah was in the Muslim ranks, and his father Abdullah ibn al-Jarrah in the polytheist ranks. They met in the battle, and Abu Ubaydah tried to avoid his father. But Abu Ubaydah\'s father began to seek him out, trying to kill him. Abu Ubaydah had no choice but to fight him, and he killed him. Allah revealed in this incident the verse: "You will not find a people who believe in Allah and the Last Day having affection for those who oppose Allah and His Messenger, even if they are their fathers."',
      'At the Battle of Uhud, the hardest moments of Abu Ubaydah\'s life occurred. The Prophet ﷺ had been struck in his noble face, and two links of the helmet had entered his cheek. The links were deeply embedded; no one could remove them without harm. Abu Ubaydah came forward, grasped the helmet link with his teeth, and pulled hard until the link came out. But his two front teeth fell out from the force. He then grasped the second link with his teeth as well, pulled until it came out, and another tooth fell out. He sacrificed three teeth to lighten the Prophet\'s ﷺ pain. People came to say: "We have never seen a gap-toothed man more handsome than the gap of Abu Ubaydah."',
      'The Prophet ﷺ said about him: "Every Ummah has a trustee, and the trustee of this Ummah is Abu Ubaydah ibn al-Jarrah." This special title was not given to anyone else. Trustworthiness is a great virtue, and to be the trustee of an entire Ummah is an honour no honour matches.',
      'In another hadith: "Abu Bakr is in Paradise, Umar is in Paradise, and Abu Ubaydah ibn al-Jarrah is in Paradise." The Prophet ﷺ counted him among the ten promised Paradise and mentioned him specifically in more than one hadith.',
      'When death approached Abu Bakr, he consulted those around him: who will succeed me? Some Companions suggested Umar, others Abu Ubaydah. Abu Bakr almost chose Abu Ubaydah had Abu Ubaydah not himself said: "O Abu Bakr, I do not love to be advanced over a man to whom the Prophet ﷺ said: ‘Tell Abu Bakr to lead the people in prayer.’" He was ascetic in leadership as he was ascetic in this world.',
      'During the reign of Umar ibn al-Khattab, Abu Ubaydah took command of the Muslim army in the conquest of Sham. He was among the greatest military commanders in Islamic history. He conquered Damascus, Homs, Aleppo, Hama, Qinnasrin, and Jabalah, and fought in the Battle of Yarmuk that decided the fate of Sham.',
      'In the conquest of Damascus a strange story occurred. Khalid ibn al-Walid was besieging the Eastern Gate and Abu Ubaydah was besieging the Jabiyah Gate. The gate Khalid entered by was through fighting. The gate Abu Ubaydah entered by was through treaty and safety. When the two armies entered and met in the centre of Damascus, Abu Ubaydah enforced the treaty even on the side Khalid had conquered by force, out of mercy for the people of Damascus.',
      'In the plague of Amwas in 18 AH, the plague spread in the army of Sham and its people. About twenty-five thousand died from it. Abu Ubaydah was the commander of Sham at the time. Umar wrote to him to leave the affected area. Abu Ubaydah apologised and said: "I know your need for me, but we are in an army of the Muslim armies; I would not wish for myself away from them."',
      'Abu Ubaydah died in the plague itself in a village called Fahl near Jordan, in 18 AH, at fifty-eight years of age. Before his death he consoled the people and reminded them of Allah. When death approached him, he turned to his companions and said: "I have a counsel for you which, if you accept, you will not cease to be in good: establish prayer, give zakat, fast Ramadan, give charity, perform Hajj and Umrah, give mutual counsel, advise your rulers, and do not deceive them."',
      'Mu\'adh ibn Jabal prayed over him and buried him. Mu\'adh ibn Jabal succeeded him in the governorship of Sham, then died in the same plague. As if Allah gathered the righteous Companions in a single plague and raised them to His gardens. Abu Ubaydah was buried in Fahl, and his grave is still known to this day.',
      'Abu Ubaydah ibn al-Jarrah remains in the history of Islam the Trustee of this Ummah, conqueror of Sham, ascetic in leadership, sacrificer of his teeth for the Prophet ﷺ, dying of plague in the ranks of his soldiers without leaving them. A model of the commander who does not separate himself from his soldiers, the trustee who does not lie, and the Companion who lived to serve Islam not himself. O Allah, be pleased with Abu Ubaydah, and make us inheritors of trust as he was the Trustee of this Ummah.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 11. بلال بن رباح رضي الله عنه — مؤذن الإسلام
  // ──────────────────────────────────────────────────────────────────────
  'bilal': {
    ar: P([
      'هو بلال بن رباح الحبشي، عبد لأمية بن خلف الجمحي. وُلد في الحبشة قبل البعثة بنحو ثلاثين سنة، ثم جيء به إلى مكة عبدًا. أمه حمامة كانت أمَة في بيت سيدها. نشأ في مكة بين عبيد قريش، يخدم سيده أمية بن خلف — أحد أعتى المشركين وأكثرهم عداوة للإسلام.',
      'أسلم في أوائل البعثة. لم تذكر الروايات بالضبط كيف أسلم، لكن المرجح أنه سمع عن النبي ﷺ من أبي بكر أو من غيره، فآمن في قلبه قبل أن يعلن. لما علم أمية أن عبده أسلم، استشاط غضبًا. كيف يجرؤ عبد على ترك دين سيده؟',
      'بدأ أمية يعذّبه بأشد أنواع التعذيب. كان يخرجه في حرّ الظهيرة إلى الرمضاء — الأرض الحارة — يلقيه على ظهره، ثم يضع على صدره صخرة عظيمة. يقول له: لا تزال هكذا حتى تموت أو تكفر بمحمد وتعبد اللات والعزى. كان بلال يردّ كلمة واحدة فقط: أحد، أحد. أي الله أحد. يكرّرها ولا يقول غيرها.',
      'كان بعض الناس يقولون: أعلِنها كلمة الكفر بلسانك فقط، وقلبك مطمئنّ بالإيمان، حتى تخلص من العذاب. لكن بلال أبى أن يقول كلمة الكفر حتى بلسانه. وكان يقول: والله، لو علمت كلمة هي أغيظ لهم منها لقلتها. هذا الصبر الخارق على التعذيب جعله من أعظم رموز ثبات الإيمان.',
      'سمع أبو بكر الصديق بحال بلال، فأشفق عليه. ذهب إلى أمية بن خلف وقال له: بكم تبيعه؟ قال أمية ساخرًا: بأوقية. قال أبو بكر: لو زدت ما زاد، اشتريته. اشتراه بسبع أواق من الفضة، ثم أعتقه فورًا لوجه الله. صار بلال حرًا. وأنزل الله في حقّ أبي بكر آية: وسيُجنبها الأتقى، الذي يؤتي ماله يتزكى.',
      'هاجر إلى المدينة مع النبي ﷺ. في المدينة، اختاره النبي ﷺ ليكون أول مؤذن في الإسلام. كان النبي قد رأى في منام عبد الله بن زيد كيفية الأذان. لما أراد النبي ﷺ من يؤذّن، قال عبد الله: يا رسول الله، الذي رأى الرؤيا أنا، فأمر بلالًا فلينادِ بها، فإنه أندى صوتًا منك. أعجب النبي ﷺ، فعلّم بلالًا الأذان، وكان أول من رفعه على ظهر الكعبة بعد الفتح.',
      'صار بلال مؤذّن النبي ﷺ، يؤذن لكل صلاة. كان النبي ﷺ يحب صوته جدًا. وكان من تواضع النبي وحبه لبلال أنه قال له يومًا: يا بلال، حدّثني بأرجى عمل عملته في الإسلام، فإني سمعت دفّ نعليك بين يديّ في الجنة. قال بلال: ما أعرف عملًا، إلا أنّي لم أتطهّر طهورًا في ساعة من ليل أو نهار، إلا صلّيت بذلك الطهور ما كتب لي أن أصلّي. كان بلال يصلي ركعتين بعد كل وضوء — هذا ما أدخله الجنة.',
      'لما فتح النبي ﷺ مكة، دخلها مع بلال. أمر بلالًا أن يصعد على ظهر الكعبة ويؤذّن. ارتفع صوت بلال — العبد الحبشي الذي عُذّب فيها — يقول: الله أكبر، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله. سمعه قريش، فقال بعضهم متحسرًا: لقد كرّم الله أبا سفيان حين قبضه قبل هذا اليوم. وقال غيره: انظروا هذا العبد الأسود يصعد على ظهر الكعبة! نزلت آية: يا أيها الناس إنا خلقناكم من ذكر وأنثى وجعلناكم شعوبًا وقبائل لتعارفوا، إن أكرمكم عند الله أتقاكم.',
      'لما مات النبي ﷺ، حزن بلال حزنًا شديدًا. أراد أن يؤذّن أول مرة بعد موت النبي، فلما بلغ: أشهد أن محمدًا رسول الله، اختنق صوته بالبكاء. سقط على الأرض من فرط الحزن، ولم يستطع إكمال الأذان. بكى الصحابة كلهم. ثم قال: لا أؤذّن لأحد بعد رسول الله ﷺ. وترك التأذين.',
      'استأذن أبا بكر الصديق أن يخرج إلى الشام للجهاد. أراد أن يبتعد عن المدينة لأن كل ركن فيها يذكّره بالنبي ﷺ ويزيد حزنه. سمح له أبو بكر. خرج بلال إلى الشام، وشارك في الفتوحات هناك تحت قيادة أبي عبيدة وخالد بن الوليد.',
      'في خلافة عمر بن الخطاب، زار عمر الشام لمتابعة الفتوحات. كان بلال هناك. سمعه عمر فطلب منه أن يؤذّن. تردّد بلال، ثم رفع صوته بالأذان للمرة الأولى بعد سنين. سمعه الصحابة الذين عاشوا في زمن النبي ﷺ، فبكوا بكاءً عظيمًا. كأن صوته أعادهم إلى أيام المدينة مع رسول الله. حتى عمر بكى حتى بلّت دموعه لحيته.',
      'حدثت قصة عجيبة بين بلال وأبي ذرّ الغفاري. في يوم من الأيام، تخاصما، فقال أبو ذر لبلال: يا ابن السوداء. تأذّى بلال وذهب إلى النبي ﷺ يشكو. غضب النبي ﷺ وقال لأبي ذر: أعيّرته بأمه؟ إنك امرؤ فيك جاهلية. ندم أبو ذر ندمًا شديدًا، فذهب إلى بلال، وضع خدّه على الأرض، وقال: لن أرفع خدّي حتى تطأه. لم يرفع بلال قدمه عنه، بل قبّله. عناق صادق بين صحابيين، رفعت الجاهلية في لحظة وحلّ مكانها الإسلام.',
      'بقي بلال في الشام يجاهد. مات في دمشق سنة 20 هـ، وعمره نحو ستين سنة. صلى عليه أبو عبيدة ودفنه. كانت آخر كلماته: غدًا نلقى الأحبة، محمدًا وحزبه. مات وهو يفرح بلقاء النبي ﷺ بعد عشرين سنة من فراقه.',
      'يبقى بلال بن رباح في تاريخ الإسلام رمزًا لـ ثلاث: قوة الإيمان حتى تحت التعذيب، والمساواة في الإسلام بين السود والبيض، وحب النبي ﷺ الذي لا يفنى. أحد، أحد. كلمة قالها بلال تحت الصخرة، فصارت شعارًا للمستضعفين في كل عصر. اللهم ارضَ عن بلال، واحشرنا معه في زمرة الذين يحبهم النبي ﷺ.',
    ]),
    en: P([
      'He is Bilal ibn Rabah al-Habashi, a slave of Umayyah ibn Khalaf al-Jumahi. He was born in Abyssinia about thirty years before the mission, then brought to Makkah as a slave. His mother Hamamah was a slave-woman in her master\'s house. He grew up in Makkah among Quraysh\'s slaves, serving his master Umayyah ibn Khalaf — one of the harshest polytheists and most hostile to Islam.',
      'He embraced Islam in the early days of the mission. The narrations do not specify exactly how he embraced Islam, but most likely he heard of the Prophet ﷺ from Abu Bakr or another, and believed in his heart before announcing. When Umayyah learned that his slave had embraced Islam, he flared with anger. How dare a slave leave his master\'s religion?',
      'Umayyah began to torture him with the harshest tortures. He would take him out in the noonday heat to the burning sand, lay him on his back, then place a great rock on his chest. He would say to him: "You shall remain so until you die or disbelieve in Muhammad and worship al-Lat and al-Uzza." Bilal would reply only one word: "One, One." Meaning Allah is One. He repeated it and said nothing else.',
      'Some people said: "Just utter the word of disbelief with your tongue while your heart is firm in faith, to escape the torture." But Bilal refused to utter the word of disbelief even with his tongue. He used to say: "By Allah, if I knew a word more enraging to them than this, I would say it." This extraordinary patience under torture made him among the greatest symbols of steadfast faith.',
      'Abu Bakr al-Siddiq heard of Bilal\'s condition and had mercy on him. He went to Umayyah ibn Khalaf and said: "For how much will you sell him?" Umayyah said mockingly: "For an ounce." Abu Bakr said: "If you increased, I would have increased; I have bought him." He bought him for seven ounces of silver, then freed him at once for Allah\'s sake. Bilal became free. Allah revealed concerning Abu Bakr the verse: "And the most righteous will be spared it — the one who gives his wealth to purify himself."',
      'He emigrated to Madinah with the Prophet ﷺ. In Madinah, the Prophet ﷺ chose him to be the first muezzin in Islam. The Prophet had seen in the dream of Abdullah ibn Zayd the manner of the adhan. When the Prophet ﷺ wanted someone to call the adhan, Abdullah said: "O Messenger of Allah, I am the one who saw the vision; command Bilal to call it, for his voice is more resonant than mine." This pleased the Prophet ﷺ, so he taught Bilal the adhan, and Bilal was the first to raise it from atop the Ka\'bah after the Conquest.',
      'Bilal became the Prophet\'s ﷺ muezzin, calling for every prayer. The Prophet ﷺ loved his voice greatly. Of the Prophet\'s humility and love of Bilal, he said to him one day: "O Bilal, tell me of the most hopeful deed you have done in Islam, for I heard the tread of your sandals before me in Paradise." Bilal said: "I know of no deed, except that I have never performed ablution at any hour of night or day except that I prayed with that ablution whatever was decreed for me to pray." Bilal used to pray two rak\'ahs after every ablution — this is what entered him into Paradise.',
      'When the Prophet ﷺ conquered Makkah, he entered with Bilal. He ordered Bilal to ascend the back of the Ka\'bah and call the adhan. Bilal\'s voice — the Abyssinian slave who had been tortured there — rose saying: "Allah is the Greatest, I bear witness that there is no god but Allah, I bear witness that Muhammad is the Messenger of Allah." Quraysh heard him. Some said in regret: "Allah honoured Abu Sufyan when He took him before this day." Another said: "Look at this black slave climbing atop the Ka\'bah!" The verse was revealed: "O mankind, indeed We have created you from male and female and made you peoples and tribes that you may know one another. Indeed, the most noble of you with Allah is the most righteous of you."',
      'When the Prophet ﷺ died, Bilal grieved severely. He wanted to call the adhan for the first time after the Prophet\'s death; when he reached "I bear witness that Muhammad is the Messenger of Allah," his voice choked with weeping. He fell to the ground from intense grief and could not complete the adhan. All the Companions wept. He then said: "I will not call the adhan for anyone after the Messenger of Allah ﷺ." And he stopped calling.',
      'He asked Abu Bakr al-Siddiq for permission to leave for Sham for jihad. He wanted to be away from Madinah because every corner of it reminded him of the Prophet ﷺ and increased his grief. Abu Bakr permitted him. Bilal left for Sham and participated in the conquests there under the command of Abu Ubaydah and Khalid ibn al-Walid.',
      'In the caliphate of Umar ibn al-Khattab, Umar visited Sham to follow up on the conquests. Bilal was there. Umar asked him to call the adhan. Bilal hesitated, then raised his voice in the adhan for the first time in years. The Companions who had lived in the time of the Prophet ﷺ heard him and wept greatly. As if his voice returned them to the days of Madinah with the Messenger of Allah. Even Umar wept until his tears wet his beard.',
      'A striking story occurred between Bilal and Abu Dharr al-Ghifari. One day they quarrelled, and Abu Dharr said to Bilal: "O son of a black woman." Bilal was hurt and went to the Prophet ﷺ to complain. The Prophet ﷺ became angry and said to Abu Dharr: "Did you taunt him with his mother? You are a man with Jahiliyyah in you." Abu Dharr deeply regretted it, went to Bilal, placed his cheek on the ground, and said: "I shall not raise my cheek until you step on it." Bilal did not lift his foot onto him; rather he kissed him. A sincere embrace between two Companions; the Jahiliyyah was lifted in a moment and Islam took its place.',
      'Bilal remained in Sham fighting. He died in Damascus in 20 AH, at about sixty years of age. Abu Ubaydah prayed over him and buried him. His last words were: "Tomorrow we meet the beloved — Muhammad and his band." He died rejoicing in meeting the Prophet ﷺ after twenty years of separation.',
      'Bilal ibn Rabah remains in the history of Islam a symbol of three things: the strength of faith even under torture, equality in Islam between black and white, and a love of the Prophet ﷺ that does not fade. "One, One" — a word Bilal said under the rock — became a banner for the oppressed in every era. O Allah, be pleased with Bilal and gather us with him in the band of those whom the Prophet ﷺ loves.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 12. عمار بن ياسر رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'ammar': {
    ar: P([
      'هو عمار بن ياسر بن عامر بن مالك العنسي. ولد في مكة قبل البعثة بنحو سبعين سنة. أبوه ياسر من قبيلة عنس اليمنية، جاء إلى مكة باحثًا عن أخوين له، ثم بقي فيها وتزوج سُمية بنت خياط — أمة أبي حذيفة بن المغيرة المخزومي. ولد عمار في مكة، فكان عبدًا لأبي حذيفة بحكم أمه، ثم أعتقه أبو حذيفة.',
      'أسلم عمار وأبوه ياسر وأمه سُمية وأخوه عبد الله في أوائل البعثة. كانوا من السابقين الأولين، السابعة في الإسلام. كان إسلامهم سرًا في البداية، لكن سرعان ما عُلم به فبدأ التعذيب الشديد لهم. لأنهم كانوا فقراء ضعفاء — لا قبيلة تحميهم، ولا مال يحجزهم — صبّ عليهم أبو جهل وأقاربه أشد أنواع العذاب.',
      'كانت أسرة ياسر أول أسرة شُهرت بالتعذيب في الإسلام. كانوا يأخذونهم إلى الرمضاء في حرّ الظهيرة، ويلبسونهم دروع الحديد الحامية، ويعذبونهم بشتى الأنواع. مر عليهم النبي ﷺ يومًا وهم يُعذّبون، فقال كلمته الخالدة: صبرًا آل ياسر، فإن موعدكم الجنة. وعد إلهي عظيم على لسان نبي.',
      'سُمية أم عمار صبرت أعظم صبر. كان أبو جهل يعذّبها فلا تتراجع. في النهاية، طعنها أبو جهل في قُبُلها بحربة فماتت شهيدة. صارت سُمية أول شهيدة في الإسلام، وأول من ذاق طعم الشهادة من المسلمين. مات بعدها زوجها ياسر تحت التعذيب أيضًا. صار عمار يتيمًا وحيدًا.',
      'لم يستطع عمار أن يتحمل العذاب كما تحمّله أبواه. ضعف يومًا، وأظهر بلسانه ما لا يعتقد بقلبه ليتخلّص من العذاب. سبّ النبي ﷺ ومدح الأصنام. ثم ذهب إلى النبي ﷺ يبكي ويخبره بما حدث. سأله النبي: كيف قلبك؟ قال: مطمئنّ بالإيمان. قال النبي ﷺ: فإن عادوا فعد. أنزل الله: إلا من أُكره وقلبه مطمئنّ بالإيمان. كانت رخصة شرعية لمن يُكره على كلمة الكفر تحت التعذيب.',
      'هاجر عمار إلى المدينة. شارك في كل غزوات النبي ﷺ ابتداءً من بدر. كان النبي ﷺ يحبه حبًا شديدًا، ويقول عنه: عمّار ملئ إيمانًا من فرقه إلى قدمه. أي من رأسه إلى قدمه إيمان. ووصفه أيضًا بأن قلبه مطمئنّ بالإيمان حتى لو نطق لسانه بالكفر.',
      'في غزوة الخندق، شارك عمار في حفر الخندق. كانت أعمالًا شاقّة، يحملون التراب والحجارة في رمضاء المدينة. كان الناس يحملون لبنة واحدة، فيحمل عمار لبنتين أو ثلاثًا. مرّ به النبي ﷺ ينفض التراب عن رأسه، فقال له النبي ﷺ كلمة هزّت أرجاء التاريخ: ويح ابن سمية، تقتلك الفئة الباغية. تنبأ النبي ﷺ بمقتل عمار على يد فئة باغية. هذا الحديث صحيح متواتر.',
      'كان عمار من أعلام الصحابة في الورع والعلم. تولّى ولاية الكوفة في عهد عمر بن الخطاب. كان زاهدًا، يأكل من بيت المال ما يكفيه، ولا يتعدّى ذلك. عُزل من ولايته لأسباب إدارية، لكنه قبل العزل بصدر رحب، وقال: ما سرّني أن وُلّيت، وما حزنت أن عُزلت.',
      'كان من المتمسكين برأي علي بن أبي طالب في الفتنة. لما قُتل عثمان وبايع الناس عليًا، كان عمار من أشد المؤيدين لعلي. شارك في معركة الجمل في صف علي ضد طلحة والزبير. ثم شارك في معركة صفين ضد معاوية.',
      'في معركة صفين سنة 37 هـ، استشهد عمار. كان عمره يومئذ نحو ثلاث وتسعين سنة. قبل المعركة، طلب من أصحابه ماءً مع لبن. قال: إن آخر رزقي من الدنيا اللبن. ثم تقدّم إلى المعركة بنفسه يقاتل. قتله رجل من جيش معاوية، فلما سمع الناس بقتله، تذكّروا حديث النبي ﷺ: ويح ابن سمية، تقتلك الفئة الباغية.',
      'كان هذا الحديث صدمة لجيش معاوية. لأن النبي ﷺ تنبأ بأن قاتلي عمار فئة باغية. عند أصحاب معاوية تأويلات للحديث، لكن الواضح أن جمهور أهل العلم رأى أن المعصية كانت في صف معاوية لا في صف علي. هذا ما يقوله أهل السنة. مع الاحترام لمعاوية لأنه صحابي، لكن في هذه القضية كان علي على الصواب.',
      'حُمل جثمان عمار من ميدان المعركة. صلى عليه علي بن أبي طالب بنفسه، ودفنه في أرض صفين. كان لعمار قبر هناك معروف لسنين. ولم يغسّل ولم يكفّن في كفن جديد — دُفن في ثيابه التي قاتل فيها — اقتداء بسنة الشهداء في غزوات النبي ﷺ.',
      'يبقى عمار بن ياسر في تاريخ الإسلام نموذجًا للصحابي الذي عاش فقيرًا، عُذّب من أجل الإيمان، شارك في كل المعارك، ومات شهيدًا على يد فئة باغية، تحقيقًا لنبوءة النبي ﷺ. أمه سُمية أول شهيدة، وهو شاهد على أن الحق يبقى ولو ذهب أصحابه. اللهم ارضَ عن عمار وأمه وأبيه، واجمعنا بهم في الفردوس الأعلى.',
    ]),
    en: P([
      'He is Ammar ibn Yasir ibn Amir ibn Malik al-Ansi. He was born in Makkah about seventy years before the mission. His father Yasir, from the Yemeni tribe of Ans, came to Makkah seeking two of his brothers, then stayed and married Sumayyah bint Khayyat — a slave-girl of Abu Hudhayfah ibn al-Mughirah al-Makhzumi. Ammar was born in Makkah, and was thus a slave of Abu Hudhayfah through his mother, then Abu Hudhayfah freed him.',
      'Ammar, his father Yasir, his mother Sumayyah, and his brother Abdullah embraced Islam in the early days of the mission. They were among the very first, the seventh in Islam. Their Islam was secret at first, but it was soon known and severe torture began against them. Because they were poor and weak — with no tribe to protect them and no wealth to shield them — Abu Jahl and his kin poured upon them the harshest tortures.',
      'The family of Yasir was the first family famously tortured in Islam. They would be taken to the burning sand in noonday heat and dressed in scorching iron armour. The Prophet ﷺ passed by them one day as they were being tortured, and said his immortal words: "Patience, family of Yasir; your appointment is Paradise." A great divine promise on the tongue of a prophet.',
      'Sumayyah, Ammar\'s mother, bore the greatest patience. Abu Jahl would torture her and she would not retreat. In the end, Abu Jahl pierced her with a spear and she died a martyr. Sumayyah became the first martyr in Islam, the first to taste the taste of martyrdom among the Muslims. Her husband Yasir died under torture too. Ammar was left an orphan.',
      'Ammar could not bear the torture as his parents had. He weakened one day and uttered with his tongue what he did not believe in his heart, to escape the torture. He cursed the Prophet ﷺ and praised the idols. Then he went to the Prophet ﷺ weeping and told him what had happened. The Prophet asked: "How is your heart?" He said: "Firm in faith." The Prophet ﷺ said: "If they return, you may return." Allah revealed: "Except for one who is coerced while his heart is firm in faith." It was a legal dispensation for one coerced to a word of disbelief under torture.',
      'Ammar emigrated to Madinah. He participated in every campaign of the Prophet ﷺ starting from Badr. The Prophet ﷺ loved him deeply and said about him: "Ammar is filled with faith from head to toe." From his head to his foot is faith. He also described him as one whose heart is firm in faith even if his tongue utters disbelief.',
      'At the Battle of the Trench, Ammar participated in digging the trench. The work was hard — carrying earth and stones in Madinah\'s heat. People would carry one block; Ammar would carry two or three. The Prophet ﷺ passed by him as he was dusting off his head, and said words that shook the corridors of history: "Woe to the son of Sumayyah; the transgressing party will kill you." The Prophet ﷺ foretold Ammar\'s killing at the hands of a transgressing party. This hadith is authentically established (mutawatir).',
      'Ammar was among the foremost Companions in piety and knowledge. He took the governorship of Kufa during the reign of Umar ibn al-Khattab. He was ascetic, eating from the treasury what sufficed him and not exceeding that. He was removed from his governorship for administrative reasons, but accepted removal with an open chest, saying: "It did not please me to be appointed, and it did not sadden me to be removed."',
      'He was among those firmly with Ali ibn Abi Talib in the trial. When Uthman was killed and the people pledged allegiance to Ali, Ammar was among Ali\'s strongest supporters. He participated in the Battle of the Camel on Ali\'s side against Talhah and al-Zubayr. He then participated in the Battle of Siffin against Mu\'awiyah.',
      'In the Battle of Siffin in 37 AH, Ammar was martyred. He was about ninety-three years old. Before the battle, he asked his companions for water with milk. He said: "My last provision from this world will be milk." He then advanced into the battle himself fighting. A man from Mu\'awiyah\'s army killed him. When people heard of his killing, they remembered the hadith of the Prophet ﷺ: "Woe to the son of Sumayyah; the transgressing party will kill you."',
      'This hadith was a shock to Mu\'awiyah\'s army. Because the Prophet ﷺ had foretold that Ammar\'s killers would be a transgressing party. Mu\'awiyah\'s side had interpretations of the hadith, but the clear majority of the people of knowledge held that the transgression was on Mu\'awiyah\'s side, not Ali\'s. This is what Ahl al-Sunnah hold. With respect for Mu\'awiyah as a Companion, in this matter Ali was on the correct view.',
      'Ammar\'s body was carried from the battlefield. Ali ibn Abi Talib prayed over him personally and buried him in the land of Siffin. Ammar had a known grave there for years. He was not washed or shrouded in a new shroud — he was buried in the clothes he had fought in — following the Sunnah of the martyrs in the Prophet\'s ﷺ campaigns.',
      'Ammar ibn Yasir remains in the history of Islam a model of the Companion who lived poor, was tortured for faith, participated in every battle, and died a martyr at the hands of a transgressing party, fulfilling the prophecy of the Prophet ﷺ. His mother Sumayyah was the first martyr, and he is a witness that truth remains even after its bearers depart. O Allah, be pleased with Ammar and his mother and father, and gather us with them in the Highest Paradise.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 13. مصعب بن عمير رضي الله عنه — السفير الأول
  // ──────────────────────────────────────────────────────────────────────
  'musab': {
    ar: P([
      'هو مصعب بن عمير بن هاشم بن عبد مناف بن عبد الدار بن قُصي، القرشي العبدري. وُلد بمكة قبل البعثة بنحو خمس وعشرين سنة. كان من أعرق بيوت قريش وأغناها. أبوه عمير كان من سادة قريش، وأمه خنّاس بنت مالك. كان مصعب وحيدًا مدلّلًا، يربى في أرخى عيش وأنعمه.',
      'كان قبل الإسلام أنعم فتى في مكة. يلبس أفخر الثياب، أحدها كان من الحرير المطرّز بالذهب — وكان لا يلبس الثوب مرتين. يستعمل أغلى العطور، حتى كان الناس يعرفون مكانه من رائحته من بعيد. أمه كانت تنفق عليه نفقة عظيمة، توفّر له كل ما يشتهي.',
      'سمع عن دعوة النبي ﷺ، فدخل دار الأرقم سرًا ليرى ما يحدث. سمع كلام النبي ﷺ، فأسلم في الحال. كان مسلمًا في قلبه، يخفي إسلامه عن أمه خوفًا من أن تعذّبه. لكن في النهاية اكتُشف أمره. عرف رجل اسمه عثمان بن طلحة أنه يدخل دار الأرقم، فأخبر أمه.',
      'لما علمت أمه، اشتعلت غضبًا. حبسته في البيت، ومنعته الطعام والشراب، ثم بدأت تعذّبه بكل وسيلة. عذابها كان قاسيًا — كان شابًا مرفّهًا لم يعرف الجوع ولا الحرّ ولا الإهانة. لكن إيمانه ثبت. هرب من البيت بعد فترة، وانضم إلى المهاجرين إلى الحبشة.',
      'لما أراد أن يرجع إلى مكة، رفضت أمه أن تقبله ما لم يترك دينه. تركت تنفق عليه. صار يلبس ثوبًا واحدًا مرقّعًا، يحتذي حذاء من ليف. يأكل ما يجده. هو الذي كان أنعم فتى في مكة. مرّ به النبي ﷺ يومًا فبكى لما رآه على تلك الحال، وقال: لقد رأيت مصعبًا وما بمكة فتى أنعم عند أبويه منه، ثم ترك ذلك كله ابتغاء مرضاة الله ورسوله.',
      'لما أراد النبي ﷺ أن يرسل سفيرًا للإسلام إلى المدينة قبل الهجرة، اختار مصعبًا. كان هذا أعظم اختيار. مصعب كان شابًا، وعالمًا بالقرآن، ولبقًا في الكلام، ومحبوبًا. ذهب إلى المدينة، يعلّم الأنصار القرآن والإسلام. أسلم على يديه أكثر أهل المدينة. أسلم سعد بن معاذ وأُسيد بن حضير على يديه — سيدا الأوس. كان السفير الناجح الذي مهّد الأرض للهجرة.',
      'بعد الهجرة، شارك مصعب في غزوة بدر. كان حامل راية المهاجرين. ثم في غزوة أحد، أعطاه النبي ﷺ راية المسلمين. وقع في تلك الغزوة موقفه العظيم. لما انكشف المسلمون بعد مخالفة الرماة، اتجهت قريش نحو النبي ﷺ تريد قتله. وقف مصعب يحمل الراية ويقاتل دون النبي. ضُربت يده اليمنى فقطعت، فأمسك الراية بيده اليسرى. ثم قُطعت يده اليسرى، فاحتضن الراية بساعديه. ثم طعنه ابن قميئة برمح فاستشهد رضي الله عنه.',
      'لما جاء النبي ﷺ يتفقد القتلى، وقف عند جثة مصعب وبكى. تلا قول الله: من المؤمنين رجال صدقوا ما عاهدوا الله عليه، فمنهم من قضى نحبه ومنهم من ينتظر، وما بدّلوا تبديلًا. ثم قال: أشهد أنكم شهداء عند الله يوم القيامة.',
      'حدثت قصة عجيبة في كفنه. لم يجدوا له ما يكفّنوه به إلا بُردة قصيرة — قطعة قماش قصيرة. إذا غطّوا بها رأسه ظهرت قدماه. إذا غطّوا بها قدميه ظهر رأسه. قال النبي ﷺ: غطّوا بها رأسه، واجعلوا على رجليه إذخرًا — حشيش له رائحة طيبة. هذا مصعب، أنعم فتى في مكة، يُدفن بدون كفن كامل، وتغطّى قدماه بحشيش.',
      'بكى النبي ﷺ والصحابة على مصعب. كان أعظم خسارة شخصية في أحد للنبي ﷺ بعد عمّه حمزة. كان النبي ﷺ يقدّر مصعبًا كثيرًا، لأنه ضحّى بكل شيء: بالنعمة، بالأم، بالمكانة الاجتماعية. وفي النهاية ضحّى بحياته.',
      'وقف بعد عشرين سنة عبد الرحمن بن عوف على مائدة فاخرة في بيته، فبكى. سُئل: ما يبكيك يا أبا محمد؟ قال: ذكرت مصعب بن عمير، وهو أفضل مني في كل شيء، ولم يجد في كفنه إلا بُردة قصيرة، فأخاف أن يكون قد عُجّلت لي طيباتي في الدنيا. تخاف الصحابة من نعمة الدنيا، لأنهم رأوا مصعبًا يموت فقيرًا والآن يعيشون في ثراء.',
      'سيرة مصعب نموذج للداعية الشاب. شاب من أرفع الطبقات، ترك كل شيء لله. سافر إلى مدينة لا يعرف فيها أحدًا، علّم الناس القرآن، أسلم على يديه آلاف. ثم مات شهيدًا في عمر الشباب — نحو الأربعين أو أقل. لم يبني له بيتًا، لم يجمع له مالًا، لم يخلّف وراءه أولادًا — مات وحيدًا في معركة.',
      'دروسه عظيمة: أن الإيمان يكسر كل القيود، حتى قيود الأم والمال والمكانة. أن الداعية الناجح هو من يجمع بين العلم والأدب والصدق. أن الشهادة في سبيل الله هي خاتمة الفائزين. وأن المسلم لا يخاف من الفقر إذا كان معه دينه.',
      'يبقى مصعب بن عمير في تاريخ الإسلام أول سفير في الإسلام، وحامل راية المسلمين في أحد، والشهيد الذي لم يجد كفنًا يستره. ضرب أعظم مثل على التضحية لله. اللهم ارضَ عن مصعب، وارفع درجته إلى أعلى عليين، وارزقنا الاقتداء بصدقه وتضحيته.',
    ]),
    en: P([
      'He is Mus\'ab ibn Umayr ibn Hashim ibn Abd Manaf ibn Abd al-Dar ibn Qusayy, al-Qurashi al-Abdari. He was born in Makkah about twenty-five years before the mission. He was of one of the most distinguished and wealthy households of Quraysh. His father Umayr was among the chiefs of Quraysh, and his mother was Khannas bint Malik. Mus\'ab was an only, pampered child raised in the easiest and most luxurious life.',
      'Before Islam he was the most pampered youth in Makkah. He wore the finest clothes — one of which was silk embroidered with gold — and would not wear a garment twice. He used the most expensive perfumes, until people knew his place by his scent from afar. His mother spent on him lavishly, providing him everything he desired.',
      'He heard about the call of the Prophet ﷺ and secretly entered the house of al-Arqam to see what was happening. He heard the speech of the Prophet ﷺ and embraced Islam at once. He was Muslim in his heart, hiding his Islam from his mother for fear she would torture him. But finally his matter was discovered. A man named Uthman ibn Talhah learned he was entering the house of al-Arqam and told his mother.',
      'When his mother learned, she flared with anger. She confined him in the house and denied him food and drink, then began torturing him by every means. Her torture was harsh — he was a pampered youth who had not known hunger, heat, or humiliation. But his faith stood firm. He escaped from the house after a period and joined the emigrants to Abyssinia.',
      'When he wanted to return to Makkah, his mother refused to accept him unless he left his religion. She stopped providing for him. He came to wear a single patched garment and to walk in sandals of palm fibre. He ate what he could find. He who had been the most pampered youth in Makkah. The Prophet ﷺ passed by him one day and wept when he saw him in that state, saying: "I have seen Mus\'ab when there was not in Makkah a youth more pampered by his parents than him, then he abandoned all that seeking the pleasure of Allah and His Messenger."',
      'When the Prophet ﷺ wanted to send an ambassador for Islam to Madinah before the Hijrah, he chose Mus\'ab. It was a greatest choice. Mus\'ab was a youth, knowledgeable in the Qur\'an, eloquent in speech, and beloved. He went to Madinah, teaching the Ansar the Qur\'an and Islam. Most of the people of Madinah embraced Islam at his hand. Sa\'d ibn Mu\'adh and Usayd ibn Hudayr embraced Islam at his hand — chiefs of the Aws. He was the successful ambassador who prepared the ground for the Hijrah.',
      'After the Hijrah, Mus\'ab participated in the Battle of Badr. He was the standard-bearer of the Muhajirun. Then at the Battle of Uhud, the Prophet ﷺ gave him the standard of the Muslims. His great stand fell in that battle. When the Muslims were exposed after the archers\' disobedience, Quraysh moved toward the Prophet ﷺ wanting to kill him. Mus\'ab stood carrying the standard and fighting before the Prophet. His right hand was struck and severed; he grasped the standard with his left hand. His left hand was severed; he embraced the standard with his forearms. Then Ibn Qami\'ah stabbed him with a spear, and he was martyred.',
      'When the Prophet ﷺ came inspecting the slain, he stood over Mus\'ab\'s body and wept. He recited Allah\'s words: "Among the believers are men who have been true to what they promised Allah. Among them is he who has fulfilled his vow, and among them is he who awaits; and they did not alter in any way." Then he said: "I bear witness that you are martyrs with Allah on the Day of Resurrection."',
      'A striking story occurred about his shroud. They could find nothing to shroud him with but a short cloak — a short piece of cloth. If they covered his head with it, his feet would show; if they covered his feet, his head would show. The Prophet ﷺ said: "Cover his head with it, and place idhkhir grass — a fragrant grass — on his feet." This is Mus\'ab, the most pampered youth in Makkah, buried without a complete shroud, his feet covered with grass.',
      'The Prophet ﷺ and the Companions wept over Mus\'ab. He was the greatest personal loss at Uhud for the Prophet ﷺ after his uncle Hamzah. The Prophet ﷺ valued Mus\'ab greatly, because he sacrificed everything: comfort, mother, social standing. In the end he sacrificed his life.',
      'Twenty years later Abd al-Rahman ibn Awf stood over a sumptuous table in his house and wept. He was asked: "What makes you weep, Abu Muhammad?" He said: "I remembered Mus\'ab ibn Umayr — he is better than me in every way — and they could not find for his shroud but a short cloak. I fear that my good things may have been hastened for me in this world." The Companions feared the bounty of this world, because they had seen Mus\'ab die poor and now lived in wealth.',
      'Mus\'ab\'s life is a model for the young caller. A youth of the highest classes who left everything for Allah. He travelled to a city where he knew no one, taught people the Qur\'an, and thousands embraced Islam at his hand. Then he died a martyr in the age of youth — around forty or less. He did not build himself a house, did not gather wealth, did not leave children behind — he died alone in a battle.',
      'His lessons are great: that faith breaks all chains, even the chains of mother, wealth, and standing. That the successful caller is one who combines knowledge, manners, and truthfulness. That martyrdom in Allah\'s cause is the ending of the successful. And that the Muslim does not fear poverty if he has his religion with him.',
      'Mus\'ab ibn Umayr remains in the history of Islam the first ambassador in Islam, the standard-bearer of the Muslims at Uhud, and the martyr who could not find a shroud to cover him. He set the greatest example of sacrifice for Allah. O Allah, be pleased with Mus\'ab, raise his rank to the highest of the high, and grant us to follow his truthfulness and sacrifice.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 14. خالد بن الوليد رضي الله عنه — سيف الله المسلول
  // ──────────────────────────────────────────────────────────────────────
  'khalid': {
    ar: P([
      'هو خالد بن الوليد بن المغيرة بن عبد الله بن عمر بن مخزوم، القرشي المخزومي. وُلد بمكة قبل البعثة بنحو سبع عشرة سنة. كان من سادات قريش، أبوه الوليد بن المغيرة من أعتى المشركين، الذي قال الله فيه: ذرني ومن خلقت وحيدًا. أمه لُبابة الصغرى بنت الحارث، أخت ميمونة بنت الحارث زوج النبي ﷺ.',
      'كان من أعظم فرسان قريش في الجاهلية. منذ صغره تعلم الفروسية والرماية والقتال. شارك في معارك قريش ضد العرب قبل الإسلام، وكان له فيها بلاء عظيم. لما بدأت الدعوة، وقف خالد مع قريش ضد النبي ﷺ. وكان من أشد الناس عداء للإسلام.',
      'في غزوة أحد، قاد خالد فرسان قريش. حين خالف الرماة أمر النبي ﷺ ونزلوا من الجبل، رأى خالد بثاقب نظره الفرصة. تسلّل بفرسانه من خلف المسلمين، وأحاط بهم. هذا التكتيك العسكري حوّل النصر إلى هزيمة. كاد المسلمون يُهلكون كلهم. كان لخالد دور رئيسي في تلك الهزيمة.',
      'في غزوة الحديبية سنة 6 هـ، أرسلت قريش خالدًا بفرسانها لاعتراض النبي ﷺ في طريقه إلى مكة. لكن النبي ﷺ تجنّبه بسلوك طريق آخر. هنا بدأ خالد يفكر. قال في نفسه: ما رأيت هذا الرجل يهزم. كان يلاحظ أن النبي ﷺ دائمًا يخرج من المعارك سليمًا، وأن الإسلام في انتشار مستمر.',
      'في السنة السابعة من الهجرة، أسلم خالد. خرج من مكة مع عمرو بن العاص وعثمان بن طلحة. التقوا في الطريق إلى المدينة. قال خالد لرفيقيه: لقد ضاق عليّ الأمر، فأنا أرى أن محمدًا قد ظهر على العرب والعجم، وما من بقعة من الأرض إلا وسأقاتل فيها معه. اتجهوا إلى المدينة وأعلنوا إسلامهم. فرح النبي ﷺ بإسلام خالد فرحًا شديدًا.',
      'بعد أشهر فقط من إسلامه، شارك خالد في غزوة مؤتة سنة 8 هـ. كان هذا أول قتال له مع المسلمين. كان النبي ﷺ قد أمر بثلاثة أمراء: زيد بن حارثة، فإن قُتل فجعفر بن أبي طالب، فإن قُتل فعبد الله بن رواحة. قُتل الثلاثة كلهم. اختار الجيش حينها خالدًا أميرًا.',
      'كانت المعركة ضد جيش الروم الذي بلغ مئتي ألف، والمسلمون ثلاثة آلاف فقط. كان النصر مستحيلًا. لكن خالد فعل العجائب. غيّر تشكيل الجيش، وأعاد توزيع الفرق، فكأنه أتى بمدد جديد كل لحظة. لم ينتصر، لكنه أنقذ الجيش من الإبادة. خرج الجيش الإسلامي سالمًا تقريبًا. لما عاد إلى المدينة، استقبله النبي ﷺ وقال: قاتل خالد قتالًا شديدًا، وقد كسرت في يده تسعة أسياف، فما ثبت في يده إلا صفيحة يمانية. ولقّبه يومئذ: سيف الله المسلول.',
      'صار خالد بعد ذلك القائد العسكري الأول للمسلمين. شارك في فتح مكة سنة 8 هـ، وفي غزوة حنين، وفي غزوة الطائف، وفي غزوة تبوك. لم يهزم في معركة أبدًا. أرسله النبي ﷺ في سرايا كثيرة، وكلها انتصر فيها.',
      'لما توفي النبي ﷺ، ارتدّ كثير من العرب. أبو بكر الصديق أرسل أحد عشر جيشًا لقتال المرتدين، أعظمها جيش خالد بن الوليد. حارب طُليحة الأسدي، ومالك بن نويرة، ومسيلمة الكذاب. في معركة اليمامة ضد مسيلمة، قُتل من المسلمين أكثر من ألف ومئتين شهيد، لكن الجيش انتصر وقُتل مسيلمة على يد وحشي بن حرب — قاتل حمزة في أحد، الذي أسلم وأراد أن يكفّر عن قتله لحمزة بقتل أعدى أعداء الإسلام.',
      'في عهد أبي بكر، أرسل خالد إلى العراق. فتح الحيرة وعين تمر والأنبار، وكسر شوكة الفرس في العراق. ثم نقله أبو بكر إلى الشام لمعونة جيش أبي عبيدة. خالد قطع الصحراء بجيشه في مسيرة من أعظم المسيرات العسكرية في التاريخ. وصل إلى الشام في الوقت المناسب لقيادة المسلمين في معركة اليرموك سنة 13 هـ. هزم الروم هزيمة كاسحة، وفقدوا الشام إلى الأبد.',
      'في عهد عمر بن الخطاب، عُزل خالد من القيادة. لم يكن عمر يكره خالدًا، لكنه خشي أن يفتتن الناس به ويعتقدوا أن النصر بسبب خالد لا بسبب الله. قال عمر: والله ما عزلته عن سُخط، ولكني خشيت أن يُفتن الناس به. خالد قبل العزل بصدر رحب. قال: عزلني سيف الله المسلول؟ والله ما كنت أعمل لعمر، ولكنّي كنت أعمل لله. ثم استمر يقاتل تحت قيادة أبي عبيدة، جنديًا من جنود المسلمين.',
      'مات خالد في حمص بسوريا سنة 21 هـ. كان يبكي على فراش الموت ويقول: لقد شهدتُ مئة زحف أو زحوفًا، وما في جسدي موضع شبر إلا وفيه ضربة بسيف، أو طعنة برمح، أو رمية بسهم، وها أنا ذا أموت على فراشي كما يموت البعير، فلا نامت أعين الجبناء. كان يتمنى الشهادة فلم تأته. مات على فراشه، لكن موته من فراش الجهاد، فهو شهيد بإذن الله.',
      'حُمل في جنازة عظيمة. خرجت نساء بني المغيرة يبكينه. سمع عمر بن الخطاب بكاءهن، فمنع منه أحدهم، لكن عمر قال: دعهن يبكين على أبي سليمان، فما على نساء بني المغيرة من بأس أن يسفكن من دموعهن على أبي سليمان، ما لم يكن نقع — أي ندبة شديدة. دفن في حمص، وقبره معروف فيها إلى اليوم.',
      'يبقى خالد بن الوليد في تاريخ الإسلام سيف الله المسلول، القائد الذي لم يهزم. عاش حياة الفروسية والجهاد، وفتح بسيفه نصف العالم القديم — الشام والعراق. كانت طاعته للقيادة آية. لما عزله عمر قبل بصدر رحب، ولم ينافس ولم يثر. ضرب أعظم مثل على القائد الذي يطيع حتى لو لم يقتنع. اللهم ارضَ عن خالد، وارفع درجته في أعلى الجنة.',
    ]),
    en: P([
      'He is Khalid ibn al-Walid ibn al-Mughirah ibn Abdullah ibn Umar ibn Makhzum, al-Qurashi al-Makhzumi. He was born in Makkah about seventeen years before the mission. He was of the chiefs of Quraysh. His father al-Walid ibn al-Mughirah was among the harshest polytheists, of whom Allah said: "Leave Me with him whom I created alone." His mother was Lubabah the Younger, daughter of al-Harith, sister of Maymunah bint al-Harith, wife of the Prophet ﷺ.',
      'He was among the greatest knights of Quraysh in the Jahiliyyah. From his youth he learned horsemanship, archery, and combat. He took part in Quraysh\'s battles against the Arabs before Islam, showing great prowess. When the mission began, Khalid stood with Quraysh against the Prophet ﷺ. He was among the most hostile people to Islam.',
      'At the Battle of Uhud, Khalid led Quraysh\'s knights. When the archers disobeyed the Prophet\'s ﷺ command and descended from the hill, Khalid saw the opportunity with his sharp eye. He slipped with his knights behind the Muslims and surrounded them. This military tactic turned victory into defeat. The Muslims were nearly destroyed. Khalid had a principal role in that defeat.',
      'At Hudaybiyyah in 6 AH, Quraysh sent Khalid with his knights to intercept the Prophet ﷺ on his way to Makkah. But the Prophet ﷺ avoided him by taking another route. Here Khalid began to think. He said to himself: "I have not seen this man defeated." He noticed that the Prophet ﷺ always came out of battles safely, and that Islam was in continuous spread.',
      'In the seventh year of the Hijrah, Khalid embraced Islam. He left Makkah with Amr ibn al-As and Uthman ibn Talhah. They met on the road to Madinah. Khalid said to his two companions: "The matter has become tight upon me; I see that Muhammad has prevailed over the Arabs and the non-Arabs, and there is no spot of land where I will not fight with him." They went to Madinah and announced their Islam. The Prophet ﷺ rejoiced greatly at Khalid\'s Islam.',
      'Only months after his Islam, Khalid took part in the Battle of Mu\'tah in 8 AH. This was his first fighting with the Muslims. The Prophet ﷺ had ordered three commanders: Zayd ibn Harithah, and if killed then Ja\'far ibn Abi Talib, and if killed then Abdullah ibn Rawahah. All three were killed. The army then chose Khalid as commander.',
      'The battle was against a Roman army of two hundred thousand, with only three thousand Muslims. Victory was impossible. But Khalid worked wonders. He changed the army\'s formation and redistributed the divisions, as if he brought reinforcements every moment. He did not win, but he saved the army from annihilation. The Muslim army returned almost intact. When he returned to Madinah, the Prophet ﷺ received him and said: "Khalid fought severely; nine swords broke in his hand, and only a Yemeni sword remained in his hand." He gave him the title that day: "Saif Allah al-Maslul" — the drawn sword of Allah.',
      'Khalid afterward became the first military commander of the Muslims. He participated in the conquest of Makkah in 8 AH, in the Battle of Hunayn, the Battle of Ta\'if, and the Battle of Tabuk. He was never defeated in a battle. The Prophet ﷺ sent him on many raids, in all of which he was victorious.',
      'When the Prophet ﷺ died, many Arabs apostatised. Abu Bakr al-Siddiq sent eleven armies to fight the apostates, the greatest of which was Khalid ibn al-Walid\'s army. He fought Tulayhah al-Asadi, Malik ibn Nuwayrah, and Musaylimah the Liar. At the Battle of Yamamah against Musaylimah, more than one thousand two hundred Muslims were martyred, but the army won and Musaylimah was killed at the hand of Wahshi ibn Harb — the killer of Hamzah at Uhud, who had embraced Islam and wanted to atone for killing Hamzah by killing Islam\'s greatest enemy.',
      'In Abu Bakr\'s era, Khalid was sent to Iraq. He conquered al-Hira, Ayn al-Tamr, and al-Anbar, and broke the Persian power in Iraq. Abu Bakr then transferred him to Sham to aid Abu Ubaydah\'s army. Khalid cut across the desert with his army in a march among the greatest military marches in history. He arrived in Sham at the right time to lead the Muslims in the Battle of Yarmuk in 13 AH. He defeated the Romans devastatingly, and they lost Sham forever.',
      'In Umar ibn al-Khattab\'s era, Khalid was removed from command. Umar did not hate Khalid, but feared people would be tried by him and believe victory was because of Khalid not because of Allah. Umar said: "By Allah, I did not remove him out of displeasure, but I feared people would be tried by him." Khalid accepted the removal with an open chest. He said: "The Drawn Sword of Allah removed me? By Allah, I was not working for Umar; I was working for Allah." He continued fighting under Abu Ubaydah\'s command, as a soldier among the Muslim soldiers.',
      'Khalid died in Homs in Syria in 21 AH. He wept on his deathbed and said: "I have witnessed a hundred charges or so, and there is no spot on my body the size of a span but it has a sword strike, a spear thrust, or an arrow shot. Here I am dying on my bed as a camel dies. May the eyes of cowards never sleep." He longed for martyrdom and it did not come to him. He died on his bed, but his death was from the bed of jihad, so he is a martyr by Allah\'s permission.',
      'He was carried in a great funeral. The women of Banu al-Mughirah went out weeping for him. Umar ibn al-Khattab heard their weeping and someone tried to prevent it. But Umar said: "Let them weep for Abu Sulayman; there is no harm on the women of Banu al-Mughirah in shedding their tears for Abu Sulayman, as long as there is no wailing." He was buried in Homs, and his grave is known there to this day.',
      'Khalid ibn al-Walid remains in the history of Islam the Drawn Sword of Allah, the commander who was never defeated. He lived a life of horsemanship and jihad, and conquered with his sword half the ancient world — Sham and Iraq. His obedience to command was a sign. When Umar removed him he accepted with an open chest, did not compete or stir trouble. He set the greatest example of the commander who obeys even if he is not convinced. O Allah, be pleased with Khalid and raise his rank in the highest Paradise.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 15. عبد الله بن مسعود رضي الله عنه — أعلم الصحابة بالقرآن
  // ──────────────────────────────────────────────────────────────────────
  'ibn-masud': {
    ar: P([
      'هو عبد الله بن مسعود بن غافل بن حبيب الهذلي. وُلد بمكة قبل البعثة بنحو ست وعشرين سنة. كان من قبيلة هذيل، وكان فقيرًا، يعمل في رعي غنم لعقبة بن أبي معيط — أحد المشركين الكبار. كان شخصًا صغير الجسم، نحيلًا، حافي القدمين، يعمل بأجر زهيد. لا أحد كان يلقي له بالًا.',
      'قصة إسلامه عجيبة. كان يومًا يرعى الغنم في طرف مكة، فمر به النبي ﷺ ومعه أبو بكر الصديق. كانا جائعين عطشانين. سألاه أن يحلب لهما من الغنم. قال: لست بالذي يحلب — أي لا أستطيع لأنها ليست لي. أعجب النبي ﷺ بأمانته. قال: هل من شاة لم ينزُ عليها الفحل؟ — أي شاة لم تحبل ولا لبن فيها. قال: نعم. أتى بها.',
      'مسح النبي ﷺ على ضرعها ودعا، فدرّ منها لبن كثير. شربا وسقياه. تعجب عبد الله غاية العجب — كيف تدرّ شاة لا لبن لها؟ ثم قال للنبي ﷺ: علّمني من هذا القول. قال النبي ﷺ: إنك غلام مُعَلَّم. كانت إشارة من النبي ﷺ بأنه سيتعلم الكثير ويصبح من أعلم الناس.',
      'أسلم في الحال. كان السادس في الإسلام من السابقين الأولين. لما أسلم، صار يدخل بيت النبي ﷺ بإذنه في أي وقت، حتى قال عمر بن الخطاب: لا يحجب ابن مسعود عني حين حضرت. كان من خواصّ النبي ﷺ الذين يدخلون عليه في أي وقت.',
      'صار أول من جهر بالقرآن في مكة. خرج إلى الكعبة، حيث كانت قريش متجمعة، ووقف وقرأ بصوت عالٍ: بسم الله الرحمن الرحيم، الرحمن، علّم القرآن. غضبت قريش غضبًا شديدًا. قاموا إليه وضربوه ضربًا شديدًا حتى أدموا وجهه. رجع إلى النبي ﷺ وآثار الضرب على وجهه. قال له: أتسمعوا غدًا. قال النبي ﷺ: أصبحت أحب إلي من نفسي.',
      'هاجر إلى المدينة. شارك في كل غزوات النبي ﷺ ابتداءً من بدر. في غزوة بدر، حدثت قصة عجيبة. أبو جهل — رأس المشركين — كان قد سقط جريحًا في الميدان. مرّ به عبد الله بن مسعود، وكان صغيرًا نحيفًا. قال أبو جهل ساخرًا: لقد ارتقيت مرتقى صعبًا يا رويعي الغنم — أي يا راعي الغنم الصغير. قال ابن مسعود: لله ولرسوله الحمد. ثم قطع رأس أبي جهل. كل الذي ضربه في مكة، انتقم منه في يوم واحد.',
      'كان من أعلم الصحابة بالقرآن. حفظ من فم النبي ﷺ سبعين سورة. قال النبي ﷺ: من أراد أن يقرأ القرآن غضًّا كما أُنزل، فليقرأه على قراءة ابن أم عبد — أي ابن مسعود. كان النبي ﷺ يحب صوته في القرآن. قال له يومًا: اقرأ علي القرآن يا ابن مسعود. قال: أأقرأ عليك وعليك أُنزل؟ قال: نعم، إني أحب أن أسمعه من غيري. فقرأ ابن مسعود من سورة النساء، حتى وصل إلى آية: فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيدًا. فبكى النبي ﷺ وقال: حسبك. كانت آية تؤرّقه.',
      'كان فقيهًا عظيمًا. عمر بن الخطاب وعثمان بن عفان أرسلاه إلى الكوفة ليعلّم الناس فيها القرآن والفقه. صار ابن مسعود مرجع الكوفة. كل علماء الكوفة الذين جاؤوا بعده — كأبي حنيفة وغيره — يرجعون إلى ابن مسعود في كثير من فقههم. وصار مذهب الكوفة في الفقه مبنيًا أساسًا على فقه ابن مسعود.',
      'كان يحب التواضع. كان قصير القامة، نحيف الساقين. صعد يومًا على شجرة، فجاءت ريح فحركته على فروع الشجرة. ضحك بعض الصحابة من نحالة ساقيه. غضب النبي ﷺ وقال: أتضحكون من ساقي ابن مسعود؟ والذي نفسي بيده، إنهما لأثقل في الميزان من جبل أحد. أي أعماله الصالحة أثقل من جبل أحد في الميزان، لا تنخدعوا بصغر جسمه.',
      'لما تولى عثمان الخلافة، أرسل ابن مسعود إلى الكوفة عاملًا على بيت المال. لكن بعد سنين، اختلف ابن مسعود مع الوالي الجديد للكوفة — الوليد بن عقبة — في بعض الأمور. اشتكاه إلى عثمان، فأمر عثمان بنقل ابن مسعود إلى المدينة. حدث بعد ذلك خلاف بين ابن مسعود وعثمان حول مصاحفه، إذ أمر عثمان بحرق المصاحف الفردية بعد جمع المصحف العثماني الموحد. غضب ابن مسعود من ذلك في البداية، ثم رضي به.',
      'كانت سيرته في المدينة بعد عودته زهدًا ومحاسبة. لما حضرته الوفاة سنة 32 هـ، جاء عثمان يعوده. سأله: ما تشتكي؟ قال: ذنوبي. قال: ما تشتهي؟ قال: رحمة ربي. قال: ألا أدعو لك بطبيب؟ قال: الطبيب أمرضني. قال: ألا آمر لك بعطائك؟ — وكان عثمان قد قطع عنه عطاءه لخلاف سابق — قال: لا حاجة لي به. قال: يكون لبناتك من بعدك. قال: أتخشى على بناتي الفقر؟ إني قد أمرتهن أن يقرأن كل ليلة سورة الواقعة، لأني سمعت رسول الله ﷺ يقول: من قرأ الواقعة كل ليلة لم تصبه فاقة أبدًا.',
      'مات ابن مسعود في المدينة، وعمره نحو ستين سنة. صلى عليه عثمان أو الزبير على خلاف بين الروايات. دفن بالبقيع. ترك مدرسة فقهية كاملة هي مدرسة الكوفة، التي خرّجت جيلًا من العلماء بعده.',
      'يبقى عبد الله بن مسعود في تاريخ الإسلام نموذجًا للفقير الذي رفعه الإسلام. كان راعي غنم نحيلًا، فصار من أعظم علماء الأمة. علّم قراءة القرآن لجيل كامل في الكوفة. كان صغير الجسم، لكن أعماله ساقاه أثقل من جبل أحد. اللهم ارضَ عن ابن مسعود، وارزقنا علمًا كعلمه، وزهدًا كزهده، وحبًا للنبي ﷺ كحبه.',
    ]),
    en: P([
      'He is Abdullah ibn Mas\'ud ibn Ghafil ibn Habib al-Hudhali. He was born in Makkah about twenty-six years before the mission. He was of the tribe of Hudhayl and was poor, working as a shepherd for Uqbah ibn Abi Mu\'ayt — one of the major polytheists. He was a small-bodied, slender person, walked barefoot, worked for meagre wages. No one paid him any attention.',
      'The story of his Islam is remarkable. He was one day shepherding at the edge of Makkah when the Prophet ﷺ passed by him with Abu Bakr al-Siddiq. They were hungry and thirsty. They asked him to milk one of the sheep for them. He said: "I am not the one to milk it" — meaning I cannot because they are not mine. The Prophet ﷺ was impressed by his trustworthiness. He said: "Is there a sheep that no male has mounted?" — meaning one that has not conceived and has no milk. He said: "Yes." He brought her.',
      'The Prophet ﷺ wiped her udder and prayed, and abundant milk flowed from her. They drank and gave him to drink. Abdullah was astonished — how does a sheep without milk give milk? He then said to the Prophet ﷺ: "Teach me of this speech." The Prophet ﷺ said: "You are an instructed youth." It was an indication from the Prophet ﷺ that he would learn much and become among the most knowledgeable of people.',
      'He embraced Islam at once. He was the sixth in Islam among the very first. When he embraced Islam, he came to enter the Prophet\'s ﷺ house with his permission at any time, until Umar ibn al-Khattab said: "Ibn Mas\'ud is not to be screened from me when I am present." He was among the elite of the Prophet ﷺ who entered upon him at any time.',
      'He was the first to recite the Qur\'an aloud in Makkah. He went out to the Ka\'bah where Quraysh was gathered, stood, and recited loudly: "In the name of Allah, the Most Merciful, the Most Compassionate. The Most Merciful taught the Qur\'an." Quraysh became very angry. They rose against him and beat him severely until they bloodied his face. He returned to the Prophet ﷺ with the marks of the beating on his face. He said to him: "Shall they hear tomorrow?" The Prophet ﷺ said: "You have become more beloved to me than myself."',
      'He emigrated to Madinah. He participated in every campaign of the Prophet ﷺ starting from Badr. At Badr a striking story occurred. Abu Jahl — the head of the polytheists — had fallen wounded in the field. Abdullah ibn Mas\'ud passed by him, small and slender. Abu Jahl said mockingly: "You have climbed a difficult ascent, O little shepherd of sheep." Ibn Mas\'ud said: "To Allah and His Messenger belongs the praise." Then he cut off Abu Jahl\'s head. All those who beat him in Makkah, he avenged in a single day.',
      'He was among the most knowledgeable Companions of the Qur\'an. He memorised from the Prophet\'s ﷺ mouth seventy surahs. The Prophet ﷺ said: "Whoever wishes to recite the Qur\'an fresh as it was revealed, let him recite it in the recitation of Ibn Umm Abd" — meaning Ibn Mas\'ud. The Prophet ﷺ loved his voice in the Qur\'an. He said to him one day: "Recite the Qur\'an to me, Ibn Mas\'ud." He said: "Shall I recite to you when it was revealed to you?" He said: "Yes, I love to hear it from another." Ibn Mas\'ud recited from Surah al-Nisa\', until he reached the verse: "How then if We brought from each nation a witness, and We brought you as a witness against these?" The Prophet ﷺ wept and said: "Enough." It was a verse that troubled him.',
      'He was a great jurist. Umar ibn al-Khattab and Uthman ibn Affan sent him to Kufa to teach the people there the Qur\'an and jurisprudence. Ibn Mas\'ud became the reference of Kufa. All the scholars of Kufa who came after him — such as Abu Hanifah and others — refer to Ibn Mas\'ud in much of their jurisprudence. The Kufan school of jurisprudence is essentially built on Ibn Mas\'ud\'s jurisprudence.',
      'He loved humility. He was short of stature, slender of leg. He once climbed a tree, and a wind came and moved him on the branches. Some Companions laughed at the slenderness of his legs. The Prophet ﷺ became angry and said: "Do you laugh at the legs of Ibn Mas\'ud? By Him in whose hand is my soul, they are heavier in the scale than Mount Uhud." His good deeds are heavier than Mount Uhud in the scale; do not be deceived by the smallness of his body.',
      'When Uthman took the caliphate, he sent Ibn Mas\'ud to Kufa as an officer over the treasury. But after years, Ibn Mas\'ud disagreed with the new governor of Kufa — al-Walid ibn Uqbah — in some matters. He complained to Uthman, who ordered Ibn Mas\'ud transferred to Madinah. A disagreement then arose between Ibn Mas\'ud and Uthman about his Mushafs, as Uthman ordered the burning of individual Mushafs after compiling the unified Uthmanic Mushaf. Ibn Mas\'ud became angry about that at first, then accepted it.',
      'His life in Madinah after his return was asceticism and self-accounting. When death approached him in 32 AH, Uthman came to visit him. He asked: "What do you complain of?" He said: "My sins." He said: "What do you desire?" He said: "The mercy of my Lord." He said: "Shall I call a physician for you?" He said: "The Physician has made me ill." He said: "Shall I order your stipend for you?" — Uthman had cut off his stipend over an earlier dispute — He said: "I have no need of it." He said: "It will be for your daughters after you." He said: "Do you fear poverty for my daughters? I have ordered them to recite Surah al-Waqi\'ah every night, for I heard the Messenger of Allah ﷺ say: ‘Whoever recites al-Waqi\'ah every night, poverty will never strike him.’"',
      'Ibn Mas\'ud died in Madinah, at about sixty years of age. Uthman or al-Zubayr prayed over him — narrations differ. He was buried in al-Baqi\'. He left a complete school of jurisprudence — the Kufan school — which produced a generation of scholars after him.',
      'Abdullah ibn Mas\'ud remains in the history of Islam a model of the poor whom Islam raised. He was a slender shepherd of sheep, then became among the greatest scholars of the Ummah. He taught the recitation of the Qur\'an to an entire generation in Kufa. He was small-bodied, but his two legs were heavier than Mount Uhud. O Allah, be pleased with Ibn Mas\'ud, grant us knowledge like his knowledge, asceticism like his asceticism, and love for the Prophet ﷺ like his love.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 16. سعد بن معاذ رضي الله عنه — سيد الأوس
  // ──────────────────────────────────────────────────────────────────────
  'saad-muadh': {
    ar: P([
      'هو سعد بن معاذ بن النعمان بن امرئ القيس الأوسي الأنصاري. ولد بيثرب — المدينة — قبل البعثة بنحو ست وثلاثين سنة. كان من سادات الأوس، وكانت قبيلة الأوس من القبيلتين الكبيرتين في يثرب مع الخزرج. كان رجلًا قويًا، صاحب رأي وحكمة، تطيعه قبيلته بنو عبد الأشهل.',
      'أسلم على يد مصعب بن عمير، السفير الأول للنبي ﷺ إلى المدينة. كانت قصة إسلامه عجيبة. لما جاء مصعب إلى المدينة، بدأ يدعو الناس إلى الإسلام. أرسل إليه سعد بن معاذ ابن خاله أُسيد بن حضير ليطرده. أتى أسيد إلى مصعب غاضبًا، فقال له مصعب: اجلس فاسمع، فإن رضيت أمرنا قبلته، وإن كرهت كففنا عنك ما تكره. سمع أسيد القرآن، فأسلم في الحال.',
      'رجع أسيد إلى سعد. لما رآه سعد، قال: لقد جاءني بغير الوجه الذي ذهب به. غضب سعد وقام بنفسه إلى مصعب. قال له مثل ما قال أسيد: اجلس فاسمع. سمع سعد القرآن، فأسلم في الحال أيضًا. ثم رجع إلى قومه — بني عبد الأشهل — وقال لهم: يا بني عبد الأشهل، كيف تعلمون أمري فيكم؟ قالوا: سيدنا، وأفضلنا رأيًا، وأيمننا نقيبة. قال: فإن كلام رجالكم ونسائكم عليّ حرام حتى تؤمنوا بالله ورسوله. فأسلمت بنو عبد الأشهل كلها في يوم واحد، رجالهم ونساؤهم.',
      'لما هاجر النبي ﷺ إلى المدينة، كان سعد من المستقبلين له. آخى النبي ﷺ بينه وبين أبي عبيدة بن الجراح. شارك في غزوة بدر. لكن دوره العظيم كان في غزوة الأحزاب — الخندق.',
      'في غزوة الأحزاب سنة 5 هـ، حاصرت الأحزاب — قريش واليهود والقبائل العربية — المدينة لأسابيع. كان سعد قائد الأنصار في الخندق. أصابه سهم في تلك الغزوة، اخترق ذراعه وقطع شريانًا. قال سعد دعاءه الشهير: اللهم إن كنت أبقيت من حرب قريش شيئًا فأبقني لها، فإنه لا قوم أحب إلي من أن أجاهدهم من قوم آذوا رسولك. وإن كنت قد وضعت الحرب بيننا وبينهم، فاجعلها لي شهادة، ولا تمتني حتى تقرّ عيني من بني قريظة.',
      'كان بنو قريظة من اليهود الذين نقضوا العهد مع النبي ﷺ في غزوة الأحزاب. لما انقضت الأحزاب وعادت قريش، حاصر النبي ﷺ بني قريظة. ولأن سعدًا كان حليفهم في الجاهلية، طلبوا أن يحكّم سعد في أمرهم. وافق النبي ﷺ.',
      'جاؤوا بسعد محمولًا على حمار من شدة جرحه. لما اقترب، قال النبي ﷺ للأنصار: قوموا إلى سيدكم. أكرمه النبي ﷺ بهذه العبارة. حكم سعد بحكم الله: أن تُقتل مقاتلة بني قريظة، وتسبى ذراريهم. كان حكمه قاسيًا لكنه كان موافقًا لحكم الله في التوراة نفسها في حق من نقض العهد في الحرب. قال النبي ﷺ: لقد حكمت بحكم الله من فوق سبع سماوات.',
      'بعد حكمه على بني قريظة، انتقض جرحه. سال الدم منه. أصابته الحمى. كان قد دعا الله ألا يميته حتى يقرّ عينه من بني قريظة. بعد أن قرّت عينه، استجاب الله الدعاء بأن ييتقبل شهادته. مات سعد رضي الله عنه من جرحه.',
      'لما مات، اهتزّ عرش الرحمن لموته — كما في الحديث الصحيح. قال النبي ﷺ: لقد اهتزّ عرش الرحمن لموت سعد بن معاذ. هذا شرف لم ينله غير قليلين من البشر. اهتزاز العرش علامة على عظم منزلة سعد عند الله، وعلى فرح الملائكة بنفسه الصاعدة.',
      'ولما جاء أهله ليكفنوه، كان النبي ﷺ يحضر جنازته. شيّعه سبعون ألف ملك من الملائكة لم ينزلوا إلى الأرض من قبل. قال النبي ﷺ: ينزل سبعون ألفًا من الملائكة لم يطؤوا الأرض قبل اليوم. هذا تشريف فوق التصوّر — جنازة سعد كانت أعظم جنازة شهدتها الأرض.',
      'دفن سعد في البقيع. كان عمره يومئذ نحو سبع وثلاثين سنة فقط. عاش حياة قصيرة لكنها كانت ممتلئة بالعمل العظيم. أسلم عام الهجرة، ومات سنة 5 هـ — أي خمس سنوات فقط من حياته في الإسلام. ومع ذلك حقّق في هذه السنوات الخمس ما لم يحققه غيره في عمر كامل.',
      'كان قبل وفاته في حالة هدوء ورضا. سمعت أمه — وكانت لا تزال حية — تبكي عليه. فقال لها: مهلًا يا أماه، لا تبكي. قال النبي ﷺ يومئذ: كل النادبة تكذب إلا أمّ سعد. كانت أمه صادقة في حزنها عليه، لأن سعدًا كان جوهرة حقيقية بكل ما تعنيه الكلمة.',
      'يبقى سعد بن معاذ في تاريخ الإسلام سيد الأوس، حاكم بني قريظة، الذي اهتزّ عرش الرحمن لموته. أسلم على يد مصعب، فأسلمت قبيلته كلها في يوم. مات بعد خمس سنوات فقط من إسلامه، لكنه ترك أعظم الأثر. كم من إنسان عاش عمرًا طويلًا ولم يترك أثرًا، وكم من إنسان عاش قصيرًا فترك التاريخ كله. اللهم ارضَ عن سعد، واجمعنا به في جنات النعيم.',
    ]),
    en: P([
      'He is Sa\'d ibn Mu\'adh ibn al-Nu\'man ibn Imri\' al-Qays al-Awsi al-Ansari. He was born in Yathrib — Madinah — about thirty-six years before the mission. He was among the chiefs of the Aws, and Aws was one of the two large tribes in Yathrib with the Khazraj. He was a strong man, possessing opinion and wisdom, his tribe Banu Abd al-Ashhal obeyed him.',
      'He embraced Islam at the hand of Mus\'ab ibn Umayr, the Prophet\'s ﷺ first ambassador to Madinah. The story of his Islam is remarkable. When Mus\'ab came to Madinah, he began calling people to Islam. Sa\'d ibn Mu\'adh sent his cousin Usayd ibn Hudayr to drive him out. Usayd came to Mus\'ab angry, and Mus\'ab said to him: "Sit and listen; if you accept our matter, take it; if you dislike it, we will refrain from what you dislike." Usayd heard the Qur\'an and embraced Islam at once.',
      'Usayd returned to Sa\'d. When Sa\'d saw him, he said: "He has come to me with a different face than the one he left with." Sa\'d became angry and rose himself to Mus\'ab. He said to him as Usayd had said: "Sit and listen." Sa\'d heard the Qur\'an and embraced Islam at once too. He then returned to his people — Banu Abd al-Ashhal — and said to them: "O Banu Abd al-Ashhal, how do you know my matter among you?" They said: "Our chief, the best of opinion among us, the most blessed in counsel." He said: "Then the speech of your men and women is forbidden upon me until you believe in Allah and His Messenger." All of Banu Abd al-Ashhal embraced Islam in a single day, men and women.',
      'When the Prophet ﷺ emigrated to Madinah, Sa\'d was among those who received him. The Prophet ﷺ joined him in brotherhood with Abu Ubaydah ibn al-Jarrah. He participated in the Battle of Badr. But his great role was in the Battle of the Confederates — the Trench.',
      'In the Battle of the Confederates in 5 AH, the Confederates — Quraysh, the Jews, and the Arab tribes — besieged Madinah for weeks. Sa\'d was the commander of the Ansar at the Trench. An arrow struck him in that battle, piercing his arm and cutting an artery. Sa\'d said his famous supplication: "O Allah, if You have left any of the war with Quraysh, leave me for it, for there is no people I would rather fight than a people who have harmed Your Messenger. And if You have laid the war between us and them to rest, make it for me martyrdom, and do not cause me to die until You have cooled my eye over Banu Qurayzah."',
      'Banu Qurayzah were Jews who had broken the covenant with the Prophet ﷺ during the Battle of the Confederates. When the Confederates departed and Quraysh returned, the Prophet ﷺ besieged Banu Qurayzah. Because Sa\'d had been their ally in the Jahiliyyah, they asked that Sa\'d arbitrate in their matter. The Prophet ﷺ agreed.',
      'They brought Sa\'d carried on a donkey from the severity of his wound. When he drew near, the Prophet ﷺ said to the Ansar: "Stand for your chief." The Prophet ﷺ honoured him with this phrase. Sa\'d gave the ruling of Allah: that the fighting men of Banu Qurayzah be killed and their descendants taken captive. His ruling was harsh but in accordance with Allah\'s ruling in the Torah itself concerning those who breach a covenant in war. The Prophet ﷺ said: "You have ruled with the ruling of Allah from above seven heavens."',
      'After his ruling on Banu Qurayzah, his wound opened. Blood flowed from him. Fever struck him. He had supplicated Allah not to let him die until his eye was cooled over Banu Qurayzah. After his eye was cooled, Allah answered the supplication by accepting his martyrdom. Sa\'d died, may Allah be pleased with him, from his wound.',
      'When he died, the Throne of the Most Merciful shook for his death — as in the authentic hadith. The Prophet ﷺ said: "The Throne of the Most Merciful shook for the death of Sa\'d ibn Mu\'adh." This is an honour only a few of humanity have received. The shaking of the Throne is a sign of the greatness of Sa\'d\'s rank with Allah, and of the angels\' joy at his ascending soul.',
      'When his family came to shroud him, the Prophet ﷺ attended his funeral. Seventy thousand angels who had not descended to earth before escorted him. The Prophet ﷺ said: "Seventy thousand angels descended who had not stepped on earth before today." This is honour beyond imagination — Sa\'d\'s funeral was the greatest funeral the earth has witnessed.',
      'Sa\'d was buried in al-Baqi\'. He was about thirty-seven years old. He lived a short life but it was filled with great work. He embraced Islam in the year of the Hijrah and died in 5 AH — only five years of his life in Islam. Yet in these five years he accomplished what others did not accomplish in an entire lifetime.',
      'Before his death he was in a state of calm and contentment. He heard his mother — still alive — weeping for him. He said to her: "Gently, mother; do not weep." The Prophet ﷺ said that day: "Every wailer lies except the mother of Sa\'d." His mother was truthful in her grief, because Sa\'d was a true jewel in every sense.',
      'Sa\'d ibn Mu\'adh remains in the history of Islam the chief of the Aws, the arbiter of Banu Qurayzah, for whose death the Throne of the Most Merciful shook. He embraced Islam at the hand of Mus\'ab, and his entire tribe embraced Islam in a single day. He died only five years after his Islam, but he left the greatest mark. How many a person lived a long life and left no mark, and how many lived briefly and left all of history. O Allah, be pleased with Sa\'d and gather us with him in the Gardens of Bliss.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 17. أسعد بن زرارة رضي الله عنه — أول من بايع في العقبة
  // ──────────────────────────────────────────────────────────────────────
  'asad-zurara': {
    ar: P([
      'هو أسعد بن زرارة بن عُدُس بن عبيد، الأنصاري الخزرجي. وُلد بيثرب قبل البعثة بنحو ثلاثين سنة. كان من سادات الخزرج، وكان عاقلًا ذا رأي. أحد الستة الذين أسلموا من أهل المدينة في موسم الحج قبل الهجرة.',
      'قصة إسلامه قبل الهجرة بسنتين. خرج إلى مكة في الحج، فالتقى بالنبي ﷺ. كان عددهم ستة من الأنصار، كلهم من الخزرج. سمعوا النبي ﷺ يدعوهم إلى الإسلام، فأسلموا. كان أسعد أحد هؤلاء الستة. رجعوا إلى المدينة يبشرون قومهم بالإسلام.',
      'في العام التالي، جاء اثنا عشر من الأنصار إلى مكة في الحج. كان أسعد أحدهم. التقوا بالنبي ﷺ عند عقبة منى — مكان قرب مكة. هناك بايعوا النبي ﷺ بيعة سُمّيت بـ بيعة العقبة الأولى. كان أسعد أول من بايع في تلك البيعة. صار من السابقين الأولين من الأنصار.',
      'لما رجعوا إلى المدينة، طلبوا من النبي ﷺ أن يرسل معهم من يعلمهم القرآن. أرسل النبي ﷺ مصعب بن عمير معهم. نزل مصعب في بيت أسعد بن زرارة، فكان بيت أسعد أول دار للإسلام في المدينة. فيها كانت تجتمع الناس لسماع القرآن والإسلام.',
      'كان أسعد يحمي مصعبًا، يدخل به على قبائل الأنصار يدعوهم إلى الإسلام. لولا أسعد لما تمكن مصعب من الحركة في المدينة. كانت دار أسعد قاعدة دعوة، ومدرسة قرآن، ومسجدًا للصلوات.',
      'أسعد كان أول من جمّع في الإسلام — أي أول من صلى صلاة الجمعة. كانت صلاة الجمعة لم تُفرض بعد بشكلها الحالي، لكن أسعد جمع مع الأنصار في بستان قرب المدينة، صلوا فيه أربعين رجلًا. هذه أول جماعة جمعة في الإسلام، قبل أن يهاجر النبي ﷺ إلى المدينة.',
      'في السنة التالية، جاء أهل المدينة في موسم الحج، وكانوا ثلاثة وسبعين رجلًا وامرأتين من الأنصار. التقوا بالنبي ﷺ عند نفس العقبة. كانت بيعة العقبة الثانية. بايعوا النبي ﷺ على أن يهاجر إليهم وعلى أن ينصروه. كان أسعد بن زرارة أحد النقباء الاثني عشر الذين عيّنهم النبي ﷺ ليقودوا الأنصار.',
      'لما هاجر النبي ﷺ إلى المدينة، نزل في بداية الأمر في بيت أبي أيوب الأنصاري. ثم بنى مسجده الشريف. كان البستان الذي بُني فيه المسجد لغلامين يتيمين من بني النجار، يكفلهما أسعد بن زرارة. اشترى النبي ﷺ البستان منهما — أو وهبه أسعد للنبي — وأقام عليه المسجد النبوي.',
      'لم يعمّر أسعد كثيرًا في المدينة. مات بعد سنتين فقط من الهجرة، قبل غزوة بدر بأشهر. مرض مرضًا شديدًا اسمه الذُّبحة — التهاب في الحلق. توفي في السنة الأولى أو الثانية من الهجرة، وعمره نحو اثنتين وثلاثين سنة. ترك بنات ولم يترك ذكورًا.',
      'حزن النبي ﷺ على موته حزنًا شديدًا. قال: مات سيدنا. كان أسعد سيد الخزرج بعد إسلامه. ولكن بعد موته، اختلف الأنصار: من يكون سيدنا بعد أسعد؟ قال النبي ﷺ كلمة جامعة: أنتم إخواني وأنا منكم. لم يعيّن سيدًا واحدًا، إنما جعلهم إخوة متساوين، لا سيد فيهم إلا الله ورسوله.',
      'دفن أسعد في البقيع — كأول من دفن من الأنصار في البقيع. كان قبره أول مقبرة المسلمين في المدينة. توالت بعده الجنائز، حتى صار البقيع أعظم مقبرة في تاريخ الإسلام، فيه مئة ألف من الصحابة والتابعين.',
      'كان أسعد من أعلام الإسلام رغم قصر عمره. الإسلام في المدينة كله بدأ في داره. لولا أسعد، لما تمكن مصعب من نشر الإسلام، ولما كانت الهجرة سهلة، ولما كان للنبي ﷺ مكان آمن يهاجر إليه. كان حجر الأساس للدولة الإسلامية الأولى.',
      'يبقى أسعد بن زرارة في تاريخ الإسلام أول من بايع في العقبة، أحد النقباء، أول من جمّع في الإسلام، صاحب أول دار للإسلام في المدينة، وأول من دفن في البقيع. حياته قصيرة، لكن أثره عظيم. اللهم ارضَ عن أسعد، واجمعنا به في جنات النعيم.',
    ]),
    en: P([
      'He is As\'ad ibn Zurarah ibn Udus ibn Ubayd, al-Ansari al-Khazraji. He was born in Yathrib about thirty years before the mission. He was among the chiefs of the Khazraj, and was wise of opinion. One of the six who embraced Islam from Madinah at the Hajj season before the Hijrah.',
      'The story of his Islam is two years before the Hijrah. He went out to Makkah for Hajj and met the Prophet ﷺ. They were six of the Ansar, all of the Khazraj. They heard the Prophet ﷺ calling them to Islam, and they embraced Islam. As\'ad was one of these six. They returned to Madinah giving glad tidings to their people of Islam.',
      'The following year, twelve of the Ansar came to Makkah for Hajj. As\'ad was one of them. They met the Prophet ﷺ at the Aqabah of Mina — a place near Makkah. There they pledged allegiance to the Prophet ﷺ in a pledge called the First Pledge of Aqabah. As\'ad was the first to pledge in that allegiance. He became among the very first of the Ansar.',
      'When they returned to Madinah, they asked the Prophet ﷺ to send with them someone to teach them the Qur\'an. The Prophet ﷺ sent Mus\'ab ibn Umayr with them. Mus\'ab stayed in the house of As\'ad ibn Zurarah, so As\'ad\'s house was the first house of Islam in Madinah. In it people gathered to hear the Qur\'an and Islam.',
      'As\'ad protected Mus\'ab, taking him to the Ansar tribes calling them to Islam. Without As\'ad, Mus\'ab could not have moved in Madinah. As\'ad\'s house was a base of da\'wah, a school of Qur\'an, and a mosque for prayers.',
      'As\'ad was the first to hold the Jumu\'ah in Islam — the first to pray Jumu\'ah. The Jumu\'ah prayer had not yet been ordained in its current form, but As\'ad gathered the Ansar in a garden near Madinah; forty men prayed in it. This was the first Jumu\'ah congregation in Islam, before the Prophet ﷺ emigrated to Madinah.',
      'The following year, the people of Madinah came in the Hajj season, seventy-three men and two women of the Ansar. They met the Prophet ﷺ at the same Aqabah. It was the Second Pledge of Aqabah. They pledged allegiance to the Prophet ﷺ that he would emigrate to them and that they would support him. As\'ad ibn Zurarah was one of the twelve chiefs whom the Prophet ﷺ appointed to lead the Ansar.',
      'When the Prophet ﷺ emigrated to Madinah, he stayed at first in the house of Abu Ayyub al-Ansari. Then he built his noble mosque. The garden on which the mosque was built belonged to two orphan boys of Banu al-Najjar, whom As\'ad ibn Zurarah was guardian over. The Prophet ﷺ bought the garden from them — or As\'ad gifted it to the Prophet — and built the Prophet\'s Mosque upon it.',
      'As\'ad did not live long in Madinah. He died only two years after the Hijrah, months before the Battle of Badr. He fell into a severe illness called dhubhah — an inflammation of the throat. He died in the first or second year of the Hijrah, at about thirty-two years of age. He left daughters but no sons.',
      'The Prophet ﷺ grieved severely over his death. He said: "Our chief has died." As\'ad was the chief of the Khazraj after his Islam. After his death, the Ansar disagreed: who would be our chief after As\'ad? The Prophet ﷺ said a comprehensive word: "You are my brothers, and I am one of you." He did not appoint a single chief; rather he made them equal brothers, with no chief among them but Allah and His Messenger.',
      'As\'ad was buried in al-Baqi\' — as the first of the Ansar to be buried in al-Baqi\'. His grave was the first Muslim grave in Madinah. Funerals followed him in succession, until al-Baqi\' became the greatest cemetery in the history of Islam, holding a hundred thousand Companions and Successors.',
      'As\'ad was among the foremost of Islam despite his short life. Islam in Madinah began entirely in his house. Without As\'ad, Mus\'ab could not have spread Islam, the Hijrah would not have been easy, and the Prophet ﷺ would not have had a safe place to emigrate to. He was the cornerstone of the first Islamic state.',
      'As\'ad ibn Zurarah remains in the history of Islam the first to pledge at Aqabah, one of the chiefs, the first to hold the Jumu\'ah in Islam, owner of the first house of Islam in Madinah, and the first to be buried in al-Baqi\'. His life was short, but his impact great. O Allah, be pleased with As\'ad and gather us with him in the Gardens of Bliss.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 18. أبو أيوب الأنصاري رضي الله عنه — مضيف رسول الله
  // ──────────────────────────────────────────────────────────────────────
  'abu-ayyub': {
    ar: P([
      'هو خالد بن زيد بن كُليب بن ثعلبة، الأنصاري الخزرجي النجاري. اشتُهر بكنيته أبو أيوب. وُلد في يثرب — المدينة — قبل البعثة بنحو خمس وعشرين سنة. من قبيلة بني النجار، التي كانت أم النبي ﷺ آمنة بنت وهب من خئولتها.',
      'بايع النبي ﷺ في بيعة العقبة الثانية، فهو من السابقين الأنصار. لما هاجر النبي ﷺ إلى المدينة، تنافست الأنصار على من ينزل النبي عنده. كل قبيلة كانت تأخذ بزمام ناقة النبي ﷺ القصواء وتقول: انزل عندنا يا رسول الله. كان النبي يقول: خلّوا سبيلها فإنها مأمورة.',
      'مشت الناقة في طرقات المدينة، حتى بركت عند موضع المسجد النبوي اليوم. كان أقرب البيوت إليها بيت أبي أيوب الأنصاري. فقام أبو أيوب فأخذ رحل النبي ﷺ — متاعه — وحمله إلى داره. قال: يا رسول الله، إن بيتي أقرب البيوت. أعجب النبي ﷺ بسرعته وحبه، فنزل في بيت أبي أيوب.',
      'كان بيت أبي أيوب طابقين. أراد أبو أيوب أن ينزل النبي ﷺ في الطابق العلوي إكرامًا له. لكن النبي ﷺ قال: يا أبا أيوب، إنه أرفق بنا وبمن يغشانا أن نكون في سفل البيت. فنزل النبي ﷺ في الطابق السفلي، وصعد أبو أيوب وأم أيوب — زوجته — إلى الطابق العلوي.',
      'لم يهنأ أبو أيوب وزوجته بنومهما تلك الليلة. كانا فوق رأس النبي ﷺ، فخافا أن يقع منهما شيء على النبي. قاما ليلتهما تلك يمشيان على أطراف الجدران، يخافان من خفقة قدم تُسمع. في الصباح، نزل أبو أيوب إلى النبي ﷺ وأخبره. قال له: لا تفعل، إنما هي راحتك. لكن أبا أيوب أصرّ. فأمر النبي ﷺ بأن يصعد إلى الطابق العلوي.',
      'كان النبي ﷺ يأكل من طعام أبي أيوب. كانت أم أيوب تطبخ وتقدّم للنبي ﷺ. كان النبي ﷺ يأكل قليلًا، فيرسل أبو أيوب ما تبقى ليأكله هو وأهله. كان يأكل أبو أيوب وأم أيوب من نفس الإناء الذي أكل منه النبي ﷺ، يلتمسان البركة.',
      'بقي النبي ﷺ في بيت أبي أيوب نحو سبعة أشهر، حتى بُني المسجد النبوي وحجرات أمهات المؤمنين. ثم انتقل إلى حجرته. لكن العلاقة بين النبي وأبي أيوب لم تنقطع. كان أبو أيوب من خواصّ النبي ﷺ.',
      'شارك أبو أيوب في كل غزوات النبي ﷺ ابتداءً من بدر. كان شجاعًا، ثابتًا، يقاتل في صفوف الأمام. لم يتخلف عن غزوة طوال حياة النبي ﷺ. وبعد وفاة النبي، استمر في الجهاد. شارك في فتوح الشام مع أبي عبيدة.',
      'كان أبو أيوب من المتمسكين بحب علي بن أبي طالب. في الفتنة بين علي ومعاوية، كان أبو أيوب مع علي، وشارك في معركة الجمل وصفّين والنهروان في صف علي. بعد مقتل علي، لم يبايع معاوية. كان من القلائل الذين بقوا على رأي علي حتى مات.',
      'في عهد معاوية، خرج أبو أيوب لجهاد الروم. كان عمره يومئذ نحو ثمانين سنة. لم يستطع أن يجلس في المدينة وغيره يجاهد. قال: لقد سمعت الله يقول: انفروا خفافًا وثقالًا. ولا أرى الله إلا قد ذكرنا فيها — يقصد كبار السن. شارك في الحملة البحرية لفتح القسطنطينية سنة 52 هـ.',
      'مرض أبو أيوب في الحملة. كان الجيش الإسلامي يحاصر القسطنطينية — عاصمة الروم. علم أن أجله قد قرب. أوصى يزيد بن معاوية — وكان قائد الجيش — أن يدفنه في أرض الروم، أبعد ما يستطيع. قال: ادفنوني تحت أقدام الفرس. سُئل: لِم؟ قال: حدثني رسول الله ﷺ أن هذه الأمة ستفتح القسطنطينية، فإن قُتلت ودفنتموني تحت أقدام أعدائكم، عسى الله أن يبعثني بين هؤلاء فأشهد فتحها.',
      'مات أبو أيوب رضي الله عنه سنة 52 هـ، وعمره نحو ثمانين سنة أو أكثر. دفنه يزيد بن معاوية تحت سور القسطنطينية كما أوصى. صار قبره معروفًا للروم، يهابونه ويستسقون به في الجدب. لما فتحت القسطنطينية بعد قرون على يد محمد الفاتح سنة 857 هـ، اكتشف العثمانيون قبر أبي أيوب، فبنوا حوله مسجدًا عظيمًا اسمه مسجد أبي أيوب الأنصاري — لا يزال قائمًا في إستانبول إلى اليوم، يزوره ملايين المسلمين كل عام.',
      'دروس أبي أيوب عظيمة. الأول: الإكرام للضيف، خاصة إذا كان رسول الله. أبو أيوب لم يُعطِ النبي ﷺ بيته فقط، بل اعتنى بأدنى تفاصيل راحته. الثاني: الجهاد لا يتوقف بكبر العمر. خرج أبو أيوب في الثمانين يجاهد. كم من شاب اليوم في العشرين لا يقوم بصلاته! الثالث: حب لقاء الله. أبو أيوب أراد أن يدفن بعيدًا عن أهله ووطنه ليكون شهيدًا في فتح القسطنطينية. ضحى حتى بمكان قبره لله.',
      'يبقى أبو أيوب الأنصاري في تاريخ الإسلام مضيف رسول الله ﷺ، الذي نزل النبي عنده عند هجرته. الذي مات في طريق الجهاد على باب القسطنطينية. ودفن بعد قرون تحت سور المدينة التي فتحها المسلمون. اللهم ارضَ عن أبي أيوب، واجمعنا به في جنات النعيم.',
    ]),
    en: P([
      'He is Khalid ibn Zayd ibn Kulayb ibn Tha\'labah, al-Ansari al-Khazraji al-Najjari. He was known by his kunya Abu Ayyub. He was born in Yathrib — Madinah — about twenty-five years before the mission. He was of the tribe of Banu al-Najjar, of which the Prophet\'s ﷺ mother Aminah bint Wahb was on the maternal side.',
      'He pledged allegiance to the Prophet ﷺ at the Second Pledge of Aqabah, so he was among the foremost Ansar. When the Prophet ﷺ emigrated to Madinah, the Ansar competed over whom the Prophet would stay with. Each tribe would take the rein of the Prophet\'s ﷺ camel al-Qaswa and say: "Stay with us, O Messenger of Allah." The Prophet would say: "Let her go, for she is commanded."',
      'The camel walked through the streets of Madinah until she knelt at the site of today\'s Prophet\'s Mosque. The closest house to her was Abu Ayyub al-Ansari\'s. Abu Ayyub rose and took the Prophet\'s ﷺ saddle — his belongings — and carried it to his house. He said: "O Messenger of Allah, my house is the nearest of houses." The Prophet ﷺ was pleased by his speed and love, and stayed in Abu Ayyub\'s house.',
      'Abu Ayyub\'s house had two storeys. Abu Ayyub wanted the Prophet ﷺ to stay on the upper storey to honour him. But the Prophet ﷺ said: "O Abu Ayyub, it is more comfortable for us and for those who visit us that we be on the lower storey." So the Prophet ﷺ stayed on the lower storey, and Abu Ayyub and Umm Ayyub — his wife — went up to the upper storey.',
      'Abu Ayyub and his wife did not enjoy their sleep that night. They were above the Prophet\'s ﷺ head, and feared something might fall from them onto the Prophet. They spent that night walking on the edges of the walls, afraid of the sound of a footstep being heard. In the morning, Abu Ayyub went down to the Prophet ﷺ and told him. The Prophet said to him: "Do not do that; this is what is comfortable for you." But Abu Ayyub insisted. So the Prophet ﷺ ordered to ascend to the upper storey.',
      'The Prophet ﷺ would eat from Abu Ayyub\'s food. Umm Ayyub would cook and serve the Prophet ﷺ. The Prophet ﷺ would eat a little, and Abu Ayyub would send what remained for him and his family to eat. Abu Ayyub and Umm Ayyub would eat from the same vessel the Prophet ﷺ had eaten from, seeking the blessing.',
      'The Prophet ﷺ stayed in Abu Ayyub\'s house about seven months, until the Prophet\'s Mosque and the chambers of the Mothers of the Believers were built. He then moved to his chamber. But the bond between the Prophet and Abu Ayyub did not break. Abu Ayyub was among the Prophet\'s ﷺ elite.',
      'Abu Ayyub participated in every campaign of the Prophet ﷺ starting from Badr. He was brave, steadfast, fighting in the front ranks. He did not miss a campaign throughout the Prophet\'s ﷺ life. After the Prophet\'s death, he continued in jihad. He participated in the conquests of Sham with Abu Ubaydah.',
      'Abu Ayyub was among those who held fast to the love of Ali ibn Abi Talib. In the trial between Ali and Mu\'awiyah, Abu Ayyub was with Ali, and participated in the Battle of the Camel, Siffin, and Nahrawan on Ali\'s side. After Ali\'s killing, he did not pledge allegiance to Mu\'awiyah. He was among the few who remained on Ali\'s view until he died.',
      'In Mu\'awiyah\'s era, Abu Ayyub went out for jihad against the Romans. He was about eighty years old. He could not sit in Madinah while others fought. He said: "I have heard Allah say: ‘Go forth, light and heavy.’ I do not see that Allah mentioned us in it" — meaning the elderly. He participated in the naval campaign to conquer Constantinople in 52 AH.',
      'Abu Ayyub fell ill in the campaign. The Muslim army was besieging Constantinople — the capital of the Romans. He knew his end had drawn near. He instructed Yazid ibn Mu\'awiyah — the army commander — to bury him in Roman land, as far as he could. He said: "Bury me under the hooves of the horses." He was asked: "Why?" He said: "The Messenger of Allah ﷺ told me this Ummah will conquer Constantinople. If I am killed and you bury me under the feet of your enemies, perhaps Allah will raise me among them and I shall witness its conquest."',
      'Abu Ayyub, may Allah be pleased with him, died in 52 AH at about eighty years of age or more. Yazid ibn Mu\'awiyah buried him under the wall of Constantinople as he had instructed. His grave became known to the Romans, who feared it and sought rain through it in droughts. When Constantinople was conquered centuries later at the hand of Muhammad the Conqueror in 857 AH, the Ottomans discovered Abu Ayyub\'s grave and built a great mosque around it called the Mosque of Abu Ayyub al-Ansari — still standing in Istanbul to this day, visited by millions of Muslims every year.',
      'Abu Ayyub\'s lessons are great. First: honouring the guest, especially if he is the Messenger of Allah. Abu Ayyub did not give the Prophet ﷺ his house only, but cared for the smallest details of his comfort. Second: jihad does not stop with old age. Abu Ayyub went out at eighty fighting. How many a youth today at twenty does not stand for his prayer! Third: love of meeting Allah. Abu Ayyub wanted to be buried far from his family and homeland to be a martyr in the conquest of Constantinople. He sacrificed even the place of his grave for Allah.',
      'Abu Ayyub al-Ansari remains in the history of Islam the host of the Messenger of Allah ﷺ, with whom the Prophet stayed at his emigration. He who died on the road of jihad at the gate of Constantinople. And was buried centuries later under the wall of the city the Muslims conquered. O Allah, be pleased with Abu Ayyub and gather us with him in the Gardens of Bliss.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 19. خديجة بنت خويلد رضي الله عنها — أم المؤمنين الأولى
  // ──────────────────────────────────────────────────────────────────────
  'khadijah': {
    ar: P([
      'هي خديجة بنت خويلد بن أسد بن عبد العزى بن قُصي القرشية الأسدية. وُلدت بمكة قبل عام الفيل بنحو خمس عشرة سنة، فهي أكبر من النبي ﷺ بخمس عشرة سنة. أبوها خويلد كان من سادات قريش. كانت من بيت شريف عريق في النسب.',
      'تزوجت قبل النبي ﷺ مرتين. الأول أبو هالة هند بن النباش، الذي مات عنها وأنجبت منه ابنين. ثم تزوجت عتيق بن عابد المخزومي، الذي طلّقها أو مات عنها. ثم بقيت أرملة، تدير تجارتها بنفسها. كانت أغنى نساء قريش، تستأجر الرجال على تجارتها، وتقاسمهم الربح.',
      'سمعت بشاب من قريش اسمه محمد بن عبد الله، يُعرف بالصدق والأمانة. لقّبته قريش بالصادق الأمين. أرسلت إليه تطلب منه أن يتاجر لها في مالها. قبل النبي ﷺ، وسافر إلى الشام في تجارتها. عاد بأرباح مضاعفة، وأخلاق رفيعة. غلامها ميسرة الذي رافقه أخبرها بما رأى: كيف ظلّ ملاكان يظلانه من الشمس، وكيف رفع الراهب بحيرى رأسه إليه في الشام معترفًا بنبوته.',
      'وقع حبها في قلبها. لكنها لم تستطع المبادرة مباشرة. بعثت صديقتها نفيسة بنت منية إليه تستطلع رأيه. سألته نفيسة: ما يمنعك أن تتزوج يا محمد؟ قال: ما عندي ما أتزوج به. قالت: فإن دعيتَ إلى المال والجمال والكفاءة والشرف، ألا تجيب؟ قال: ومن؟ قالت: خديجة. قال: وكيف لي بها؟ قالت: عليّ. فذهبت إلى خديجة فأخبرتها، فأرسلت إلى النبي ﷺ موعدًا. اتفق العمّان: عمّ النبي ﷺ أبو طالب، وعمّ خديجة. تزوجا. كان عمر النبي ﷺ خمسًا وعشرين سنة، وعمرها أربعين.',
      'عاش معها النبي ﷺ خمسًا وعشرين سنة لم يتزوج عليها فيها أحدًا. أنجبت له ستة من الأولاد: القاسم وعبد الله — وكلاهما ماتا في الصغر — وزينب ورقية وأم كلثوم وفاطمة الزهراء. كل بنات النبي ﷺ من خديجة. كانت أمَّ كل ذريّته ﷺ، إذ لم يبق له ذرية إلا من فاطمة.',
      'لما نزل الوحي على النبي ﷺ في غار حراء لأول مرة، رجع يرجف فؤاده. قال: زمّلوني زمّلوني. لفّته خديجة في ثوب وضمّته إلى صدرها حتى ذهب عنه الفزع. ثم أخبرها بما حدث، وقال: لقد خشيت على نفسي. فأجابته بكلماتها الخالدة: كلا والله، ما يخزيك الله أبدًا. إنك لتصل الرحم، وتحمل الكلّ، وتكسب المعدوم، وتقري الضيف، وتعين على نوائب الحق.',
      'هذه الكلمة من خديجة كانت أعظم تأييد. وصفت النبي ﷺ بأخلاقه الخمسة: صلة الرحم، حمل الضعفاء، إعطاء الفقراء، إكرام الضيف، إعانة المحتاج. ثم استنتجت: من فيه هذه الخصال، لا يخزيه الله أبدًا. كانت بصيرة إيمانية قبل أن تكون عاطفة زوجة.',
      'ثم أخذته إلى ابن عمها ورقة بن نوفل. كان ورقة شيخًا مسيحيًا، عالمًا بالكتب القديمة. سمع ورقة قصة النبي ﷺ، فعرف فورًا: هذا هو الناموس الذي نزل على موسى. ودعا للنبي ﷺ بالنصر. صارت خديجة أول من آمن بالنبي ﷺ من الناس جميعًا، رجالًا ونساء، أبدًا.',
      'كانت معه طوال سنوات الدعوة المكية. لما اشتدّ أذى قريش على المؤمنين، أنفقت خديجة مالها كله في سبيل الله. اشترى أبو بكر بمالها العبيد المعذبين فأعتقهم. أنفقت على المجاعات. أعانت المهاجرين إلى الحبشة. كانت داعمة مالية ومعنوية للدعوة الناشئة.',
      'في حصار قريش لبني هاشم في شعب أبي طالب — سنة 7 من البعثة — عانت خديجة مع النبي ﷺ مما عانوا. لم يكن يصلهم طعام إلا قليلًا. عشن ثلاث سنين على القليل من الطعام، حتى ضعفت أبدانهم. هذا الحصار أضعف خديجة كثيرًا، وكان أحد أسباب وفاتها بعد ذلك بقليل.',
      'بشّرها جبريل عليه السلام بسلام من ربها. روى البخاري ومسلم عن أبي هريرة: أتى جبريل النبي ﷺ فقال: يا رسول الله، هذه خديجة قد أتت معها إناء فيه إدام أو طعام أو شراب، فإذا هي أتتك فاقرأ عليها السلام من ربها ومني، وبشّرها ببيت في الجنة من قصب، لا صخب فيه ولا نصب. سلام من رب العالمين على عبدته، ووعد ببيت في الجنة لا تعب فيه ولا ضوضاء.',
      'توفيت خديجة في السنة العاشرة من البعثة، قبل الهجرة بثلاث سنين. كان عمرها يومئذ خمسًا وستين سنة. مات في نفس العام أبو طالب — عمّ النبي وحاميه. فقد النبي ﷺ في عام واحد زوجته الحبيبة وعمّه الحامي. سمّى ذلك العام عام الحزن.',
      'بعد وفاتها بسنوات، كان النبي ﷺ يذكرها كثيرًا. كان إذا ذبح شاة بعث منها إلى صديقات خديجة. كان إذا سمع صوت أختها هالة، اضطرب وقال: اللهم هالة. غارت منها عائشة، رغم أنها لم ترها، وقالت: ما غرت من امرأة ما غرت من خديجة، وما رأيتها، ولكن كان النبي ﷺ يكثر ذكرها.',
      'قال النبي ﷺ في حقّها كلمات لا تُنسى: لقد آمنت بي إذ كفر بي الناس، وصدّقتني إذ كذّبني الناس، وواستني بمالها إذ حرمني الناس، ورزقني الله ولدها إذ حرمني أولاد النساء. أربعة فضائل لخديجة، لم يدّعِها لزوجة أخرى: الإيمان، التصديق، المال، الولد.',
      'يبقى خديجة بنت خويلد أول أم للمؤمنين، أول من آمن من الناس، أم بنات النبي ﷺ. الزوجة التي ضمّت النبي ﷺ في ليلة الوحي الأولى. التي أرسل الله إليها سلامًا من فوق سبع سماوات. التي بشّر النبي ﷺ ببيت في الجنة من قصب. اللهم ارضَ عن خديجة، واجعلنا في جوارها يوم القيامة.',
    ]),
    en: P([
      'She is Khadijah bint Khuwaylid ibn Asad ibn Abd al-Uzza ibn Qusayy, al-Qurashiyyah al-Asadiyyah. She was born in Makkah about fifteen years before the Year of the Elephant, so she was fifteen years older than the Prophet ﷺ. Her father Khuwaylid was among the chiefs of Quraysh. She was of a noble household, deeply rooted in lineage.',
      'She married twice before the Prophet ﷺ. The first was Abu Halah Hind ibn al-Nabbash, who died and she bore him two sons. Then she married Atiq ibn Abid al-Makhzumi, who divorced her or died. Then she remained a widow, managing her trade herself. She was the wealthiest woman of Quraysh, hiring men for her trade and sharing the profits with them.',
      'She heard of a young man of Quraysh named Muhammad ibn Abdullah, known for truthfulness and trustworthiness. Quraysh had named him al-Sadiq al-Amin (the Truthful, the Trustworthy). She sent for him to trade for her with her wealth. The Prophet ﷺ accepted and travelled to Sham in her trade. He returned with doubled profits and elevated character. Her servant Maysarah, who had accompanied him, told her what he had seen: how two angels shaded him from the sun, and how the monk Bahira raised his head to him in Sham, acknowledging his prophethood.',
      'Love for him fell in her heart. But she could not initiate directly. She sent her friend Nafisah bint Munyah to him to gauge his view. Nafisah asked him: "What prevents you from marrying, O Muhammad?" He said: "I do not have what to marry with." She said: "If you were called to wealth, beauty, sufficiency, and honour, would you not answer?" He said: "From whom?" She said: "Khadijah." He said: "And how can I to her?" She said: "Upon me." She went to Khadijah and told her. Khadijah sent to the Prophet ﷺ an appointment. The two uncles agreed: the Prophet\'s ﷺ uncle Abu Talib, and Khadijah\'s uncle. They married. The Prophet ﷺ was twenty-five years old, and she was forty.',
      'The Prophet ﷺ lived with her twenty-five years, taking no other wife in her lifetime. She bore him six children: al-Qasim and Abdullah — both of whom died in childhood — and Zaynab, Ruqayyah, Umm Kulthum, and Fatimah al-Zahra. All of the Prophet\'s ﷺ daughters were from Khadijah. She was the mother of all his offspring, since no offspring remained for him except through Fatimah.',
      'When revelation came upon the Prophet ﷺ in the cave of Hira for the first time, he returned trembling. He said: "Wrap me up, wrap me up." Khadijah wrapped him in a garment and held him to her chest until the terror left him. Then he told her what had happened and said: "I have feared for myself." She answered with her immortal words: "No, by Allah, Allah will never disgrace you. You maintain ties of kinship, bear the burdens of others, earn for the destitute, are generous to guests, and help against the calamities of truth."',
      'These words from Khadijah were the greatest support. She described the Prophet ﷺ by his five qualities: ties of kinship, carrying the weak, giving to the poor, honouring the guest, and helping the needy. Then she concluded: one in whom these qualities are found, Allah will never disgrace. It was a believing insight before it was a wife\'s emotion.',
      'She then took him to her cousin Waraqah ibn Nawfal. Waraqah was a Christian elder, learned in the old scriptures. Waraqah heard the Prophet\'s ﷺ story and knew at once: this is the Namus that descended upon Moses. He prayed for the Prophet ﷺ for victory. Khadijah became the first to believe in the Prophet ﷺ of all people, men or women — ever.',
      'She was with him throughout the years of the Makkan call. When the harm of Quraysh upon the believers intensified, Khadijah spent all her wealth in Allah\'s cause. Abu Bakr bought the tortured slaves with her wealth and freed them. She spent on famines. She helped the emigrants to Abyssinia. She was a financial and moral supporter for the nascent call.',
      'In Quraysh\'s siege of Banu Hashim in the Valley of Abu Talib — in the seventh year of the mission — Khadijah suffered with the Prophet ﷺ what they suffered. They received only little food. They lived three years on little food, until their bodies weakened. This siege weakened Khadijah greatly, and was among the causes of her death soon after.',
      'Jibril gave her glad tidings of greetings from her Lord. Bukhari and Muslim narrate from Abu Hurayrah: "Jibril came to the Prophet ﷺ and said: O Messenger of Allah, this is Khadijah; she has come with a vessel containing relish, food, or drink. When she comes to you, convey to her greetings of peace from her Lord and from me, and give her glad tidings of a house in Paradise of pearl-cane, in which is no noise or weariness." Greetings from the Lord of the Worlds to His servant, and a promise of a house in Paradise without fatigue or noise.',
      'She died in the tenth year of the mission, three years before the Hijrah. She was sixty-five years old. In the same year his uncle Abu Talib — the Prophet\'s uncle and protector — died. The Prophet ﷺ lost in one year his beloved wife and his protecting uncle. He called that year the Year of Sorrow.',
      'Years after her death, the Prophet ﷺ would mention her often. When he slaughtered a sheep, he would send some of it to Khadijah\'s friends. When he heard the voice of her sister Halah, he would be moved and say: "O Allah, Halah!" A\'isha became jealous of her, though she had never seen her. She said: "I have not been jealous of any woman as I was jealous of Khadijah, though I never saw her. But the Prophet ﷺ would mention her often."',
      'The Prophet ﷺ said about her unforgettable words: "She believed in me when people disbelieved in me, accepted me when people denied me, supported me with her wealth when people deprived me, and Allah granted me children through her when He withheld children from other women." Four virtues of Khadijah he did not claim for any other wife: faith, acceptance, wealth, and children.',
      'Khadijah bint Khuwaylid remains the first Mother of the Believers, the first of people to believe, the mother of the Prophet\'s ﷺ daughters. The wife who embraced the Prophet ﷺ on the first night of revelation. To whom Allah sent greetings from above seven heavens. To whom the Prophet ﷺ gave glad tidings of a house in Paradise of pearl-cane. O Allah, be pleased with Khadijah and make us in her neighbourhood on the Day of Resurrection.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 20. عائشة بنت أبي بكر رضي الله عنها — الصدّيقة بنت الصدّيق
  // ──────────────────────────────────────────────────────────────────────
  'aisha': {
    ar: P([
      'هي عائشة بنت أبي بكر الصديق بن أبي قحافة، التيمية القرشية. أم المؤمنين. وُلدت بمكة في السنة الرابعة من البعثة. كانت أمها أم رومان زينب بنت عامر الكنانية، الزوجة الثانية لأبي بكر. تربّت في بيت الإسلام الأول، فقد أسلم أبواها قبل أن تولد.',
      'تزوجها النبي ﷺ في مكة قبل الهجرة بثلاث سنين، بعد وفاة خديجة. كانت يومئذ صغيرة، فلم يدخل بها النبي ﷺ إلا بعد الهجرة بسنتين، وكانت تسع سنوات حين انتقلت إلى بيت النبي ﷺ. هذا الزواج كان قبل الإسلام يعتبر عاديًا في الجزيرة العربية، حيث كانت الفتاة تتزوج عند بلوغها.',
      'كان النبي ﷺ يحبها حبًا شديدًا. سُئل: من أحب الناس إليك؟ قال: عائشة. قيل: من الرجال؟ قال: أبوها. كان حبه لها صريحًا أمام الناس. كان يضع رأسه في حجرها، يأكل من نفس الإناء معها، يسابقها في الصحراء — سبقها مرة وسبقته أخرى. علاقة زوجية فيها كل صور الود والمودة.',
      'كانت من أذكى نساء العرب. حفظت من النبي ﷺ كثيرًا من الأحاديث. روت عنه ألفين ومئتي حديث، فكانت من أكثر الصحابة رواية بعد أبي هريرة وابن عمر وأنس بن مالك وابن عباس. أكثر ما روته في فقه النساء، وفي بيت النبي ﷺ، وفي صفته الباطنة — لأنها كانت قريبة منه ﷺ.',
      'كان الصحابة يستشيرونها في الفقه. إذا أشكل عليهم أمر من أمور الدين، خاصة في النساء، رجعوا إلى عائشة. أبو موسى الأشعري قال: ما أشكل علينا أصحاب رسول الله ﷺ حديث قط، فسألنا عائشة، إلا وجدنا عندها منه علمًا. كانت مرجعًا في الفقه والحديث والقرآن واللغة العربية والشعر.',
      'وقعت في حياتها حادثة الإفك العظيمة. كانت في غزوة مع النبي ﷺ، فنزلت لتقضي حاجتها، فضاع منها قلادة. رجعت تبحث عنها. تحرك الجيش دون أن يعرف الناس أنها لم تركب. لما عادت ولم تجد الجيش، انتظرت في مكانها. مرّ بها صفوان بن المعطل، فعرفها وأركبها بعيره وسار بها حتى لحقا بالجيش.',
      'فتح المنافقون هذه الحادثة بابًا للطعن. قالوا: عائشة وصفوان وحدهما! كذبًا وافتراء. انتشرت التهمة، حتى وصلت إلى النبي ﷺ. كان النبي يحتار، يستشير، يسأل أهل الخبرة. عائشة كانت قد مرضت، لم تعرف ما يقال عنها. لما عرفت في النهاية، حُمّت من شدة الصدمة. بكت بكاءً طويلًا — قالت: لم يبقَ في جوفي دموع.',
      'نزل الوحي ببراءتها في عشر آيات من سورة النور: إن الذين جاؤوا بالإفك عصبة منكم، لا تحسبوه شرًا لكم، بل هو خير لكم، لكل امرئ منهم ما اكتسب من الإثم. أنزل الله براءتها من فوق سبع سماوات. صارت من الناحية الشرعية معصومة من تهمة الإفك إلى يوم القيامة. ومن طعن فيها بعد ذلك، فهو على خلاف القرآن نفسه — وذلك كفر صريح عند جمهور العلماء.',
      'لما توفي النبي ﷺ، كان رأسه في حجرها. قُبضت روحه وهي تضمّه إلى صدرها. هذا الفضل لم يحظ به أحد غيرها. كانت آخر امرأة لمسها النبي ﷺ، وأول من سمع آخر زفير من فمه ﷺ. تحمّلت الصدمة بصبر عجيب. لم تزل تبكيه طوال حياتها.',
      'بقيت في حجرتها في المسجد النبوي. كانت حجرتها قبل وفاة النبي ﷺ مكان عيشها معه، وبعد وفاته صارت مقبرته. صار قبر النبي ﷺ في بيتها. كانت تجلس بجوار قبره، تشعر بقربه ولو كان قد توفي. لما توفي أبو بكر بعد ذلك بسنتين، دُفن إلى جنب النبي ﷺ في بيتها. ولما توفي عمر بعد عشر سنين، دُفن أيضًا في بيتها.',
      'في خلافة عثمان، اعتزلت عائشة الفتنة. لما قُتل عثمان، شاركت في معركة الجمل، طالبة بالقصاص من قتلة عثمان. كانت تقود الجيش راكبة جملًا — لذلك سُمّيت بمعركة الجمل. هزم جيشها أمام علي. ندمت عائشة على خروجها ندمًا شديدًا، وقالت بعد ذلك: لقد سمعت رسول الله ﷺ يقول: لا يفلح قوم ولّوا أمرهم امرأة. كانت تبكي كلما ذكرت تلك المعركة.',
      'بعد معركة الجمل، رجعت عائشة إلى المدينة، واعتزلت السياسة كليًا. تفرّغت لتعليم النساء والرجال. كانت تجلس خلف ستار، تروي الأحاديث وتعلم الفقه. تخرّج على يديها كثير من فقهاء التابعين، منهم: عروة بن الزبير ابن أختها أسماء، والقاسم بن محمد بن أبي بكر ابن أخيها، وعمرة بنت عبد الرحمن.',
      'توفيت عائشة سنة 58 هـ في رمضان. كان عمرها يومئذ نحو 66 سنة. أوصت أن تُدفن في البقيع، لا في حجرتها مع النبي ﷺ، تواضعًا منها — لم تشأ أن تنفرد بشرف الدفن مع النبي. صلى عليها أبو هريرة، ودفنت في البقيع. شيّع جنازتها أهل المدينة كلهم.',
      'يبقى عائشة بنت أبي بكر في تاريخ الإسلام أم المؤمنين، حبيبة رسول الله ﷺ، الصديقة بنت الصديق، التي نزل الوحي ببراءتها. أكثر النساء فقهًا في تاريخ الإسلام. اللهم ارضَ عن عائشة، واغفر لنا حبّها، واجعلنا من المتمسكين بسنّتها وعلمها.',
    ]),
    en: P([
      'She is A\'isha bint Abi Bakr al-Siddiq ibn Abi Quhafah, al-Taymiyyah al-Qurashiyyah. Mother of the Believers. She was born in Makkah in the fourth year of the mission. Her mother was Umm Ruman Zaynab bint Amir al-Kinaniyyah, the second wife of Abu Bakr. She was raised in the first house of Islam, for her parents had embraced Islam before she was born.',
      'The Prophet ﷺ married her in Makkah three years before the Hijrah, after Khadijah\'s death. She was young then, so the Prophet ﷺ did not consummate the marriage with her until two years after the Hijrah, when she was nine years old upon moving to the Prophet\'s ﷺ house. Such marriages before Islam were considered ordinary in the Arabian Peninsula, where a girl would marry at puberty.',
      'The Prophet ﷺ loved her deeply. He was asked: "Who is the most beloved of people to you?" He said: "A\'isha." It was said: "Of men?" He said: "Her father." His love for her was explicit before people. He would place his head in her lap, eat from the same vessel with her, race her in the desert — he beat her once and she beat him another time. A marital relationship with every form of affection and love.',
      'She was among the most intelligent of Arab women. She memorised from the Prophet ﷺ many hadiths. She narrated about two thousand two hundred hadiths from him, becoming among the most prolific Companions after Abu Hurayrah, Ibn Umar, Anas ibn Malik, and Ibn Abbas. Most of what she narrated was on the fiqh of women, on the Prophet\'s ﷺ household, and on his inner qualities — because she was close to him ﷺ.',
      'The Companions would consult her on jurisprudence. If a matter of religion became unclear to them, especially in women\'s affairs, they would refer to A\'isha. Abu Musa al-Ash\'ari said: "Never did a hadith perplex us, the Companions of the Messenger of Allah ﷺ, and we asked A\'isha about it, but we found knowledge of it with her." She was a reference in fiqh, hadith, Qur\'an, Arabic language, and poetry.',
      'In her life occurred the great Slander incident. She was on a campaign with the Prophet ﷺ and descended to relieve herself. A necklace fell from her. She returned to search for it. The army moved without people knowing she had not mounted. When she returned and did not find the army, she waited in her place. Safwan ibn al-Mu\'attal passed by her, recognised her, mounted her on his camel, and walked with her until they caught up with the army.',
      'The hypocrites opened this incident as a door to attack. They said: A\'isha and Safwan alone! Lies and slander. The accusation spread, until it reached the Prophet ﷺ. The Prophet was perplexed, consulting, asking the people of experience. A\'isha had fallen ill and did not know what was being said about her. When she finally learned, she fell into fever from the shock. She wept for a long time — she said: "There were no tears left in me."',
      'Revelation came with her exoneration in ten verses of Surah al-Nur: "Indeed, those who came with the slander are a faction among you. Do not consider it bad for you; rather, it is good for you. For every person among them is what he has earned of the sin." Allah sent down her exoneration from above seven heavens. Legally she became immune from the accusation of slander until the Day of Resurrection. Whoever attacks her after that opposes the Qur\'an itself — and that is plain disbelief in the view of the majority of scholars.',
      'When the Prophet ﷺ died, his head was in her lap. His soul was taken while she embraced him to her chest. This honour was for no one else. She was the last woman the Prophet ﷺ touched, and the first to hear the last breath from his mouth ﷺ. She bore the shock with remarkable patience. She wept for him throughout her life.',
      'She remained in her chamber in the Prophet\'s Mosque. Her chamber before the Prophet\'s ﷺ death was the place of her life with him; after his death it became his tomb. The grave of the Prophet ﷺ became in her house. She would sit beside his grave, feeling his nearness though he had died. When Abu Bakr died two years later, he was buried beside the Prophet ﷺ in her house. When Umar died ten years later, he too was buried in her house.',
      'In Uthman\'s caliphate, A\'isha withdrew from the trial. When Uthman was killed, she participated in the Battle of the Camel, demanding retribution from Uthman\'s killers. She led the army riding a camel — hence its name, the Battle of the Camel. Her army was defeated before Ali. A\'isha deeply regretted her going out and said afterwards: "I heard the Messenger of Allah ﷺ say: ‘A people will not succeed who entrust their affair to a woman.’" She would weep whenever she remembered that battle.',
      'After the Battle of the Camel, A\'isha returned to Madinah and withdrew completely from politics. She devoted herself to teaching women and men. She would sit behind a screen, narrating hadiths and teaching jurisprudence. Many Successors\' jurists graduated at her hands, including: Urwah ibn al-Zubayr, son of her sister Asma\'; al-Qasim ibn Muhammad ibn Abi Bakr, son of her brother; and Amrah bint Abd al-Rahman.',
      'A\'isha died in 58 AH in Ramadan. She was about 66 years old. She bequeathed to be buried in al-Baqi\', not in her chamber with the Prophet ﷺ, out of humility — she did not wish to be singled out for the honour of burial with the Prophet. Abu Hurayrah prayed over her, and she was buried in al-Baqi\'. The people of Madinah all attended her funeral.',
      'A\'isha bint Abi Bakr remains in the history of Islam the Mother of the Believers, the beloved of the Messenger of Allah ﷺ, the Truthful daughter of the Truthful, whose exoneration revelation brought down. The most knowledgeable woman in fiqh in the history of Islam. O Allah, be pleased with A\'isha, forgive us for loving her, and make us among those who hold fast to her Sunnah and her knowledge.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 21. حفصة بنت عمر رضي الله عنها — حافظة المصحف الأول
  // ──────────────────────────────────────────────────────────────────────
  'hafsa': {
    ar: P([
      'هي حفصة بنت عمر بن الخطاب القرشية العدوية. أم المؤمنين. ولدت بمكة قبل البعثة بنحو خمس سنوات. كانت ابنة عمر بن الخطاب — أعظم رجل في الإسلام بعد أبي بكر. تربّت في بيت يجمع بين القوة والإسلام. كانت كأبيها: قوية الشخصية، صريحة، عاقلة.',
      'تزوجت قبل النبي ﷺ من خنيس بن حذافة السهمي. كان زوجها أحد المهاجرين الأوائل، شارك في غزوة بدر. أصيب في أحد إصابة بليغة، فمات منها متأثرًا. صارت حفصة أرملة وعمرها نحو عشرين سنة. لم يكن لها أولاد.',
      'حزن عمر بن الخطاب على ابنته. أراد لها زوجًا صالحًا. عرضها على عثمان بن عفان أولًا — كان عثمان قد توفيت زوجته رقية بنت النبي ﷺ. اعتذر عثمان. ثم عرضها على أبي بكر الصديق. سكت أبو بكر ولم يجبه. غضب عمر، ذهب إلى النبي ﷺ يشكو. ابتسم النبي ﷺ وقال: يتزوج حفصة من هو خير من عثمان، ويتزوج عثمان من هو خير من حفصة. ثم خطبها النبي ﷺ. وتزوج عثمان أم كلثوم — أخت رقية — بنت النبي.',
      'لم تكن حفصة الزوجة الأولى عند النبي ﷺ. كان معه يومئذ سودة بنت زمعة وعائشة. حين دخلت حفصة، كانت رابعة بعد أم سلمة. عاشت معه ثماني سنوات حتى وفاة النبي ﷺ.',
      'كانت حفصة صوّامة قوّامة. تصوم النهار وتقوم الليل. تحب العبادة وتكثر منها. وكانت من القليلات اللواتي يقرأن ويكتبن في الجزيرة العربية. تعلمت القراءة والكتابة في الصغر، فكانت من أعلم نساء قريش بهذا.',
      'كان النبي ﷺ يحبها ويحترمها. لكن في مرة من المرات، طلّقها تطليقة. حزن عمر حزنًا شديدًا. ثم نزل عليه جبريل عليه السلام وأمره أن يراجعها. قال: راجع حفصة، فإنها صوّامة قوّامة، وإنها زوجتك في الجنة. هذه شهادة عظيمة — أن جبريل ينزل بأمر إلهي بمراجعة زوجة، وأن يخبر أنها زوجة النبي في الجنة. لم ينل هذا الشرف غيرها من الزوجات.',
      'لما توفي النبي ﷺ سنة 11 هـ، صارت حفصة من أمهات المؤمنين الباقيات. تولّى أبو بكر الخلافة سنتين، ثم عمر عشر سنوات. كانت حفصة في خلافة أبيها عمر ذات نفوذ — كانت تجلس مع نساء المدينة وتسمع أخبارهن وتنقلها لأبيها. كانت من مصادر معلومات عمر عن أحوال نساء المدينة وحاجاتهن.',
      'الفضل العظيم لحفصة في تاريخ الإسلام: أنها كانت حافظة المصحف الأول. لما جمع أبو بكر القرآن في مصحف واحد — بسبب موت كثير من حفظة القرآن في حروب الردة — أودعه عند نفسه أولًا. ثم عند موته، أودعه عند عمر. ولما توفي عمر، انتقل المصحف إلى ابنته حفصة، تحفظه في بيتها كنسخة الأصل.',
      'بقي المصحف الأصلي عند حفصة طوال خلافة عثمان. لما أراد عثمان أن يوحّد قراءة الناس على مصحف واحد، أرسل إلى حفصة يطلب المصحف. أعطته إياه. نسخ منه عثمان عدة نسخ، أرسلها إلى الأمصار. ثم أعاد المصحف الأصلي إلى حفصة. بقي عندها حتى ماتت.',
      'لما توفيت حفصة، أخذ مروان بن الحكم — والي المدينة في عهد معاوية — المصحف، وأمر بإحراقه. خشي أن يُختلف فيه مع المصحف العثماني. كان قرارًا حذرًا — فقد كان المصحف العثماني هو المعتمد رسميًا، وبقاء المصحف الأصلي قد يفتح باب الجدل.',
      'كانت حفصة من رواة الحديث. روت ستين حديثًا عن النبي ﷺ. تعلم منها أخوها عبد الله بن عمر — الذي صار من أعلم الصحابة بعد ذلك — كثيرًا من الفقه والحديث. كان بيتها مدرسة. ابن عمها وابنها بالتربية — لأنها لم تنجب — كان يدخل عليها يتعلم.',
      'في الفتنة بين علي وعائشة وطلحة والزبير، اعتزلت حفصة الفتنة. لم تشارك في معركة الجمل، رغم أن أختها — أو شبيهتها في النفوذ — عائشة شاركت. كانت تفضّل الهدوء على الخوض في صراعات السياسة.',
      'توفيت حفصة في المدينة سنة 45 هـ — وفي رواية أخرى سنة 41 هـ. كان عمرها يومئذ نحو ستين سنة. صلى عليها مروان بن الحكم، ودفنت في البقيع. اجتمع لجنازتها أهل المدينة، يبكون أم المؤمنين، وحافظة المصحف الأول.',
      'يبقى حفصة بنت عمر في تاريخ الإسلام أمّ المؤمنين الصوّامة القوّامة، التي شهد لها جبريل بأنها زوجة النبي في الجنة. حافظة المصحف الأول، الذي منها انتسخ المصحف العثماني الذي يقرأ منه المسلمون اليوم. ابنة الفاروق وزوج الرسول ﷺ. اللهم ارضَ عن حفصة، واجعلنا من جيرانها في الجنة.',
    ]),
    en: P([
      'She is Hafsah bint Umar ibn al-Khattab al-Qurashiyyah al-Adawiyyah. Mother of the Believers. She was born in Makkah about five years before the mission. She was the daughter of Umar ibn al-Khattab — the greatest man in Islam after Abu Bakr. She was raised in a house combining strength and Islam. She was like her father: strong of personality, candid, intelligent.',
      'She married before the Prophet ﷺ to Khunays ibn Hudhafah al-Sahmi. Her husband was among the early Muhajirun and participated in the Battle of Badr. He was severely wounded at Uhud and died from it. Hafsah became a widow at about twenty years of age. She had no children.',
      'Umar ibn al-Khattab grieved for his daughter. He wanted a righteous husband for her. He offered her first to Uthman ibn Affan — Uthman\'s wife Ruqayyah daughter of the Prophet ﷺ had recently died. Uthman declined. He then offered her to Abu Bakr al-Siddiq. Abu Bakr remained silent and did not answer. Umar grew angry and went to the Prophet ﷺ to complain. The Prophet ﷺ smiled and said: "Hafsah will marry one who is better than Uthman, and Uthman will marry one who is better than Hafsah." The Prophet ﷺ then proposed to her. Uthman married Umm Kulthum — Ruqayyah\'s sister — daughter of the Prophet.',
      'Hafsah was not the Prophet\'s ﷺ first wife. With him at the time were Sawdah bint Zam\'ah and A\'isha. When Hafsah entered, she was the fourth after Umm Salamah. She lived with him for eight years until the Prophet\'s ﷺ death.',
      'Hafsah was much given to fasting and night prayer. She fasted by day and stood in prayer at night. She loved worship and increased in it. She was among the few who read and wrote in the Arabian Peninsula. She had learned to read and write in childhood, becoming among the most knowledgeable women of Quraysh in this.',
      'The Prophet ﷺ loved and respected her. But once he divorced her once. Umar grieved deeply. Then Jibril descended and ordered him to take her back. He said: "Take Hafsah back, for she is much given to fasting and night prayer, and she is your wife in Paradise." This is a great testimony — that Jibril descends with a divine command to take back a wife, and to inform that she is the Prophet\'s wife in Paradise. No other wife received this honour.',
      'When the Prophet ﷺ died in 11 AH, Hafsah became one of the remaining Mothers of the Believers. Abu Bakr took the caliphate for two years, then Umar for ten. Hafsah in her father Umar\'s caliphate had influence — she would sit with the women of Madinah, hear their news and convey it to her father. She was among Umar\'s sources of information on the conditions and needs of Madinah\'s women.',
      'Hafsah\'s great merit in the history of Islam: she was the keeper of the first Mushaf. When Abu Bakr collected the Qur\'an into a single Mushaf — because many memorisers died in the wars of apostasy — he deposited it with himself first. Then upon his death, he deposited it with Umar. When Umar died, the Mushaf passed to his daughter Hafsah, who kept it in her house as the original copy.',
      'The original Mushaf remained with Hafsah throughout Uthman\'s caliphate. When Uthman wished to unify the people\'s recitation on a single Mushaf, he sent to Hafsah requesting the Mushaf. She gave it to him. Uthman copied several copies from it and sent them to the regions. He then returned the original Mushaf to Hafsah. It remained with her until she died.',
      'When Hafsah died, Marwan ibn al-Hakam — the governor of Madinah in Mu\'awiyah\'s reign — took the Mushaf and ordered it burned. He feared disagreement with the Uthmanic Mushaf. It was a cautious decision — the Uthmanic Mushaf was the officially adopted one, and the remaining of the original Mushaf might open a door of dispute.',
      'Hafsah was among the narrators of hadith. She narrated sixty hadiths from the Prophet ﷺ. Her brother Abdullah ibn Umar — who later became among the most knowledgeable Companions — learned much fiqh and hadith from her. Her house was a school. Her brother\'s son, and her foster son — for she had no children — would visit her to learn.',
      'In the trial between Ali, A\'isha, Talhah, and al-Zubayr, Hafsah withdrew from the trial. She did not participate in the Battle of the Camel, although her counterpart in influence — A\'isha — did. She preferred quiet to entering political conflicts.',
      'Hafsah died in Madinah in 45 AH — in another narration 41 AH. She was about sixty years old. Marwan ibn al-Hakam prayed over her, and she was buried in al-Baqi\'. The people of Madinah gathered for her funeral, weeping for the Mother of the Believers, and the keeper of the first Mushaf.',
      'Hafsah bint Umar remains in the history of Islam the Mother of the Believers, much given to fasting and night prayer, to whom Jibril testified that she is the wife of the Prophet in Paradise. Keeper of the first Mushaf, from which the Uthmanic Mushaf — that Muslims recite from today — was copied. Daughter of al-Faruq and wife of the Messenger ﷺ. O Allah, be pleased with Hafsah and make us her neighbours in Paradise.',
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 22. سودة بنت زمعة رضي الله عنها
  // ──────────────────────────────────────────────────────────────────────
  'sawdah': {
    ar: P([
      'هي سودة بنت زمعة بن قيس بن عبد شمس القرشية العامرية. وُلدت بمكة قبل البعثة بنحو ثلاثين سنة. كانت أكبر من النبي ﷺ بقليل، وكانت من النساء الجليلات في قريش. تزوجت قبل النبي ﷺ ابن عمها السكران بن عمرو بن عبد شمس.',
      'أسلمت قديمًا مع زوجها السكران. كانا من السابقين الأولين في الإسلام. هاجرا الهجرة الثانية إلى الحبشة فرارًا من أذى قريش، وكان لهما ابن اسمه عبد الرحمن، عاش وكبر فصار من الصحابة. بقيت سودة في الحبشة سنين، ثم رجعت إلى مكة، فمات زوجها السكران بعد عودته.',
      'تزوجها النبي ﷺ في السنة العاشرة من البعثة بعد وفاة خديجة. كانت أول من تزوجها النبي ﷺ بعد خديجة. اختار النبي ﷺ سودة لعدة أسباب: كانت أرملة ذات سن، تحب الإسلام والمسلمين، وكانت من الأنصار الأوائل للنبي ﷺ في بيتها بمكة. لم يكن زواجها لجمال أو شهوة، بل إكرامًا لها على هجرتها وثباتها على الإيمان.',
      'هاجرت مع النبي ﷺ إلى المدينة بعد سنوات من زواجها. عاشت في حجرة بسيطة بجوار المسجد النبوي. كانت محبة لله ورسوله، تحب نساء النبي ﷺ ولا تنازعهن. كانت كثيرة الصدقة. روي أن عمر بن الخطاب أرسل إليها صرة فيها دراهم، فقالت لخادمتها: ما في هذه؟ قالت: دراهم. قالت: في الجراب؟! وفرّقتها على الفقراء قبل أن تغرب الشمس.',
      'لما كبرت في السن، خشيت أن يطلقها النبي ﷺ. قالت: يا رسول الله، لا أريد ما تريد النساء، إنما أريد أن أُحشر في زمرة أزواجك يوم القيامة. وهبت يومها وليلتها لعائشة، إيثارًا لرسول الله ﷺ، وحرصًا على البقاء معه في الدنيا والآخرة. أمسكها النبي ﷺ وقبل عطيّتها. أنزل الله فيها آية: وإن امرأة خافت من بعلها نشوزًا أو إعراضًا فلا جناح عليهما أن يصلحا بينهما صلحًا، والصلح خير.',
      'في هذا الموقف درس عظيم. سودة لم تنظر إلى متعة الدنيا، بل إلى منزلة الآخرة. إيثارها لعائشة كان لله، لا لعائشة. أرادت أن يبقى اسمها في زوجات النبي ﷺ — وهذا منصب لا يعدله شيء. وما من امرأة في الدنيا كلها تحتل هذا المكان: أن تُحشر مع النبي ﷺ يوم القيامة.',
      'كانت قوية البدن، طويلة القامة. روى عنها أنها لما نزلت آية الحجاب، خرجت ليلًا لقضاء حاجتها، فعرفها عمر من بعيد وقال: قد عرفناك يا سودة! فحرصًا على ستر نسائه، أنزل الله الحجاب على نساء النبي ﷺ بسببها — أي بسبب هذه الحادثة. هذا يدل على أهميتها في تاريخ تشريع الحجاب.',
      'كانت ذات روح مرحة. كانت تمزح مع النبي ﷺ في بعض الأحيان، وكان النبي ﷺ يضحك من مزحها. روي أنها قامت ذات ليلة تصلي، فأطالت السجود. فعند رفعها من السجود، أحست بفقد توازنها لطولها وثقل بدنها. ضحكت من نفسها، وأخبرت النبي ﷺ فضحك. كانت طبيعتها صادقة لا تحب التكلف.',
      'روت عن النبي ﷺ خمسة أحاديث. مع قلتها، فهي مما يستفيد منه الفقهاء. حدثت عن صفات النبي ﷺ في بيته، وعن سنن الصلاة والوضوء، وعن خلق النبي ﷺ مع نسائه. كانت أحاديثها قصيرة لكنها معدنية.',
      'في خلافة عمر بن الخطاب، توفيت سودة سنة 23 هـ. كانت في آخر السنين قد ضعفت، لكنها بقيت محتفظة بكرامتها ودينها. حُمل جثمانها في المدينة، وصلى عليها أمير المؤمنين عمر بن الخطاب، ودفنت بالبقيع، إلى جوار أخواتها من أمهات المؤمنين.',
      'دروسها كثيرة. الأول: أن المرأة المسلمة قد ترفع نفسها بمواقفها العظيمة. سودة لم تكن من أصغر زوجات النبي سنًا، ولا أجملهن، ولا أفقههن، لكنها كانت من أكرمهن نفسًا. الكرامة لا تحتاج إلى جمال، تحتاج إلى نفس عظيمة.',
      'الثاني: أن إيثار الآخرة على الدنيا هو طريق الفائزين. سودة فضلت أن يكون اسمها في زوجات النبي ﷺ يوم القيامة على متعة يوم وليلة في الدنيا. كم من إنسان اليوم يبيع آخرته بقليل من متاع الدنيا! سودة فعلت العكس.',
      'الثالث: أن الإسلام ساوى بين النساء بمستوى تقواهن. سودة لم تكن من بنات أشراف قريش الكبار. لكنها بإسلامها وهجرتها وزواجها من النبي ﷺ صارت من أمهات المؤمنين. هذا فضل الإسلام: يرفع الإنسان بالعمل، لا بالأصل.',
      'يبقى سودة بنت زمعة في تاريخ الإسلام أول من تزوجها النبي ﷺ بعد خديجة، الزوجة التي وهبت يومها لله ولرسوله، والمرأة التي نزل الحجاب على نساء النبي بسببها. اللهم ارضَ عن سودة، واجعلنا من المؤثرين الآخرة على الدنيا كما آثرت هي.',
    ]),
    en: P([
      "She is Sawdah bint Zam'ah ibn Qays ibn Abd Shams al-Qurashiyyah al-Amiriyyah. She was born in Makkah about thirty years before the mission. She was slightly older than the Prophet ﷺ and was among the noble women of Quraysh. Before the Prophet ﷺ she married her cousin al-Sakran ibn Amr ibn Abd Shams.",
      "She embraced Islam early with her husband al-Sakran. They were among the very first in Islam. They made the second emigration to Abyssinia fleeing Quraysh's harm; they had a son named Abd al-Rahman who grew up and became a Companion. Sawdah remained in Abyssinia for years, then returned to Makkah, and her husband al-Sakran died after his return.",
      "The Prophet ﷺ married her in the tenth year of the mission after Khadijah's death. She was the first the Prophet ﷺ married after Khadijah. The Prophet ﷺ chose Sawdah for several reasons: she was an aged widow, loved Islam and the Muslims, and was among the early supporters of the Prophet ﷺ in his house at Makkah. Her marriage was not for beauty or desire, but to honour her for her emigration and steadfastness in faith.",
      "She emigrated with the Prophet ﷺ to Madinah years after her marriage. She lived in a simple chamber by the Prophet's Mosque. She loved Allah and His Messenger, loved the Prophet's wives and did not quarrel with them. She was much given to charity. It is narrated that Umar ibn al-Khattab sent her a purse containing dirhams; she said to her maid: 'What is in this?' She said: 'Dirhams.' She said: 'In the bag?!' And she distributed them to the poor before sunset.",
      "When she grew old, she feared the Prophet ﷺ would divorce her. She said: 'O Messenger of Allah, I do not want what women want; I only want to be raised among your wives on the Day of Resurrection.' She gave her day and night to A'isha, preferring the Messenger of Allah ﷺ and seeking to remain with him in this world and the next. The Prophet ﷺ kept her and accepted her gift. Allah revealed about her: 'And if a woman fears from her husband contempt or evasion, there is no sin upon them if they make terms of settlement between them, and settlement is best.'",
      "In this stance is a great lesson. Sawdah did not look at the pleasure of this world but at the rank of the next. Her preference of A'isha was for Allah, not for A'isha. She wanted her name to remain among the Prophet's wives — a position nothing matches. No woman in the world holds this place: that she be raised with the Prophet ﷺ on the Day of Resurrection.",
      "She was strong of build and tall. It is narrated that when the verse of hijab was revealed, she went out at night to relieve herself, and Umar recognised her from afar and said: 'We have recognised you, Sawdah!' Out of concern to veil his wives, Allah sent down the hijab upon the Prophet's wives because of her — i.e. because of this incident. This shows her importance in the history of the legislation of hijab.",
      "She had a cheerful spirit. She would sometimes joke with the Prophet ﷺ, and the Prophet ﷺ would laugh at her jokes. It is narrated that she stood one night to pray and prolonged the prostration. When she rose, she felt her balance fail her for her height and weight of body. She laughed at herself and told the Prophet ﷺ, who laughed. Her nature was sincere, disliking artifice.",
      "She narrated from the Prophet ﷺ five hadiths. Though few, they are what jurists benefit from. She narrated about the qualities of the Prophet ﷺ in his house, about the Sunan of prayer and ablution, and about the Prophet's ﷺ character with his wives. Her hadiths were short but valuable as gold.",
      "In Umar ibn al-Khattab's caliphate, Sawdah died in 23 AH. In her last years she had grown weak, but she preserved her dignity and religion. Her body was carried in Madinah, and Commander of the Believers Umar ibn al-Khattab prayed over her. She was buried in al-Baqi' beside her sisters among the Mothers of the Believers.",
      "Her lessons are many. First: a Muslim woman may raise herself by her great stances. Sawdah was not the youngest of the Prophet's wives, nor the most beautiful, nor the most learned, but she was among the most noble in soul. Dignity does not need beauty; it needs a great soul.",
      "Second: preferring the Hereafter over this world is the path of the successful. Sawdah preferred her name to remain among the Prophet's wives on the Day of Resurrection over the pleasure of a day and a night in this world. How many today sell their Hereafter for a little of this world's pleasure! Sawdah did the opposite.",
      "Third: Islam equalised women by the level of their piety. Sawdah was not from the great noble daughters of Quraysh. But through her Islam, emigration, and marriage to the Prophet ﷺ, she became a Mother of the Believers. This is the bounty of Islam: it raises a person by deed, not by origin.",
      "Sawdah bint Zam'ah remains in the history of Islam the first the Prophet ﷺ married after Khadijah, the wife who gave her day to Allah and His Messenger, and the woman because of whom the hijab was revealed upon the Prophet's wives. O Allah, be pleased with Sawdah, and make us among those who prefer the Hereafter to this world as she preferred.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 23. أم سلمة هند بنت أبي أمية رضي الله عنها
  // ──────────────────────────────────────────────────────────────────────
  'umm-salama': {
    ar: P([
      'هي هند بنت أبي أمية حذيفة بن المغيرة المخزومية القرشية. تُكنّى بأم سلمة، وأبوها زاد الراكب — لُقّب بهذا لأنه كان يطعم الركبان في أسفارهم. وُلدت بمكة قبل البعثة بنحو 28 سنة. كانت من أشرف نساء قريش نسبًا وأجملهن وأعقلهن.',
      'تزوجت قبل الإسلام أبا سلمة عبد الله بن عبد الأسد المخزومي. أسلما معًا قديمًا في مكة، فكانا من السابقين الأولين. هاجرا الهجرة الأولى إلى الحبشة فرارًا من أذى قريش، ثم رجعا إلى مكة. أنجبت لأبي سلمة سلمة وعمر ودرة وزينب.',
      'لما اشتدّ الأذى على المسلمين مرة أخرى، عزم أبو سلمة على الهجرة إلى المدينة. كانت من أوائل من هاجر بأهله. لكن قومها — بنو المغيرة — منعوها من السفر مع زوجها. أخذوا منها ولدها سلمة. وذهب أبو سلمة وحده. بقيت أم سلمة في مكة سنة كاملة، كل صباح تخرج إلى الأبطح وتبكي على فراق زوجها وابنها، حتى رق لها بعض قومها وأذنوا لها بالسفر. سار معها رجل من قريش حتى أوصلها إلى المدينة.',
      'في غزوة أحد سنة 3 هـ، أصيب أبو سلمة إصابة بليغة. عاش بعد ذلك سنة، ثم انتقض جرحه فمات سنة 4 هـ. قبل موته، علّمها الدعاء الذي علّمه إياه النبي ﷺ: اللهم أجرني في مصيبتي واخلف لي خيرًا منها. ماتت في حضوره، وقال أم سلمة هذا الدعاء. قال أبو سلمة بعد موته الأول: أنا. ثم مات.',
      'بعد عدّتها، خطبها أبو بكر فاعتذرت. ثم خطبها عمر فاعتذرت. ثم خطبها النبي ﷺ. أعطته ثلاثة أعذار: أنها امرأة كبيرة، وأنها ذات أولاد، وأنها غيراء. فأجابها النبي ﷺ على كل عذر: أما السن فأنا أكبر منك. أما الأولاد فإلى الله ورسوله. وأما الغيرة فسأدعو الله أن يذهبها عنك. تزوجها سنة 4 هـ.',
      'كانت من أحب نساء النبي ﷺ إليه بعد عائشة. كانت ذات عقل وأدب. حدثت في حياتها مع النبي ﷺ مواقف عظيمة، أشهرها موقفها في صلح الحديبية.',
      'في صلح الحديبية سنة 6 هـ، اشتد على المسلمين شروط الصلح القاسية. أمر النبي ﷺ صحابته أن يحلوا من إحرامهم وينحروا ويحلقوا. لم يبادر أحد منهم لشدة حزنهم. كرر النبي ﷺ الأمر ثلاث مرات، فلم يقم أحد. دخل النبي ﷺ على أم سلمة حزينًا. شكا إليها فهم الصحابة للأمر.',
      'قالت أم سلمة كلمتها العظيمة التي غيّرت موقف الأمة كلها: يا رسول الله، أتحب ذلك؟ اخرج، ثم لا تكلم أحدًا منهم كلمة، حتى تنحر بدنك، وتدعو حالقك فيحلقك. خرج النبي ﷺ فما كلّم أحدًا حتى فعل ذلك. لما رآه الصحابة قاموا فنحروا، وجعل بعضهم يحلق بعضًا حتى كاد بعضهم يقتل بعضًا غمًّا. كانت نصيحة أم سلمة سببًا في إكمال أكبر صلح في تاريخ الإسلام.',
      'كانت من فقيهات الأمة. روت عن النبي ﷺ ثلاثمئة وثمانية وسبعين حديثًا. حدثت كثيرًا في أحكام الطهارة والصلاة والصيام والحج، وفي بيت النبي ﷺ، وفي معاملته مع نسائه. كانت تتلمذ عليها كثيرات من نساء التابعيات، وكانت بيتها مدرسة للفقه النسائي.',
      'كانت تروي حديث الكساء — حين جمع النبي ﷺ عليًا وفاطمة والحسن والحسين تحت كساء له، ودعا لهم. هذا الحديث من أعظم أحاديث آل البيت، رواه عن النبي ﷺ أم سلمة. ولها روايات كثيرة في فضائل أهل البيت.',
      'في فتنة قتل عثمان، كانت أم سلمة من المتمسكين بحب علي والاعتزال عن الفتنة. لما خرجت عائشة إلى البصرة، أرسلت إليها أم سلمة رسالة تنصحها بالعودة. قالت لها: يا أم المؤمنين، الزمي بيتك، فأنت زوج النبي ﷺ، والله جعل في الأعمال بركة في الأبيات. لكن عائشة لم تستمع.',
      'عاشت أم سلمة طويلًا. شهدت مقتل عثمان، ثم خلافة علي، ثم خلافة الحسن، ثم خلافة معاوية، ثم خلافة يزيد. شهدت مقتل الحسين بن علي في كربلاء سنة 61 هـ. حزنت عليه حزنًا شديدًا، فقد كان النبي ﷺ قد قال لها قبل وفاته: إن قُتل الحسين فالتراب الأحمر بين يديك علامة. فكان قبل مقتله بأيام رأت التراب يفور أحمر من قارورة كانت قد أعطاها النبي ﷺ.',
      'توفيت أم سلمة سنة 61 هـ بالمدينة، وعمرها قارب التسعين. كانت آخر أمهات المؤمنين وفاة — لم يبقَ بعدها أم مؤمنين. كان موتها نهاية عصر الزوجات الطاهرات للنبي ﷺ. صلى عليها أبو هريرة، ودُفنت بالبقيع.',
      'يبقى أم سلمة في تاريخ الإسلام صاحبة الرأي السديد في الحديبية، فقيهة الأمة، ذات الصبر العجيب على المصائب. عاشت أوّل الإسلام وآخره، وشهدت من الفتن ما يهز الجبال. اللهم ارضَ عن أم سلمة، وارزقنا الفقه في الدين كفقهها، والرأي السديد كرأيها.',
    ]),
    en: P([
      "She is Hind bint Abi Umayyah Hudhayfah ibn al-Mughirah al-Makhzumiyyah al-Qurashiyyah. She is called Umm Salamah, and her father was 'Zad al-Rakib' — nicknamed thus because he fed travellers on their journeys. She was born in Makkah about 28 years before the mission. She was among the most nobly descended, beautiful, and intelligent of the women of Quraysh.",
      "Before Islam she married Abu Salamah Abdullah ibn Abd al-Asad al-Makhzumi. They embraced Islam together early in Makkah, becoming among the very first. They made the first emigration to Abyssinia fleeing Quraysh's harm, then returned to Makkah. She bore Abu Salamah Salamah, Umar, Durrah, and Zaynab.",
      "When the harm on the Muslims intensified again, Abu Salamah resolved to emigrate to Madinah. She was among the first to emigrate with her family. But her people — Banu al-Mughirah — prevented her from travelling with her husband. They took her son Salamah from her. Abu Salamah went alone. Umm Salamah remained in Makkah a full year; every morning she went out to al-Abtah and wept over the separation from her husband and son, until some of her people had mercy on her and permitted her to travel. A man of Quraysh accompanied her until he delivered her to Madinah.",
      "At the Battle of Uhud in 3 AH, Abu Salamah was severely wounded. He lived for a year after, then his wound opened and he died in 4 AH. Before his death, he taught her the supplication the Prophet ﷺ had taught him: 'O Allah, reward me for my calamity and replace it with something better.' He died in her presence, and Umm Salamah said this supplication. Before Abu Salamah's death, she said his name and he said: 'I.' Then he died.",
      "After her waiting period, Abu Bakr proposed and she declined. Then Umar proposed and she declined. Then the Prophet ﷺ proposed. She gave him three excuses: she was an aged woman, had children, and was jealous. The Prophet ﷺ answered each: 'As for age, I am older than you. As for children, they are to Allah and His Messenger. As for jealousy, I shall pray to Allah to remove it from you.' He married her in 4 AH.",
      "She was among the most beloved of the Prophet's ﷺ wives after A'isha. She possessed intellect and refinement. In her life with the Prophet ﷺ occurred great stands, most famous her stand at the Treaty of Hudaybiyyah.",
      "At the Treaty of Hudaybiyyah in 6 AH, the harsh treaty terms were heavy on the Muslims. The Prophet ﷺ ordered his Companions to leave their ihram, slaughter, and shave. None stepped forward in their deep grief. The Prophet ﷺ repeated the order three times and none rose. The Prophet ﷺ entered Umm Salamah's place sad. He complained to her about the Companions' understanding of the matter.",
      "Umm Salamah said her great words that changed the position of the entire Ummah: 'O Messenger of Allah, do you love that? Go out, then speak to no one of them a word, until you slaughter your sacrificial animal and call your shaver to shave you.' The Prophet ﷺ went out and spoke to no one until he did so. When the Companions saw him they rose and slaughtered, and some began shaving others until they nearly killed each other in their grief. Umm Salamah's advice was the cause of completing the greatest treaty in the history of Islam.",
      "She was among the female jurists of the Ummah. She narrated from the Prophet ﷺ three hundred and seventy-eight hadiths. She narrated much about rulings of purity, prayer, fasting, and Hajj; about the Prophet's house ﷺ; and about his dealings with his wives. Many women of the Successors studied under her, and her house was a school for women's jurisprudence.",
      "She narrated the hadith of the cloak — when the Prophet ﷺ gathered Ali, Fatimah, Hasan, and Husayn under his cloak and supplicated for them. This hadith is among the greatest hadiths of the Prophet's Household, narrated from the Prophet ﷺ by Umm Salamah. She has many narrations on the virtues of the Prophet's Household.",
      "In the trial of Uthman's killing, Umm Salamah was among those who held to the love of Ali and withdrew from the trial. When A'isha went out to Basra, Umm Salamah sent her a letter advising her to return. She said to her: 'O Mother of the Believers, stay in your home; you are the wife of the Prophet ﷺ, and Allah placed in deeds a blessing in homes.' But A'isha did not listen.",
      "Umm Salamah lived a long life. She witnessed Uthman's killing, then Ali's caliphate, then Hasan's caliphate, then Mu'awiyah's caliphate, then Yazid's caliphate. She witnessed al-Husayn ibn Ali's killing at Karbala in 61 AH. She grieved deeply for him, for the Prophet ﷺ had said to her before his death: 'If al-Husayn is killed, the red soil before you will be a sign.' Days before his killing she saw soil overflow red from a flask the Prophet ﷺ had given her.",
      "Umm Salamah died in 61 AH in Madinah at nearly ninety years of age. She was the last of the Mothers of the Believers to die — no Mother of the Believers remained after her. Her death was the end of the era of the pure wives of the Prophet ﷺ. Abu Hurayrah prayed over her, and she was buried in al-Baqi'.",
      "Umm Salamah remains in the history of Islam the owner of the wise counsel at Hudaybiyyah, the jurist of the Ummah, possessor of remarkable patience against calamities. She lived the beginning of Islam and its end and witnessed of trials that shake mountains. O Allah, be pleased with Umm Salamah, and grant us jurisprudence in religion as her jurisprudence, and wise counsel as her counsel.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 24. فاطمة الزهراء رضي الله عنها — سيدة نساء أهل الجنة
  // ──────────────────────────────────────────────────────────────────────
  'fatima': {
    ar: P([
      'هي فاطمة بنت محمد بن عبد الله ﷺ. أم أبيها، البتول، الزهراء، سيدة نساء أهل الجنة، الإنسانة الوحيدة التي بقي من نسلها ذرية النبي ﷺ كلها. وُلدت بمكة قبل البعثة بخمس سنوات تقريبًا، أصغر بنات النبي ﷺ من خديجة بنت خويلد.',
      'نشأت في بيت النبي ﷺ، وكانت أحب البنات إليه. لما توفيت أمها خديجة وفاطمة في الثامنة من عمرها، حزنت حزنًا شديدًا. صارت تعتني بأبيها النبي ﷺ بدل أمها. لذلك لُقّبت بـ أم أبيها — لأنها كانت ترعى أباها كأنه ولدها. كان النبي ﷺ يقول لها: فديتك يا فاطمة.',
      'هاجرت إلى المدينة مع أبيها النبي ﷺ. في المدينة، طلبها أبو بكر الصديق للزواج، لكن النبي ﷺ اعتذر. ثم طلبها عمر بن الخطاب، فاعتذر. ثم طلبها علي بن أبي طالب — ابن عم النبي ﷺ. قبل النبي ﷺ. كان عمرها يومئذ 18 سنة، وعلي 21 سنة. تزوجا في السنة الثانية من الهجرة.',
      'كان مهر فاطمة درعًا اشتراها علي بأربعمئة درهم. عاشا حياة فقر مدقع. لم يكن في بيتهما إلا فراش من جلد كبش يفترشانه، ووسادة محشوة بليف نخل. كانت فاطمة تطحن القمح بيدها حتى مجلت يداها — أي تشققت من الإجهاد. وكانت تستقي الماء بقربة على ظهرها حتى أثّرت القربة على صدرها. وعلي كان يحطب ويسقي الزرع.',
      'في يوم من الأيام، جاء النبي ﷺ بأسرى. سمعت فاطمة بذلك، فقالت لعلي: لو ذهبنا إلى أبي نطلب منه خادمًا يعيننا. ذهبا، فلم يجدا النبي ﷺ. فلما رجع النبي إلى بيت علي وفاطمة، كانا قد ناما. دخل عليهما، فأرادت فاطمة أن تقوم. قال: مكانكما. ثم جلس بينهما وقدماه على بطنه. قال: ألا أعلمكما خيرًا مما سألتما؟ إذا أويتما إلى فراشكما، فسبّحا الله ثلاثًا وثلاثين، واحمداه ثلاثًا وثلاثين، وكبّراه أربعًا وثلاثين، فإنه خير لكما من خادم.',
      'هذه تسبيحة فاطمة المشهورة. علّمها النبي ﷺ بنته بدل الخادم. فيها تربية عظيمة: الذكر أفضل من الراحة، والاستعانة بالله أعظم من الاستعانة بالخادم. ظلت فاطمة وعلي يقولانها كل ليلة. صارت سنة لكل المسلمين بعدهما.',
      'أنجبت فاطمة لعلي خمسة من الأولاد: الحسن والحسين — سيدا شباب أهل الجنة — وزينب وأم كلثوم ومحسن. مات محسن صغيرًا. كان النبي ﷺ يحب أحفاده حبًا شديدًا. كان يحملهم على ظهره وهو يصلي، فيطيل السجود لئلا يسقطا. وكان يقول: ابناي هذان ريحانتاي من الدنيا. فاطمة هي الواحدة الوحيدة من بنات النبي ﷺ التي بقي نسلها — كل آل البيت اليوم من ذرية الحسن والحسين.',
      'كانت فاطمة شبيهة النبي ﷺ في خلقها وخُلُقها. قالت عائشة: ما رأيت أحدًا أشبه برسول الله ﷺ كلامًا وحديثًا من فاطمة. كانت إذا دخلت على النبي ﷺ قام إليها وقبّلها وأخذ بيدها وأجلسها في مجلسه. وإذا دخل عليها قامت إليه وقبّلت يده وأجلسته في مجلسها.',
      'كانت محبة للنبي ﷺ حبًا غير عادي. في غزوة أحد، أصيب النبي ﷺ في وجهه الشريف. جاءت فاطمة لتداوي وجه أبيها. أوقفت الدم، وأخذت قطعة من حصيرة وأحرقتها، ووضعت رمادها على الجرح حتى وقف الدم. ثم بكت بكاءً شديدًا — حتى دموع علي بن أبي طالب تساقطت رحمةً بها.',
      'في مرض النبي ﷺ الأخير، دعاها وأسرّ إليها بكلمتين. ضحكت ثم بكت. سُئلت بعد ذلك، فقالت: أخبرني النبي ﷺ أنه ميت في مرضه هذا، فبكيت. ثم أخبرني أنّي أول أهله لحوقًا به، وأنّي سيدة نساء أهل الجنة، فضحكت. كانت بشارة من النبي ﷺ بأنها ستلحقه أولًا بأولاده.',
      'لما توفي النبي ﷺ سنة 11 هـ، حزنت فاطمة حزنًا شديدًا لم يكن لأحد مثله. لم ترَ ضاحكة بعد موت أبيها. قالت كلمتها المشهورة: يا أبتاه، أجاب ربًا دعاه، يا أبتاه، جنة الفردوس مأواه، يا أبتاه، إلى جبريل ننعاه. ضعفت بدنها. مرضت. وفي رواية، حصل بينها وبين أبي بكر الصديق خلاف حول ميراث أبيها — أرادت أرض فدك، فاعتذر أبو بكر بأن النبي ﷺ قال: لا نورث، ما تركنا صدقة. غضبت فاطمة وهجرت أبا بكر. ثم تصالحا قبل وفاتها.',
      'توفيت فاطمة بعد النبي ﷺ بستة أشهر فقط، في 3 رمضان سنة 11 هـ. كان عمرها 28 أو 29 سنة. كانت كما أخبرها النبي ﷺ، أول أهله لحاقًا به. أوصت ألا يصلّي عليها أحد إلا علي بن أبي طالب وعدد قليل من أهل بيتها. غسّلتها أسماء بنت عميس بحضور علي. دفنها علي ليلًا بالبقيع. وقيل دُفنت في حجرتها بجوار قبر أبيها ﷺ. الله أعلم.',
      'بقي ذكر فاطمة في تاريخ الإسلام. كل آل البيت من نسلها. كل سلالة الأشراف في الإسلام كلها — في المغرب والمشرق وآسيا — تنتسب إليها. هي الجسر الوحيد بين النبي ﷺ وبين كل من ينتسب إلى أهل البيت اليوم. والعلويون والحسينيون والسادة من ذريتها.',
      'دروس فاطمة عظيمة. الأول: أن السعادة ليست في الثروة. عاشت فاطمة في فقر مع علي، لكنها كانت أسعد امرأة في الدنيا — كانت بنت أعظم رجل في تاريخ البشرية وزوجة من أعظم الرجال. الفقر مع الإيمان أعظم من الثروة بدون إيمان.',
      'الثاني: أن الذكر يكفي عن كل شيء. تسبيحة فاطمة كافية بدل خادم — أي بدل راحة جسدية كاملة. الذكر يقوي القلب ويخفّف الجسد. كم من غني له خدم كثيرون ولا يستطيع النوم! وكم من فقير يذكر الله فينام نوم الراحة.',
      'الثالث: أن أهل البيت يستحقون الحب لا الغلو. فاطمة بنت رسول الله، وأم سيدي شباب أهل الجنة. حبها فرض على كل مسلم. لكن الغلو فيها — كأن يُدعى لها من دون الله، أو تُعبد — كفر صريح. الإسلام دين توحيد، ولا يقبل أن يُعبد إلا الله وحده.',
      'يبقى فاطمة الزهراء في تاريخ الإسلام سيدة نساء أهل الجنة، البتول الطاهرة، الزهراء المباركة، أم الحسن والحسين، زوج علي بن أبي طالب، وأحب الناس إلى رسول الله ﷺ. اللهم ارضَ عن فاطمة، واجمعنا بها وبأبيها وبأولادها في جنات النعيم.',
    ]),
    en: P([
      "She is Fatimah bint Muhammad ibn Abdullah ﷺ. Mother of her Father, the Pure, the Radiant, Lady of the Women of Paradise, the only human through whose lineage the entire offspring of the Prophet ﷺ remained. She was born in Makkah about five years before the mission, the youngest of the Prophet's ﷺ daughters from Khadijah bint Khuwaylid.",
      "She grew up in the Prophet's ﷺ house and was the most beloved of his daughters. When her mother Khadijah died and Fatimah was eight years old, she grieved deeply. She came to care for her father the Prophet ﷺ in place of her mother. That is why she was nicknamed 'Umm Abiha' — Mother of her Father — because she tended her father as if he were her child. The Prophet ﷺ would say to her: 'May I be ransomed for you, Fatimah.'",
      "She emigrated to Madinah with her father the Prophet ﷺ. In Madinah, Abu Bakr al-Siddiq sought her in marriage, but the Prophet ﷺ apologised. Then Umar ibn al-Khattab sought her, and he apologised. Then Ali ibn Abi Talib — the Prophet's ﷺ cousin — sought her. The Prophet ﷺ accepted. She was 18 years old, and Ali 21. They married in the second year of the Hijrah.",
      "Fatimah's dowry was a coat of mail Ali bought for four hundred dirhams. They lived a life of extreme poverty. In their house was only a bed of sheepskin to lie on and a pillow stuffed with palm fibres. Fatimah ground wheat with her hand until her hands blistered — i.e. cracked from exertion. She drew water with a waterskin on her back until the skin marked her chest. Ali gathered firewood and watered the crops.",
      "One day the Prophet ﷺ came with captives. Fatimah heard of it and said to Ali: 'If only we went to my father to ask him for a servant to help us.' They went and did not find the Prophet ﷺ. When the Prophet returned to the house of Ali and Fatimah, they had slept. He entered upon them, and Fatimah wanted to rise. He said: 'Stay in your places.' He sat between them with his feet on her belly. He said: 'Shall I not teach you better than what you asked? When you go to your bed, say SubhanAllah thirty-three times, Alhamdulillah thirty-three times, and Allahu Akbar thirty-four times. That is better for you than a servant.'",
      "This is the famous Tasbih of Fatimah. The Prophet ﷺ taught his daughter instead of a servant. In it is a great teaching: remembrance is better than rest, and seeking help from Allah is greater than seeking help from a servant. Fatimah and Ali continued to say it every night. It became a Sunnah for all Muslims after them.",
      "Fatimah bore Ali five children: Hasan and Husayn — leaders of the youth of Paradise — Zaynab, Umm Kulthum, and Muhassin. Muhassin died young. The Prophet ﷺ loved his grandchildren dearly. He would carry them on his back while praying and prolong the prostration lest they fall. He would say: 'These two sons of mine are my two basils of this world.' Fatimah is the only one of the Prophet's ﷺ daughters whose offspring remained — every member of the Household today descends from Hasan and Husayn.",
      "Fatimah resembled the Prophet ﷺ in appearance and character. A'isha said: 'I have not seen anyone more similar to the Messenger of Allah ﷺ in speech and conversation than Fatimah.' When she entered upon the Prophet ﷺ, he would rise to her, kiss her, take her hand, and seat her in his place. When he entered upon her, she would rise to him, kiss his hand, and seat him in her place.",
      "She loved the Prophet ﷺ with an unusual love. At the Battle of Uhud, the Prophet ﷺ was struck in his noble face. Fatimah came to treat her father's face. She stopped the bleeding, took a piece of mat and burned it, and placed its ash on the wound until the bleeding stopped. Then she wept deeply — until Ali ibn Abi Talib's tears fell out of mercy for her.",
      "In the Prophet's ﷺ final illness, he called her and whispered to her two things. She laughed, then she wept. She was asked about it afterward, and she said: 'The Prophet ﷺ told me he would die in this illness of his, so I wept. Then he told me I would be the first of his household to follow him, and that I am the Lady of the Women of Paradise, so I laughed.' It was glad tidings from the Prophet ﷺ that she would follow him first of all his children.",
      "When the Prophet ﷺ died in 11 AH, Fatimah grieved a grief no one else matched. She was not seen laughing after her father's death. She said her famous words: 'O my father, he answered a Lord who called him. O my father, his abode is the Paradise of Firdaws. O my father, to Jibril we mourn him.' Her body weakened. She fell ill. In one narration, a disagreement occurred between her and Abu Bakr al-Siddiq about her father's inheritance — she wanted the land of Fadak, but Abu Bakr apologised that the Prophet ﷺ had said: 'We do not bequeath; what we leave is charity.' Fatimah was angered and shunned Abu Bakr. They reconciled before her death.",
      "Fatimah died after the Prophet ﷺ by only six months, on the 3rd of Ramadan in 11 AH. She was 28 or 29 years old. She was as the Prophet ﷺ had told her, the first of his household to follow him. She bequeathed that no one pray over her but Ali ibn Abi Talib and a small number of her household. Asma' bint Umays washed her in Ali's presence. Ali buried her at night in al-Baqi'. It is said she was buried in her chamber beside her father's grave ﷺ. Allah knows best.",
      "Fatimah's memory remained in the history of Islam. All the Household are from her lineage. Every line of nobles in Islam — in the Maghrib, the Mashriq, and Asia — traces back to her. She is the only bridge between the Prophet ﷺ and everyone who claims descent from the Household today. The Alawiyyun, Husayniyyun, and Sayyids are from her offspring.",
      "Fatimah's lessons are great. First: happiness is not in wealth. Fatimah lived in poverty with Ali, but she was the happiest woman in the world — she was the daughter of the greatest man in human history and the wife of one of the greatest men. Poverty with faith is greater than wealth without faith.",
      "Second: remembrance suffices for everything. The Tasbih of Fatimah suffices instead of a servant — i.e. instead of complete bodily rest. Remembrance strengthens the heart and lightens the body. How many a wealthy one has many servants and cannot sleep! And how many a poor one remembers Allah and sleeps the sleep of rest.",
      "Third: the Prophet's Household deserve love, not extremism. Fatimah is the daughter of the Messenger of Allah and the mother of the leaders of the youth of Paradise. Her love is obligatory on every Muslim. But extremism toward her — such as supplicating to her apart from Allah, or worshipping her — is plain disbelief. Islam is a religion of monotheism and does not accept that any be worshipped but Allah alone.",
      "Fatimah al-Zahra remains in the history of Islam the Lady of the Women of Paradise, the Pure Maiden, the Blessed Radiant, mother of Hasan and Husayn, wife of Ali ibn Abi Talib, and the most beloved of people to the Messenger of Allah ﷺ. O Allah, be pleased with Fatimah, and gather us with her, her father, and her children in the Gardens of Bliss.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 25. زينب بنت رسول الله ﷺ
  // ──────────────────────────────────────────────────────────────────────
  'zaynab-prophet': {
    ar: P([
      'هي زينب بنت محمد بن عبد الله ﷺ. كبرى بنات النبي ﷺ من خديجة بنت خويلد. وُلدت بمكة قبل البعثة بنحو عشر سنين. كانت أكبر إخوتها، فهي الأم الكبيرة في بيت النبي ﷺ.',
      'تزوجت قبل البعثة من ابن خالتها أبي العاص بن الربيع. كانت أمه هالة بنت خويلد، أخت خديجة أم زينب. وكان أبو العاص من أوفياء قريش الكرماء، رجل تاجر ميسور، يحب زينب حبًا شديدًا. تزوجها وأنجب منها عليًا وأمامة.',
      'لما بُعث النبي ﷺ وأسلمت خديجة وبناتها، آمنت زينب مع أمها. لكن زوجها أبا العاص لم يسلم — تردد. ضغطت قريش عليه أن يطلّق زينب عقوبة للنبي ﷺ، لكنه رفض رفضًا قاطعًا. قال: لا أبدّل زوجتي بأخرى! بقي على شركه ولكنه احتفظ بزوجته الموحّدة.',
      'هاجر النبي ﷺ إلى المدينة، وبقيت زينب في مكة مع زوجها. كانت أحوالها صعبة — مسلمة في بيت مشرك، أبوها مهاجر، أمها متوفاة، إخوتها متفرقات. صبرت سنين تنتظر فرصة الهجرة.',
      'في غزوة بدر سنة 2 هـ، شارك أبو العاص مع قريش ضد المسلمين. أُسر يومئذ. أرسلت زينب فدية لزوجها، وكانت من ضمن الفدية قلادة لأمها خديجة قد أعطتها إياها يوم زواجها. لما رأى النبي ﷺ القلادة، رقّ لها رقّة شديدة. تذكر خديجة. سأل الصحابة: إن رأيتم أن تطلقوا لها أسيرها وتردّوا عليها الذي لها، فافعلوا. فأطلقوا أبا العاص بدون فدية، وأعادوا القلادة لزينب.',
      'اشترط النبي ﷺ على أبي العاص أن يرسل زينب إلى المدينة. وفّى أبو العاص بوعده. أرسلها مع أخيه كنانة. في الطريق، اعترضها رجل من قريش اسمه هبار بن الأسود. ضربها بالرمح وهي حامل. سقطت من بعيرها فأسقطت جنينها. مرضت من تلك الإصابة، وبقي المرض معها سنين، حتى ماتت من آثاره.',
      'وصلت إلى المدينة. عاشت في بيت أبيها النبي ﷺ. كان أبو العاص لا يزال مشركًا في مكة. مرت سنوات، حتى خرج أبو العاص في تجارة، فاعترضته سرية إسلامية وأخذت ماله. لجأ إلى زينب في المدينة، فأجارته. وفي الصبح، صلت زينب الفجر مع المسلمين وقالت بصوت مرتفع: قد أجرت أبا العاص بن الربيع. التفت النبي ﷺ وسأل: هل سمعتم ما سمعت؟ قالوا: نعم. فأجاز جوارها. ردّ المسلمون مال أبي العاص.',
      'رجع أبو العاص إلى مكة، ردّ الأموال إلى أصحابها، ثم أعلن إسلامه. هاجر إلى المدينة، ورجعت إليه زينب بنفس النكاح القديم — حسب الفتوى التي اختارها النبي ﷺ في تلك المسألة. كانت قصة حب نادرة في التاريخ: زوج وزوجة بقي حبهما رغم اختلاف دينهما لسنين، حتى جمعهما الإسلام في النهاية.',
      'لم تعش زينب طويلًا بعد عودة أبي العاص. ماتت سنة 8 هـ في المدينة، متأثرة بإصابة هبار التي حدثت لها في طريق الهجرة. كان النبي ﷺ حزنه عليها شديدًا. غسّلتها أم أيمن وأم سلمة وسودة. كفّنها النبي ﷺ بحقوه — أي ثوبه الداخلي — تبرّكًا. ودعا لها: يا فاطمة، انزعي عنها ثوبيها، وادفنوها بحقوي. دفنت بالبقيع.',
      'قال النبي ﷺ في حقّها: خير بناتي زينب. وفي رواية أخرى: ابنتي بُتلت في زوجها — أي ابتُليت في زواجها. كانت زينب نموذجًا للمرأة الصابرة التي تحمل الأذى بسبب دينها. سنوات من البعد عن أبيها وأمها وإخوتها. ضربة في الطريق أفقدتها جنينها. مرض طويل. كل هذا تحملته راضية لأنها مسلمة.',
      'تركت زينب من الأولاد علي بن أبي العاص — مات صغيرًا — وأمامة بنت أبي العاص. أمامة عاشت طويلًا، وتزوجها علي بن أبي طالب بعد وفاة فاطمة الزهراء — وكانت من نسل النبي ﷺ، فأراد علي أن يبقى نسل النبي في بيته. لم تنجب أمامة لعلي ولدًا، فبقي نسل النبي ﷺ من فاطمة فقط، لا من زينب.',
      'دروس زينب عظيمة. الأول: أن المرأة المسلمة قد تتحمل بسبب دينها ما لا يتحمله غيرها. سنوات من الانفصال عن أبيها وأمها وإخوتها. كل هذا الصبر بسبب أنها مسلمة في بيت مشرك. وكم من امرأة اليوم تشكو من أصعب الأوضاع، وهي أهون بكثير مما لاقته زينب.',
      'الثاني: أن الإسلام لا يلغي الأسرة. زينب أحبت زوجها المشرك ولم تطلبه. والإسلام لم يأمرها بفسخ الزواج فورًا، بل صبرت سنوات حتى نزل التشريع بحرمة زواج المسلمة من المشرك بعد بدر. الإسلام يحفظ الأسرة قدر الإمكان.',
      'الثالث: أن النبي ﷺ بشر يحب أولاده ويفقدهم. حزن النبي ﷺ على زينب أعظم الحزن. كانت أكبر بناته. تذكره بخديجة وبأيام مكة. كل هذا الحزن دليل أن النبوة لا تلغي البشرية. النبي ﷺ يحب ويحزن ويفرح كأي إنسان.',
      'يبقى زينب بنت رسول الله ﷺ في تاريخ الإسلام كبرى البنات، أم أمامة التي تزوجها علي، خير بنات النبي ﷺ كما قال أبوها. اللهم ارضَ عن زينب، واجمعنا بها وبأبيها في جنات النعيم.',
    ]),
    en: P([
      "She is Zaynab bint Muhammad ibn Abdullah ﷺ. The eldest of the Prophet's ﷺ daughters from Khadijah bint Khuwaylid. She was born in Makkah about ten years before the mission. She was the eldest of her siblings, the elder mother in the Prophet's ﷺ house.",
      "Before the mission she married her maternal cousin Abu al-As ibn al-Rabi. His mother was Halah bint Khuwaylid, sister of Khadijah, Zaynab's mother. Abu al-As was among the faithful, generous of Quraysh, a well-off merchant who loved Zaynab dearly. He married her and she bore him Ali and Umamah.",
      "When the Prophet ﷺ was sent and Khadijah and her daughters embraced Islam, Zaynab believed with her mother. But her husband Abu al-As did not embrace Islam — he hesitated. Quraysh pressured him to divorce Zaynab as a punishment to the Prophet ﷺ, but he refused absolutely. He said: 'I will not exchange my wife for another!' He remained on his shirk but kept his believing wife.",
      "The Prophet ﷺ emigrated to Madinah, and Zaynab remained in Makkah with her husband. Her conditions were hard — a Muslim in a polytheist's house, her father an emigrant, her mother deceased, her sisters dispersed. She bore patiently for years awaiting an opportunity to emigrate.",
      "At the Battle of Badr in 2 AH, Abu al-As participated with Quraysh against the Muslims. He was captured that day. Zaynab sent ransom for her husband, including a necklace of her mother Khadijah she had given her on her wedding day. When the Prophet ﷺ saw the necklace, he was deeply moved. He remembered Khadijah. He asked the Companions: 'If you see fit to release her captive for her and return what is hers, do so.' They released Abu al-As without ransom and returned the necklace to Zaynab.",
      "The Prophet ﷺ stipulated that Abu al-As send Zaynab to Madinah. Abu al-As kept his promise. He sent her with his brother Kinanah. On the road, a man of Quraysh named Habbar ibn al-Aswad intercepted her. He struck her with a spear while she was pregnant. She fell from her camel and miscarried. She fell ill from that injury, and the illness remained with her for years, until she died from its effects.",
      "She reached Madinah. She lived in her father the Prophet's ﷺ house. Abu al-As was still a polytheist in Makkah. Years passed. Abu al-As went on a trading expedition, but a Muslim raiding party intercepted him and took his goods. He sought refuge with Zaynab in Madinah, and she granted him refuge. In the morning, Zaynab prayed Fajr with the Muslims and said in a raised voice: 'I have granted refuge to Abu al-As ibn al-Rabi.' The Prophet ﷺ turned and asked: 'Did you hear what I heard?' They said: 'Yes.' He allowed her grant of refuge. The Muslims returned Abu al-As's goods.",
      "Abu al-As returned to Makkah, returned the goods to their owners, then announced his Islam. He emigrated to Madinah, and Zaynab returned to him under the original marriage contract — according to the ruling the Prophet ﷺ chose in that matter. It was a rare love story in history: a husband and wife whose love remained despite the difference of their religion for years, until Islam joined them at last.",
      "Zaynab did not live long after Abu al-As's return. She died in 8 AH in Madinah from the effects of Habbar's blow on her emigration road. The Prophet's ﷺ grief over her was severe. Umm Ayman, Umm Salamah, and Sawdah washed her. The Prophet ﷺ shrouded her in his waist-wrap — his inner garment — for blessing. He supplicated for her: 'O Fatimah, remove her two garments and bury her in my waist-wrap.' She was buried in al-Baqi'.",
      "The Prophet ﷺ said about her: 'The best of my daughters is Zaynab.' In another narration: 'My daughter was tested in her husband' — i.e. tested in her marriage. Zaynab was a model of the patient woman who bears harm for her religion. Years of separation from her father, mother, and siblings. A blow on the road that lost her her unborn child. A long illness. She bore all this contentedly because she was a Muslim.",
      "Zaynab left as children Ali ibn Abi al-As — who died young — and Umamah bint Abi al-As. Umamah lived long, and Ali ibn Abi Talib married her after Fatimah al-Zahra's death — she was of the Prophet's ﷺ lineage, and Ali wanted to keep the Prophet's lineage in his house. Umamah did not bear Ali a son, so the Prophet's ﷺ lineage remained only through Fatimah, not Zaynab.",
      "Zaynab's lessons are great. First: a Muslim woman may bear because of her religion what others do not bear. Years of separation from her father, mother, and siblings. All this patience because she was a Muslim in a polytheist's house. How many a woman today complains of conditions far easier than what Zaynab met.",
      "Second: Islam does not abolish the family. Zaynab loved her polytheist husband and did not demand divorce. Islam did not order her to dissolve the marriage at once but she bore patiently for years until the legislation came down forbidding the marriage of a Muslim woman to a polytheist after Badr. Islam preserves the family as much as possible.",
      "Third: the Prophet ﷺ is a human who loves his children and loses them. The Prophet ﷺ grieved greatly over Zaynab. She was his eldest daughter. She reminded him of Khadijah and the days of Makkah. All this grief is evidence that prophethood does not abolish humanity. The Prophet ﷺ loved, grieved, and rejoiced like any human.",
      "Zaynab bint Rasulillah ﷺ remains in the history of Islam the eldest daughter, mother of Umamah whom Ali married, the best of the Prophet's ﷺ daughters as her father said. O Allah, be pleased with Zaynab, and gather us with her and her father in the Gardens of Bliss.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 26. رقية بنت رسول الله ﷺ
  // ──────────────────────────────────────────────────────────────────────
  'ruqayyah': {
    ar: P([
      'هي رقية بنت محمد بن عبد الله ﷺ. ثانية بنات النبي ﷺ من خديجة بنت خويلد. وُلدت بمكة قبل البعثة بسبع سنوات. كانت من أجمل نساء قريش، وأمها خديجة سيدة قريش.',
      'خطبها قبل البعثة عتبة بن أبي لهب — ابن عم النبي ﷺ، ابن أبي لهب عبد العزى. كان زواجًا متفقًا عليه بين قبيلتين شريفتين. لكن لما بُعث النبي ﷺ، نزلت سورة المسد في حق أبي لهب وأم جميل زوجته. غضب أبو لهب وأم جميل غضبًا شديدًا. أمر ابنه عتبة بطلاق رقية فطلّقها قبل البناء بها. كانت أول مصيبة عاشتها رقية في حياتها بسبب إيمانها.',
      'لم تحزن رقية على طلاق عتبة. كانت من المؤمنات المتحمسات للدين الجديد. تزوجها عثمان بن عفان — ابن خالتها أروى بنت كريز — وكان من السابقين الأولين في الإسلام. كان عثمان فتى جميل، تاجرًا غنيًا، من سادات قريش. تزوجها قبل الهجرة إلى الحبشة بقليل.',
      'لما اشتد الأذى على المسلمين في مكة، أمر النبي ﷺ المسلمين بالهجرة الأولى إلى الحبشة. كان عثمان ورقية من أوائل من هاجروا. خرجوا في ليلة مظلمة من مكة، ركبوا سفينة إلى الحبشة. قال النبي ﷺ لما خرجا: إنهما لأول من هاجر بأهله في سبيل الله بعد لوط. كرّم النبي ﷺ هذه الزيجة بتنويه إلى أنها أول هجرة بزوج كامل في الإسلام.',
      'وصلا إلى الحبشة، فاستقبلهما النجاشي ملك الحبشة المسيحي الصالح. عاشا في الحبشة سنوات، حتى أنجبت رقية لعثمان ابنها عبد الله — الذي عاش بعد ذلك حتى توفي صغيرًا في المدينة. لما سمع المسلمون في الحبشة أن قريشًا أسلمت بسبب قراءة النبي ﷺ سورة النجم، رجع بعضهم إلى مكة. لكن الخبر كان كاذبًا — قريش لم تسلم. رجعت رقية وعثمان مرة أخرى إلى الحبشة، وبقيا حتى الهجرة إلى المدينة.',
      'هاجرا إلى المدينة بعد الهجرة بقليل. عاشت رقية في بيتها بالمدينة. كانت تحب النبي ﷺ كحب البنت لأبيها، وتحب زوجها عثمان حبًا قويًا. كانت من أقرب البنات إلى النبي ﷺ بعد فاطمة.',
      'في غزوة بدر سنة 2 هـ، خرج عثمان مع الجيش الإسلامي. لكن قبل الخروج، مرضت رقية مرضًا شديدًا. أمر النبي ﷺ عثمان بأن يبقى ليرعى زوجته. خرج النبي ﷺ والجيش، وبقي عثمان في المدينة. شدّ مرض رقية. في يوم بدر بالذات — يوم النصر الكبير — توفيت رقية. ماتت ولم تعش لتسمع نبأ النصر العظيم.',
      'في طريق العودة من بدر، جاء زيد بن حارثة يبشّر بالنصر. قابل عثمان عند مقابر المدينة. لم يستطع عثمان أن يبتسم بالنصر، فقد كان قد دفن زوجته للتو. قال زيد: إنا لله وإنا إليه راجعون. لما رجع النبي ﷺ، حزن على ابنته رقية حزنًا شديدًا، لكنه ضرب لعثمان بسهم من غنائم بدر وأجر، وقال: هو فيمن شهد بدرًا.',
      'بعد فترة من وفاة رقية، زوّج النبي ﷺ عثمان بأختها أم كلثوم. صار عثمان ذا النورين لأنه تزوج اثنتين من بنات النبي ﷺ. قال النبي ﷺ: لو كان عندي ثالثة لزوجتك إياها يا عثمان. هذا أعظم تكريم لرجل لم يتزوج اثنتين من بنات نبي قبله ولا بعده.',
      'لم تترك رقية ذرية باقية. ابنها عبد الله مات صغيرًا في المدينة بعدها بسنوات. لما توفي عبد الله، حضر النبي ﷺ جنازته، فبكى. كان النبي ﷺ يحب أحفاده الصغار حبًا شديدًا. عبد الله بن عثمان كان أحد أحفاد النبي ﷺ القلائل الذين رآهم وحملهم.',
      'دفنت رقية بالبقيع — أول من دُفن من بنات النبي ﷺ في البقيع. صلى عليها النبي ﷺ. كانت بنية ابن عمها زائرة لها قبل موتها — أسماء بنت أبي بكر أو غيرها. حزن النبي ﷺ على رقية حزنًا شديدًا. كانت أول من فقد من بناته بعد الهجرة.',
      'دروس رقية عظيمة. الأول: أن المؤمنة قد تُبتلى بالطلاق بسبب دينها. عتبة بن أبي لهب طلق رقية لأن أباها أنذر قومه. هذه أول مصيبة لها. لكنها لم تحزن، لأن دينها أعظم من زوج.',
      'الثاني: أن الهجرة بالنفس والأهل من أعظم الأعمال. رقية وعثمان كانا أول زوج كامل يهاجر في الإسلام بعد لوط. هذا فضل عظيم — أن يكون الزوج والزوجة معًا على دين، ويهاجران معًا من بلد إلى بلد.',
      'الثالث: أن النبي ﷺ يفقد أولاده كأي أب. توفي القاسم وعبد الله صغارًا. توفيت رقية في يوم بدر. توفيت زينب. توفيت أم كلثوم. لم يبقَ للنبي ﷺ من أولاده عند وفاته إلا فاطمة، التي ماتت بعده بستة أشهر. هذه ابتلاءات عظيمة، تحملها النبي ﷺ بصبر إيماني عجيب.',
      'يبقى رقية بنت رسول الله ﷺ في تاريخ الإسلام ثانية البنات، زوج عثمان ذي النورين الأولى، أم عبد الله، التي ماتت يوم النصر الكبير في بدر. اللهم ارضَ عن رقية، واجمعنا بها وبأبيها وأمها وأخواتها في جنات النعيم.',
    ]),
    en: P([
      "She is Ruqayyah bint Muhammad ibn Abdullah ﷺ. The second of the Prophet's ﷺ daughters from Khadijah bint Khuwaylid. She was born in Makkah seven years before the mission. She was among the most beautiful women of Quraysh, and her mother Khadijah was the Lady of Quraysh.",
      "Before the mission she was engaged to Utbah ibn Abi Lahab — the Prophet's ﷺ cousin, son of Abu Lahab Abd al-Uzza. It was an agreed marriage between two noble tribes. But when the Prophet ﷺ was sent, Surah al-Masad was revealed concerning Abu Lahab and his wife Umm Jamil. Abu Lahab and Umm Jamil became severely angry. He ordered his son Utbah to divorce Ruqayyah, and he divorced her before consummation. It was the first calamity Ruqayyah lived in her life because of her faith.",
      "Ruqayyah did not grieve at Utbah's divorce. She was an enthusiastic believer in the new religion. Uthman ibn Affan — her maternal cousin through Arwa bint Kurayz — married her; he was among the very first in Islam. Uthman was a beautiful youth, a wealthy merchant, of the chiefs of Quraysh. He married her shortly before the emigration to Abyssinia.",
      "When the harm on the Muslims in Makkah intensified, the Prophet ﷺ ordered the Muslims to make the first emigration to Abyssinia. Uthman and Ruqayyah were among the first to emigrate. They went out on a dark night from Makkah, boarded a ship to Abyssinia. The Prophet ﷺ said when they went out: 'They are the first to emigrate with family in Allah's cause after Lot.' The Prophet ﷺ honoured this marriage by noting it was the first emigration with a complete couple in Islam.",
      "They arrived in Abyssinia, where the Negus — its righteous Christian king — received them. They lived in Abyssinia for years, and Ruqayyah bore Uthman a son Abdullah — who later lived until he died young in Madinah. When the Muslims in Abyssinia heard that Quraysh had embraced Islam because of the Prophet's ﷺ recitation of Surah al-Najm, some returned to Makkah. But the news was false — Quraysh had not embraced Islam. Ruqayyah and Uthman returned again to Abyssinia and stayed until the emigration to Madinah.",
      "They emigrated to Madinah shortly after the Hijrah. Ruqayyah lived in her house in Madinah. She loved the Prophet ﷺ as a daughter loves her father, and loved her husband Uthman with a strong love. She was among the closest daughters to the Prophet ﷺ after Fatimah.",
      "At the Battle of Badr in 2 AH, Uthman went out with the Muslim army. But before leaving, Ruqayyah fell into a severe illness. The Prophet ﷺ ordered Uthman to stay and care for his wife. The Prophet ﷺ and the army went out, and Uthman remained in Madinah. Ruqayyah's illness intensified. On the very day of Badr — the day of great victory — Ruqayyah died. She died without living to hear the news of the great victory.",
      "On the road back from Badr, Zayd ibn Harithah came giving glad tidings of victory. He met Uthman at the Madinah cemeteries. Uthman could not smile at the victory, for he had just buried his wife. Zayd said: 'Inna lillahi wa inna ilayhi raji'un.' When the Prophet ﷺ returned, he grieved deeply for his daughter Ruqayyah, but allotted Uthman a share of Badr's spoils and reward, saying: 'He is among those who witnessed Badr.'",
      "After a period from Ruqayyah's death, the Prophet ﷺ married Uthman to her sister Umm Kulthum. Uthman became Dhu al-Nurayn (Possessor of the Two Lights) because he married two of the Prophet's ﷺ daughters. The Prophet ﷺ said: 'If I had a third, I would have married her to you, Uthman.' This is the greatest honour for a man — no one married two daughters of a prophet before or after him.",
      "Ruqayyah did not leave any surviving offspring. Her son Abdullah died young in Madinah years after her. When Abdullah died, the Prophet ﷺ attended his funeral and wept. The Prophet ﷺ loved his young grandchildren dearly. Abdullah ibn Uthman was one of the few grandchildren of the Prophet ﷺ whom he saw and carried.",
      "Ruqayyah was buried in al-Baqi' — the first of the Prophet's ﷺ daughters to be buried in al-Baqi'. The Prophet ﷺ prayed over her. Her cousin's daughter was visiting her before her death — Asma' bint Abi Bakr or another. The Prophet ﷺ grieved deeply for Ruqayyah. She was the first of his daughters he lost after the Hijrah.",
      "Ruqayyah's lessons are great. First: a believing woman may be tested with divorce because of her religion. Utbah ibn Abi Lahab divorced Ruqayyah because her father had warned his people. This was her first calamity. But she did not grieve, because her religion was greater than a husband.",
      "Second: emigration with one's family is among the greatest deeds. Ruqayyah and Uthman were the first complete couple to emigrate in Islam after Lot. This is a great virtue — that husband and wife be together on the religion and emigrate together from one land to another.",
      "Third: the Prophet ﷺ loses his children like any father. al-Qasim and Abdullah died young. Ruqayyah died on the day of Badr. Zaynab died. Umm Kulthum died. Of the Prophet's ﷺ children at his death only Fatimah remained, who died six months after him. These are great trials, which the Prophet ﷺ bore with remarkable believing patience.",
      "Ruqayyah bint Rasulillah ﷺ remains in the history of Islam the second daughter, the first wife of Uthman Dhu al-Nurayn, mother of Abdullah, who died on the day of the great victory at Badr. O Allah, be pleased with Ruqayyah, and gather us with her and her father, mother, and sisters in the Gardens of Bliss.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 27. أم كلثوم بنت رسول الله ﷺ
  // ──────────────────────────────────────────────────────────────────────
  'umm-kulthum-daughter': {
    ar: P([
      'هي أم كلثوم بنت محمد بن عبد الله ﷺ. ثالثة بنات النبي ﷺ من خديجة بنت خويلد. وُلدت بمكة قبل البعثة بنحو ست سنين. كانت أصغر من أختها رقية بسنة، وأكبر من أختها فاطمة بسنة.',
      'خطبها قبل البعثة عتيبة بن أبي لهب — أخو عتبة الذي خطب رقية. كان زواجًا مرتّبًا بين العائلتين. لما بُعث النبي ﷺ ونزلت سورة المسد في حق أبي لهب وأم جميل، غضب أبو لهب وأمر ابنيه بطلاق بنتي محمد ﷺ. طلّق عتيبة أم كلثوم قبل البناء بها، كما طلّق أخوه عتبة رقية. كانت كل البنات الثلاث الكبرى — زينب ورقية وأم كلثوم — قد عانين من أذى أبي لهب الذي صار أحد رموز الكفر في القرآن.',
      'بقيت أم كلثوم في بيت أبيها سنين بعد طلاقها. كانت تربى في بيت الإيمان مع أبيها وأمها وأخواتها. هاجرت إلى المدينة مع أهل بيت النبي ﷺ بعد الهجرة. عاشت في بيت النبي ﷺ، تعينه على أمور بيته.',
      'في غزوة بدر سنة 2 هـ، توفيت أختها رقية. حزنت أم كلثوم حزنًا شديدًا. بعد فترة من وفاة رقية، اقترح بعض الصحابة على النبي ﷺ أن يزوّج عثمان من بناته الأخرى. زوّجها النبي ﷺ من عثمان بن عفان سنة 3 هـ. قال النبي ﷺ لعثمان: لو كان عندي ثالثة لزوّجتك إياها. صار عثمان ذا النورين بزواج أم كلثوم.',
      'عاشت أم كلثوم مع عثمان ست سنوات تقريبًا. كانت زوجة طيبة، تشبه أختها رقية في الجمال والدين. كانت من السيدات الفاضلات في المدينة. لم تنجب لعثمان أي ولد، فبقي عبد الله — ابنها رقية — وحيد عثمان من بنات النبي ﷺ.',
      'في السنة التاسعة من الهجرة، مرضت أم كلثوم مرضًا شديدًا. توفيت في شعبان أو رمضان من تلك السنة. كان النبي ﷺ في غزوة تبوك، فلم يحضر دفنها. لما رجع، حزن عليها حزنًا شديدًا. قام عند قبرها يبكي، وقال: لو كان عندي ثالثة لزوّجتك إياها يا عثمان. كانت كلمة عجيبة — تكرار للوعد السابق، تأكيدًا على فضل عثمان وفقد ابنته.',
      'دفنت أم كلثوم بالبقيع، إلى جنب أختها رقية. أم أيمن وأسماء بنت عميس وصفية بنت عبد المطلب — عمة النبي ﷺ — كانوا حاضرين دفنها. تولى عبد الرحمن بن عوف وعمر بن الخطاب إنزالها إلى قبرها بطلب من النبي ﷺ في غيابه. شاركت أمهات المؤمنين والصحابيات في تجهيزها.',
      'لم تترك أم كلثوم ذرية. كأخواتها رقية وزينب. الذرية الوحيدة الباقية للنبي ﷺ كانت من فاطمة الزهراء فقط. هذا قدر الله أن يبقى نسل أعظم الناس من بنت واحدة.',
      'بعد وفاة أم كلثوم، لم يبقَ للنبي ﷺ من بناته إلا فاطمة. كل البنات الأخريات قد مت في حياته. توفي القاسم وعبد الله — ابنيه — صغارين. توفيت زينب سنة 8 هـ. توفيت رقية سنة 2 هـ. توفيت أم كلثوم سنة 9 هـ. لم يبق إلا فاطمة، التي ماتت بعد النبي ﷺ بستة أشهر سنة 11 هـ.',
      'مع كل هذه المصائب، صبر النبي ﷺ صبرًا عظيمًا. كان يبكي على بنته لكنه لا يقول إلا ما يرضي الله. وقفته بجوار قبر أم كلثوم درس في الصبر. تذكر لعثمان فضله، وتذكر أن الموت سنة الحياة، وتذكر أن الله يبتلي من يحب.',
      'دروس أم كلثوم عظيمة. الأول: أن المؤمنة قد تعيش حياة قصيرة لكنها مليئة بالفضل. أم كلثوم لم تعش طويلًا — ماتت في الثلاثينات من عمرها. لكنها كانت بنت رسول الله ﷺ، وزوج عثمان ذي النورين، وأخت فاطمة الزهراء. حياة قصيرة لكنها كانت في أعظم بيت في التاريخ.',
      'الثاني: أن العمر لا يقاس بالسنين بل بالفضل. كم من إنسان عاش طويلًا ولم يترك أثرًا. وكم من إنسان عاش قصيرًا فترك التاريخ كله. أم كلثوم تركت ذكرها في كتب الحديث والسيرة، تذكر في كل مرة يُذكر فيها عثمان أو بنات النبي ﷺ.',
      'الثالث: أن الزواج من بنت رسول الله شرف لا يدانيه شرف. عثمان نال هذا الشرف مرتين — رقية ثم أم كلثوم. هذا ما لم يحظَ به أحد قبله ولا بعده. وفضل عثمان عظيم بسبب هذه الكرامة من النبي ﷺ.',
      'يبقى أم كلثوم بنت رسول الله ﷺ في تاريخ الإسلام ثالثة بنات النبي ﷺ، زوج عثمان ذي النورين الثانية، أخت فاطمة وزينب ورقية. اللهم ارضَ عن أم كلثوم، واجمعنا بها وبأبيها وأخواتها في جنات النعيم.',
    ]),
    en: P([
      "She is Umm Kulthum bint Muhammad ibn Abdullah ﷺ. The third of the Prophet's ﷺ daughters from Khadijah bint Khuwaylid. She was born in Makkah about six years before the mission. She was a year younger than her sister Ruqayyah and a year older than her sister Fatimah.",
      "Before the mission she was engaged to Utaybah ibn Abi Lahab — brother of Utbah who was engaged to Ruqayyah. It was an arranged marriage between the two families. When the Prophet ﷺ was sent and Surah al-Masad was revealed about Abu Lahab and Umm Jamil, Abu Lahab grew angry and ordered his two sons to divorce Muhammad's ﷺ two daughters. Utaybah divorced Umm Kulthum before consummation, as his brother Utbah divorced Ruqayyah. All three elder daughters — Zaynab, Ruqayyah, and Umm Kulthum — had suffered the harm of Abu Lahab who became a symbol of disbelief in the Qur'an.",
      "Umm Kulthum remained in her father's house for years after her divorce. She was raised in the house of faith with her father, mother, and sisters. She emigrated to Madinah with the Prophet's ﷺ household after the Hijrah. She lived in the Prophet's ﷺ house, helping him with the affairs of his home.",
      "At the Battle of Badr in 2 AH, her sister Ruqayyah died. Umm Kulthum grieved deeply. After a period from Ruqayyah's death, some Companions suggested to the Prophet ﷺ that he marry Uthman to another of his daughters. The Prophet ﷺ married her to Uthman ibn Affan in 3 AH. The Prophet ﷺ said to Uthman: 'If I had a third, I would have married her to you.' Uthman became Dhu al-Nurayn (Possessor of the Two Lights) by marrying Umm Kulthum.",
      "Umm Kulthum lived with Uthman about six years. She was a good wife, resembling her sister Ruqayyah in beauty and religion. She was among the virtuous ladies in Madinah. She did not bear Uthman any children, so Abdullah — Ruqayyah's son — remained Uthman's only child from the Prophet's ﷺ daughters.",
      "In the ninth year of the Hijrah, Umm Kulthum fell into a severe illness. She died in Sha'ban or Ramadan of that year. The Prophet ﷺ was at the Tabuk campaign and did not attend her burial. When he returned, he grieved deeply for her. He stood at her grave weeping and said: 'If I had a third, I would have married her to you, Uthman.' It was a remarkable word — a repetition of the previous promise, affirming Uthman's virtue and the loss of his daughter.",
      "Umm Kulthum was buried in al-Baqi', beside her sister Ruqayyah. Umm Ayman, Asma' bint Umays, and Safiyya bint Abd al-Muttalib — the Prophet's ﷺ aunt — were present at her burial. Abd al-Rahman ibn Awf and Umar ibn al-Khattab undertook lowering her into her grave at the Prophet's ﷺ request in his absence. The Mothers of the Believers and women Companions participated in her preparation.",
      "Umm Kulthum left no offspring. Like her sisters Ruqayyah and Zaynab. The only surviving offspring for the Prophet ﷺ was through Fatimah al-Zahra alone. This is Allah's decree, that the lineage of the greatest of people remained through only one daughter.",
      "After Umm Kulthum's death, only Fatimah remained of the Prophet's ﷺ daughters. All other daughters had died in his lifetime. al-Qasim and Abdullah — his two sons — died young. Zaynab died in 8 AH. Ruqayyah died in 2 AH. Umm Kulthum died in 9 AH. Only Fatimah remained, who died six months after the Prophet ﷺ in 11 AH.",
      "Despite all these calamities, the Prophet ﷺ bore with great patience. He would weep for his daughter but said only what pleased Allah. His stand beside Umm Kulthum's grave is a lesson in patience. He remembered Uthman's virtue, remembered that death is the Sunnah of life, and remembered that Allah tests whom He loves.",
      "Umm Kulthum's lessons are great. First: a believing woman may live a short life full of virtue. Umm Kulthum did not live long — she died in her thirties. But she was the daughter of the Messenger of Allah ﷺ, wife of Uthman Dhu al-Nurayn, and sister of Fatimah al-Zahra. A short life, but it was in the greatest house in history.",
      "Second: life is not measured by years but by virtue. How many a person lived long and left no mark. And how many a person lived briefly and left all of history. Umm Kulthum left her memory in the books of hadith and biography, remembered whenever Uthman or the Prophet's ﷺ daughters are mentioned.",
      "Third: marrying the daughter of the Messenger of Allah is an honour nothing matches. Uthman attained this honour twice — Ruqayyah then Umm Kulthum. This is what no one before or after him received. Uthman's virtue is great because of this honour from the Prophet ﷺ.",
      "Umm Kulthum bint Rasulillah ﷺ remains in the history of Islam the third of the Prophet's ﷺ daughters, the second wife of Uthman Dhu al-Nurayn, sister of Fatimah, Zaynab, and Ruqayyah. O Allah, be pleased with Umm Kulthum, and gather us with her, her father, and her sisters in the Gardens of Bliss.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 28. زينب بنت جحش رضي الله عنها
  // ──────────────────────────────────────────────────────────────────────
  'zaynab-jahsh': {
    ar: P([
      'هي زينب بنت جحش بن رئاب الأسدية. ابنة عمة النبي ﷺ — أمها أميمة بنت عبد المطلب. وُلدت بمكة قبل البعثة بنحو 20 سنة. كانت من بنات قريش الشريفات، ذات جمال وفصاحة. أسلمت من السابقات في مكة.',
      'هاجرت إلى المدينة بعد الهجرة. لما أراد النبي ﷺ أن يكسر الفوارق الطبقية في المجتمع الإسلامي، خطبها لمولاه زيد بن حارثة. كان زيد عبدًا معتقًا، وكانت زينب من بنات الأشراف القرشيات. رفضت في البداية، لأنها لم ترَ في نفسها أن تتزوج عبدًا معتقًا.',
      'نزلت في حقها آية: وما كان لمؤمن ولا مؤمنة إذا قضى الله ورسوله أمرًا أن يكون لهم الخيرة من أمرهم. قبلت زينب الزواج بعد نزول الآية، طاعة لله ورسوله. تزوجها زيد. لكن الحياة الزوجية بينهما لم تكن سعيدة. اختلاف الأصل والثقافة والطبيعة جعل الزواج صعبًا. شكا زيد إلى النبي ﷺ مرارًا. نصحه النبي ﷺ بالصبر: أمسك عليك زوجك واتق الله.',
      'لكن في النهاية لم يستطع زيد، فطلّقها. كان أمرًا قدّره الله. نزل الوحي بأمر عظيم: فلما قضى زيد منها وطرًا زوّجناكها لكي لا يكون على المؤمنين حرج في أزواج أدعيائهم إذا قضوا منهن وطرًا. زوّج الله نبيه ﷺ بزينب من فوق سبع سماوات مباشرة، بدون خطبة من النبي ولا وكيل. أرسل النبي ﷺ زيد بن حارثة نفسه يخبرها بالأمر.',
      'فرحت زينب فرحًا شديدًا. ولأنها قد قبلت بزواج زيد طاعة، عوّضها الله بزواج النبي ﷺ — أعظم زواج في الدنيا. كانت تفتخر على نساء النبي ﷺ بهذه الكرامة وتقول: زوجكن أهاليكن وزوجني الله من فوق سبع سماوات. كانت كلمة صادقة لا فيها كبر، إنما تذكير بفضل الله عليها.',
      'حدث في زواجها أمر آخر مهم في تاريخ التشريع. لما تزوجها النبي ﷺ، أولم عليها وليمة عظيمة. جاء الناس وأكلوا، لكن بعضهم بقي يتحدث في بيت النبي بعد انتهاء الطعام. كان النبي ﷺ يحب الخصوصية في بيته، لكنه كان يستحي من إخراجهم. نزلت آية: يا أيها الذين آمنوا لا تدخلوا بيوت النبي إلا أن يؤذن لكم إلى طعام غير ناظرين إناه، ولكن إذا دعيتم فادخلوا فإذا طعمتم فانتشروا. هذه آية الحجاب الأولى.',
      'كانت زينب من أكثر زوجات النبي ﷺ صدقة وكرمًا. كانت تعمل بيدها — تخيط الجلود وتصنع منها أشياء — ثم تتصدّق بكل ما تكسب. قال النبي ﷺ عن زوجاته: أسرعكن لحاقًا بي أطولكن يدًا. ظنّت كل واحدة من زوجاته أن المقصود طول اليد الحقيقية — البدنية. كنّ يقيسن أيديهن. أم المؤمنين سودة كانت أطولهن جسمًا، فظنوا أنها أول من تموت.',
      'لكن مرت السنوات. توفي النبي ﷺ. ثم بعده بعدة سنين، توفيت زينب بنت جحش أول الأزواج — في سنة 20 هـ في خلافة عمر بن الخطاب. عرفت زوجات النبي ﷺ أن المقصود طول اليد ليس البدن، بل طول اليد في الصدقة. كانت زينب أكثرهن صدقة، فلحقت بالنبي ﷺ أولًا.',
      'لما حضرتها الوفاة، أوصت بمالها كله للفقراء والمساكين. لم تخلّف لأهلها شيئًا. كانت في آخر حياتها تقول: ما تركتُ لورثتي إلا ما لا يضرّهم ولا ينفعهم. كل ما عندي للفقراء. ماتت وعمرها 53 سنة. صلى عليها عمر بن الخطاب، ودفنت بالبقيع.',
      'كانت زينب أكثر زوجات النبي ﷺ روايةً للحديث في شخصياتها الخاصة. روت 11 حديثًا. لم تكثر من الرواية مثل عائشة أو أم سلمة، لكن أحاديثها صحيحة وفيها فقه عظيم. ومن أحاديثها المشهورة حديث طول اليد في الصدقة، وحديث الحجاب.',
      'دروس زينب عظيمة. الأول: أن الطاعة لله ورسوله قد تجلب الخير من غير حساب. زينب لم تكن ترغب بزواج زيد، لكنها أطاعت لله. فعوّضها الله بزواج النبي ﷺ. كم من إنسان يرفض شيئًا بسيطًا، فيحرمه الله من خير عظيم. الطاعة الصادقة دائمًا تجلب البركة.',
      'الثاني: أن الصدقة طريق إلى الجنة وإلى محبة النبي ﷺ. زينب كانت أكثرهن صدقة، فلحقت بالنبي ﷺ أولًا. كل صدقة تنفقها في الدنيا تقترب بها إلى الله. والمؤمن يتعجل في الصدقة قبل أن يفوت الأجل.',
      'الثالث: أن العمل باليد كرامة. زينب كانت تعمل بيدها — تخيط وتصنع — مع أنها أم مؤمنين، وزوجة أعظم الناس. لم تستنكف عن العمل لأنها زوجة نبي. كم من امرأة اليوم تأنف من العمل بحجة أنها من طبقة معينة! زينب فعلت العكس.',
      'يبقى زينب بنت جحش في تاريخ الإسلام التي زوّجها الله من فوق سبع سماوات، أطول زوجات النبي يدًا بالصدقة، أول الأزواج لحاقًا بالنبي ﷺ بعد وفاته. اللهم ارضَ عن زينب، وارزقنا الصدقة والعمل بأيدينا.',
    ]),
    en: P([
      "She is Zaynab bint Jahsh ibn Ri'ab al-Asadiyyah. The Prophet's ﷺ cousin — her mother was Umaymah bint Abd al-Muttalib. She was born in Makkah about 20 years before the mission. She was among the noble women of Quraysh, possessing beauty and eloquence. She embraced Islam among the foremost in Makkah.",
      "She emigrated to Madinah after the Hijrah. When the Prophet ﷺ wanted to break class distinctions in Muslim society, he proposed for her to his freed slave Zayd ibn Harithah. Zayd was a freed slave, and Zaynab was from the noble Qurashi families. She refused at first, because she did not see fit to marry a freed slave.",
      "A verse was revealed about her: 'It is not for a believing man or woman, when Allah and His Messenger have decided a matter, that they should have any choice in their matter.' Zaynab accepted the marriage after the verse was revealed, in obedience to Allah and His Messenger. Zayd married her. But the marriage between them was not happy. Differences in origin, culture, and nature made the marriage difficult. Zayd complained to the Prophet ﷺ repeatedly. The Prophet ﷺ advised him patience: 'Keep your wife and fear Allah.'",
      "But in the end Zayd could not, and divorced her. It was a matter Allah had decreed. Revelation came with a great matter: 'When Zayd had no further need of her, We married her to you, so that there should be no difficulty for the believers concerning the wives of their adopted sons when they have no further need of them.' Allah married His Prophet ﷺ to Zaynab from above seven heavens directly, without a proposal from the Prophet or a deputy. The Prophet ﷺ sent Zayd ibn Harithah himself to inform her of the matter.",
      "Zaynab rejoiced greatly. Because she had accepted Zayd's marriage out of obedience, Allah compensated her with marriage to the Prophet ﷺ — the greatest marriage in the world. She used to take pride before the Prophet's ﷺ wives with this honour and say: 'Your families married you off, but Allah married me from above seven heavens.' It was a sincere word, no arrogance in it, but a reminder of Allah's bounty on her.",
      "Another important matter in the history of legislation occurred in her marriage. When the Prophet ﷺ married her, he held a great walima. People came and ate, but some lingered talking in the Prophet's house after the food ended. The Prophet ﷺ loved privacy in his house but was shy to put them out. A verse was revealed: 'O you who believe, do not enter the houses of the Prophet except when you are permitted for a meal — without awaiting its readiness. But when you are invited, enter; and when you have eaten, disperse.' This is the first verse of hijab.",
      "Zaynab was among the most charitable and generous of the Prophet's ﷺ wives. She worked with her hand — sewing leather and making things from it — then gave in charity everything she earned. The Prophet ﷺ said about his wives: 'The first of you to follow me will be the one with the longest hand.' Each of his wives thought the longest physical hand was meant. They measured their hands. Mother of the Believers Sawdah was the tallest, so they thought she would be the first to die.",
      "But the years passed. The Prophet ﷺ died. Then several years after him, Zaynab bint Jahsh died first of the wives — in 20 AH in Umar ibn al-Khattab's caliphate. The Prophet's ﷺ wives knew that the longest hand did not mean the body but the longest hand in charity. Zaynab was the most charitable of them, so she followed the Prophet ﷺ first.",
      "When death approached her, she bequeathed all her wealth to the poor and needy. She left her family nothing. In her last days she would say: 'I have left my heirs only what does not harm them and does not benefit them. All I have is for the poor.' She died at 53 years old. Umar ibn al-Khattab prayed over her, and she was buried in al-Baqi'.",
      "Zaynab was among the more prolific of the Prophet's ﷺ wives in narrating hadith in her personal life. She narrated 11 hadiths. She did not narrate as much as A'isha or Umm Salamah, but her hadiths are authentic and contain great jurisprudence. Among her famous hadiths is the hadith of the longest hand in charity and the hadith of hijab.",
      "Zaynab's lessons are great. First: obedience to Allah and His Messenger may bring good without count. Zaynab did not wish for marriage to Zayd, but she obeyed for Allah. So Allah compensated her with marriage to the Prophet ﷺ. How many a person refuses a simple thing, and Allah deprives him of a great good. Sincere obedience always brings blessing.",
      "Second: charity is a road to Paradise and to the love of the Prophet ﷺ. Zaynab was the most charitable of them, so she followed the Prophet ﷺ first. Every charity you spend in this world brings you closer to Allah. The believer hastens in charity before time runs out.",
      "Third: working with one's hand is dignity. Zaynab worked with her hand — sewing and making — though she was a Mother of the Believers and wife of the greatest of people. She did not disdain work because she was a prophet's wife. How many a woman today disdains work claiming her class! Zaynab did the opposite.",
      "Zaynab bint Jahsh remains in the history of Islam the one whom Allah married from above seven heavens, the Prophet's wife with the longest hand in charity, the first of the wives to follow the Prophet ﷺ after his death. O Allah, be pleased with Zaynab, and grant us charity and work with our hands.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 29. جويرية بنت الحارث رضي الله عنها
  // ──────────────────────────────────────────────────────────────────────
  'juwayriyya': {
    ar: P([
      'هي جويرية بنت الحارث بن أبي ضرار من قبيلة بني المصطلق من خزاعة. اسمها الأصلي بَرَّة، فسماها النبي ﷺ جويرية تفاؤلًا بها. وُلدت قبل البعثة بنحو 20 سنة. كانت من بنات سادات قبيلتها — أبوها سيد بني المصطلق.',
      'تزوجت قبل الإسلام مسافع بن صفوان من قومها. كانت من النساء الجميلات الشريفات في قبيلتها. لم تسلم في البداية، لأن قومها كانوا على الجاهلية والشرك. كانت تعيش في قبيلتها بعيدًا عن دعوة الإسلام.',
      'في السنة الخامسة من الهجرة، خطّط أبوها الحارث بن أبي ضرار لغزو المدينة بقومه. جمع الجيش وعزم على الهجوم. لكن النبي ﷺ علم بأمره، فأرسل عيونًا تتأكد من الخبر. لما تأكد، خرج بنفسه بجيش من المسلمين، وحاصر بني المصطلق في موقع اسمه المريسيع — قرب قُديد على ساحل البحر الأحمر.',
      'وقعت معركة المريسيع — أو غزوة بني المصطلق — في شعبان من السنة الخامسة. هزم المسلمون بني المصطلق هزيمة كاسحة. قتل من قومها رجال كثيرون. سُبيت النساء والأطفال، ومن ضمنهن جويرية. كانت قد فقدت في الغزوة زوجها مسافع وأقاربها. وقعت سهمها في قسمة الغنائم لثابت بن قيس بن شماس وابن عم له.',
      'كانت جويرية بنت سيد، فلم تطق أن تكون أمَة. كاتبت ثابت بن قيس على نفسها — أي اتفقت معه على شراء حريتها بمال معين. ثم جاءت إلى النبي ﷺ تطلب المساعدة في فدائها. دخلت على النبي ﷺ، وكانت جميلة جدًا. لما رأتها أم المؤمنين عائشة، شعرت بالغيرة في قلبها فورًا، وعرفت أن النبي ﷺ سيُعجب بها.',
      'قالت جويرية للنبي ﷺ: يا رسول الله، أنا جويرية بنت الحارث سيد قومه، وقد أصابني من البلاء ما لم يخفَ عليك، وقد وقعت في سهم ثابت بن قيس وابن عم له، فكاتبته على نفسي، فجئتك أستعينك على كتابتي. قال النبي ﷺ كلمة عجيبة: فهل لكِ في خير من ذلك؟ قالت: وما هو يا رسول الله؟ قال: أقضي عنكِ كتابتكِ وأتزوجكِ. قالت: نعم يا رسول الله. قال: قد فعلت.',
      'هذا الزواج كان من أعظم البركات على قبيلتها. لما سمع المسلمون الذين سبوا من بني المصطلق أن النبي ﷺ تزوج جويرية، قالوا: أصهار رسول الله ﷺ! وأطلقوا فورًا ما بأيديهم من السبي — قيل مئة بيت. كل من سُبي في تلك الغزوة من بني المصطلق صار حرًا بسبب زواج جويرية واحدة. قالت عائشة: ما رأيت امرأة أعظم بركة على قومها منها.',
      'أسلم الحارث بن أبي ضرار، أبو جويرية، لما رأى ما حدث. جاء إلى المدينة، وأسلم. أسلم بنو المصطلق كلهم بعد ذلك. صارت جويرية سببًا في إسلام قبيلة كاملة. هذه قصة عجيبة في فضل الله — حرب انتهت بزواج، والزواج جلب إسلام أمة كاملة.',
      'عاشت جويرية في بيت النبي ﷺ. كانت من العابدات الذاكرات. روى مسلم أن النبي ﷺ خرج من عندها بعد صلاة الصبح وهي في مسجدها — في مكان صلاتها. ثم رجع قبل الضحى فوجدها لا تزال في مسجدها. قال لها النبي ﷺ: ما زلتِ على الحال التي فارقتك عليها؟ قالت: نعم. قال: لقد قلت بعدك أربع كلمات ثلاث مرات، لو وُزنت بما قلتِ منذ اليوم لوزنتهن: سبحان الله وبحمده، عدد خلقه، ورضا نفسه، وزنة عرشه، ومداد كلماته.',
      'هذا الذكر النبوي العظيم نقلته جويرية للأمة. كل من قال هذه الكلمات ثلاث مرات بعد الفجر يكسب أجرًا عظيمًا. هذا فضل بقي للأمة كلها من جويرية.',
      'كانت جويرية كثيرة الصيام. روت أحاديث في فقه الصيام. منها حديث: لا تخصّوا يوم الجمعة بصيام من بين الأيام، إلا أن يكون في صوم يصومه أحدكم. هذا الحديث أصل لتحريم تخصيص يوم الجمعة بصيام منفرد.',
      'توفيت جويرية بنت الحارث في خلافة معاوية سنة 56 هـ، وعمرها 65 سنة. صلى عليها مروان بن الحكم — والي المدينة — ودُفنت بالبقيع. عاشت طويلًا في الإسلام، وكانت من أمهات المؤمنين الجليلات.',
      'دروس جويرية عظيمة. الأول: أن الله يدبّر الأمر بحكمة لا نفهمها. ذهبت جويرية إلى النبي ﷺ تطلب فدائها، فخرجت منها أم مؤمنين، وسبب عتق قبيلتها، وسبب إسلامها. لم تتوقع شيئًا من هذا. الله يدبّر للمؤمن من حيث لا يحتسب.',
      'الثاني: أن العمل الفردي قد يجلب الخير الجماعي. جويرية بزواجها واحد، أنقذت قبيلتها. كم من قرار شخصي يكون له أثر عظيم على من حول صاحبه! العاقل يفكر في أثر قراراته على الآخرين.',
      'الثالث: أن الذكر القليل العظيم خير من الذكر الكثير العادي. النبي ﷺ علّم جويرية أربع كلمات تعادل ساعات من الذكر العادي. الكيف أعظم من الكم. والذكر بقلب حاضر أعظم من ذكر بلسان وقلب غافل.',
      'يبقى جويرية بنت الحارث في تاريخ الإسلام أعظم بركة على قومها، الزوجة التي أعتق بزواجها مئة بيت، صاحبة الذكر الفجري العظيم. اللهم ارضَ عن جويرية، واجمعنا بها في جنات النعيم.',
    ]),
    en: P([
      "She is Juwayriyya bint al-Harith ibn Abi Dirar of the tribe of Banu al-Mustaliq of Khuza'ah. Her original name was Barrah, but the Prophet ﷺ named her Juwayriyya as a good omen. She was born about 20 years before the mission. She was among the daughters of the chiefs of her tribe — her father was the chief of Banu al-Mustaliq.",
      "Before Islam she married Musafi' ibn Safwan of her people. She was among the beautiful, noble women of her tribe. She did not embrace Islam at first, because her people were upon Jahiliyyah and shirk. She lived in her tribe away from the call of Islam.",
      "In the fifth year of the Hijrah, her father al-Harith ibn Abi Dirar planned a raid on Madinah with his people. He gathered an army and resolved to attack. But the Prophet ﷺ learned of his matter and sent scouts to verify the news. When confirmed, he himself went out with a Muslim army and besieged Banu al-Mustaliq in a place called al-Muraysi' — near Qudayd on the Red Sea coast.",
      "The Battle of al-Muraysi' — or the campaign of Banu al-Mustaliq — occurred in Sha'ban of the fifth year. The Muslims defeated Banu al-Mustaliq devastatingly. Many men of her people were killed. The women and children were captured, including Juwayriyya. She had lost in the campaign her husband Musafi' and her relatives. Her share in the division of spoils fell to Thabit ibn Qays ibn Shammas and a cousin of his.",
      "Juwayriyya was the daughter of a chief and could not bear to be a slave. She contracted with Thabit ibn Qays for her freedom — agreeing with him to buy her freedom for a certain sum. Then she came to the Prophet ﷺ seeking help with her ransom. She entered upon the Prophet ﷺ, and she was very beautiful. When Mother of the Believers A'isha saw her, jealousy entered her heart at once, and she knew the Prophet ﷺ would be impressed with her.",
      "Juwayriyya said to the Prophet ﷺ: 'O Messenger of Allah, I am Juwayriyya bint al-Harith, chief of his people. Such trial has befallen me as is not hidden from you. I fell in the share of Thabit ibn Qays and a cousin of his, and I contracted with him for my freedom. I came to seek your help with my contract.' The Prophet ﷺ said a remarkable word: 'Shall I offer you something better than that?' She said: 'What is it, O Messenger of Allah?' He said: 'I will pay your contract for you and marry you.' She said: 'Yes, O Messenger of Allah.' He said: 'I have done.'",
      "This marriage was among the greatest blessings on her tribe. When the Muslims who had captured from Banu al-Mustaliq heard that the Prophet ﷺ had married Juwayriyya, they said: 'In-laws of the Messenger of Allah ﷺ!' They immediately released what was in their possession of captives — said to be a hundred households. Everyone captured in that campaign from Banu al-Mustaliq became free because of one Juwayriyya's marriage. A'isha said: 'I have not seen a woman greater in blessing to her people than her.'",
      "al-Harith ibn Abi Dirar, Juwayriyya's father, embraced Islam when he saw what happened. He came to Madinah and embraced Islam. All of Banu al-Mustaliq embraced Islam after that. Juwayriyya became the cause of the Islam of an entire tribe. This is a remarkable story of Allah's bounty — a war that ended in marriage, and the marriage brought the Islam of an entire people.",
      "Juwayriyya lived in the Prophet's ﷺ house. She was among the worshipping, remembering ones. Muslim narrated that the Prophet ﷺ left her after Fajr while she was in her place of prayer — her place of prayer. He then returned before Duha and found her still in her place of prayer. The Prophet ﷺ said to her: 'Are you still in the state I left you in?' She said: 'Yes.' He said: 'I have said after you four words three times, which, if weighed against what you have said since the day, would outweigh them: SubhanAllah wa bihamdih, by the number of His creation, by His self's pleasure, by the weight of His Throne, and the ink of His words.'",
      "This great prophetic remembrance Juwayriyya transmitted to the Ummah. Whoever says these words three times after Fajr earns a great reward. This is a virtue that remained for the entire Ummah from Juwayriyya.",
      "Juwayriyya fasted often. She narrated hadiths on the jurisprudence of fasting. Among them the hadith: 'Do not single out Friday for fasting alone, unless it is in a fast one of you is keeping.' This hadith is a basis for the prohibition of singling out Friday alone for fasting.",
      "Juwayriyya bint al-Harith died in Mu'awiyah's caliphate in 56 AH at 65 years old. Marwan ibn al-Hakam — the governor of Madinah — prayed over her, and she was buried in al-Baqi'. She lived long in Islam and was among the noble Mothers of the Believers.",
      "Juwayriyya's lessons are great. First: Allah arranges the matter with wisdom we do not understand. Juwayriyya went to the Prophet ﷺ seeking her ransom, and emerged a Mother of Believers, the cause of her tribe's freedom, and the cause of its Islam. She did not expect any of this. Allah arranges for the believer from where he does not reckon.",
      "Second: an individual act may bring collective good. Juwayriyya with one marriage saved her tribe. How many a personal decision has a great effect on those around its owner! The wise thinks of the effect of his decisions on others.",
      "Third: a great little remembrance is better than ordinary much remembrance. The Prophet ﷺ taught Juwayriyya four words equal to hours of ordinary remembrance. Quality is greater than quantity. Remembrance with a present heart is greater than remembrance with tongue and heedless heart.",
      "Juwayriyya bint al-Harith remains in the history of Islam the greatest blessing on her people, the wife through whose marriage a hundred households were freed, owner of the great Fajr remembrance. O Allah, be pleased with Juwayriyya, and gather us with her in the Gardens of Bliss.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 30. صفية بنت حيي رضي الله عنها
  // ──────────────────────────────────────────────────────────────────────
  'safiyya': {
    ar: P([
      'هي صفية بنت حيي بن أخطب بن سعنة، من سبط لاوي بن يعقوب بن إسحاق بن إبراهيم. ترجع نسبًا إلى هارون أخي موسى عليهما السلام، فهي من بيت النبوة في بني إسرائيل. أبوها حيي بن أخطب كان سيد بني النضير — أكبر قبيلة يهودية في المدينة. أمها بنت سيد بني قريظة — قبيلة يهودية أخرى. أصلها يهودي من أشرف بيوت اليهود.',
      'وُلدت في المدينة قبل الهجرة بنحو 17 سنة. ربتها أسرة يهودية متدينة. كانت تعرف من التوراة كثيرًا. لما هاجر النبي ﷺ إلى المدينة، رأت صفية مع أبيها وعمها يخرجان لمقابلته. رجعا حزينين. سألت أباها وعمها عنه. قال أحدهما للآخر: هو هو. قال الآخر: ماذا تنوي معه؟ قال: عداوته ما بقيت. كانت صفية صغيرة سمعت ذلك، فعرفت أن النبي ﷺ هو الذي تتحدث عنه التوراة.',
      'تزوجت قبل الإسلام مرتين من رجال من قومها. زوجها الأخير كان كنانة بن أبي الحقيق، أحد رؤساء يهود خيبر. عاشت في خيبر حياة مرفّهة. لكن في السنة السابعة من الهجرة، غزا النبي ﷺ خيبر — مركز اليهود الأخير في الجزيرة العربية. هزم اليهود. قُتل أبوها حيي قبلها في غزوة بني قريظة. وقُتل زوجها كنانة في غزوة خيبر. سُبيت صفية وكثير من نساء يهود.',
      'وقعت صفية في سهم دحية الكلبي — صحابي معروف بحسن المعاملة. لكن لما رأى النبي ﷺ صفية وعرف أنها بنت سيد بني النضير وزوجة سيد خيبر — لا يليق أن تكون أمَة لأحد. اشتراها النبي ﷺ من دحية بسبعة من الجواري الأخريات. ثم أعتقها، وعرض عليها الإسلام والزواج. قبلت. تزوجها النبي ﷺ، وجعل عتقها صداقها. كانت سنة 7 هـ.',
      'في الطريق من خيبر إلى المدينة، حدث موقف مشهور. اقترحت أم سليم بنت ملحان على النبي ﷺ أن يجعل صفية على ناقته معه. تحجبت ضمت إلى نفسها. ركبت خلف النبي ﷺ على ناقته القصواء. ضرب النبي ﷺ على فخذها ليساعدها على الصعود، فكان ذلك إعلانًا لرسولها بأنه قد دخل بها — لأن الاحتجاب علامة على أنها أم مؤمنين.',
      'كانت صفية ذات عقل وأدب. لكن أصلها اليهودي كان مصدر إيذاء لها أحيانًا في بيت النبي ﷺ. روى أن بعض زوجات النبي ﷺ كنّ يعيّرنها بأنها بنت يهودي وأم يهودي. شكت إلى النبي ﷺ مرة. علّمها النبي ﷺ كلمة ترد بها على المعتدين: قولي لهنّ كيف تكنّ خيرًا منّي، وأبي هارون، وعمي موسى، وزوجي محمد. فإذا قلتِ ذلك، أُسكت أهل المعارضة.',
      'كانت صفية تحب النبي ﷺ حبًا شديدًا. في مرض النبي ﷺ الأخير، جاءت تعوده وقالت كلمتها الشهيرة: يا رسول الله، والله لوددتُ أن الذي بك بي. لم تكن مجاملة، بل كانت محبة صادقة. التفتت بعض زوجاته إلى بعض. عرف النبي ﷺ ما يدور في خواطرهن. قال لهن: مهلًا، إنها صادقة. كان دفاع النبي ﷺ عنها أمام أم المؤمنين دفاعًا عن حبها الصادق.',
      'كانت صفية كريمة جدًا. أعطت في الصدقة الكثير من حليّها ومالها. قال النبي ﷺ عنها: ما رأيت امرأة قطّ خيرًا من صفية. اعتزلت الفتنة في زمن علي ومعاوية، ولم تشارك في الجمل ولا صفين. كانت تجلس في بيتها للعبادة والقراءة والذكر.',
      'مع مرور السنين، حدث أمر عجيب يدل على نقاء قلبها. كان لها ابن أخت ما زال على اليهودية لم يسلم. مرض هذا الابن. ذهبت صفية تعوده، رغم أنه لم يسلم. وعندما توفي، أوصت بثلث ميراثها له. فقهاء الصحابة اختلفوا في هذا — هل تجوز الوصية لكافر؟ ذهب بعضهم إلى جوازها، لأن الوصية صدقة، والصدقة على الأقارب حتى من غير المسلمين جائزة. كان موقف صفية درسًا في رحمة الأقارب حتى من غير الدين.',
      'روت صفية عن النبي ﷺ عشرة أحاديث، بعضها متفق عليه. منها حديث الاعتكاف في رمضان، وحديث الكلام مع زوجة النبي في الطريق ليلًا، وأحاديث في الصلاة والصيام. كانت معدودة من المحدّثات الفقيهات.',
      'توفيت صفية في خلافة معاوية سنة 50 هـ، وعمرها قارب الستين. صلى عليها معاوية، أو الوالي عبد الله بن سلام. دُفنت بالبقيع. كانت من أكرم نساء الإسلام، رغم ما لاقته من معايرة بسبب أصلها.',
      'دروس صفية عظيمة. الأول: أن الإسلام يساوي بين الناس. صفية كانت يهودية من بيت كبير، فصارت أم مؤمنين. لا يمنع أصل أحد من الوصول إلى أعلى المنازل في الإسلام. كل من أسلم بصدق، نسبه إلى الإسلام أعظم من نسبه إلى أي شيء آخر.',
      'الثاني: أن المعايرة بالأصل من أخلاق الجاهلية. حتى أمهات المؤمنين عيّرن صفية أحيانًا بأصلها. النبي ﷺ علّمها كيف ترد بحكمة. وعلّمنا أن لا نعيّر أحدًا بأصل ولد فيه — الإنسان لا يختار أصله، إنما يختار دينه.',
      'الثالث: أن الرحمة بالأقارب حتى غير المسلمين جائزة. وصية صفية لابن أختها اليهودي درس على أن صلة الرحم لا تنقطع بكفر القريب. الإحسان للقريب الكافر — مع عدم إعانته على كفره — من جميل الأخلاق.',
      'يبقى صفية بنت حيي في تاريخ الإسلام أم مؤمنين من نسل هارون عليه السلام، صبرت على فقد أهلها، وثبتت في وجه المعايرة بحكمة، وأحبت النبي ﷺ حبًا صادقًا. اللهم ارضَ عن صفية، واجمعنا بها في جنات النعيم.',
    ]),
    en: P([
      "She is Safiyya bint Huyayy ibn Akhtab ibn Sa'nah, of the tribe of Levi ibn Yaqub ibn Ishaq ibn Ibrahim. She descends in lineage to Harun, brother of Musa, so she is from the house of prophethood in the Children of Israel. Her father Huyayy ibn Akhtab was chief of Banu al-Nadir — the largest Jewish tribe in Madinah. Her mother was daughter of the chief of Banu Qurayzah — another Jewish tribe. Her origin is Jewish from the noblest of Jewish houses.",
      "She was born in Madinah about 17 years before the Hijrah. She was raised by a religious Jewish family. She knew much from the Torah. When the Prophet ﷺ emigrated to Madinah, Safiyya saw her father and uncle go out to meet him. They returned grieving. She asked her father and uncle about him. One of them said to the other: 'He is the one.' The other said: 'What do you intend with him?' He said: 'Enmity to him as long as I live.' Safiyya was small and heard that, and knew that the Prophet ﷺ was the one the Torah spoke of.",
      "Before Islam she married twice to men of her people. Her last husband was Kinanah ibn Abi al-Huqayq, one of the leaders of the Jews of Khaybar. She lived in Khaybar a comfortable life. But in the seventh year of the Hijrah, the Prophet ﷺ attacked Khaybar — the last Jewish centre in the Arabian Peninsula. The Jews were defeated. Her father Huyayy had been killed before her at the campaign of Banu Qurayzah. Her husband Kinanah was killed at the campaign of Khaybar. Safiyya and many Jewish women were captured.",
      "Safiyya fell in the share of Dihyah al-Kalbi — a Companion known for good treatment. But when the Prophet ﷺ saw Safiyya and knew she was the daughter of the chief of Banu al-Nadir and wife of the chief of Khaybar — it was not fitting that she be a slave to anyone. The Prophet ﷺ bought her from Dihyah with seven other slave-girls. He then freed her and offered her Islam and marriage. She accepted. The Prophet ﷺ married her, making her freeing her dowry. It was 7 AH.",
      "On the road from Khaybar to Madinah, a famous situation occurred. Umm Sulaym bint Milhan suggested to the Prophet ﷺ that he place Safiyya on his camel with him. She veiled and was helped behind the Prophet ﷺ on his camel al-Qaswa. The Prophet ﷺ struck on her thigh to help her up; this was an announcement to his messenger that he had consummated with her — because veiling is a sign that she is a Mother of the Believers.",
      "Safiyya possessed intellect and refinement. But her Jewish origin was sometimes a source of harm in the Prophet's ﷺ house. It is narrated that some of the Prophet's ﷺ wives would taunt her with being a Jew's daughter and son. She complained to the Prophet ﷺ once. The Prophet ﷺ taught her a word to reply to the aggressors: 'Say to them: How can you be better than me, when my father is Harun, my uncle is Musa, and my husband is Muhammad.' When you say that, the opposition will be silenced.",
      "Safiyya loved the Prophet ﷺ deeply. In the Prophet's ﷺ final illness, she came to visit him and said her famous words: 'O Messenger of Allah, by Allah, I wish what is upon you were upon me.' It was not flattery but sincere love. Some of his wives turned to each other. The Prophet ﷺ knew what passed in their minds. He said to them: 'Gently, she is truthful.' The Prophet's ﷺ defense of her before the Mothers of the Believers was a defense of her sincere love.",
      "Safiyya was very generous. She gave in charity much of her jewellery and wealth. The Prophet ﷺ said about her: 'I have not seen a woman better than Safiyya.' She withdrew from the trial in the era of Ali and Mu'awiyah and did not participate in the Camel or Siffin. She would sit in her house for worship, recitation, and remembrance.",
      "With passing years, a remarkable matter occurred showing the purity of her heart. She had a nephew still upon Judaism who had not embraced Islam. This nephew fell ill. Safiyya went to visit him though he had not embraced Islam. When he died, she bequeathed a third of her inheritance to him. The jurists of the Companions differed on this — is a bequest to a non-Muslim permitted? Some held it permissible, because a bequest is charity, and charity to relatives even from non-Muslims is permitted. Safiyya's position was a lesson in mercy to relatives even from outside the religion.",
      "Safiyya narrated from the Prophet ﷺ ten hadiths, some agreed upon. Among them the hadith of i'tikaf in Ramadan, the hadith of speaking with the Prophet's wife on the road at night, and hadiths on prayer and fasting. She was counted among the jurist female narrators.",
      "Safiyya died in Mu'awiyah's caliphate in 50 AH at nearly sixty years of age. Mu'awiyah prayed over her, or the governor Abdullah ibn Salam. She was buried in al-Baqi'. She was among the most noble women of Islam, despite what she met of taunting because of her origin.",
      "Safiyya's lessons are great. First: Islam equalises people. Safiyya was Jewish from a great house, and became a Mother of the Believers. No one's origin prevents reaching the highest stations in Islam. Whoever embraces Islam sincerely, his attribution to Islam is greater than his attribution to anything else.",
      "Second: taunting by origin is among the morals of Jahiliyyah. Even the Mothers of the Believers taunted Safiyya sometimes by her origin. The Prophet ﷺ taught her how to reply with wisdom. And he taught us not to taunt anyone with an origin he was born into — a person does not choose his origin, but chooses his religion.",
      "Third: mercy to relatives even non-Muslims is permitted. Safiyya's bequest to her Jewish nephew is a lesson that ties of kinship are not cut by a relative's disbelief. Kindness to a disbelieving relative — without aiding him in his disbelief — is among beautiful morals.",
      "Safiyya bint Huyayy remains in the history of Islam a Mother of the Believers from the lineage of Harun, peace be upon him; she bore the loss of her family with patience, stood firm against taunting with wisdom, and loved the Prophet ﷺ with sincere love. O Allah, be pleased with Safiyya, and gather us with her in the Gardens of Bliss.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 31. أم حبيبة رملة بنت أبي سفيان رضي الله عنها
  // ──────────────────────────────────────────────────────────────────────
  'umm-habiba': {
    ar: P([
      'هي رملة بنت أبي سفيان صخر بن حرب الأموية القرشية. تُكنّى بأم حبيبة. وُلدت بمكة قبل البعثة بنحو 17 سنة. ابنة أبي سفيان زعيم قريش في الجاهلية، الذي قاد الحروب ضد النبي ﷺ. وأخت معاوية بن أبي سفيان الذي صار خليفة بعد ذلك.',
      'تزوجت قبل البعثة من عبيد الله بن جحش الأسدي. أسلمت مع زوجها قديمًا في مكة، فكانا من السابقين الأولين. كان إسلامها تحديًا كبيرًا لأبيها أبي سفيان، الذي بقي على الشرك. لما اشتد الأذى على المسلمين، هاجرت مع زوجها إلى الحبشة في الهجرة الثانية.',
      'في الحبشة، حدث أمر مدهش ومحزن. تنصّر زوجها عبيد الله — ارتد عن الإسلام إلى المسيحية. كانت محنة قاسية لها: زوج كان معها على الإيمان فجأة يصبح كافرًا. لم يكن أمامها إلا أن تفارقه. عاشت في الحبشة وحيدة، أرملة معنوية، بعيدة عن أهلها وأبيها الذي كان أعدى أعداء الإسلام في مكة.',
      'مات زوجها عبيد الله بعد فترة في الحبشة، ميتة الكافر. صارت أرملة حقيقية. كانت في غربة كاملة: في بلد غريب، بدون زوج، أهلها في مكة على الكفر. بقيت ثابتة على الإسلام رغم كل هذا. هذا أعظم درس في ثبات الإيمان — أن تصمد المرأة على دينها حتى تحت ضغط لا يطاق.',
      'لما وصل خبرها إلى النبي ﷺ في المدينة، حزن لحالها وقرّر أن يخفّف عنها بالزواج منها. أرسل إلى النجاشي ملك الحبشة المسيحي رسالة يطلب فيها أن يخطب له أم حبيبة من أهلها في الحبشة. وافق النجاشي، ودبّر العقد بنفسه نيابة عن النبي ﷺ.',
      'كان النجاشي وكيل الزواج. زوّجها لرسول الله ﷺ بأربعمئة دينار من مال النجاشي الخاص — لم يطلب من النبي ﷺ شيئًا. ثم أرسلها إلى المدينة مع شُرحبيل بن حسنة. وصلت إلى المدينة سنة 7 هـ بعد فتح خيبر. كان هذا أعجب زواج في الإسلام: زوج في المدينة، زوجة في الحبشة، ووكيل ملك مسلم في إفريقيا، ومهر من بيت مال غير المسلم. كل هذا تكريمًا لها لما لاقت من البلاء.',
      'دخلت أم حبيبة في بيت النبي ﷺ وكانت من أعزّ زوجاته. كان أبوها أبو سفيان لا يزال مشركًا في مكة. زارها مرة في المدينة، فأرادت أن تعلّمه أدب الإسلام. أراد أبو سفيان أن يجلس على فراش النبي ﷺ. طوته أم حبيبة دونه. سألها بدهشة: يا بنية، أرغبتِ بهذا الفراش عني، أم رغبتِ بي عنه؟ قالت كلمتها العظيمة: بل هو فراش رسول الله ﷺ، وأنت رجل مشرك نجس، فلا أحب أن تجلس على فراش رسول الله. قال أبو سفيان حزينًا: لقد أصابك يا بنية بعدي شر. خرج من بيتها وفي قلبه أثر هذا الموقف.',
      'في فتح مكة سنة 8 هـ، أسلم أبو سفيان أخيرًا. لما رأى قوة المسلمين وعدلهم، دخل في الإسلام. صار رضي الله عنه من المؤلفة قلوبهم في البداية، ثم حسن إسلامه. مات سنة 31 هـ، وكان قد شهد فتوحات الإسلام وفرح بها.',
      'كانت أم حبيبة من المتفقهات في الدين. روت عن النبي ﷺ 65 حديثًا. كان ابن أخيها عبد الله بن العتبة بن أبي سفيان من تلاميذها. تعلّم منها كثيرًا من فقه النساء.',
      'لما وقعت الفتنة بين علي ومعاوية أخيها، اعتزلتها أم حبيبة. لم تدخل في الصراع رغم أن أخاها معاوية كان طرفًا فيها. اكتفت بقول ما يصلح بين الناس، ودعت بالخير. كان موقفها يدل على حكمة عميقة — لا تنحاز لأخيها على حساب صحابي جليل كعلي بن أبي طالب.',
      'توفيت أم حبيبة سنة 44 هـ في خلافة أخيها معاوية. كان عمرها قارب الـ 70. صلى عليها أهل المدينة، ودُفنت بالبقيع. شيّعها معاوية من الشام بحزن شديد على أخته.',
      'دروس أم حبيبة عظيمة. الأول: أن الثبات على الدين أحيانًا يكون تحت أصعب الظروف. أم حبيبة كانت في غربة، أبوها عدو الإسلام، زوجها ارتد، ومع ذلك ثبتت. كم من إنسان اليوم يترك دينه لأقل من ذلك! كل صعوبة نعيشها أهون من صعوبتها.',
      'الثاني: أن الله يكافئ الصابرين بأعظم مما يتوقعون. أم حبيبة فقدت زوجها وأهلها وبلدها، فعوّضها الله بزواج النبي ﷺ. صارت من أمهات المؤمنين. من ترك شيئًا لله، عوضه الله خيرًا منه.',
      'الثالث: أن أدب الإسلام يعلو على أدب القرابة. أم حبيبة منعت أباها من الجلوس على فراش النبي ﷺ. لم تجامل أباها على حساب احترام النبي. كل من قدّم القرابة على الحق ضل، وكل من قدّم الحق على القرابة هُدي.',
      'يبقى أم حبيبة بنت أبي سفيان في تاريخ الإسلام نموذجًا للثبات والكرامة. الزوجة التي عاد ت من الحبشة أم مؤمنين. اللهم ارضَ عن أم حبيبة، واجعلنا ثابتين على دينك في كل الظروف.',
    ]),
    en: P([
      "She is Ramlah bint Abi Sufyan Sakhr ibn Harb al-Umawiyyah al-Qurashiyyah. She is called Umm Habibah. She was born in Makkah about 17 years before the mission. Daughter of Abu Sufyan, chief of Quraysh in the Jahiliyyah, who led the wars against the Prophet ﷺ. And sister of Mu'awiyah ibn Abi Sufyan who later became caliph.",
      "Before the mission she married Ubaydullah ibn Jahsh al-Asadi. She embraced Islam with her husband early in Makkah, becoming among the very first. Her Islam was a great challenge to her father Abu Sufyan, who remained upon shirk. When harm on the Muslims intensified, she emigrated with her husband to Abyssinia in the second emigration.",
      "In Abyssinia, an astonishing and sad matter occurred. Her husband Ubaydullah converted to Christianity — apostatised from Islam. It was a harsh trial for her: a husband who had been with her on faith suddenly became a disbeliever. There was nothing for her but to separate from him. She lived in Abyssinia alone, a moral widow, far from her family and her father who was the worst enemy of Islam in Makkah.",
      "Her husband Ubaydullah died after a period in Abyssinia, the death of a disbeliever. She became a real widow. She was in total estrangement: in a foreign land, without a husband, her family in Makkah upon disbelief. She remained firm on Islam despite all this. This is the greatest lesson in steadfast faith — that a woman stands firm on her religion even under unbearable pressure.",
      "When her news reached the Prophet ﷺ in Madinah, he grieved for her condition and decided to lighten her burden by marrying her. He sent to the Negus, the Christian king of Abyssinia, a letter asking him to propose to Umm Habibah on his behalf from her family in Abyssinia. The Negus agreed and arranged the contract himself on the Prophet's ﷺ behalf.",
      "The Negus was the marriage agent. He married her to the Messenger of Allah ﷺ with four hundred dinars from the Negus's own wealth — he asked nothing from the Prophet ﷺ. Then he sent her to Madinah with Shurahbil ibn Hasanah. She arrived in Madinah in 7 AH after the conquest of Khaybar. This was the most remarkable marriage in Islam: a husband in Madinah, a wife in Abyssinia, a Muslim king's agent in Africa, and a dowry from a non-Muslim's treasury. All this in honour of what she had met of trial.",
      "Umm Habibah entered the Prophet's ﷺ house and was among the most beloved of his wives. Her father Abu Sufyan was still a polytheist in Makkah. He visited her once in Madinah, and she wanted to teach him the manners of Islam. Abu Sufyan wanted to sit on the Prophet's ﷺ bed. Umm Habibah folded it away from him. He asked in amazement: 'My daughter, did you keep this bed from me, or did you keep me from it?' She said her great words: 'Rather, it is the bed of the Messenger of Allah ﷺ, and you are a polytheist, impure man. I do not love that you sit on the bed of the Messenger of Allah.' Abu Sufyan said sadly: 'Some evil has touched you after me, my daughter.' He left her house with the effect of this stance in his heart.",
      "At the conquest of Makkah in 8 AH, Abu Sufyan finally embraced Islam. When he saw the strength and justice of the Muslims, he entered Islam. He became, may Allah be pleased with him, among those whose hearts were reconciled at first, then his Islam became good. He died in 31 AH, having witnessed the conquests of Islam and rejoiced in them.",
      "Umm Habibah was among the female jurists in religion. She narrated from the Prophet ﷺ 65 hadiths. Her nephew Abdullah ibn al-Utbah ibn Abi Sufyan was among her students. He learned from her much of the jurisprudence of women.",
      "When the trial occurred between Ali and her brother Mu'awiyah, Umm Habibah withdrew from it. She did not enter the conflict though her brother Mu'awiyah was a party to it. She contented herself with saying what reconciles between people and supplicated for good. Her position showed deep wisdom — she did not side with her brother at the expense of a noble Companion like Ali ibn Abi Talib.",
      "Umm Habibah died in 44 AH during her brother Mu'awiyah's caliphate. She was nearly 70. The people of Madinah prayed over her, and she was buried in al-Baqi'. Mu'awiyah escorted her from Sham with deep grief for his sister.",
      "Umm Habibah's lessons are great. First: steadfastness on the religion is sometimes under the harshest circumstances. Umm Habibah was in estrangement, her father an enemy of Islam, her husband apostatised — yet she stood firm. How many today leave their religion for less than that! Every difficulty we live is lighter than her difficulty.",
      "Second: Allah rewards the patient with greater than they expect. Umm Habibah lost her husband, family, and country, and Allah compensated her with marriage to the Prophet ﷺ. She became a Mother of the Believers. Whoever leaves something for Allah, Allah replaces it with better.",
      "Third: the manners of Islam rise above the manners of kinship. Umm Habibah prevented her father from sitting on the Prophet's ﷺ bed. She did not flatter her father at the expense of respect for the Prophet. Whoever puts kinship above truth has gone astray, and whoever puts truth above kinship has been guided.",
      "Umm Habibah bint Abi Sufyan remains in the history of Islam a model of steadfastness and dignity. The wife who returned from Abyssinia as a Mother of the Believers. O Allah, be pleased with Umm Habibah, and make us firm on Your religion in all circumstances.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 32. ميمونة بنت الحارث رضي الله عنها — آخر من تزوج النبي
  // ──────────────────────────────────────────────────────────────────────
  'maymuna': {
    ar: P([
      'هي ميمونة بنت الحارث بن حزن الهلالية. اسمها قبل الإسلام بَرَّة، فسماها النبي ﷺ ميمونة تفاؤلًا بها. وُلدت قبل البعثة بنحو 26 سنة. كانت من قبيلة بني هلال — قبيلة عربية كريمة. أختها أم الفضل لبابة كانت زوجة العباس بن عبد المطلب — عم النبي ﷺ. وأختها الأخرى زينب بنت خزيمة — أم المساكين — كانت زوجة النبي ﷺ قبلها.',
      'تزوجت قبل الإسلام من مسعود بن عمرو الثقفي، ثم طُلّقت منه. ثم تزوجت أبا رهم بن عبد العزى، فمات عنها. صارت أرملة. أسلمت في فترة قريبة من زواجها من النبي ﷺ. كان عمرها يومئذ نحو 26 سنة، وكانت من الجمالات.',
      'في السنة السابعة من الهجرة، أدّى النبي ﷺ عمرة القضاء — العمرة التي اتفق عليها مع قريش في صلح الحديبية. كان مع الجيش الإسلامي الذي دخل مكة لأداء العمرة. مكث ثلاثة أيام بأمر من قريش — حسب شروط الصلح. في تلك الأيام، خطب النبي ﷺ ميمونة من العباس بن عبد المطلب وكيلها. وافقت ميمونة بكل سرور.',
      'حدث الزواج في مكان اسمه سَرِف — وهو مكان قرب مكة على طريق المدينة، على بُعد نحو 10 أميال شمالي مكة. كانت ميمونة آخر من تزوج النبي ﷺ من النساء. بعدها لم يتزوج النبي ﷺ أحدًا حتى توفي. كانت أم المؤمنين الأخيرة من حيث ترتيب الزواج.',
      'بعد العمرة، رجعت ميمونة مع النبي ﷺ إلى المدينة. عاشت في حجرة بسيطة في المسجد النبوي مثل بقية أمهات المؤمنين. كانت ميمونة من العابدات الصوامات القوامات. كانت تكثر من الصلاة وقراءة القرآن والذكر.',
      'حدثت في بيتها حادثة مشهورة وقع فيها رسول الله ﷺ يتعلم الناس منها فقه الصلاة بالليل. باتت في بيتها ابن أختها عبد الله بن عباس — الذي صار ترجمان القرآن. أراد ابن عباس أن يرى صلاة النبي ﷺ بالليل. بقي مستيقظًا، ووقف خلف النبي ﷺ يصلي معه. كانت هذه الحادثة سببًا في كثير من أحاديث صلاة الليل التي رواها ابن عباس.',
      'كانت ميمونة خالة ابن عباس وخالة خالد بن الوليد. ابن عباس كان يجلس معها كثيرًا يتعلم منها. روى عنها أنه قال: ما رأيت أتقى لله ولا أوصل لرحم من ميمونة. كانت تواصل قرابتها حتى من غير المسلمين بالهدايا والصدقات.',
      'روت ميمونة عن النبي ﷺ 46 حديثًا. كانت أحاديثها كلها صحيحة وفيها فقه عظيم. أكثر أحاديثها في صفة الغسل والوضوء والطهارة، لأنها كانت زوجة النبي ﷺ ترى أفعاله الخاصة. ومن أشهر أحاديثها وصف غسل النبي ﷺ من الجنابة — حديث صحيح متفق عليه.',
      'كانت كريمة جدًا. روي أن النبي ﷺ أعطاها مرة جارية، فأعتقتها. لما سُئلت لِم أعتقتها؟ قالت: سمعت رسول الله ﷺ يقول: من أعتق رقبة مؤمنة أعتقه الله من النار. لم تنتفع بها مع أنها كانت في حاجة، إنما آثرت أجر الآخرة.',
      'في عمر التسعينات، وفي خلافة معاوية، قررت ميمونة أن تخرج من المدينة إلى مكة. كانت في طريقها لزيارة بلدها الأصلي. في الطريق، وصلت إلى سَرِف — نفس المكان الذي تزوجها فيه النبي ﷺ قبل 44 سنة. مرضت في سرف مرضًا شديدًا. لم تستطع إكمال الرحلة.',
      'علمت ميمونة أن أجلها قد قرب. قالت لمن حولها: أخرجوني من مكة، إن رسول الله ﷺ أخبرني أنّي لا أموت بمكة. فأخرجوها إلى سَرِف. هناك توفيت سنة 51 هـ. حُمل جثمانها إلى سرف، ودُفنت في نفس المكان الذي تزوجها فيه النبي ﷺ.',
      'وقفت أم المؤمنين عائشة على قبر ميمونة وقالت كلمتها العظيمة: والله، إنها أنزلتها سَرِف، وفي ذلك الموضع وضعها رسول الله ﷺ — أي تزوجها — فدفناها فيه. سبحان الذي بدأها أمها قبل ابتدائها، وفي سَرِف ابتدأها رسول الله ﷺ زوجة، وفي سرف رد روحها إليه. كانت كلمات تأمل عجيب — أن تنتهي حياة المرأة في نفس المكان الذي بدأت فيه قصتها الأهم.',
      'دروس ميمونة عظيمة. الأول: أن العبادة الخاصة في البيت أعظم من العبادة العلنية. ميمونة كانت تتعبد في بيتها فقط، ولم تخرج في غزو أو شهرة، لكنها رفعت إلى منزلة عظيمة. كثير من الناس يطلبون الشهرة بعبادتهم، والأفضل أن تكون عبادة بينك وبين الله.',
      'الثاني: أن صلة الرحم تنفع حتى مع غير المسلمين. ميمونة كانت تواصل أقاربها — حتى الذين لم يسلموا — بالهدايا والصدقات. هذا فقه عظيم: الصلة لا تنقطع بالكفر، إنما يُحسن إلى القريب دون إعانته على كفره.',
      'الثالث: أن الله يكتب أمكنة الناس. ميمونة تزوجت في سرف، وماتت في سرف. مكان واحد بدأ قصتها وأنهاها. كل إنسان له مكان مكتوب يموت فيه. الموت يأتي حيث يقدّر الله، لا حيث يخطّط الإنسان.',
      'يبقى ميمونة بنت الحارث في تاريخ الإسلام آخر من تزوج النبي ﷺ، خالة ابن عباس، المرأة التي ماتت حيث تزوجت. اللهم ارضَ عن ميمونة، واجمعنا بها وبالنبي ﷺ في جنات النعيم.',
    ]),
    en: P([
      "She is Maymunah bint al-Harith ibn Hazn al-Hilaliyyah. Her name before Islam was Barrah, but the Prophet ﷺ named her Maymunah as a good omen. She was born about 26 years before the mission. She was of the tribe of Banu Hilal — a noble Arab tribe. Her sister Umm al-Fadl Lubabah was the wife of al-Abbas ibn Abd al-Muttalib — the Prophet's ﷺ uncle. Her other sister Zaynab bint Khuzaymah — Mother of the Poor — had been the Prophet's ﷺ wife before her.",
      "Before Islam she married Mas'ud ibn Amr al-Thaqafi, then was divorced from him. Then she married Abu Rahm ibn Abd al-Uzza, who died. She became a widow. She embraced Islam in a period close to her marriage to the Prophet ﷺ. She was about 26 years old, and was among the beautiful.",
      "In the seventh year of the Hijrah, the Prophet ﷺ performed the Compensatory Umrah — the Umrah agreed upon with Quraysh at the Treaty of Hudaybiyyah. He was with the Muslim army that entered Makkah to perform Umrah. He stayed three days by Quraysh's order — according to the terms of the treaty. In those days, the Prophet ﷺ proposed to Maymunah through al-Abbas ibn Abd al-Muttalib, her agent. Maymunah agreed with all joy.",
      "The marriage occurred at a place called Sarif — a place near Makkah on the road to Madinah, about 10 miles north of Makkah. Maymunah was the last woman the Prophet ﷺ married. After her, the Prophet ﷺ did not marry anyone until he died. She was the last Mother of the Believers in order of marriage.",
      "After the Umrah, Maymunah returned with the Prophet ﷺ to Madinah. She lived in a simple chamber in the Prophet's Mosque like the rest of the Mothers of the Believers. Maymunah was among the worshipping ones, much given to fasting and night prayer. She would multiply prayer, recitation of the Qur'an, and remembrance.",
      "A famous incident occurred in her house in which the Messenger of Allah ﷺ taught people the jurisprudence of night prayer. Her nephew Abdullah ibn Abbas — who became the Translator of the Qur'an — spent the night in her house. Ibn Abbas wanted to see the Prophet's ﷺ night prayer. He stayed awake, stood behind the Prophet ﷺ, and prayed with him. This incident was the cause of many hadiths on night prayer that Ibn Abbas narrated.",
      "Maymunah was the aunt of Ibn Abbas and the aunt of Khalid ibn al-Walid. Ibn Abbas would sit with her often, learning from her. He narrated about her, saying: 'I have not seen anyone more God-fearing or more connected to kinship than Maymunah.' She would maintain ties with her relatives even non-Muslims through gifts and charity.",
      "Maymunah narrated from the Prophet ﷺ 46 hadiths. Her hadiths were all authentic and contained great jurisprudence. Most of her hadiths were on the description of ghusl, ablution, and purity, because she was the Prophet's ﷺ wife seeing his private acts. Among her most famous hadiths is the description of the Prophet's ﷺ ghusl from major impurity — an authentic agreed-upon hadith.",
      "She was very generous. It is narrated that the Prophet ﷺ gave her a slave-girl once, and she freed her. When asked why she freed her? She said: 'I heard the Messenger of Allah ﷺ say: Whoever frees a believing neck, Allah frees him from the Fire.' She did not benefit from her though she was in need, but preferred the reward of the Hereafter.",
      "In her nineties, in Mu'awiyah's caliphate, Maymunah decided to leave Madinah for Makkah. She was on her way to visit her original homeland. On the road, she reached Sarif — the same place the Prophet ﷺ had married her 44 years earlier. She fell ill at Sarif with a severe illness. She could not complete the journey.",
      "Maymunah knew her end had drawn near. She said to those around her: 'Take me out of Makkah. The Messenger of Allah ﷺ told me I would not die in Makkah.' They took her out to Sarif. There she died in 51 AH. Her body was carried to Sarif and buried in the very place the Prophet ﷺ had married her.",
      "Mother of the Believers A'isha stood at Maymunah's grave and said her great words: 'By Allah, she descended at Sarif, and in that place the Messenger of Allah ﷺ consummated with her — meaning he married her — and we buried her in it. Glory to the One who began her there before her beginning. At Sarif the Messenger of Allah ﷺ began her as a wife, and at Sarif He returned her soul to Him.' They were words of remarkable reflection — that a woman's life would end in the same place her most important story began.",
      "Maymunah's lessons are great. First: private worship at home is greater than public worship. Maymunah would worship in her house only and did not go out in raid or fame, yet she was raised to a great station. Many people seek fame through their worship; better is that worship be between you and Allah.",
      "Second: ties of kinship benefit even with non-Muslims. Maymunah would maintain ties with her relatives — even those who had not embraced Islam — through gifts and charity. This is great jurisprudence: ties are not cut by disbelief; rather, kindness is shown to the relative without aiding him in his disbelief.",
      "Third: Allah writes the places of people. Maymunah married at Sarif and died at Sarif. One place began and ended her story. Every person has a written place where he dies. Death comes where Allah decrees, not where the person plans.",
      "Maymunah bint al-Harith remains in the history of Islam the last woman the Prophet ﷺ married, the aunt of Ibn Abbas, the woman who died where she was married. O Allah, be pleased with Maymunah, and gather us with her and the Prophet ﷺ in the Gardens of Bliss.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 33. زينب بنت خزيمة رضي الله عنها — أم المساكين
  // ──────────────────────────────────────────────────────────────────────
  'zaynab-khuzayma': {
    ar: P([
      'هي زينب بنت خزيمة بن الحارث بن عبد الله الهلالية. لُقّبت قبل الإسلام بـ أم المساكين، لكثرة إطعامها الفقراء وعطفها على المحتاجين. وُلدت قبل البعثة بنحو ثلاثين سنة. كانت أختا غير شقيقتين لميمونة بنت الحارث — أم المؤمنين الأخرى. كانتا من نفس القبيلة — بنو هلال.',
      'تزوجت قبل الإسلام من ابن عمها الطفيل بن الحارث الهاشمي. ثم طُلّقت أو مات عنها. ثم تزوجت أخاه عبيدة بن الحارث بن المطلب الهاشمي. أسلم عبيدة قديمًا في الإسلام، وكان من السابقين. هاجر إلى المدينة. شارك في غزوة بدر، وكان من أبطالها. لكنه أصيب فيها إصابة بليغة في ساقه، وقطعت ساقه، ومات من جرحه بعد فترة. صارت زينب أرملة.',
      'كانت زينب من النساء الكريمات الصالحات. عُرفت بأم المساكين قبل الإسلام لأنها كانت تطعم الفقراء كثيرًا. كان بيتها مأوى للمحتاجين، تفتحه لهم في كل وقت. لم تكن غنية جدًا، لكنها كانت تتقاسم ما عندها مع من لا يجد.',
      'لما توفي زوجها عبيدة، رحم النبي ﷺ حالها. كانت أرملة في المدينة، بعيدة عن قبيلتها. لم يكن لها من يعينها. تزوجها النبي ﷺ في السنة الثالثة من الهجرة، تكريمًا لها على صبرها وعطفها على المساكين. كان عمرها يومئذ نحو 30 سنة، والنبي ﷺ في الستينات.',
      'لم تعش زينب في بيت النبي ﷺ طويلًا. بقيت ثمانية أشهر تقريبًا — على أكثر الروايات. توفيت سنة 3 هـ أو 4 هـ في المدينة. كانت أول زوجات النبي ﷺ موتًا في حياته بعد خديجة بنت خويلد. لم تترك له ذرية.',
      'صلى عليها النبي ﷺ بنفسه. ودُفنت بالبقيع. كانت ميتها صدمة للنبي ﷺ، لأنها كانت ثاني زوجة يفقدها بعد خديجة. حزن عليها أهل المدينة، خاصة المساكين والفقراء الذين كانوا يتعيشون من كرمها.',
      'لما توفيت، تركت بيتها مفتوحًا للفقراء. كان الفقراء يأتون إلى بيتها كل يوم بحثًا عن طعام. حزنوا عليها حزنًا شديدًا. قالت إحدى الفقيرات: من سيطعمنا بعد أم المساكين؟ كان ذكرها يعيش في قلوب من أحسنت إليهم سنين.',
      'لقبها أم المساكين كان لقبًا حقيقيًا، ليس مجاملة. الناس لقّبوها بهذا اللقب قبل الإسلام، وبقي لقبها حتى ماتت. هذا يدل على شدة كرمها وتعاطفها مع الفقراء.',
      'كانت زينب من القلائل اللواتي ذكرهن الحديث رغم قصر حياتها مع النبي ﷺ. لم ترو عنه أحاديث كثيرة — لقصر مدتها معه. لكن سيرتها ذكرت في كل كتب السنة.',
      'في وقت قصير عاشته في بيت النبي ﷺ، كانت تواصل عملها مع الفقراء. كانت تأخذ ما يأتي إلى بيت النبي ﷺ من طعام وتفرّقه على المحتاجين. لم يبق طعام في بيتها لها أحيانًا، لكنها كانت سعيدة بإطعام غيرها.',
      'حدث في بيتها مع النبي ﷺ موقف جميل. جاء فقير يطرق الباب. كان عند زينب طعام تكفيها هي وزوجها النبي ﷺ. أعطت الفقير كل الطعام، وبقيت هي والنبي ﷺ بدون طعام في تلك الليلة. ابتسم النبي ﷺ ولم يعاتبها. كان يحب من زوجاته الكرم.',
      'بعد موتها، تذكر النبي ﷺ أم المساكين دائمًا. كان إذا ذُكرت، قال: رحم الله أم المساكين. كانت سيرة قصيرة لكنها مليئة بالخير.',
      'دروس زينب بنت خزيمة عظيمة. الأول: أن الكرم مع الفقراء يخلّد الذكر. زينب لم تعش طويلًا، لم تُنجب، لم تكن من بنات الأشراف الكبار، لكنها كانت كريمة. كرمها هذا جعل ذكرها يبقى مدى التاريخ. كم من غني عاش طويلًا ولم يذكره أحد بخير، وكم من فقير عاش قصيرًا فبقي ذكره.',
      'الثاني: أن العمل مع الفقراء عبادة. زينب لم تكن من العابدات اللواتي يكثرن من الصلاة والصيام، لكنها كانت من العاملات اللواتي يقمن بحقوق المساكين. كل عمل يخدم الناس بنية الله عبادة عظيمة.',
      'الثالث: أن الأم ليست بالحمل والولادة فقط. زينب لُقّبت أم المساكين رغم أنها لم تنجب أبدًا. كانت أمًا لكل فقير ومسكين. الأمومة في الإسلام أوسع من معناها البيولوجي — هي عاطفة وحماية ورعاية.',
      'يبقى زينب بنت خزيمة في تاريخ الإسلام أم المساكين، الزوجة القصيرة العمر في بيت النبي ﷺ، الكريمة على الفقراء. اللهم ارضَ عن زينب، وارحم بنا كرمها، واجعلنا من أهل العطاء كما كانت.',
    ]),
    en: P([
      "She is Zaynab bint Khuzaymah ibn al-Harith ibn Abdullah al-Hilaliyyah. She was nicknamed before Islam 'Mother of the Poor' for her frequent feeding of the destitute and compassion for the needy. She was born about thirty years before the mission. She was a paternal half-sister of Maymunah bint al-Harith — the other Mother of the Believers. They were of the same tribe — Banu Hilal.",
      "Before Islam she married her cousin al-Tufayl ibn al-Harith al-Hashimi. Then she was divorced or he died. Then she married his brother Ubaydah ibn al-Harith ibn al-Muttalib al-Hashimi. Ubaydah embraced Islam early and was among the very first. He emigrated to Madinah. He participated in the Battle of Badr and was among its heroes. But he was severely wounded in his leg, his leg was amputated, and he died of his wound after a period. Zaynab became a widow.",
      "Zaynab was among the noble, righteous women. She was known as Mother of the Poor before Islam because she fed the poor much. Her house was a refuge for the needy; she opened it to them at every time. She was not very wealthy, but she shared what she had with those who had nothing.",
      "When her husband Ubaydah died, the Prophet ﷺ had mercy on her condition. She was a widow in Madinah, far from her tribe. She had no one to help her. The Prophet ﷺ married her in the third year of the Hijrah, honouring her for her patience and compassion for the poor. She was about 30 years old, and the Prophet ﷺ in his sixties.",
      "Zaynab did not live in the Prophet's ﷺ house long. She stayed about eight months — on most narrations. She died in 3 AH or 4 AH in Madinah. She was the first of the Prophet's ﷺ wives to die in his lifetime after Khadijah bint Khuwaylid. She left him no offspring.",
      "The Prophet ﷺ prayed over her himself. She was buried in al-Baqi'. Her death was a shock to the Prophet ﷺ, because she was the second wife he lost after Khadijah. The people of Madinah grieved for her, especially the poor and needy who had subsisted on her generosity.",
      "When she died, she left her house open to the poor. The poor would come to her house every day seeking food. They grieved deeply for her. One poor woman said: 'Who will feed us after the Mother of the Poor?' Her memory lived in the hearts of those she had been kind to for years.",
      "Her title 'Mother of the Poor' was a real title, not flattery. People nicknamed her this before Islam, and her title remained until she died. This indicates her great generosity and compassion for the poor.",
      "Zaynab was among the few mentioned by hadith despite the shortness of her life with the Prophet ﷺ. She did not narrate many hadiths from him — due to her short time with him. But her life is mentioned in every book of Sunnah.",
      "In the short time she lived in the Prophet's ﷺ house, she continued her work with the poor. She would take what came to the Prophet's ﷺ house of food and distribute it to the needy. Sometimes no food remained in her house for her, but she was happy feeding others.",
      "A beautiful situation occurred in her house with the Prophet ﷺ. A poor man knocked on the door. Zaynab had food enough for her and her husband the Prophet ﷺ. She gave the poor man all the food, and she and the Prophet ﷺ remained without food that night. The Prophet ﷺ smiled and did not blame her. He loved generosity in his wives.",
      "After her death, the Prophet ﷺ always remembered Mother of the Poor. When she was mentioned he would say: 'May Allah have mercy on the Mother of the Poor.' It was a short life but filled with good.",
      "Zaynab bint Khuzaymah's lessons are great. First: generosity to the poor immortalises remembrance. Zaynab did not live long, did not give birth, was not from the great noble daughters, but she was generous. Her generosity made her remembrance remain through history. How many a wealthy one lived long and no one remembered him with good, and how many a poor one lived briefly and his remembrance remained.",
      "Second: working with the poor is worship. Zaynab was not among the worshippers who multiplied prayer and fasting, but she was among the workers who fulfilled the rights of the poor. Every work that serves people with the intention of Allah is great worship.",
      "Third: motherhood is not by carrying and birth alone. Zaynab was nicknamed Mother of the Poor though she never gave birth. She was a mother to every poor and needy person. Motherhood in Islam is broader than its biological meaning — it is emotion, protection, and care.",
      "Zaynab bint Khuzaymah remains in the history of Islam the Mother of the Poor, the short-lived wife in the Prophet's ﷺ house, generous to the poor. O Allah, be pleased with Zaynab, have mercy on us through her generosity, and make us among those of giving as she was.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 34. أُبيّ بن كعب رضي الله عنه — سيد القراء
  // ──────────────────────────────────────────────────────────────────────
  'ubayy': {
    ar: P([
      'هو أُبيّ بن كعب بن قيس بن عبيد بن زيد بن معاوية الأنصاري الخزرجي النجاري. وُلد بيثرب — المدينة — قبل البعثة بنحو 20 سنة. كان من قبيلة بني النجار، التي كانت أم النبي ﷺ آمنة بنت وهب من خئولتها. فهو يجمع بين شرف الأنصار وقرابة النبي ﷺ من جهة أمه.',
      'كان من القلائل في يثرب الذين يقرأون ويكتبون قبل الإسلام. تعلّم الكتابة من اليهود في المدينة. كانت الكتابة في ذلك الوقت مهارة نادرة بين العرب. هذه المهارة جعلت من أُبيّ شخصية مهمة منذ شبابه.',
      'أسلم في بيعة العقبة الثانية، فكان من السابقين الأنصار. شارك في كل بيعة بعدها — بيعة الحديبية، بيعة الرضوان، وكل أمر بايع فيه النبي ﷺ. لما هاجر النبي ﷺ إلى المدينة، اختاره النبي ﷺ من بين كتّاب الوحي. صار يكتب القرآن للنبي ﷺ كلما نزل عليه.',
      'كان أحفظ الناس للقرآن في عصر النبي ﷺ. قال النبي ﷺ مدحه: أقرؤكم أُبيّ. أي أكثرهم إتقانًا لقراءة القرآن. كان النبي ﷺ يحب صوته في القرآن. حفظ سبع سور من القرآن بطرق مختلفة — أي قراءات متعددة لنفس الآيات.',
      'حدثت قصة عجيبة مع أُبيّ. روى البخاري ومسلم أن النبي ﷺ قال لأبيّ: إن الله أمرني أن أقرأ عليك القرآن. تعجب أُبيّ وقال: آلله سمّاني لك؟ قال النبي ﷺ: نعم. فبكى أُبيّ بكاءً شديدًا. قال: ذكرت عند رب العالمين؟ قال: نعم. فبكى بكاء أعظم. كانت كرامة لم ينلها كثير من الصحابة — أن يذكره الله في وحيه لنبيه.',
      'لما قرأ النبي ﷺ على أبيّ، قرأ سورة لم يكن قد سمعها أُبيّ من قبل بنفس القراءة. اختلف فيها مع النبي ﷺ. قال أُبيّ: نسيتها أم تجدّدت؟ قال النبي ﷺ: لا، الكل من الله. هذا أصل ما يسمى بـ القراءات السبع. القرآن نزل على سبعة أحرف. كل حرف منها يُسمح بقراءته. أُبيّ كان من رواة هذا الأمر، فهو علم من أعلام علم القراءات.',
      'شارك أُبيّ في غزوات النبي ﷺ كلها: بدر، أحد، الخندق، الحديبية، خيبر، فتح مكة، حنين، الطائف، تبوك. كان شجاعًا فارسًا. كان أيضًا في كتابة المراسلات الدبلوماسية للنبي ﷺ — رسائله إلى ملوك الفرس والروم والحبشة. كان مرجع النبي ﷺ في الكتابة.',
      'لما جمع أبو بكر القرآن في مصحف واحد بعد موت كثير من الحفظة في حروب الردة، كان أُبيّ من المستشارين في هذا الجمع. زيد بن ثابت كان الجامع، لكنه كان يستشير أُبيّ في القراءات والأحرف. ثم في خلافة عثمان، لما أراد توحيد القراءة على مصحف واحد، كان أُبيّ من الأربعة الذين كلّفهم عثمان بنسخ المصحف العثماني. الثلاثة الآخرون: زيد بن ثابت، سعيد بن العاص، عبد الرحمن بن الحارث بن هشام.',
      'روى أُبيّ عن النبي ﷺ 164 حديثًا. كانت أحاديثه دقيقة معتمدة. روى بعض أعظم الأحاديث في فضل سور القرآن، خاصة فضل سورة الفاتحة وآية الكرسي وسورة الإخلاص.',
      'كان أُبيّ يميل إلى الزهد والعبادة. كان يتعبّد في بيته كثيرًا. روى أنه كان إذا قرأ سورة الفاتحة في الصلاة، يبكي من معانيها العميقة. كان يقول: الفاتحة فيها كل القرآن.',
      'في الفتنة بين علي ومعاوية، اعتزل أُبيّ. لم يشارك في الجمل ولا صفين. كان من المتفرغين للعلم والقرآن. لم يحب الخوض في السياسة. مات قبل أن تنتهي الفتنة، فلم يشهد آخرها.',
      'توفي أُبيّ في خلافة عثمان سنة 32 هـ بالمدينة. كان عمره يومئذ نحو 67 سنة. صلى عليه عثمان بنفسه. حضر جنازته جمع كبير من الصحابة والتابعين. دُفن بالبقيع، إلى جوار سيدنا عثمان وغيره من الصحابة.',
      'دروس أُبيّ عظيمة. الأول: أن العلم بالقرآن أعظم العلوم. أُبيّ نال شرف القراءة على لسان النبي ﷺ، وصار قائد قراء الإسلام. كل من جاء بعده من القراء يتشرف بأن ينسب علمه إلى علم أُبيّ. القرآن أساس كل علم في الإسلام.',
      'الثاني: أن الذكر في الوحي شرف عظيم. أُبيّ ذكره الله في وحيه لنبيه. هذا ما يبكي منه. كل من يقرأ القرآن اليوم يقرأ علمًا له صلة بأبيّ. هذا أثر باقٍ لا يفنى.',
      'الثالث: أن المهارة النادرة قد ترفع صاحبها. أُبيّ كان من القلائل الذين يقرأون ويكتبون قبل الإسلام. هذه المهارة النادرة جعلت منه كاتب وحي للنبي ﷺ. تطوير المهارات في كل عصر يرفع المؤمن في مكانته.',
      'يبقى أُبيّ بن كعب في تاريخ الإسلام سيد القراء، كاتب الوحي، الذي ذكره الله في وحيه لنبيه. اللهم ارضَ عن أُبيّ، وارزقنا حب القرآن كحبه.',
    ]),
    en: P([
      "He is Ubayy ibn Ka'b ibn Qays ibn Ubayd ibn Zayd ibn Mu'awiyah al-Ansari al-Khazraji al-Najjari. He was born in Yathrib — Madinah — about 20 years before the mission. He was of the tribe of Banu al-Najjar, of which the Prophet's ﷺ mother Aminah bint Wahb was on the maternal side. He thus combined the honour of the Ansar with kinship to the Prophet ﷺ through his mother.",
      "He was among the few in Yathrib who could read and write before Islam. He learned writing from the Jews in Madinah. Writing at that time was a rare skill among the Arabs. This skill made Ubayy an important figure from his youth.",
      "He embraced Islam at the Second Pledge of Aqabah, so he was among the foremost Ansar. He participated in every pledge afterwards — the Pledge of Hudaybiyyah, the Pledge of Ridwan, and every matter the Prophet ﷺ took allegiance for. When the Prophet ﷺ emigrated to Madinah, the Prophet ﷺ chose him from among the scribes of revelation. He came to write the Qur'an for the Prophet ﷺ whenever it descended.",
      "He was the most memorising of people of the Qur'an in the era of the Prophet ﷺ. The Prophet ﷺ said in his praise: 'The best reciter among you is Ubayy.' That is, the most precise of them in recitation of the Qur'an. The Prophet ﷺ loved his voice in the Qur'an. He memorised seven surahs of the Qur'an in different ways — multiple recitations of the same verses.",
      "A remarkable story occurred with Ubayy. Bukhari and Muslim narrated that the Prophet ﷺ said to Ubayy: 'Allah has commanded me to recite the Qur'an to you.' Ubayy was amazed and said: 'Did Allah name me to you?' The Prophet ﷺ said: 'Yes.' Ubayy wept deeply. He said: 'I have been mentioned before the Lord of the Worlds?' He said: 'Yes.' He wept a greater weeping. It was an honour many Companions did not attain — that Allah should mention him in His revelation to His Prophet.",
      "When the Prophet ﷺ recited to Ubayy, he recited a surah Ubayy had not heard before in that recitation. He disagreed with the Prophet ﷺ about it. Ubayy said: 'Did I forget or did it change?' The Prophet ﷺ said: 'No, all is from Allah.' This is the origin of what is called the Seven Recitations. The Qur'an was revealed in seven letters. Each letter is permitted to be recited. Ubayy was among the narrators of this matter, so he is a sign of the science of recitations.",
      "Ubayy participated in all the Prophet's ﷺ campaigns: Badr, Uhud, the Trench, Hudaybiyyah, Khaybar, the Conquest of Makkah, Hunayn, Ta'if, Tabuk. He was a brave knight. He was also in the writing of the Prophet's ﷺ diplomatic correspondence — his letters to the kings of Persia, Rome, and Abyssinia. He was the Prophet's ﷺ reference in writing.",
      "When Abu Bakr collected the Qur'an into a single Mushaf after the death of many memorisers in the wars of apostasy, Ubayy was among the consultants in this collection. Zayd ibn Thabit was the collector, but he would consult Ubayy on the recitations and letters. Then in Uthman's caliphate, when he wanted to unify the recitation on a single Mushaf, Ubayy was one of the four whom Uthman charged with copying the Uthmanic Mushaf. The other three: Zayd ibn Thabit, Sa'id ibn al-As, and Abd al-Rahman ibn al-Harith ibn Hisham.",
      "Ubayy narrated from the Prophet ﷺ 164 hadiths. His hadiths were precise and reliable. He narrated some of the greatest hadiths on the virtue of the surahs of the Qur'an, especially the virtue of Surah al-Fatihah, Ayat al-Kursi, and Surah al-Ikhlas.",
      "Ubayy inclined to asceticism and worship. He would worship at home much. It is narrated that when he recited Surah al-Fatihah in prayer, he would weep at its deep meanings. He used to say: 'al-Fatihah contains all of the Qur'an.'",
      "In the trial between Ali and Mu'awiyah, Ubayy withdrew. He did not participate in the Camel or Siffin. He was among those devoted to knowledge and the Qur'an. He did not love delving into politics. He died before the trial ended, so he did not witness its end.",
      "Ubayy died in Uthman's caliphate in 32 AH in Madinah. He was about 67 years old. Uthman prayed over him himself. A great gathering of Companions and Successors attended his funeral. He was buried in al-Baqi', next to Uthman and others among the Companions.",
      "Ubayy's lessons are great. First: knowledge of the Qur'an is the greatest of sciences. Ubayy attained the honour of recitation upon the tongue of the Prophet ﷺ and became the leader of the reciters of Islam. Every reciter after him takes pride in tracing his knowledge to Ubayy's knowledge. The Qur'an is the foundation of every science in Islam.",
      "Second: being mentioned in revelation is a great honour. Ubayy was mentioned by Allah in His revelation to His Prophet. This is what made him weep. Every person who reads the Qur'an today reads knowledge connected to Ubayy. This is an enduring effect that does not perish.",
      "Third: rare skill may raise its owner. Ubayy was among the few who could read and write before Islam. This rare skill made him a scribe of revelation for the Prophet ﷺ. Developing skills in every era raises the believer in his station.",
      "Ubayy ibn Ka'b remains in the history of Islam the master of reciters, scribe of revelation, the one Allah mentioned in His revelation to His Prophet. O Allah, be pleased with Ubayy, and grant us love of the Qur'an as his love.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 35. عبادة بن الصامت رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'ubada': {
    ar: P([
      'هو عبادة بن الصامت بن قيس بن أصرم الأنصاري الخزرجي. وُلد بيثرب قبل البعثة بنحو 38 سنة. كان من سادات الخزرج، طويل القامة، شديد البأس، صريحًا في الحق. كان قبل الإسلام من القادة العسكريين في قبيلته.',
      'أسلم في بيعة العقبة الأولى — فكان من السابقين الأنصار. ثم شارك في بيعة العقبة الثانية، وكان من النقباء الاثني عشر الذين بايعوا النبي ﷺ على حمل أمر الإسلام في المدينة. كان نقيب بني عوف بن الخزرج.',
      'حدثت في بيعة العقبة الثانية موقفه المشهور. كانت قريش لا تزال تطارد المسلمين. لما أراد النبي ﷺ من الأنصار البيعة، قال عبادة وأصحابه: نبايعك يا رسول الله على أن ننصرك مما نمنع منه نساءنا وأبناءنا. وعدوا بحماية النبي ﷺ كحماية أزواجهم وأبنائهم — أعظم وعد.',
      'هاجر النبي ﷺ إلى المدينة. آخى النبي ﷺ بين عبادة وبين أبي مرثد الغنوي من المهاجرين. شارك عبادة في كل غزوات النبي ﷺ ابتداءً من بدر. كان حامل راية في غزوات كثيرة. أبلى بلاءً حسنًا في أحد، الخندق، خيبر، فتح مكة، حنين، الطائف، تبوك.',
      'كان من حافظي القرآن في حياة النبي ﷺ. كان من المعلّمين لأهل الصُّفة — الفقراء الذين يعيشون في المسجد ويتعلمون القرآن. أرسله النبي ﷺ كثيرًا ليعلّم الناس.',
      'في عهد عمر بن الخطاب، أرسل عمر عبادة مع معاذ بن جبل وأبي الدرداء إلى الشام لتعليم أهلها الإسلام. كان أهل الشام جدد في الإسلام بعد فتوحات أبي عبيدة، يحتاجون إلى علماء يعلمونهم القرآن والفقه. عبادة استقر في حمص. علّم أهلها القرآن والحديث.',
      'تولّى قضاء فلسطين. كان قاضيًا صارمًا، يحكم بالحق ولا يخاف من أحد. قال عنه عمر بن الخطاب: من سرّه أن ينظر إلى رجل من أهل الجنة يطأ على وجه الأرض فلينظر إلى عبادة بن الصامت.',
      'حدثت بينه وبين معاوية بن أبي سفيان مواقف اشتهرت في التاريخ. كان معاوية يومئذ والي الشام لعمر بن الخطاب. رأى عبادة من معاوية أمرًا فيه فساد — تجار يبيعون الذهب والفضة بطريقة فيها ربا. أنكر عليه عبادة علنًا. غضب معاوية، وكتب إلى عمر يشكوه: عبادة بن الصامت يعكر علي أمري.',
      'كتب عمر إلى معاوية كلمة شهيرة: خل بين عبادة وبين الشام، فإنما أراد ما أنزل الله. أي اترك عبادة يعمل لله، ولا تمنعه من قول الحق. عمر كان يحب عبادة ويثق في علمه ودينه.',
      'استأذن عبادة معاوية ليرجع إلى المدينة بعد ذلك، لأنه شعر أن وجوده في الشام صار صعبًا. وافق معاوية. رجع عبادة إلى المدينة. لكن عمر أمره أن يرجع إلى الشام، قائلًا: ما يمنعك أن تكون مع قومك في الشام؟ رجع إلى فلسطين.',
      'روى عبادة عن النبي ﷺ 181 حديثًا. منها أحاديث في غاية الأهمية: حديث "لا ضرر ولا ضرار" — أحد القواعد الخمس الكبرى في الفقه الإسلامي. وحديث: "لا صلاة لمن لم يقرأ بفاتحة الكتاب" — أصل وجوب الفاتحة في الصلاة. وأحاديث في أحكام البيع والربا.',
      'في خلافة عثمان، شارك عبادة في فتح قبرص بحرًا. كان مع زوجته أم حرام بنت ملحان — أخت أم سُليم. وقعت قصة مؤثرة في تلك الغزوة: ركبت أم حرام بغلًا، فسقطت منه، فماتت. دفنت في قبرص — أول قبر صحابي في تلك الجزيرة. عبادة دفنها وحزن عليها.',
      'توفي عبادة بن الصامت في خلافة عثمان أو معاوية على خلاف في الروايات. الراجح أنه توفي في الرملة بفلسطين سنة 34 هـ. كان عمره يومئذ 72 سنة. دُفن في الرملة، وقبره معروف بها إلى اليوم، يُزار من المسلمين.',
      'دروس عبادة عظيمة. الأول: أن الصراحة في الحق درجة عالية. عبادة لم يخف من معاوية رغم أنه كان والي الشام. أنكر عليه علنًا. هذا فقه السلف الصالح — لا يحابي الحاكم على حساب الحق.',
      'الثاني: أن العلم رسالة. عبادة لم يبقَ في المدينة، إنما ترك أهله وذهب إلى الشام لتعليم الناس. كل عالم اليوم يحمل رسالة التعليم. لا يكفي أن يعلم لنفسه، يجب أن ينقل العلم إلى من يحتاجه.',
      'الثالث: أن أحاديث الفقه أصول للأمة. عبادة روى أحاديث صارت أصولًا في الفقه: لا ضرر ولا ضرار، لا صلاة لمن لم يقرأ بفاتحة الكتاب. كل فقيه اليوم يبني عليها أحكامًا كثيرة. هذه الأحاديث القليلة لها أثر عظيم.',
      'يبقى عبادة بن الصامت في تاريخ الإسلام صريحًا في الحق، نقيبًا من نقباء العقبة، قاضي فلسطين، صاحب الأحاديث الفقهية الأصلية. اللهم ارضَ عن عبادة، واجعلنا من الصريحين في الحق.',
    ]),
    en: P([
      "He is Ubadah ibn al-Samit ibn Qays ibn Asram al-Ansari al-Khazraji. He was born in Yathrib about 38 years before the mission. He was among the chiefs of the Khazraj, tall, strong, candid in truth. Before Islam he was among the military commanders of his tribe.",
      "He embraced Islam at the First Pledge of Aqabah — among the foremost Ansar. He then participated in the Second Pledge of Aqabah, and was among the twelve chiefs who pledged to the Prophet ﷺ to bear the matter of Islam in Madinah. He was the chief of Banu Awf ibn al-Khazraj.",
      "His famous stance occurred at the Second Pledge of Aqabah. Quraysh was still pursuing the Muslims. When the Prophet ﷺ wanted the Ansar's pledge, Ubadah and his companions said: 'We pledge allegiance to you, O Messenger of Allah, that we will support you with what we defend our wives and children with.' They promised to protect the Prophet ﷺ as they protected their wives and children — the greatest promise.",
      "The Prophet ﷺ emigrated to Madinah. The Prophet ﷺ joined Ubadah in brotherhood with Abu Marthad al-Ghanawi of the Muhajirun. Ubadah participated in every campaign of the Prophet ﷺ starting from Badr. He was a standard-bearer in many campaigns. He showed great prowess at Uhud, the Trench, Khaybar, the Conquest of Makkah, Hunayn, Ta'if, and Tabuk.",
      "He was among the memorisers of the Qur'an in the Prophet's ﷺ lifetime. He was among the teachers of the People of al-Suffah — the poor who lived in the mosque and learned the Qur'an. The Prophet ﷺ sent him much to teach people.",
      "In Umar ibn al-Khattab's era, Umar sent Ubadah with Mu'adh ibn Jabal and Abu al-Darda' to Sham to teach its people Islam. The people of Sham were new in Islam after Abu Ubaydah's conquests, needing scholars to teach them the Qur'an and jurisprudence. Ubadah settled in Homs. He taught its people the Qur'an and hadith.",
      "He took the judgeship of Palestine. He was a strict judge, ruling with truth and fearing no one. Umar ibn al-Khattab said about him: 'Whoever wishes to look at a man of the people of Paradise walking on the face of the earth, let him look at Ubadah ibn al-Samit.'",
      "Between him and Mu'awiyah ibn Abi Sufyan occurred stances famous in history. Mu'awiyah was at that time the governor of Sham for Umar ibn al-Khattab. Ubadah saw from Mu'awiyah a matter in which there was corruption — merchants selling gold and silver in a way containing usury. Ubadah objected to him publicly. Mu'awiyah became angry and wrote to Umar complaining: 'Ubadah ibn al-Samit disturbs my matter.'",
      "Umar wrote to Mu'awiyah a famous word: 'Leave Ubadah alone with Sham; he only wants what Allah revealed.' That is, let Ubadah work for Allah and do not prevent him from speaking the truth. Umar loved Ubadah and trusted his knowledge and religion.",
      "Ubadah sought Mu'awiyah's permission to return to Madinah afterward, because he felt his presence in Sham had become difficult. Mu'awiyah agreed. Ubadah returned to Madinah. But Umar ordered him to return to Sham, saying: 'What prevents you from being with your people in Sham?' He returned to Palestine.",
      "Ubadah narrated from the Prophet ﷺ 181 hadiths. Among them hadiths of utmost importance: the hadith 'No harm and no reciprocal harm' — one of the five great rules in Islamic jurisprudence. The hadith: 'There is no prayer for one who does not recite the Opening of the Book' — the basis for the obligation of al-Fatihah in prayer. And hadiths on the rulings of sale and usury.",
      "In Uthman's caliphate, Ubadah participated in the naval conquest of Cyprus. He was with his wife Umm Haram bint Milhan — sister of Umm Sulaym. A moving story occurred on that campaign: Umm Haram rode a mule, fell from it, and died. She was buried in Cyprus — the first Companion's grave on that island. Ubadah buried her and grieved for her.",
      "Ubadah ibn al-Samit died in Uthman's or Mu'awiyah's caliphate, with narrations differing. The strongest is that he died in al-Ramlah in Palestine in 34 AH. He was 72 years old. He was buried in al-Ramlah, and his grave is known there to this day, visited by Muslims.",
      "Ubadah's lessons are great. First: candor in truth is a high degree. Ubadah did not fear Mu'awiyah though he was the governor of Sham. He objected to him publicly. This is the jurisprudence of the righteous predecessors — they do not flatter the ruler at the expense of truth.",
      "Second: knowledge is a message. Ubadah did not stay in Madinah; he left his family and went to Sham to teach people. Every scholar today bears the message of teaching. It does not suffice that he learns for himself; he must transmit knowledge to those who need it.",
      "Third: hadiths of jurisprudence are foundations for the Ummah. Ubadah narrated hadiths that became foundations in jurisprudence: no harm and no reciprocal harm, no prayer for one who does not recite the Opening of the Book. Every jurist today builds many rulings upon them. These few hadiths have a great effect.",
      "Ubadah ibn al-Samit remains in the history of Islam candid in truth, a chief of the Aqabah chiefs, the judge of Palestine, the owner of the foundational jurisprudential hadiths. O Allah, be pleased with Ubadah, and make us among those candid in truth.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 36. أُسيد بن حُضير رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'usayd': {
    ar: P([
      'هو أُسيد بن حُضير بن سماك بن عتيك الأنصاري الأوسي. وُلد بيثرب قبل البعثة بنحو 25 سنة. كان من بني عبد الأشهل من الأوس. ابن خال سعد بن معاذ سيد الأوس. كان قبل الإسلام من سادات قبيلته، شجاعًا فطنًا، شاعرًا فصيحًا، رياضيًا ماهرًا في الرماية.',
      'كان أبوه حُضير الكتائب أحد قادة الأوس في حرب بُعاث ضد الخزرج قبل الإسلام. لما توفي أبوه، صار أُسيد من قادة قبيلته في سن مبكرة. لقّبوه بـ الكامل لكماله في الفروسية والشعر والذكاء.',
      'دخل الإسلام إلى يثرب قبل الهجرة عن طريق مصعب بن عمير الذي أرسله النبي ﷺ سفيرًا. كان مصعب يدعو الأنصار في بيت أسعد بن زرارة. شكا قوم منه إلى سعد بن معاذ سيد الأوس. أرسل سعد ابن خاله أُسيد بن حُضير لطرد مصعب.',
      'جاء أُسيد إلى مصعب وأسعد. كان غاضبًا. قال لهما: ما يجيء بكما إلينا تسفّهان ضعفاءنا؟ اعتزلانا إن كانت لكما في أنفسكما حاجة. فقال له مصعب بهدوء وحكمة: أو تجلس فتسمع؟ إن رضيتَ أمرًا قبلته، وإن كرهتَ كُفّ عنك ما تكره. قال أُسيد: أنصفت.',
      'جلس أُسيد، فقرأ عليه مصعب من القرآن. لم تكن ثوانٍ حتى تلمعت عيناه. قال: ما أحسن هذا الكلام وأجمله! كيف تصنعون إذا أردتم أن تدخلوا في هذا الدين؟ علّمه مصعب الشهادة. أعلن أُسيد إسلامه في الحال.',
      'رجع أُسيد إلى سعد بن معاذ. لما رآه سعد، قال: لقد جاءني بغير الوجه الذي ذهب به. غضب سعد وقام بنفسه إلى مصعب. حدث له نفس ما حدث لأُسيد — جلس فاسمع فأسلم. ثم أسلمت بنو عبد الأشهل كلها في يوم واحد، بسبب إسلام سيدها سعد، الذي أسلم بسبب أُسيد، الذي أسلم بسبب مصعب. سلسلة من الإيمان بدأت بأُسيد.',
      'لما هاجر النبي ﷺ إلى المدينة، استقبله أُسيد بحفاوة. شارك أُسيد في كل غزوات النبي ﷺ. كان حامل راية الأوس في معاركهم. في غزوة أحد، كان من الذين ثبتوا حول النبي ﷺ. ضُرب يومئذ بسبعة جراح.',
      'كان أُسيد من أحسن الناس صوتًا في قراءة القرآن. روى البخاري ومسلم قصته العجيبة. كان ليلة يقرأ سورة البقرة وفرسه مربوطة بقربه، فاضطربت الفرس. أمسك عن القراءة فهدأت. قرأ مرة أخرى، فاضطربت. فعل ذلك ثلاث مرات.',
      'خشي أُسيد على ابنه الصغير يحيى الذي كان نائمًا بقربه، فالتفت. لما رفع رأسه، رأى مثل الظلة فيها مصابيح تعرج إلى السماء. ذُهل. لما حدّث النبي ﷺ بما رأى، قال النبي ﷺ: تلك الملائكة كانت تستمع لك. لو قرأت لأصبحت ينظر الناس إليها، لا تتوارى منهم. كانت كرامة عجيبة — ملائكة تنزل من السماء لتستمع لقراءة رجل.',
      'كان أُسيد فطنًا حكيمًا. في إحدى الأحاديث، شكا الأنصار يومًا أن النبي ﷺ أعطى المهاجرين من قريش حصصًا أكثر في غنائم حنين. اقترب أُسيد من النبي ﷺ يخبره. جمع النبي ﷺ الأنصار وقال لهم كلمته المشهورة: ألا ترضون أن يذهب الناس بالأموال وترجعون برسول الله إلى رحالكم؟ بكى الأنصار وقالوا: رضينا برسول الله قسمًا وحظًا.',
      'في خلافة عمر بن الخطاب، عمل أُسيد على شؤون الأنصار في المدينة. كان من المرجعيات. عمر كان يحبه ويستشيره. توفي أُسيد بن حُضير في المدينة سنة 20 هـ، وعمره 45 سنة. حملت جنازته من قبل عمر بن الخطاب بنفسه. صلى عليه عمر، ودُفن بالبقيع.',
      'تفاصيل وفاته مؤثرة. لما حضرته الوفاة، جاءه أهله وأقاربه. كان عليه ديون من المعاملات التجارية. أوصى بقضائها. قال: ليس لي مال أتركه، ولكن أرضًا. بيعوها، واقضوا ديوني. باع عمر بن الخطاب أرضه بنفسه، وقضى ديونه كلها. ولم يبقَ لورثته شيء — لكن أُسيد فضّل أن يلقى الله بدون دَين.',
      'دروس أُسيد عظيمة. الأول: أن العقل سبيل إلى الإيمان. أُسيد لم يأت غاضبًا فقط، بل جاء بحجة العقل. لما سمع القرآن، آمن فورًا. كم من شخص يرفض الإسلام بدون أن يسمعه! المعرفة قبل الحكم.',
      'الثاني: أن الإيمان يصنع التاريخ. أُسيد أسلم، فأسلم سعد، فأسلمت بنو عبد الأشهل، فبدأ الإسلام ينتشر في الأوس. سلسلة من الإيمان غيّرت تاريخ المدينة كلها. كل شخص قد يكون نقطة بداية لانتشار الخير.',
      'الثالث: أن الموت بدون دَين أعظم من الموت بثروة. أُسيد آثر أن لا يبقى عنده دَين على أن يبقى لورثته شيء. الدَّين أمانة، والمؤمن يكره أن يلقى الله وفي ذمته حق لأحد.',
      'يبقى أُسيد بن حُضير في تاريخ الإسلام الذي اختلطت قراءته بأصوات الملائكة، أحد النقباء، الذي أسلمت قبيلته بإسلامه. اللهم ارضَ عن أُسيد، وارفع درجته في الجنة.',
    ]),
    en: P([
      "He is Usayd ibn Hudayr ibn Simak ibn Atik al-Ansari al-Awsi. He was born in Yathrib about 25 years before the mission. He was of Banu Abd al-Ashhal of the Aws. The cousin of Sa'd ibn Mu'adh, chief of the Aws. Before Islam he was among the chiefs of his tribe, brave and astute, an eloquent poet, an athlete skilled in archery.",
      "His father Hudayr al-Kata'ib was one of the commanders of the Aws in the war of Bu'ath against the Khazraj before Islam. When his father died, Usayd became one of the commanders of his tribe at an early age. He was nicknamed 'al-Kamil' (the Perfect One) for his perfection in horsemanship, poetry, and intelligence.",
      "Islam entered Yathrib before the Hijrah through Mus'ab ibn Umayr, whom the Prophet ﷺ had sent as an ambassador. Mus'ab was calling the Ansar at the house of As'ad ibn Zurarah. Some people complained about him to Sa'd ibn Mu'adh, chief of the Aws. Sa'd sent his cousin Usayd ibn Hudayr to drive Mus'ab out.",
      "Usayd came to Mus'ab and As'ad. He was angry. He said to them: 'What brings you to us to mislead our weak ones? Withdraw from us if you have any need for yourselves.' Mus'ab said to him calmly and wisely: 'Will you not sit and listen? If you accept the matter, take it; if you dislike it, we will refrain from what you dislike.' Usayd said: 'You have been fair.'",
      "Usayd sat, and Mus'ab recited to him from the Qur'an. Mere seconds passed before his eyes brightened. He said: 'How fine and beautiful this speech is! What do you do if you want to enter this religion?' Mus'ab taught him the testimony. Usayd announced his Islam at once.",
      "Usayd returned to Sa'd ibn Mu'adh. When Sa'd saw him, he said: 'He has come to me with a different face than the one he left with.' Sa'd became angry and rose himself to Mus'ab. The same happened to him as had happened to Usayd — he sat, listened, and embraced Islam. Then all of Banu Abd al-Ashhal embraced Islam in a single day, because of the Islam of their chief Sa'd, who embraced Islam because of Usayd, who embraced Islam because of Mus'ab. A chain of faith that began with Usayd.",
      "When the Prophet ﷺ emigrated to Madinah, Usayd received him with honour. Usayd participated in every campaign of the Prophet ﷺ. He was the standard-bearer of the Aws in their battles. At the Battle of Uhud, he was among those who stood firm around the Prophet ﷺ. He was struck that day with seven wounds.",
      "Usayd had one of the most beautiful voices among the people in reciting the Qur'an. Bukhari and Muslim narrated his remarkable story. He was one night reciting Surah al-Baqarah with his horse tied near him, and the horse stirred. He stopped reciting and it calmed. He recited again, and it stirred. He did so three times.",
      "Usayd feared for his young son Yahya who was sleeping near him, so he turned. When he lifted his head, he saw something like a canopy with lamps ascending to the sky. He was amazed. When he told the Prophet ﷺ what he had seen, the Prophet ﷺ said: 'Those were the angels listening to you. Had you recited more, people would see them in the morning; they would not have hidden from them.' It was a remarkable honour — angels descending from the sky to listen to a man's recitation.",
      "Usayd was wise and astute. In one of the hadiths, the Ansar complained one day that the Prophet ﷺ had given the Muhajirun of Quraysh greater shares of the spoils of Hunayn. Usayd approached the Prophet ﷺ to inform him. The Prophet ﷺ gathered the Ansar and said to them his famous words: 'Are you not pleased that people go away with the wealth and you return with the Messenger of Allah to your homes?' The Ansar wept and said: 'We are pleased with the Messenger of Allah as our portion and lot.'",
      "In Umar ibn al-Khattab's caliphate, Usayd worked on the affairs of the Ansar in Madinah. He was a reference. Umar loved him and consulted him. Usayd ibn Hudayr died in Madinah in 20 AH at 45 years old. His bier was carried by Umar ibn al-Khattab himself. Umar prayed over him, and he was buried in al-Baqi'.",
      "The details of his death are moving. When death approached, his family and relatives came. He had debts from commercial dealings. He bequeathed to pay them. He said: 'I have no wealth to leave, but I have land. Sell it and pay my debts.' Umar ibn al-Khattab sold his land himself and paid all his debts. Nothing remained for his heirs — but Usayd preferred to meet Allah without debt.",
      "Usayd's lessons are great. First: the intellect is a path to faith. Usayd did not come merely angry but came with the argument of the intellect. When he heard the Qur'an, he believed at once. How many a person refuses Islam without hearing it! Knowledge before judgement.",
      "Second: faith makes history. Usayd embraced Islam, so Sa'd embraced Islam, so Banu Abd al-Ashhal embraced Islam, and Islam began to spread among the Aws. A chain of faith changed the history of all Madinah. Every person may be a starting point for the spread of good.",
      "Third: death without debt is greater than death with wealth. Usayd preferred not to leave a debt behind over leaving his heirs anything. Debt is a trust, and the believer hates to meet Allah with someone's right outstanding against him.",
      "Usayd ibn Hudayr remains in the history of Islam the one whose recitation mingled with the voices of the angels, one of the chiefs, whose tribe embraced Islam through his Islam. O Allah, be pleased with Usayd and raise his rank in Paradise.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 37. جابر بن عبد الله رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'jabir': {
    ar: P([
      'هو جابر بن عبد الله بن عمرو بن حرام الأنصاري الخزرجي السلمي. وُلد بيثرب قبل الهجرة بنحو 16 سنة. كان من بني سلمة من الخزرج. أبوه عبد الله بن عمرو بن حرام كان من النقباء الاثني عشر، ومن السادة الأوائل في الأنصار. شارك أبوه في غزوة بدر، ثم استشهد في غزوة أحد.',
      'كانت قصة استشهاد أبيه من أحزن ما عاش جابر. قبل غزوة أحد، استدعى عبد الله ابنه جابر. قال له: يا جابر، إنّي لا أراني إلا مقتولًا في غزوة أحد هذه. وإنّي لا أترك بعدي أحب إلي منك بعد رسول الله ﷺ. وإنّي تركتُ عليّ دَيْنًا فاقضِ، واستوصِ بأخواتك خيرًا. وأنا أوصيك أن لا تجزع، لئلا تشمت بك قبائل العرب.',
      'قُتل عبد الله في أحد. كان جابر صغيرًا — في الـ 15 من عمره تقريبًا. خرج إلى ساحة المعركة بعد المعركة يبحث عن أبيه. وجده مقتولًا مع المسلمين. حزن حزنًا شديدًا. مرّ به النبي ﷺ، فقال له: ما تبكي يا جابر؟ قال: يا رسول الله، استُشهد أبي وترك عيالًا ودَيْنًا. قال النبي ﷺ كلمات تصبّره: ما من أحد يكلم الله إلا من وراء حجاب، إلا أباك. كلّمه الله كفاحًا — أي وجهًا لوجه. فقال: يا عبدي تمنّ. قال: أتمنى أن تردني فأُقتل فيك ثانية.',
      'هذه أعظم بشارة لأب لابنه: أن الله كلّمه مباشرة، وأن أباه يحب الجهاد حتى بعد موته. اطمأن قلب جابر. ورث الدَّيْن من أبيه — وكان دَيْنًا كبيرًا. جاء أصحاب الدَّيْن — يهود في الغالب — يطالبون. كان عند جابر بستان من النخل، فيه ثمر يكاد يكفي لقضاء الدَّيْن، لكن أصحاب الدين قالوا: لا نأخذ بالمساومة، إنما نأخذ كل البستان.',
      'ذهب جابر إلى النبي ﷺ يطلب الدعاء. جاء النبي ﷺ إلى البستان. مشى حول النخل، ودعا الله بالبركة. ثم قال لجابر: اجمع التمر من النخل، واقضِ به دَينك. جمع جابر، فإذا الله قد جعل في التمر بركة عجيبة. قضى دَيْن أبيه كله، وبقي عنده من التمر مثل ما قضى به الدَّيْن أو أكثر. كانت معجزة نبوية.',
      'شارك جابر في غزوات النبي ﷺ بعد أحد. شهد 19 غزوة على ما رواه هو نفسه. كان شجاعًا، فطنًا، صبورًا. لم تثنه الفقر ولا الدَّيْن ولا فقد أبيه عن الجهاد.',
      'حدثت معه قصة عجيبة في غزوة ذات الرقاع. كان جابر في الطريق مع النبي ﷺ. كان جمل جابر ضعيفًا، يتأخر عن الجيش. مرّ به النبي ﷺ وقال: ما لك يا جابر؟ قال: جملي قد كل. أخذ النبي ﷺ عصاه وضرب الجمل ضربة خفيفة. صار الجمل من أسبق جمل في الجيش. ثم اشترى النبي ﷺ منه الجمل بأوقية، واشترط أن يحمله إلى المدينة، فحمله جابر.',
      'في المدينة، جاء جابر بالجمل. أعطاه النبي ﷺ ثمنه أوقية. ثم قال: خذ الجمل أيضًا، فهو لك. لم يأخذ النبي ﷺ منه شيئًا. كانت من كرم النبي ﷺ. جابر روى هذه القصة بنفسه في صحيح البخاري.',
      'كان جابر تزوج امرأة ثيبًا — أي كانت مطلقة أو أرملة. سأله النبي ﷺ: ما لك تتزوج ثيبًا؟ ألا تتزوج بكرًا تلاعبها وتلاعبك؟ قال جابر: يا رسول الله، إن لي أخوات صغارًا، فخشيت أن تجيء التي مثلهن فلا تربّيهن. تزوجت ثيبًا لتعينني على شؤون أخواتي. قال النبي ﷺ: أصبت يا جابر.',
      'كان جابر من أكثر الصحابة رواية. روى عن النبي ﷺ 1540 حديثًا. كانت أحاديثه دقيقة معتمدة. ذكر الفقهاء أن جابر هو الصحابي الذي روى أكثر ما يُحتاج إليه في فقه الحج. حدّث بكل تفاصيل حجة الوداع في حديث طويل اشتهر بـ حديث جابر في الحج.',
      'كان جابر طويل العمر. عاش بعد النبي ﷺ سنين كثيرة. شهد الفتنة بين علي ومعاوية، لكنه اعتزلها. تفرّغ للحديث والفقه. كان شيخ المحدّثين في المدينة في آخر عمره.',
      'عمي جابر في آخر حياته. لكنه ظل يحدّث الناس بأحاديث النبي ﷺ من حفظه. كان طلاب العلم يأتون من بعيد ليسمعوا منه. منهم من صار من أعلام التابعين — أبو الزبير المكي، عمرو بن دينار، وغيرهما.',
      'توفي جابر بن عبد الله في المدينة سنة 78 هـ في خلافة عبد الملك بن مروان. كان عمره 94 سنة. كان آخر صحابي توفي بالمدينة. صلى عليه أبان بن عثمان والي المدينة. دُفن بالبقيع، إلى جوار سادات الصحابة.',
      'دروس جابر عظيمة. الأول: أن البر بالوالد يستمر بعد موته. جابر قضى دَيْن أبيه ورعى أخواته. هذا بر الوالد بعد الموت. كم من ولد يهمل أمر أبيه بعد وفاته! جابر فعل عكس ذلك.',
      'الثاني: أن دعاء النبي ﷺ يبارك في الرزق. بستان جابر كان قليلًا، فبارك فيه النبي ﷺ، فصار كثيرًا. كم من إنسان عنده القليل، فلو سأل الله بصدق لبارك في رزقه. الرزق بيد الله.',
      'الثالث: أن أكثر الصحابة رواية للحديث كانوا من الذين بقوا أطول. جابر عاش 94 سنة. أبو هريرة عاش طويلًا. ابن عمر عاش طويلًا. عائشة عاشت طويلًا. الله أبقاهم ليحفظوا السنة وينقلوها للأمة.',
      'يبقى جابر بن عبد الله في تاريخ الإسلام راوي حجة الوداع، البار بأبيه الشهيد، الذي بارك النبي ﷺ في بستانه. اللهم ارضَ عن جابر، واجمعنا به في جنات النعيم.',
    ]),
    en: P([
      "He is Jabir ibn Abdullah ibn Amr ibn Haram al-Ansari al-Khazraji al-Sulami. He was born in Yathrib about 16 years before the Hijrah. He was of Banu Salimah of the Khazraj. His father Abdullah ibn Amr ibn Haram was one of the twelve chiefs and among the early chiefs of the Ansar. His father participated in the Battle of Badr, then was martyred at the Battle of Uhud.",
      "The story of his father's martyrdom was among the saddest Jabir lived. Before the Battle of Uhud, Abdullah summoned his son Jabir. He said to him: 'O Jabir, I see myself as nothing but slain in this Battle of Uhud. I leave behind no one more beloved to me than you after the Messenger of Allah ﷺ. I have left upon me a debt; pay it, and counsel your sisters with good. I instruct you not to despair, lest the Arab tribes rejoice at your misfortune.'",
      "Abdullah was killed at Uhud. Jabir was young — about 15 years old. He went out to the battlefield after the battle searching for his father. He found him slain with the Muslims. He grieved deeply. The Prophet ﷺ passed by him and said: 'What makes you weep, Jabir?' He said: 'O Messenger of Allah, my father was martyred and left children and a debt.' The Prophet ﷺ said words to console him: 'No one Allah speaks to is from behind a veil except your father. Allah spoke to him face to face. He said: O My servant, wish. He said: I wish that You return me so I may be killed in Your cause a second time.'",
      "This is the greatest glad tiding for a father to his son: that Allah spoke to him directly, and that his father loved jihad even after his death. Jabir's heart was reassured. He inherited the debt from his father — and it was a great debt. The creditors came — Jews mostly — demanding. Jabir had a palm garden with fruit nearly enough to pay the debt, but the creditors said: 'We will not take by negotiation; we will take the entire garden.'",
      "Jabir went to the Prophet ﷺ asking for supplication. The Prophet ﷺ came to the garden. He walked around the palms and supplicated to Allah for blessing. Then he said to Jabir: 'Gather the dates from the palms and pay your debt with them.' Jabir gathered, and Allah had placed in the dates a remarkable blessing. He paid his father's entire debt, and there remained with him of dates the same as what he paid the debt with, or more. It was a prophetic miracle.",
      "Jabir participated in the Prophet's ﷺ campaigns after Uhud. He witnessed 19 campaigns according to what he himself narrated. He was brave, astute, patient. Neither poverty, debt, nor the loss of his father turned him from jihad.",
      "A remarkable story occurred with him at the campaign of Dhat al-Riqa'. Jabir was on the road with the Prophet ﷺ. Jabir's camel was weak, falling behind the army. The Prophet ﷺ passed him and said: 'What is wrong with you, Jabir?' He said: 'My camel has tired.' The Prophet ﷺ took his staff and struck the camel a light blow. The camel became among the fastest in the army. The Prophet ﷺ then bought the camel from him for an ounce, stipulating that he carry him to Madinah, which Jabir did.",
      "In Madinah, Jabir brought the camel. The Prophet ﷺ gave him its price, an ounce. Then he said: 'Take the camel too; it is for you.' The Prophet ﷺ took nothing from him. It was from the Prophet's ﷺ generosity. Jabir narrated this story himself in Sahih al-Bukhari.",
      "Jabir had married a non-virgin — i.e. a divorcée or widow. The Prophet ﷺ asked him: 'What is wrong with you that you marry a non-virgin? Would you not marry a virgin to play with you and you with her?' Jabir said: 'O Messenger of Allah, I have young sisters, and I feared a young one like them would come and not raise them. I married a non-virgin to help me with my sisters' affairs.' The Prophet ﷺ said: 'You did well, Jabir.'",
      "Jabir was among the most prolific Companion narrators. He narrated from the Prophet ﷺ 1,540 hadiths. His hadiths were precise and reliable. Jurists mentioned that Jabir is the Companion who narrated most of what is needed in the jurisprudence of Hajj. He narrated all the details of the Farewell Pilgrimage in a long hadith famous as the 'hadith of Jabir on Hajj.'",
      "Jabir lived a long life. He lived after the Prophet ﷺ for many years. He witnessed the trial between Ali and Mu'awiyah but withdrew from it. He devoted himself to hadith and jurisprudence. He was the elder of the hadith scholars in Madinah in his old age.",
      "Jabir went blind at the end of his life. But he continued to narrate to people the hadiths of the Prophet ﷺ from his memory. Students of knowledge would come from afar to hear from him. Among them were those who became signs of the Successors — Abu al-Zubayr al-Makki, Amr ibn Dinar, and others.",
      "Jabir ibn Abdullah died in Madinah in 78 AH in Abd al-Malik ibn Marwan's caliphate. He was 94 years old. He was the last Companion to die in Madinah. Aban ibn Uthman, the governor of Madinah, prayed over him. He was buried in al-Baqi', next to the chiefs of the Companions.",
      "Jabir's lessons are great. First: kindness to a father continues after his death. Jabir paid his father's debt and cared for his sisters. This is kindness to the father after death. How many a son neglects his father's affairs after his death! Jabir did the opposite.",
      "Second: the supplication of the Prophet ﷺ brings blessing in provision. Jabir's garden was small; the Prophet ﷺ blessed it, and it became great. How many a person has little; if he asked Allah sincerely, his provision would be blessed. Provision is in Allah's hand.",
      "Third: most of the Companions who narrated much hadith were those who lived longest. Jabir lived 94 years. Abu Hurayrah lived long. Ibn Umar lived long. A'isha lived long. Allah kept them to preserve the Sunnah and transmit it to the Ummah.",
      "Jabir ibn Abdullah remains in the history of Islam the narrator of the Farewell Pilgrimage, dutiful to his martyred father, in whose garden the Prophet ﷺ blessed. O Allah, be pleased with Jabir, and gather us with him in the Gardens of Bliss.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 38. أنس بن مالك رضي الله عنه — خادم رسول الله
  // ──────────────────────────────────────────────────────────────────────
  'anas': {
    ar: P([
      'هو أنس بن مالك بن النضر بن ضمضم الأنصاري الخزرجي النجاري. وُلد بيثرب — المدينة — قبل الهجرة بعشر سنوات. كان من بني النجار، التي كانت أم النبي ﷺ آمنة بنت وهب من خئولتها. فهو أنصاري من قبيلة لها قرابة بالنبي ﷺ.',
      'أمه أم سُليم بنت ملحان — التي كان مهرها الإسلام (انظر قصتها). كانت أم سُليم من أوائل النساء الأنصاريات اللواتي أسلمن. أبوه مالك بن النضر كان مشركًا، فغضب لما أسلمت زوجته، وغادر إلى الشام. مات هناك. صارت أم سُليم أرملة بابن صغير اسمه أنس.',
      'لما هاجر النبي ﷺ إلى المدينة، جاءت أم سُليم بابنها أنس إلى النبي ﷺ. قالت: يا رسول الله، هذا أنس غلامك، يخدمك. ادعُ الله له. كان عمر أنس عشر سنين. قبل النبي ﷺ هديتها. صار أنس خادم رسول الله ﷺ من ذلك اليوم.',
      'بقي أنس في خدمة النبي ﷺ عشر سنين كاملة، من السنة الأولى للهجرة حتى وفاة النبي ﷺ سنة 11 هـ. عاش معه يخدمه في بيته وسفره وغزواته. كان قريبًا منه قربًا عجيبًا. رأى كل تفاصيل حياة النبي ﷺ الخاصة.',
      'كانت معاملة النبي ﷺ له معاملة لطيفة محبوبة. قال أنس بعد ذلك: خدمتُ رسول الله ﷺ عشر سنين، فما قال لي لشيء فعلتُه: لمَ فعلت؟ ولا لشيء لم أفعله: لمَ لم تفعل؟ ولا قال لي: أُف. هذا أعظم وصف لخلق النبي ﷺ مع غلام صغير. لم يعنّفه يومًا، ولم يقل له كلمة غير كريمة في عشر سنوات.',
      'دعا له النبي ﷺ بدعاء عجيب. روى البخاري ومسلم أن أم سُليم طلبت من النبي ﷺ أن يدعو لأنس. فقال النبي ﷺ: اللهم أكثر ماله وولده، وبارك له فيما أعطيته. هذا دعاء جامع لكل ما يطلبه الإنسان في الدنيا: مال كثير، ولد كثير، وبركة فيهما.',
      'استجاب الله الدعاء استجابة عجيبة. عاش أنس 103 سنين — أطول من معظم الصحابة. كان من أغنى الأنصار. روي أن دخله السنوي كان من أكبر دخول الأنصار في زمنه. ورأى من ولده وولد ولده أكثر من مئة — أي رأى أحفاد أحفاده.',
      'قال أنس بنفسه: يا بنيّ، إن رسول الله ﷺ دعا لي بثلاث، فقد رأيت اثنتين، وأرجو الثالثة. سُئل: وما الثالثة؟ قال: الجنة. كان واثقًا أن الدعاء الذي استجاب في الدنيا، سيستجاب في الآخرة أيضًا.',
      'شارك أنس في غزوات النبي ﷺ صغيرًا. كان في سن لا تسمح بالقتال، لكنه كان يحمل السلاح ويسقي العطشى. شهد بدرًا وأحدًا والخندق وفتح مكة وحنينًا والطائف. كل غزوة شهدها وفيها أيام يتذكر تفاصيلها.',
      'بعد وفاة النبي ﷺ، شارك أنس في فتوحات الإسلام. ذهب إلى البصرة في خلافة عمر، وشارك في فتحها. ثم استقر في البصرة — حيث صار من أعلامها. علّم الناس فيها القرآن والحديث.',
      'روى أنس عن النبي ﷺ 2286 حديثًا. هو ثاني أكثر الصحابة رواية بعد أبي هريرة. أحاديثه دقيقة لأنه عاش مع النبي ﷺ 10 سنوات — رأى تفاصيل لم يرها غيره. روى في كل أبواب الفقه والعبادة والمعاملات والأخلاق.',
      'اعتزل أنس الفتنة بين علي ومعاوية. كان في البصرة، وحاول أن يجمع بين الفريقين، لكنه فشل. لم يشارك في معركة الجمل ولا صفين. تفرّغ للتعليم. كان شيخ المحدثين في البصرة، يجلس له طلاب العلم من كل مكان.',
      'كان أنس يحب أن يتذكر النبي ﷺ. كان إذا حدّث عنه، يبكي. روي أنه إذا حضرت الصلاة، تذكر صلاة النبي ﷺ. وإذا جلس على الطعام، تذكر كيف كان النبي ﷺ يأكل. وإذا توضأ، تذكر كيف كان النبي ﷺ يتوضأ. كان يعيش مع النبي ﷺ حتى بعد موته.',
      'توفي أنس بن مالك بالبصرة سنة 93 هـ في عهد الوليد بن عبد الملك. كان عمره 103 سنين — على أرجح الأقوال. كان آخر صحابي يتوفى بالبصرة. حضر جنازته جمع غفير. كان موته نهاية عصر — لم يبقَ بعده في البصرة من صحب النبي ﷺ.',
      'دروس أنس عظيمة. الأول: أن خدمة العلماء والصالحين شرف عظيم. أنس كان خادمًا للنبي ﷺ. هذه الخدمة جعلت منه ثاني أكثر الصحابة رواية. كم من إنسان يستحقر العمل في خدمة عالم! والحقيقة أن من خدم عالمًا، نال نصيبًا من علمه.',
      'الثاني: أن الدعاء أعظم سبب للبركة. النبي ﷺ دعا لأنس بثلاث، فاستجاب الله. كل من يستطيع أن يطلب دعاء من صالح، فليطلب. وكل والدة تستطيع أن تطلب لأطفالها الدعاء من العلماء، فلتطلب.',
      'الثالث: أن الذاكرة الحية أعظم ميراث. أنس لم يكن يتفاخر بكثرة ماله أو ولده، إنما كان يحدث الناس بسيرة النبي ﷺ. هذا أعظم ميراث — أن تنقل سيرة من تحب إلى من يأتي بعدك.',
      'يبقى أنس بن مالك في تاريخ الإسلام خادم رسول الله ﷺ عشر سنين، ثاني أكثر الصحابة رواية للحديث، من دعا له النبي بطول العمر وكثرة المال والولد. اللهم ارضَ عن أنس، واجمعنا به في جنات النعيم.',
    ]),
    en: P([
      "He is Anas ibn Malik ibn al-Nadr ibn Damdam al-Ansari al-Khazraji al-Najjari. He was born in Yathrib — Madinah — ten years before the Hijrah. He was of Banu al-Najjar, of which the Prophet's ﷺ mother Aminah bint Wahb was on the maternal side. He was an Ansari from a tribe with kinship to the Prophet ﷺ.",
      "His mother was Umm Sulaym bint Milhan — whose dowry was Islam (see her story). Umm Sulaym was among the first Ansari women to embrace Islam. His father Malik ibn al-Nadr was a polytheist; he became angry when his wife embraced Islam and left for Sham. He died there. Umm Sulaym became a widow with a small son named Anas.",
      "When the Prophet ﷺ emigrated to Madinah, Umm Sulaym brought her son Anas to the Prophet ﷺ. She said: 'O Messenger of Allah, this is Anas, your servant boy, to serve you. Supplicate to Allah for him.' Anas was ten years old. The Prophet ﷺ accepted her gift. Anas became the servant of the Messenger of Allah ﷺ from that day.",
      "Anas remained in the Prophet's ﷺ service for ten full years, from the first year of the Hijrah until the Prophet's ﷺ death in 11 AH. He lived with him serving him in his house, travel, and campaigns. He was remarkably close to him. He saw all the details of the Prophet's ﷺ private life.",
      "The Prophet's ﷺ treatment of him was kind and loving. Anas said afterward: 'I served the Messenger of Allah ﷺ for ten years; he never said to me about something I did: Why did you do it? Nor about something I did not do: Why did you not do it? Nor did he ever say to me: Uff.' This is the greatest description of the Prophet's ﷺ character with a young servant boy. He never scolded him a day and did not say to him an unkind word in ten years.",
      "The Prophet ﷺ supplicated for him with a remarkable supplication. Bukhari and Muslim narrated that Umm Sulaym asked the Prophet ﷺ to supplicate for Anas. The Prophet ﷺ said: 'O Allah, increase his wealth and children, and bless him in what You have given him.' This is a comprehensive supplication for everything a person seeks in this world: abundant wealth, abundant children, and blessing in them.",
      "Allah answered the supplication remarkably. Anas lived 103 years — longer than most of the Companions. He was among the wealthiest of the Ansar. It is narrated that his annual income was among the greatest Ansari incomes in his time. He saw of his children and grandchildren more than a hundred — he saw the grandchildren of his grandchildren.",
      "Anas himself said: 'O my son, the Messenger of Allah ﷺ supplicated for me with three things; I have seen two and hope for the third.' He was asked: 'What is the third?' He said: 'Paradise.' He was confident that the supplication answered in this world would be answered in the next as well.",
      "Anas participated in the Prophet's ﷺ campaigns as a young boy. He was at an age not allowing combat, but he would carry weapons and water the thirsty. He witnessed Badr, Uhud, the Trench, the Conquest of Makkah, Hunayn, and Ta'if. Every campaign he witnessed had days he remembered in detail.",
      "After the Prophet's ﷺ death, Anas participated in the conquests of Islam. He went to Basra in Umar's caliphate and participated in its conquest. He then settled in Basra — where he became one of its signs. He taught its people the Qur'an and hadith.",
      "Anas narrated from the Prophet ﷺ 2,286 hadiths. He is the second-most prolific Companion after Abu Hurayrah. His hadiths are precise because he lived with the Prophet ﷺ 10 years — he saw details others did not see. He narrated in every chapter of jurisprudence, worship, dealings, and ethics.",
      "Anas withdrew from the trial between Ali and Mu'awiyah. He was in Basra and tried to reconcile between the two parties, but he failed. He did not participate in the Battle of the Camel or Siffin. He devoted himself to teaching. He was the elder of the hadith scholars in Basra; students of knowledge sat with him from everywhere.",
      "Anas loved to remember the Prophet ﷺ. When he narrated about him, he would weep. It is narrated that when prayer time came, he remembered the Prophet's ﷺ prayer. When he sat for food, he remembered how the Prophet ﷺ ate. When he performed ablution, he remembered how the Prophet ﷺ performed ablution. He lived with the Prophet ﷺ even after his death.",
      "Anas ibn Malik died in Basra in 93 AH during al-Walid ibn Abd al-Malik's reign. He was 103 years old — on the strongest opinion. He was the last Companion to die in Basra. A large gathering attended his funeral. His death was the end of an era — no one remained in Basra after him who had accompanied the Prophet ﷺ.",
      "Anas's lessons are great. First: serving scholars and the righteous is a great honour. Anas was the Prophet's ﷺ servant. This service made him the second-most prolific narrator. How many a person belittles the work of serving a scholar! In truth, whoever serves a scholar gains a share of his knowledge.",
      "Second: supplication is the greatest cause of blessing. The Prophet ﷺ supplicated for Anas with three things, and Allah answered. Whoever can request a supplication from a righteous one should request it. Every mother who can request supplications for her children from scholars should request.",
      "Third: living memory is the greatest inheritance. Anas did not boast of his much wealth or children, but he would narrate to people the life of the Prophet ﷺ. This is the greatest inheritance — that you transmit the life of one you love to those who come after you.",
      "Anas ibn Malik remains in the history of Islam the servant of the Messenger of Allah ﷺ for ten years, the second-most prolific Companion narrator of hadith, the one for whom the Prophet supplicated for long life, abundant wealth, and children. O Allah, be pleased with Anas, and gather us with him in the Gardens of Bliss.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 39. أبو هريرة رضي الله عنه — أكثر الصحابة رواية للحديث
  // ──────────────────────────────────────────────────────────────────────
  'abu-hurayra': {
    ar: P([
      'هو عبد الرحمن بن صخر الدوسي من قبيلة دوس باليمن. اسمه قبل الإسلام عبد شمس، فسماه النبي ﷺ عبد الرحمن. لقّبوه أبا هريرة لأنه كان يحمل دائمًا هرة صغيرة. وُلد بأرض دوس باليمن قبل البعثة بنحو 19 سنة. كان فقيرًا يتيمًا، يخدم الناس مقابل طعامه فقط.',
      'سمع عن النبي ﷺ في اليمن. كان رئيس قبيلة دوس الطفيل بن عمرو الدوسي قد جاء إلى مكة، والتقى بالنبي ﷺ، وأسلم. رجع الطفيل إلى دوس يدعو قومه إلى الإسلام. أسلم على يديه كثير من بني دوس، منهم أبو هريرة.',
      'هاجر أبو هريرة إلى المدينة سنة 7 هـ، أي بعد فتح خيبر. كان متأخرًا في الهجرة عن كثير من الصحابة. لم يلحق بالنبي ﷺ إلا في آخر 3 سنوات من حياته ﷺ. لكنه عوّض هذا التأخر بحرص شديد على ملازمة النبي ﷺ.',
      'لما جاء إلى المدينة، اختار أن يكون من أهل الصُّفّة. الصُّفّة كانت ظلة في طرف المسجد النبوي، يسكن فيها الفقراء من المسلمين الذين ليس لهم أهل ولا مأوى. كانوا يأكلون مما يأتيهم من الصدقة. أبو هريرة آثر الفقر مع ملازمة العلم على الغنى مع البعد عنه.',
      'كان أبو هريرة أحرص الصحابة على العلم. ترك التجارة والكسب وآثر صحبة النبي ﷺ. كان يلازم النبي ﷺ في كل أوقاته — في الصلاة، في الأكل، في الجلوس، في الحديث. كل دقيقة يقضيها مع النبي ﷺ يحفظ شيئًا جديدًا.',
      'كان أبو هريرة يعاني من النسيان. شكا إلى النبي ﷺ مرة: يا رسول الله، إنّي أسمع منك حديثًا كثيرًا أنساه. قال النبي ﷺ: ابسط رداءك. فبسطه. حدّث النبي ﷺ ثم قال: ضمّه. فضمّه أبو هريرة إلى صدره. قال أبو هريرة: فما نسيتُ شيئًا بعده. كانت معجزة نبوية — دعاء النبي ﷺ غيّر طبيعة الذاكرة.',
      'بسبب هذه المعجزة، صار أبو هريرة أكثر الصحابة رواية للحديث. روى 5374 حديثًا — أكثر من أي صحابي آخر، مع أنه لازم النبي ﷺ 3 سنوات فقط. هذا يدل على بركة الدعاء النبوي. الصحابة الذين لازموا النبي ﷺ 10 و 20 سنة كانوا أقل رواية منه.',
      'كانت ملازمته للنبي ﷺ تفوق التصور. روى أبو هريرة: كان رسول الله ﷺ ينام في بيت أزواجه، فأبيتُ أنا في الصُّفّة. ولا تأتيني الصلاة إلا وأكون قائمًا. أكون أقرب الناس إلى النبي ﷺ في صلواته. كان لا يفوته شيء من سلوك النبي ﷺ.',
      'بعد وفاة النبي ﷺ، تفرّغ أبو هريرة لتعليم الحديث. صار شيخ المحدّثين في المدينة. كان طلاب العلم يأتون إليه من كل البلاد. تخرّج على يديه كثير من علماء التابعين — منهم سعيد بن المسيب، عطاء بن أبي رباح، عروة بن الزبير، وغيرهم.',
      'تولى أبو هريرة إمارة المدينة فترة في خلافة مروان بن الحكم. كان واليًا عادلًا، لا يأخذ من بيت المال إلا ما يكفيه ضرورة. ثم استعفى من الإمارة وتفرّغ للحديث. كان يكره السياسة ويحب العلم.',
      'في الفتنة بين علي ومعاوية، اعتزل أبو هريرة. لم يشارك في الجمل ولا صفين. كان يقول: لن أقاتل المسلمين، ولن آكل لحومهم بالخوض في فتنتهم. سلامة دينه أهم عنده من أي موقف سياسي.',
      'كان زاهدًا متواضعًا. روي أنه دخل المدينة على حمار في أيامه الأخيرة، فقال الناس: هذا أبو هريرة! قال هو: أعرفكم برسول الله ﷺ. هذا أعظم وصف يفتخر به — معرفة النبي ﷺ. لم يفتخر بمال ولا منصب، إنما بقربه من النبي ﷺ.',
      'كان كثير الذكر. روى أنه كان يستغفر كل يوم 12000 مرة. كان يقول: استغفر بعدد ذنوبي. كان شديد المحاسبة لنفسه. وكان كثير الصيام. وفي رمضان يقوم الليل كله تقريبًا.',
      'توفي أبو هريرة في المدينة سنة 57 أو 58 هـ. كان عمره يومئذ 78 سنة. شهد جنازته كل أهل المدينة من الصحابة الباقين والتابعين. صلى عليه الوليد بن عتبة بن أبي سفيان والي المدينة. دُفن بالبقيع.',
      'تفاصيل وفاته مؤثرة. لما حضرته الوفاة، بكى. سُئل: ما يبكيك؟ قال: ما أبكي على دنياكم هذه، إنما أبكي على بُعد سفري، وقلّة زادي، وأنّي مصبح على صعود في مهبط إلى جنة أو نار، لا أدري أيهما يؤخذ بي. هذا خوف العبد الصالح من الحساب.',
      'دروس أبو هريرة عظيمة. الأول: أن التأخر في الإسلام يعوضه الجد في الطلب. أبو هريرة أسلم متأخرًا، لكنه بحرصه صار أكثر الصحابة علمًا. كم من إنسان متقدم في الإيمان لكنه كسلان! والأهمية ليست بمن سبق، بل بمن جدّ في الطلب.',
      'الثاني: أن دعاء النبي ﷺ يفتح الأبواب المغلقة. أبو هريرة شكا النسيان، فعالجه النبي ﷺ بمعجزة. كم من مشكلة نشكوها اليوم! لو طلبنا الله بصدق، لفتح لنا أبواب الحلول.',
      'الثالث: أن العلم أعظم من المنصب. أبو هريرة كان يفضّل العلم على الإمارة. اعتزل المنصب وتفرّغ للحديث. خلّد ذكره العلم، لا المنصب. كم من والٍ نسيه التاريخ، وكم من عالم يبقى ذكره!',
      'يبقى أبو هريرة في تاريخ الإسلام أكثر الصحابة رواية للحديث، صاحب الذاكرة المعجزة، الفقير الذي اختار العلم على الغنى. اللهم ارضَ عن أبي هريرة، واجمعنا به في جنات النعيم.',
    ]),
    en: P([
      "He is Abd al-Rahman ibn Sakhr al-Dawsi of the tribe of Daws in Yemen. His name before Islam was Abd Shams; the Prophet ﷺ named him Abd al-Rahman. They nicknamed him Abu Hurayrah (Father of the Kitten) because he always carried a small kitten. He was born in the land of Daws in Yemen about 19 years before the mission. He was poor and orphaned, serving people for his food alone.",
      "He heard of the Prophet ﷺ in Yemen. The chief of the tribe of Daws, al-Tufayl ibn Amr al-Dawsi, had come to Makkah, met the Prophet ﷺ, and embraced Islam. al-Tufayl returned to Daws calling his people to Islam. Many of Banu Daws embraced Islam at his hand, among them Abu Hurayrah.",
      "Abu Hurayrah emigrated to Madinah in 7 AH, that is, after the conquest of Khaybar. He was late in emigration compared to many Companions. He did not catch up with the Prophet ﷺ except in the last 3 years of his life ﷺ. But he compensated for this delay with intense eagerness to accompany the Prophet ﷺ.",
      "When he came to Madinah, he chose to be among the People of al-Suffah. al-Suffah was a shaded area at the edge of the Prophet's Mosque, where poor Muslims with no family or shelter lived. They would eat from what came to them of charity. Abu Hurayrah preferred poverty with closeness to knowledge over wealth with distance from it.",
      "Abu Hurayrah was the most eager of the Companions for knowledge. He left trade and earning and preferred the companionship of the Prophet ﷺ. He would accompany the Prophet ﷺ at all his times — in prayer, eating, sitting, conversation. Every minute spent with the Prophet ﷺ he memorised something new.",
      "Abu Hurayrah suffered from forgetfulness. He complained to the Prophet ﷺ once: 'O Messenger of Allah, I hear much hadith from you and I forget it.' The Prophet ﷺ said: 'Spread out your cloak.' He spread it. The Prophet ﷺ spoke, then said: 'Wrap it.' Abu Hurayrah wrapped it to his chest. Abu Hurayrah said: 'I have not forgotten anything after it.' It was a prophetic miracle — the Prophet's ﷺ supplication changed the nature of memory.",
      "Because of this miracle, Abu Hurayrah became the most prolific Companion in narrating hadith. He narrated 5,374 hadiths — more than any other Companion, although he accompanied the Prophet ﷺ for only 3 years. This shows the blessing of the Prophetic supplication. Companions who accompanied the Prophet ﷺ for 10 and 20 years narrated less than him.",
      "His accompaniment of the Prophet ﷺ exceeded imagination. Abu Hurayrah narrated: 'The Messenger of Allah ﷺ would sleep in his wives' houses, and I would spend the night at al-Suffah. The prayer would not come except I was standing. I was the closest of people to the Prophet ﷺ in his prayers.' Nothing of the Prophet's ﷺ conduct escaped him.",
      "After the Prophet's ﷺ death, Abu Hurayrah devoted himself to teaching hadith. He became the elder of the hadith scholars in Madinah. Students of knowledge would come to him from every land. Many Successor scholars graduated at his hands — among them Sa'id ibn al-Musayyib, Ata ibn Abi Rabah, Urwah ibn al-Zubayr, and others.",
      "Abu Hurayrah took the governorship of Madinah for a period in Marwan ibn al-Hakam's caliphate. He was a just governor, taking from the public treasury only what sufficed him by necessity. He then asked to be relieved of governorship and devoted himself to hadith. He disliked politics and loved knowledge.",
      "In the trial between Ali and Mu'awiyah, Abu Hurayrah withdrew. He did not participate in the Camel or Siffin. He used to say: 'I will not fight Muslims, and I will not eat their flesh by delving into their trial.' The safety of his religion was more important to him than any political position.",
      "He was ascetic and humble. It is narrated that he entered Madinah on a donkey in his last days, and people said: 'This is Abu Hurayrah!' He said himself: 'The one of you most knowledgeable about the Messenger of Allah ﷺ.' This is the greatest description he boasted of — knowledge of the Prophet ﷺ. He did not boast of wealth or position, but of his closeness to the Prophet ﷺ.",
      "He was much given to remembrance. It is narrated that he would seek forgiveness 12,000 times every day. He used to say: 'I seek forgiveness for the number of my sins.' He was strict in self-accounting. He fasted much. In Ramadan he stood almost the entire night.",
      "Abu Hurayrah died in Madinah in 57 or 58 AH. He was 78 years old. All the people of Madinah attended his funeral, the remaining Companions and Successors. al-Walid ibn Utbah ibn Abi Sufyan, the governor of Madinah, prayed over him. He was buried in al-Baqi'.",
      "The details of his death are moving. When death approached him, he wept. He was asked: 'What makes you weep?' He said: 'I do not weep over this world of yours; rather, I weep over the distance of my journey, the scarcity of my provision, and that I am setting out on an ascent to a descent into Paradise or Fire — I do not know to which I shall be taken.' This is the fear of the righteous servant from the reckoning.",
      "Abu Hurayrah's lessons are great. First: delay in Islam is compensated by earnestness in seeking. Abu Hurayrah embraced Islam late, but through his eagerness he became the most knowledgeable Companion. How many a person is early in faith but lazy! Importance is not in who came first, but in who strives in the seeking.",
      "Second: the Prophet's ﷺ supplication opens closed doors. Abu Hurayrah complained of forgetfulness, and the Prophet ﷺ treated it with a miracle. How many a problem do we complain of today! If we asked Allah sincerely, He would open for us the doors of solutions.",
      "Third: knowledge is greater than position. Abu Hurayrah preferred knowledge over governorship. He withdrew from position and devoted himself to hadith. Knowledge immortalised his memory, not position. How many a governor history has forgotten, and how many a scholar whose memory remains!",
      "Abu Hurayrah remains in the history of Islam the most prolific Companion narrator of hadith, owner of the miraculous memory, the poor one who chose knowledge over wealth. O Allah, be pleased with Abu Hurayrah, and gather us with him in the Gardens of Bliss.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 40. عبد الله بن عمر رضي الله عنه
  // ──────────────────────────────────────────────────────────────────────
  'ibn-umar': {
    ar: P([
      'هو عبد الله بن عمر بن الخطاب القرشي العدوي. وُلد بمكة قبل البعثة بنحو ثلاث سنوات. أمه زينب بنت مظعون — أخت عثمان بن مظعون أحد كبار الصحابة. كان من أصغر أبناء عمر بن الخطاب من زوجاته. تربى في بيت أبيه عمر، فجمع بين فقه أبيه وملازمة النبي ﷺ.',
      'أسلم مع أبيه عمر صغيرًا في مكة. كان في الـ 6 من عمره تقريبًا حين أسلم عمر. هاجر مع أبيه إلى المدينة في الـ 10 من عمره. شهد بيعة الرضوان والحديبية وخيبر وفتح مكة وحنينًا والطائف وتبوك. عرض نفسه على النبي ﷺ يوم أحد وعمره 13 — فلم يأذن له النبي ﷺ لصغر سنه. ثم عرض نفسه في الخندق وعمره 15، فأذن له النبي ﷺ.',
      'كان من أحب الناس إلى أبيه عمر. تربى في بيت العدل والشدة في الحق. عاش طفولته يرى أعظم رجل في الإسلام بعد الأنبياء — أبوه عمر — يحكم العالم ويعدل بين الناس. هذه التربية صنعت منه شخصية فريدة.',
      'كان أعلم الصحابة باتباع السنة. قال ابن مسعود: أكثر الناس اتباعًا لسنة النبي ﷺ ابن عمر. كان دقيقًا في الاتباع — إذا رأى النبي ﷺ يفعل شيئًا في مكان، حاول أن يفعل مثله في نفس المكان. كان يصلي حيث صلى النبي، ويقف حيث وقف، ويناخ بعيره حيث ناخ النبي بعيره.',
      'حدثت معه قصة عجيبة في الحج. كان يطوف بالكعبة ويقبّل الحجر الأسود ويسجد عليه. سُئل: لمَ تفعل ذلك؟ قال: لأنّي رأيت رسول الله ﷺ يفعله. ثم أضاف: والله، لو لم أرَ رسول الله ﷺ يقبّله ما قبّلته. هذا فقه عظيم: لا يعبد الإنسان حجرًا أبدًا، إنما يفعل ما أمر به النبي ﷺ.',
      'روى ابن عمر عن النبي ﷺ 2630 حديثًا. هو ثالث أو رابع أكثر الصحابة رواية بعد أبي هريرة وأنس وعائشة. أحاديثه دقيقة لأنه عاش مع النبي ﷺ من طفولته إلى نهاية حياة النبي ﷺ. كل تفصيل سمعه أو رآه حفظه.',
      'كان زاهدًا في الدنيا. مع أنه ابن خليفة المسلمين، عاش حياة بسيطة. كان عمر يعطيه من بيت المال نصيبه، فيفرّقه ابن عمر في الفقراء قبل أن يغرب اليوم. لم يجمع له مالًا. كان يأكل ما يأكله الفقير. ما لبس ثوبًا فاخرًا. كان كأبيه في الزهد.',
      'في الفتنة بين علي ومعاوية، اعتزل ابن عمر. لم يبايع عليًا ولا معاوية. كان يقول: لا أقاتل المسلمين. اعتزل في المدينة وتفرّغ للعبادة والعلم. لم يشارك في الجمل ولا صفين ولا النهروان. كان من المشهورين بالاعتزال.',
      'ندم في آخر عمره على عدم مشاركته. قال: ما آسى على شيء في الدنيا كأسفي على أنّي لم أقاتل الفئة الباغية كما أمرني الله. كان يعني علي بن أبي طالب. لما رأى الفتنة طويلة، عرف أن الواجب كان مع علي. لكن الأمر كان قد فات.',
      'كان كثير الإحسان. روي أنه ما من ليلة إلا ويبكي من خشية الله. كان شديد الخوف من الله. روى عائشة أنه كان من أتقى الناس في زمنه. كان يصلي الليل بطوله، ويبكي حتى يبتل المصحف.',
      'كانت له مكانة عظيمة عند الصحابة. حين اقترح بعضهم أن يبايع ابن عمر للخلافة بعد مقتل عثمان، رفض ابن عمر تمامًا. قال: لا أتعرض لما لم يأمرني الله به. كان يكره أن يأخذ منصبًا، خوفًا من المحاسبة.',
      'كان كريمًا جدًا. روي أن كل ما يدخل عنده من مال يفرّقه فورًا. لم يكن يحفظ شيئًا لنفسه. مات وما خلّف إلا ثيابه التي عليه. وفي رواية ترك دراهم قليلة فقط.',
      'كان كثير الحج والعمرة. يقال إنه حج 60 حجة وعمرة. كان يحب البيت الحرام ويصلي عنده كثيرًا. وكان يكره أن تمر سنة دون أن يأتي مكة.',
      'توفي ابن عمر بمكة سنة 73 هـ، في عام مقتل ابن الزبير. كان عمره يومئذ 84 سنة. توفي بعد أن جرح في رمي قدمه برمح في زحام الناس بمكة — قيل عمدًا من بعض المتعصبين، وقيل خطأ. صلى عليه الحجاج بن يوسف الثقفي — الذي كان والي مكة لعبد الملك بن مروان. دُفن بمكة.',
      'دروس ابن عمر عظيمة. الأول: أن اتباع السنة دقيقًا أعظم العبادات. ابن عمر كان يحاول تقليد النبي ﷺ في كل شيء. هذا أعظم حب للنبي ﷺ — أن تتبعه في كل تفاصيل حياتك. كم من إنسان يحب النبي ﷺ بقلبه، لكنه لا يتبعه في عمل!',
      'الثاني: أن الاعتزال في الفتن ليس دائمًا الصواب. ابن عمر اعتزل، ثم ندم. كم من مرة يجب على المؤمن أن يقف مع الحق ولو كان ضد قرابته أو راحته! الاعتزال أحيانًا فشل في حمل المسؤولية.',
      'الثالث: أن البكاء من خشية الله علامة الإيمان. ابن عمر كان من البكائين. الخوف من الله ليس ضعفًا، إنما قوة. من خاف الله، خاف منه كل شيء.',
      'يبقى عبد الله بن عمر في تاريخ الإسلام أكثر الصحابة اتباعًا للسنة، البكاء من خشية الله، ابن الفاروق عمر. اللهم ارضَ عن ابن عمر، واجعلنا من المتبعين للسنة بدقة.',
    ]),
    en: P([
      "He is Abdullah ibn Umar ibn al-Khattab al-Qurashi al-Adawi. He was born in Makkah about three years before the mission. His mother was Zaynab bint Maz'un — sister of Uthman ibn Maz'un, one of the senior Companions. He was among the younger sons of Umar ibn al-Khattab from his wives. He was raised in his father Umar's house, combining his father's jurisprudence with companionship of the Prophet ﷺ.",
      "He embraced Islam with his father Umar as a child in Makkah. He was about 6 years old when Umar embraced Islam. He emigrated with his father to Madinah at 10 years old. He witnessed the Pledge of Ridwan, Hudaybiyyah, Khaybar, the Conquest of Makkah, Hunayn, Ta'if, and Tabuk. He presented himself to the Prophet ﷺ on the day of Uhud at 13 — the Prophet ﷺ did not permit him for his young age. He then presented himself at the Trench at 15, and the Prophet ﷺ permitted him.",
      "He was among the most beloved of people to his father Umar. He was raised in the house of justice and firmness in truth. He lived his childhood seeing the greatest man in Islam after the prophets — his father Umar — ruling the world and judging justly between people. This upbringing made of him a unique personality.",
      "He was the most knowledgeable Companion in following the Sunnah. Ibn Mas'ud said: 'The most of people in following the Sunnah of the Prophet ﷺ is Ibn Umar.' He was precise in following — if he saw the Prophet ﷺ do something in a place, he would try to do the same in the same place. He would pray where the Prophet prayed, stand where he stood, and kneel his camel where the Prophet's camel knelt.",
      "A remarkable story occurred with him at Hajj. He was circumambulating the Ka'bah and would kiss the Black Stone and prostrate on it. He was asked: 'Why do you do that?' He said: 'Because I saw the Messenger of Allah ﷺ do it.' Then he added: 'By Allah, had I not seen the Messenger of Allah ﷺ kiss it, I would not have kissed it.' This is great jurisprudence: a person never worships a stone but does what the Prophet ﷺ commanded.",
      "Ibn Umar narrated from the Prophet ﷺ 2,630 hadiths. He is the third or fourth most prolific Companion after Abu Hurayrah, Anas, and A'isha. His hadiths are precise because he lived with the Prophet ﷺ from his childhood to the end of the Prophet's ﷺ life. Every detail he heard or saw he memorised.",
      "He was ascetic in this world. Though he was the son of the caliph of the Muslims, he lived a simple life. Umar would give him his share from the public treasury, and Ibn Umar would distribute it to the poor before the day set. He did not amass wealth. He ate what the poor ate. He did not wear fine clothing. He was like his father in asceticism.",
      "In the trial between Ali and Mu'awiyah, Ibn Umar withdrew. He pledged allegiance to neither Ali nor Mu'awiyah. He used to say: 'I will not fight Muslims.' He withdrew in Madinah and devoted himself to worship and knowledge. He did not participate in the Camel, Siffin, or Nahrawan. He was famous for his withdrawal.",
      "He regretted in his old age his non-participation. He said: 'I regret nothing in this world as much as I regret not having fought the transgressing party as Allah commanded me.' He meant Ali ibn Abi Talib. When he saw the trial was long, he knew the duty was with Ali. But the matter had passed.",
      "He was much given to good. It is narrated that no night passed but he wept from fear of Allah. He was intensely fearful of Allah. A'isha narrated that he was among the most God-fearing of people in his time. He would pray the night through and weep until his Mushaf was wet.",
      "He had a great standing with the Companions. When some suggested pledging allegiance to Ibn Umar for the caliphate after Uthman's killing, Ibn Umar refused entirely. He said: 'I do not expose myself to what Allah has not commanded me.' He hated to take a position, fearing the reckoning.",
      "He was very generous. It is narrated that everything that entered his possession of wealth he distributed immediately. He did not keep anything for himself. He died and left nothing but the clothes upon him. In one narration he left only a few dirhams.",
      "He performed Hajj and Umrah much. It is said he performed 60 Hajj and Umrah. He loved the Sacred House and would pray there often. He hated for a year to pass without coming to Makkah.",
      "Ibn Umar died in Makkah in 73 AH, in the year of Ibn al-Zubayr's killing. He was 84 years old. He died after being wounded by a spear in his foot in the crowd of people at Makkah — said to be intentional from some fanatics, said to be by mistake. al-Hajjaj ibn Yusuf al-Thaqafi — who was the governor of Makkah for Abd al-Malik ibn Marwan — prayed over him. He was buried in Makkah.",
      "Ibn Umar's lessons are great. First: precise following of the Sunnah is the greatest of worship. Ibn Umar tried to imitate the Prophet ﷺ in everything. This is the greatest love for the Prophet ﷺ — that you follow him in every detail of your life. How many a person loves the Prophet ﷺ in his heart but does not follow him in deed!",
      "Second: withdrawal in trials is not always correct. Ibn Umar withdrew, then regretted. How many a time the believer must stand with truth though against his kin or his comfort! Withdrawal is sometimes failure to bear responsibility.",
      "Third: weeping from fear of Allah is a sign of faith. Ibn Umar was among the weeping ones. Fear of Allah is not weakness but strength. Whoever fears Allah, everything fears him.",
      "Abdullah ibn Umar remains in the history of Islam the most following Companion of the Sunnah, the one who wept from fear of Allah, son of al-Faruq Umar. O Allah, be pleased with Ibn Umar, and make us among those following the Sunnah precisely.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 41. عبد الله بن عباس رضي الله عنه — حبر الأمة
  // ──────────────────────────────────────────────────────────────────────
  'ibn-abbas': {
    ar: P([
      'هو عبد الله بن العباس بن عبد المطلب بن هاشم القرشي الهاشمي. ابن عم النبي ﷺ. وُلد بمكة قبل الهجرة بثلاث سنوات. أبوه العباس بن عبد المطلب من سادات قريش، أسلم متأخرًا قبل فتح مكة. أمه أم الفضل لبابة بنت الحارث، أخت ميمونة بنت الحارث أم المؤمنين.',
      'تربى ابن عباس في بيت النبوة. كانت أمه أم الفضل من أوائل النساء اللاتي أسلمن، فربّته على الإيمان منذ صغره. كان النبي ﷺ يحبه حبًا شديدًا، لأنه ابن عمه وقريبه. كان النبي ﷺ يداعبه ويأخذه إلى جواره. مات النبي ﷺ وعبد الله ابن 13 سنة.',
      'كانت قصة دعاء النبي ﷺ له من أعظم البركات. ضمّه النبي ﷺ إلى صدره وقال: اللهم فقّهه في الدين، وعلّمه التأويل. هذا الدعاء الجامع شمل أمرين عظيمين: الفقه — العلم بأحكام الله، والتأويل — تفسير القرآن وفهم معانيه. كل ما حصل لابن عباس بعد ذلك من علم كان بهذا الدعاء.',
      'استجاب الله الدعاء استجابة عجيبة. صار ابن عباس من أعلم الناس بالقرآن وتفسيره، حتى لقّبوه بـ ترجمان القرآن و حبر الأمة. كان عمر بن الخطاب يستشيره مع أنه كان صغيرًا. كان عمر يقول: نعم ترجمان القرآن ابن عباس.',
      'كان مجلسه في المسجد النبوي حلقة علم كاملة. يجلس له طلاب العلم من كل البلاد. وكان مجلسه مقسمًا حسب أنواع العلم: مجلس للفقه، مجلس للحديث، مجلس للتفسير، مجلس للأدب، مجلس للأنساب. كل علم له مجلس منفصل. كان فريدًا في كل هذه العلوم.',
      'كانت طريقته في طلب العلم عجيبة. قال هو نفسه: علمتُ أن العلم لا يجمعه إلا الجد والتقصد، فكنت إذا بلغني عن صحابي حديث، أتيت بيته. فإن وجدته نائمًا، توسدت ردائي على بابه، فيهبّ التراب على وجهي، حتى يخرج فيراني، فيقول: يا ابن عم رسول الله ﷺ، ما جاء بك؟ ألا أرسلت إليّ فآتيك؟ فأقول: لا، أنا أحق أن آتيك، فأسأله عن الحديث. هذا حرص خارق على العلم.',
      'روى ابن عباس عن النبي ﷺ 1660 حديثًا. مع صغر عمره عند وفاة النبي ﷺ، روى أكثر من كثير من الصحابة الكبار. سبب ذلك: روايته عن غيره من الصحابة ما لم يسمعه مباشرة من النبي ﷺ. كان يأخذ من كل صحابي ما عنده من علم.',
      'كان فقيهًا عظيمًا. أفتى في مسائل كثيرة، بعض فتاواه صارت مذاهب فقهية. مذهبه في زواج المتعة كان مخالفًا لجمهور الصحابة، وقد رجع عنه في آخر عمره. لكن بقي له فتاوى كثيرة معتمدة في الفقه الإسلامي.',
      'كانت له معرفة باللغة العربية والشعر. كان طلاب العلم يسألونه عن معنى كلمة في القرآن، فيرد بشاهد من شعر العرب. حفظ شعر العرب القدماء حفظًا عظيمًا. قال: إذا سألتم عن غريب القرآن فالتمسوه في الشعر، فإن الشعر ديوان العرب.',
      'في خلافة علي بن أبي طالب، ولاه علي على البصرة. كان واليًا عادلًا. شارك في معركة صفين مع علي. في النهروان، نصح علي بالمصالحة مع الخوارج، فلم يأخذ علي بنصيحته. ثم انفصل عن علي قبل قتله بفترة قصيرة، واستقر في مكة.',
      'في خلافة معاوية وما بعدها، اعتزل السياسة كاملًا. تفرّغ للعلم والإفتاء. صار مرجعًا للعلماء في كل بلاد الإسلام. كل مسألة لم يجد لها العلماء حلًا، يرسلون إليه. كان يجيب بفصاحة وحكمة.',
      'تخرّج على يديه كثير من علماء التابعين. منهم: مجاهد بن جبر، عكرمة مولاه، عطاء بن أبي رباح، طاووس بن كيسان، سعيد بن جبير. كل هؤلاء صاروا أعلامًا في تفسير القرآن، تعلموا من ابن عباس.',
      'في آخر حياته، عمي ابن عباس. لكنه ظل يحدّث الناس ويفتي. قال لمن جلس معه: تأخر فهم بصري، ولم يتأخر فهم قلبي. كان البصر العقلي عنده أهم من البصر العيني. ظل يفتي حتى آخر يوم.',
      'كان كثير العبادة. روي أنه صلى صلاة قام فيها الليل كله، فبكى حتى وافق دموعه على لحيته خط. كان يستغفر كثيرًا. قال: ما من شيء أنا أبكي عليه أكثر من ذنب أعلمه فأذكره.',
      'توفي ابن عباس بالطائف سنة 68 هـ. كان عمره يومئذ 71 سنة. صلى عليه محمد بن الحنفية ابن علي بن أبي طالب. دُفن بالطائف، وقبره معروف بها إلى اليوم، يُزار من المسلمين.',
      'تفاصيل وفاته مؤثرة. لما حضرته الوفاة، قال: اللهم إنّي أعوذ بك من الذنب الذي قلّ شأنه عنده وعظم في قدرك. كان شديد الخوف من الذنوب الصغيرة، لأنه يعرف أن الله يحاسب على الذرة من العمل.',
      'دروس ابن عباس عظيمة. الأول: أن دعاء النبي ﷺ يفتح أبواب العلم. ابن عباس دعا له النبي ﷺ، فصار حبر الأمة. كم من والد ووالدة يدعون لأطفالهم! الدعاء الصادق سلاح المؤمن.',
      'الثاني: أن العلم يحتاج إلى تواضع. ابن عباس ابن عم النبي ﷺ، ابن العباس سيد قريش، ومع ذلك كان يأتي بيوت الصحابة طالبًا للعلم. لو كان متكبرًا لما تعلم. التواضع شرط للعلم.',
      'الثالث: أن العين قد تعمى لكن القلب لا يعمى. ابن عباس عمي بصره، لكن بصيرته بقيت. كم من إنسان مبصر لا يرى الحق! والإيمان قد يستبدل العين بنور أعظم.',
      'يبقى عبد الله بن عباس في تاريخ الإسلام ترجمان القرآن، حبر الأمة، الذي دعا له النبي ﷺ بالعلم والفهم. اللهم ارضَ عن ابن عباس، وارزقنا العلم النافع والفهم الصحيح.',
    ]),
    en: P([
      "He is Abdullah ibn al-Abbas ibn Abd al-Muttalib ibn Hashim al-Qurashi al-Hashimi. The cousin of the Prophet ﷺ. He was born in Makkah three years before the Hijrah. His father al-Abbas ibn Abd al-Muttalib was among the chiefs of Quraysh and embraced Islam late before the conquest of Makkah. His mother Umm al-Fadl Lubabah bint al-Harith was the sister of Maymunah bint al-Harith, Mother of the Believers.",
      "Ibn Abbas was raised in the house of prophethood. His mother Umm al-Fadl was among the first women to embrace Islam, raising him on faith from his childhood. The Prophet ﷺ loved him deeply because he was his cousin and relative. The Prophet ﷺ would play with him and take him to his side. The Prophet ﷺ died when Abdullah was 13.",
      "The story of the Prophet's ﷺ supplication for him was among the greatest blessings. The Prophet ﷺ embraced him to his chest and said: 'O Allah, grant him understanding in religion and teach him interpretation.' This comprehensive supplication contained two great matters: jurisprudence — knowledge of Allah's rulings, and interpretation — tafsir of the Qur'an and understanding its meanings. Everything Ibn Abbas attained of knowledge afterwards was by this supplication.",
      "Allah answered the supplication remarkably. Ibn Abbas became the most knowledgeable of people in the Qur'an and its tafsir, until they nicknamed him 'Translator of the Qur'an' and 'Scholar of the Ummah.' Umar ibn al-Khattab would consult him though he was young. Umar would say: 'The best Translator of the Qur'an is Ibn Abbas.'",
      "His circle in the Prophet's Mosque was a complete circle of knowledge. Students of knowledge from every land sat with him. His circle was divided according to types of knowledge: a circle for jurisprudence, a circle for hadith, a circle for tafsir, a circle for literature, a circle for genealogy. Each science had a separate circle. He was unique in all these sciences.",
      "His way of seeking knowledge was remarkable. He himself said: 'I knew that knowledge could not be gathered except through earnestness and determination. If I heard a hadith about a Companion, I would come to his house. If I found him sleeping, I would lay my cloak as a pillow at his door, and dust would blow on my face until he came out, saw me, and said: O cousin of the Messenger of Allah ﷺ, what brings you? Why did you not send for me, and I would come to you? I would say: No, I am more deserving to come to you, and I would ask him about the hadith.' This is extraordinary eagerness for knowledge.",
      "Ibn Abbas narrated from the Prophet ﷺ 1,660 hadiths. Despite his young age at the Prophet's ﷺ death, he narrated more than many senior Companions. The reason: his narration from other Companions of what he had not heard directly from the Prophet ﷺ. He would take from every Companion what he had of knowledge.",
      "He was a great jurist. He gave fatwas on many issues; some of his fatwas became schools of jurisprudence. His school on Mut'ah marriage was contrary to the majority of the Companions, and he retracted it at the end of his life. But many of his fatwas remained reliable in Islamic jurisprudence.",
      "He had knowledge of the Arabic language and poetry. Students of knowledge would ask him about the meaning of a word in the Qur'an, and he would respond with a witness from Arab poetry. He memorised the poetry of the ancient Arabs greatly. He said: 'If you ask about an obscure word of the Qur'an, seek it in poetry, for poetry is the diwan of the Arabs.'",
      "In Ali ibn Abi Talib's caliphate, Ali appointed him over Basra. He was a just governor. He participated in the Battle of Siffin with Ali. At Nahrawan, he advised Ali to reconcile with the Khawarij, but Ali did not take his advice. He then separated from Ali a short while before his killing and settled in Makkah.",
      "In Mu'awiyah's caliphate and after, he withdrew from politics completely. He devoted himself to knowledge and giving fatwa. He became a reference for scholars in every Muslim land. Every issue scholars could not find a solution for, they would send to him. He would answer with eloquence and wisdom.",
      "Many Successor scholars graduated at his hands. Among them: Mujahid ibn Jabr, Ikrimah his freed slave, Ata ibn Abi Rabah, Tawus ibn Kaysan, Sa'id ibn Jubayr. All these became signs in tafsir of the Qur'an, learning from Ibn Abbas.",
      "At the end of his life, Ibn Abbas went blind. But he continued to narrate to people and give fatwas. He said to whoever sat with him: 'The understanding of my sight has been delayed, but the understanding of my heart has not been delayed.' Intellectual sight was more important to him than physical sight. He continued giving fatwas until his last day.",
      "He was much given to worship. It is narrated that he prayed a prayer in which he stood the entire night, weeping until tears made a line on his beard. He sought forgiveness much. He said: 'There is nothing I weep over more than a sin I know and remember.'",
      "Ibn Abbas died in Ta'if in 68 AH. He was 71 years old. Muhammad ibn al-Hanafiyyah, son of Ali ibn Abi Talib, prayed over him. He was buried in Ta'if, and his grave is known there to this day, visited by Muslims.",
      "The details of his death are moving. When death approached him, he said: 'O Allah, I seek refuge in You from the sin whose matter is small in my eyes but great in Your measure.' He was intensely fearful of small sins, because he knew Allah holds to account over an atom of deed.",
      "Ibn Abbas's lessons are great. First: the Prophet's ﷺ supplication opens the doors of knowledge. Ibn Abbas was supplicated for by the Prophet ﷺ, and he became the Scholar of the Ummah. How many a father and mother supplicate for their children! Sincere supplication is the believer's weapon.",
      "Second: knowledge needs humility. Ibn Abbas was the Prophet's ﷺ cousin, son of al-Abbas chief of Quraysh, yet he would come to the houses of the Companions seeking knowledge. Had he been arrogant, he would not have learned. Humility is a condition of knowledge.",
      "Third: the eye may go blind but the heart does not. Ibn Abbas's sight went blind, but his insight remained. How many a sighted person does not see truth! Faith may replace the eye with a greater light.",
      "Abdullah ibn Abbas remains in the history of Islam the Translator of the Qur'an, Scholar of the Ummah, the one for whom the Prophet ﷺ supplicated for knowledge and understanding. O Allah, be pleased with Ibn Abbas, and grant us beneficial knowledge and correct understanding.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 42. جعفر بن أبي طالب رضي الله عنه — ذو الجناحين
  // ──────────────────────────────────────────────────────────────────────
  'jaafar': {
    ar: P([
      'هو جعفر بن أبي طالب بن عبد المطلب بن هاشم القرشي الهاشمي. ابن عم النبي ﷺ. وُلد بمكة قبل البعثة بنحو 30 سنة. كان أخا علي بن أبي طالب الأكبر بعشر سنين. أمه فاطمة بنت أسد بن هاشم — التي ربّت النبي ﷺ في صغره مع زوجها أبي طالب.',
      'كان جعفر من أشبه الناس بالنبي ﷺ خَلقًا وخُلُقًا. كان قوي البنية، كريم الوجه، حسن الأخلاق. أحبه النبي ﷺ حبًا شديدًا. كان النبي ﷺ يقول له: أنت أشبه الناس بي خَلقًا وخُلُقًا. هذه شهادة عظيمة — أن يكون رجل أشبه الناس بالنبي ﷺ.',
      'أسلم جعفر مبكرًا في الإسلام، من السابقين الأولين. كان من أوائل من أعلن إسلامه في مكة. حضر مع زوجته أسماء بنت عميس الصلاة في دار الأرقم. شاهد بأم عينه بدايات الدين الذي سيغيّر العالم.',
      'لما اشتد الأذى على المسلمين في مكة، أمر النبي ﷺ المسلمين بالهجرة الأولى إلى الحبشة. هاجر جعفر مع زوجته أسماء وجماعة من المسلمين. صار جعفر في الحبشة رئيس المسلمين هناك — لأنه كان من أفضلهم وأفصحهم.',
      'لما علمت قريش بحال المسلمين عند النجاشي ملك الحبشة، أرسلت سفيرين عظيمين: عمرو بن العاص وعبد الله بن أبي ربيعة. حملا الهدايا للنجاشي ولبطارقته. قابلا الملك وقالا: أيها الملك، إنه قد ضوى إلى بلدك منا غلمان سفهاء، فارقوا دين قومهم ولم يدخلوا في دينك، وجاؤوا بدين مبتدع لا نعرفه نحن ولا أنت، وقد بعثنا إليك فيهم أشراف قومهم لتردهم إليهم.',
      'استدعى النجاشي المسلمين ليسأل عنهم. اختار جعفر بن أبي طالب أن يتكلم نيابة عن الجماعة. وقف أمام النجاشي وبطارقته. قال كلامه العظيم الذي خلّده التاريخ: أيها الملك، كنا قومًا أهل جاهلية، نعبد الأصنام، ونأكل الميتة، ونأتي الفواحش، ونقطع الأرحام، ونسيء الجوار، يأكل القوي منا الضعيف. فكنا على ذلك حتى بعث الله إلينا رسولًا منا، نعرف نسبه وصدقه وأمانته وعفافه.',
      'تابع جعفر: فدعانا إلى الله لنوحّده ونعبده، ونخلع ما كنا نعبد نحن وآباؤنا من دونه من الحجارة والأوثان. وأمرنا بصدق الحديث، وأداء الأمانة، وصلة الرحم، وحسن الجوار، والكف عن المحارم والدماء. ونهانا عن الفواحش، وقول الزور، وأكل مال اليتيم، وقذف المحصنة. وأمرنا أن نعبد الله وحده ولا نشرك به شيئًا، وأمرنا بالصلاة والزكاة والصيام. فصدقناه، وآمنا به، واتبعناه على ما جاء به من الله.',
      'تأثر النجاشي تأثرًا شديدًا. سأل جعفر: هل عندك شيء مما جاء به عن الله؟ قال جعفر: نعم. قرأ على النجاشي أول سورة مريم — في قصة عيسى وأمه. لما سمع النجاشي القرآن، بكى بكاءً شديدًا حتى ابتلت لحيته. وبكى بطارقته. ثم قال: إن هذا والذي جاء به موسى ليخرج من مشكاة واحدة. اذهبوا فأنتم آمنون في بلدي.',
      'لكن عمرو بن العاص لم ييأس. عاد من الغد وقال للنجاشي: إنهم يقولون عن عيسى ابن مريم قولًا عظيمًا. استدعى النجاشي جعفرًا مرة ثانية وسأله. وقف جعفر بإيمان وثبات وقال: نقول فيه ما قال الله ورسوله، هو عبد الله ورسوله، ابن مريم العذراء البتول، التي حصنت فرجها فنفخ فيها من روحه.',
      'ضرب النجاشي بيده على الأرض، وقال: ما عدا عيسى ما قلتَ هذا العود — أي أن قولكم في عيسى ليس فيه زيادة على ما هو الحق. ثم رد للسفيرين هداياهما وقال للمسلمين: اذهبوا فأنتم في بلدي آمنون. هذه الكلمة العجيبة من جعفر حمت المسلمين في الحبشة كل تلك السنين.',
      'بقي جعفر في الحبشة 13 سنة. تزوج هناك أسماء بنت عميس، وأنجبا عبد الله بن جعفر ومحمدًا وعونًا. كانت حياتهم في الحبشة آمنة هادئة، يمارسون دينهم بحرية.',
      'في السنة السابعة من الهجرة، أرسل النبي ﷺ إلى النجاشي يطلب رجوع المسلمين. عادوا إلى المدينة. كانت العودة في وقت غزوة خيبر. لما رأى النبي ﷺ جعفر، فرح فرحًا شديدًا. وقفه وقبّل جبينه. قال: ما أدري بأيهما أنا أسرّ، بفتح خيبر أم بقدوم جعفر! كلمة عظيمة — يساوي قدوم جعفر بفتح خيبر.',
      'في السنة الثامنة من الهجرة، جهّز النبي ﷺ جيشًا لغزو الروم في مؤتة. أمّر النبي ﷺ ثلاثة قادة بالتتابع: زيد بن حارثة، فإن قُتل فجعفر بن أبي طالب، فإن قُتل فعبد الله بن رواحة. كان جيش المسلمين ثلاثة آلاف، وجيش الروم 200 ألف.',
      'وقعت معركة مؤتة. قُتل زيد بن حارثة أولًا. أخذ جعفر الراية وقاتل ببسالة. كان يقاتل وهو على فرسه. لما اشتد القتال، نزل عن فرسه — لأنه كان لا يستطيع المناورة عليها — وقاتل راجلًا. ضُربت يده اليمنى فقطعت. أخذ الراية بيده اليسرى. ضُربت اليسرى فقطعت. احتضن الراية بساعديه. ثم ضُرب بضربة فاستشهد.',
      'وُجد في جسده 93 جرحًا — كلها في صدره وأمامه. لم يجدوا في ظهره جرحًا واحدًا — دليل أنه لم يولّ ظهره أبدًا. قال النبي ﷺ لما علم باستشهاده: إن الله أبدل جعفرًا جناحين يطير بهما في الجنة حيث شاء. لُقّب من ذلك اليوم: ذو الجناحين.',
      'دروس جعفر عظيمة. الأول: أن الفصاحة وحسن الكلام نعمة عظيمة. جعفر بكلامه أمام النجاشي حمى المسلمين في الحبشة. كلمات قليلة فيها صدق وبيان غيّرت مصير جماعة بأكملها. كل مؤمن يحتاج أن يحسن الكلام عن دينه.',
      'الثاني: أن الشجاعة في الحرب أعلى المراتب. جعفر قاتل حتى قطعت يداه، ولم يدع الراية. هذا ثبات عجيب. كم من إنسان اليوم يستسلم لأقل من ذلك! الشجاعة الحقيقية ثبات تحت أصعب الظروف.',
      'الثالث: أن الله يكافئ الشهيد أعظم مكافأة. جعفر فقد يديه في الدنيا، فأعطاه الله جناحين في الجنة. كل تضحية لله تعوض بأعظم منها. لا يضيع عند الله شيء.',
      'يبقى جعفر بن أبي طالب في تاريخ الإسلام ذا الجناحين، أشبه الناس بالنبي ﷺ، السفير الفصيح أمام النجاشي، الشهيد بثلاثة وتسعين جرحًا. اللهم ارضَ عن جعفر، واجمعنا به في جنات النعيم.',
    ]),
    en: P([
      "He is Ja'far ibn Abi Talib ibn Abd al-Muttalib ibn Hashim al-Qurashi al-Hashimi. The cousin of the Prophet ﷺ. He was born in Makkah about 30 years before the mission. He was the brother of Ali ibn Abi Talib, ten years older. His mother was Fatimah bint Asad ibn Hashim — who raised the Prophet ﷺ in his childhood with her husband Abu Talib.",
      "Ja'far was among the most similar of people to the Prophet ﷺ in appearance and character. He was strong of build, generous of face, of beautiful character. The Prophet ﷺ loved him deeply. The Prophet ﷺ would say to him: 'You are the most similar of people to me in appearance and character.' This is a great testimony — that a man should be the most similar of people to the Prophet ﷺ.",
      "Ja'far embraced Islam early in Islam, among the very first. He was among the first to declare his Islam in Makkah. He attended with his wife Asma' bint Umays the prayer in the house of al-Arqam. He witnessed with his own eye the beginnings of the religion that would change the world.",
      "When harm on the Muslims in Makkah intensified, the Prophet ﷺ ordered the Muslims to make the first emigration to Abyssinia. Ja'far emigrated with his wife Asma' and a group of Muslims. Ja'far became in Abyssinia the head of the Muslims there — because he was the best of them and most eloquent.",
      "When Quraysh learned of the Muslims' condition with the Negus, king of Abyssinia, they sent two great ambassadors: Amr ibn al-As and Abdullah ibn Abi Rabi'ah. They carried gifts for the Negus and his bishops. They met the king and said: 'O King, foolish youths among us have taken refuge in your country. They have left the religion of their people and not entered yours, and have come with an invented religion neither we nor you know. The nobles of their people have sent us to you about them to return them.'",
      "The Negus summoned the Muslims to ask about them. Ja'far ibn Abi Talib chose to speak on behalf of the group. He stood before the Negus and his bishops. He spoke his great speech that history has immortalised: 'O King, we were a people of Jahiliyyah; we worshipped idols, ate carrion, committed indecencies, severed kinship, treated neighbours badly, and the strong among us would devour the weak. We were upon that until Allah sent us a messenger from among us, whose lineage, truthfulness, trustworthiness, and chastity we knew.'",
      "Ja'far continued: 'He called us to Allah to declare His oneness and worship Him, and to renounce what we and our fathers had worshipped of stones and idols apart from Him. He commanded us truthful speech, fulfilling the trust, ties of kinship, good treatment of neighbours, and refraining from forbidden things and blood. He forbade us indecencies, false witness, eating the orphan's wealth, and accusing a chaste woman. He commanded us to worship Allah alone and associate nothing with Him, and commanded us prayer, zakat, and fasting. We believed him, accepted him, and followed what he brought from Allah.'",
      "The Negus was deeply moved. He asked Ja'far: 'Do you have anything of what he brought from Allah?' Ja'far said: 'Yes.' He recited to the Negus the beginning of Surah Maryam — the story of Jesus and his mother. When the Negus heard the Qur'an, he wept deeply until his beard was wet. His bishops wept. Then he said: 'This and what Moses brought come from the same lamp. Go, you are safe in my country.'",
      "But Amr ibn al-As did not despair. He returned the next day and said to the Negus: 'They say about Jesus son of Mary a great thing.' The Negus summoned Ja'far a second time and asked. Ja'far stood with faith and steadfastness and said: 'We say of him what Allah and His Messenger said: he is the servant of Allah and His Messenger, son of the virgin Mary, who guarded her chastity; He breathed into her of His spirit.'",
      "The Negus struck the ground with his hand and said: 'Jesus has no more than what you have said by this stick' — meaning that your saying about Jesus has nothing more than the truth. He then returned the gifts to the two ambassadors and said to the Muslims: 'Go, you are safe in my country.' This remarkable word from Ja'far protected the Muslims in Abyssinia all those years.",
      "Ja'far remained in Abyssinia 13 years. He married there Asma' bint Umays, and they bore Abdullah ibn Ja'far, Muhammad, and Awn. Their life in Abyssinia was safe and quiet; they practised their religion freely.",
      "In the seventh year of the Hijrah, the Prophet ﷺ sent to the Negus requesting the return of the Muslims. They returned to Madinah. The return was at the time of the Khaybar campaign. When the Prophet ﷺ saw Ja'far, he rejoiced greatly. He stood him up and kissed his forehead. He said: 'I do not know which makes me happier — the conquest of Khaybar or Ja'far's arrival!' A great word — equating Ja'far's arrival with the conquest of Khaybar.",
      "In the eighth year of the Hijrah, the Prophet ﷺ prepared an army to attack the Romans at Mu'tah. The Prophet ﷺ appointed three commanders in succession: Zayd ibn Harithah; if killed, then Ja'far ibn Abi Talib; if killed, then Abdullah ibn Rawahah. The Muslim army was three thousand, the Roman army 200,000.",
      "The Battle of Mu'tah occurred. Zayd ibn Harithah was killed first. Ja'far took the banner and fought valiantly. He fought while on his horse. When the fighting intensified, he dismounted — because he could not manoeuvre on it — and fought on foot. His right hand was struck and severed. He took the banner with his left hand. His left was struck and severed. He embraced the banner with his forearms. Then he was struck a blow and was martyred.",
      "93 wounds were found in his body — all in his chest and front. They did not find a single wound in his back — proof that he never turned his back. The Prophet ﷺ said when he learned of his martyrdom: 'Allah has replaced Ja'far's two hands with two wings; he flies with them in Paradise wherever he wishes.' He was nicknamed from that day: Dhu al-Janahayn (the Two-Winged).",
      "Ja'far's lessons are great. First: eloquence and beautiful speech are a great blessing. Ja'far with his speech before the Negus protected the Muslims in Abyssinia. Few words containing truth and clarity changed the fate of an entire group. Every believer needs to speak well about his religion.",
      "Second: bravery in war is the highest of ranks. Ja'far fought until his hands were severed and he did not leave the banner. This is remarkable steadfastness. How many a person today surrenders for less than that! True bravery is steadfastness under the harshest circumstances.",
      "Third: Allah rewards the martyr with the greatest reward. Ja'far lost his hands in this world, and Allah gave him two wings in Paradise. Every sacrifice for Allah is compensated with greater. Nothing is lost with Allah.",
      "Ja'far ibn Abi Talib remains in the history of Islam the Two-Winged, the most similar of people to the Prophet ﷺ, the eloquent ambassador before the Negus, the martyr with ninety-three wounds. O Allah, be pleased with Ja'far, and gather us with him in the Gardens of Bliss.",
    ]),
  },

  // ──────────────────────────────────────────────────────────────────────
  // 43. زيد بن حارثة رضي الله عنه — مولى رسول الله
  // ──────────────────────────────────────────────────────────────────────
  'zayd-haritha': {
    ar: P([
      'هو زيد بن حارثة بن شراحيل بن كعب الكلبي. وُلد في الجاهلية بأرض كلب في الشام قبل البعثة بنحو 35 سنة. كان من قبيلة كلب — قبيلة عربية معروفة. أمه سُعدى بنت ثعلبة من بني معن من طيء. كانت أسرته ذات نسب شريف بين العرب.',
      'في طفولته، خرج مع أمه سعدى لزيارة أقاربها من بني معن. وقعت غارة من بني القين على بني معن، فأخذوا زيد سبيًا وهو طفل صغير. باعوه في سوق عُكاظ بمكة. اشتراه حكيم بن حزام لخالته خديجة بنت خويلد. لما تزوجت خديجة بالنبي ﷺ، أهدت زيدًا للنبي ﷺ.',
      'بحث أبوه حارثة عنه سنين. لم يعرف أحد أين هو. حتى وصل إليه خبر أن ابنه عند النبي ﷺ في مكة. خرج حارثة وأخوه كعب إلى مكة، ومعهما فدية كبيرة لشراء زيد. دخلا على النبي ﷺ. قالا: يا محمد، يا ابن عبد المطلب، يا ابن سيد قومه، أنت من أهل حرم الله، وتفك الأسير وتطعم الجائع، جئناك في ابننا عبدك، فامنن علينا وأحسن إلينا في فدائه.',
      'قال النبي ﷺ كلمة عظيمة: ادعوا زيدًا، فخيّروه، فإن اختاركما فهو لكم بغير فداء، وإن اختارني، فوالله ما أنا بالذي أختار على من اختارني أحدًا. قالا: قد زدتنا على النصف وأحسنت. دعا النبي ﷺ زيدًا. قال له: أتعرف هؤلاء؟ قال: نعم، هذا أبي وهذا عمي. قال: فأنا من قد علمت ورأيت صحبتي لك، فاخترني أو اخترهما.',
      'قال زيد كلمته الخالدة: ما أنا بالذي أختار عليك أحدًا، أنت مني مكان الأب والعم. حزن أبوه وقال: ويحك يا زيد، أتختار العبودية على الحرية وعلى أبيك وعمك وأهل بيتك؟ قال زيد: نعم، إنّي قد رأيت من هذا الرجل شيئًا ما أنا بالذي أختار عليه أحدًا أبدًا. هذا قبل البعثة! كان زيد قد عرف من خلق النبي ﷺ ما جعله يفضّله على أهله.',
      'فرح النبي ﷺ بهذا الاختيار. أعتقه فورًا. أخذه إلى الكعبة وقال: يا من حضر، اشهدوا أن زيدًا ابني، يرثني وأرثه. صار من ذلك اليوم زيد بن محمد. نُسب إلى النبي ﷺ بالتبني. كان النبي ﷺ يحبه حبًا شديدًا.',
      'لما بُعث النبي ﷺ، كان زيد من أوائل من آمن به. كان رابع من أسلم — بعد خديجة وعلي وأبي بكر. هاجر إلى المدينة. شارك في كل غزوات النبي ﷺ.',
      'كان النبي ﷺ يأمّره في كل سرية يخرج فيها. أكثر القادة العسكريين الذين عيّنهم النبي ﷺ في الغزوات والسرايا. كان قائدًا ناجحًا. شجاعًا، حازمًا، مطاعًا. لم يُهزم في معركة قادها.',
      'تزوج زيد مرات. أولًا تزوج أم أيمن — مربية النبي ﷺ — وأنجب منها أسامة بن زيد. كان أسامة من أحب الناس إلى النبي ﷺ. ثم تزوج زيد زينب بنت جحش — ابنة عمة النبي ﷺ — بأمر من النبي. لم يدم الزواج، فطلّقها. ثم تزوجها النبي ﷺ بأمر من الله مباشرة من فوق سبع سماوات.',
      'في القرآن، ذُكر زيد باسمه. الصحابي الوحيد الذي ذكره الله في القرآن باسمه الصريح. الآية: فلما قضى زيد منها وطرًا زوّجناكها لكي لا يكون على المؤمنين حرج في أزواج أدعيائهم. هذا شرف فريد — أن يُذكر اسم العبد في كتاب رب العالمين.',
      'في السنة الخامسة من الهجرة، نزل قوله تعالى: ادعوهم لآبائهم هو أقسط عند الله. كانت العادة في الجاهلية تبني الأبناء، وكان زيد يُدعى زيد بن محمد. لما نزلت الآية، رجع إلى اسم أبيه الحقيقي: زيد بن حارثة. كان قبول هذا التغيير من زيد دليلًا على إيمانه — لم يحزن أنه فقد لقب "ابن محمد".',
      'في السنة الثامنة من الهجرة، جهّز النبي ﷺ جيش مؤتة. أمّر عليه زيد بن حارثة. ثلاثة قادة بالتتابع: زيد، فإن قُتل فجعفر بن أبي طالب، فإن قُتل فعبد الله بن رواحة. كان زيد القائد الأول.',
      'في معركة مؤتة، قاتل زيد ببسالة عظيمة. كان حامل راية المسلمين. الجيش الرومي كان 200 ألف، والمسلمون 3 آلاف فقط. ضُرب زيد بطعنات كثيرة. سقط شهيدًا. كان أول قتلى المسلمين في تلك المعركة. أخذ جعفر بن أبي طالب الراية بعده.',
      'لما علم النبي ﷺ باستشهاد زيد، حزن حزنًا شديدًا. بكى. قال: استغفروا لزيد. ثم قال: زيد كان من أحب الناس إليّ. حزن النبي ﷺ على زيد كحزنه على أهله — وكان زيد من أهل بيته بالتبني السابق.',
      'بعد استشهاد زيد، أكرم النبي ﷺ ابنه أسامة بن زيد. عيّنه قائدًا لجيش يخرج لمحاربة الروم في الشام، وهو في الـ 18 من عمره. اعترض بعض الصحابة على صغر سن أسامة. غضب النبي ﷺ غضبًا شديدًا وقال: إن تطعنوا في إمارته فقد طعنتم في إمارة أبيه من قبل. كان دفاعًا عن زيد بعد موته.',
      'دروس زيد عظيمة. الأول: أن الإيمان قد يدخل القلب قبل الإسلام. زيد اختار النبي ﷺ على أبيه قبل البعثة، لأنه عرف من خلق النبي ما يجذب القلوب. كل من حسن خلقه، أحبه الناس قبل أن يعرفوا دينه.',
      'الثاني: أن النسب الحقيقي بالقلب لا بالدم. زيد كان عبدًا، فجعله النبي ﷺ ابنه. ثم لما نزل الأمر بنسبه إلى أبيه الحقيقي، قبل. الأنساب أمر إلهي، لكن المحبة لا تحدّها أنساب.',
      'الثالث: أن الشهادة خاتمة الأبطال. زيد عاش حياة حافلة بالقيادة والجهاد، فاختار الله له خاتمة الشهادة في مؤتة. كل من جاهد في سبيل الله بصدق، يرجى له أن يختم بخاتمة طيبة.',
      'يبقى زيد بن حارثة في تاريخ الإسلام مولى رسول الله ﷺ، الصحابي الوحيد المسمى في القرآن، رابع من أسلم، أمير جيش مؤتة وشهيدها. اللهم ارضَ عن زيد، واجمعنا به في جنات النعيم.',
    ]),
    en: P([
      "He is Zayd ibn Harithah ibn Sharahil ibn Ka'b al-Kalbi. He was born in the Jahiliyyah in the land of Kalb in Sham about 35 years before the mission. He was of the tribe of Kalb — a well-known Arab tribe. His mother was Su'da bint Tha'labah of Banu Ma'n of Tayy. His family had a noble lineage among the Arabs.",
      "In his childhood, he went out with his mother Su'da to visit her relatives of Banu Ma'n. A raid occurred from Banu al-Qayn against Banu Ma'n; they took Zayd captive while he was a small boy. They sold him in the market of Ukaz at Makkah. Hakim ibn Hizam bought him for his aunt Khadijah bint Khuwaylid. When Khadijah married the Prophet ﷺ, she gave Zayd as a gift to the Prophet ﷺ.",
      "His father Harithah searched for him for years. No one knew where he was. Until news reached him that his son was with the Prophet ﷺ in Makkah. Harithah and his brother Ka'b went out to Makkah with a great ransom to buy Zayd. They entered upon the Prophet ﷺ. They said: 'O Muhammad, O son of Abd al-Muttalib, O son of the chief of his people, you are of the people of Allah's sanctuary; you free the captive and feed the hungry. We have come to you about our son, your slave. Be gracious to us and treat us well in his ransom.'",
      "The Prophet ﷺ said a great word: 'Call Zayd; give him the choice. If he chooses you, he is yours without ransom; and if he chooses me, by Allah, I am not one to choose over one who chooses me anyone.' They said: 'You have done more than the half and have done good.' The Prophet ﷺ called Zayd. He said to him: 'Do you know these?' He said: 'Yes, this is my father and this is my uncle.' He said: 'I am as you know and have seen of my companionship to you. Choose me or choose them.'",
      "Zayd said his immortal word: 'I am not one to choose over you anyone; you are to me in the place of father and uncle.' His father grieved and said: 'Woe to you, Zayd! Do you choose slavery over freedom and over your father and uncle and the people of your house?' Zayd said: 'Yes, I have seen from this man something that I am not one to choose over him anyone, ever.' This was before the mission! Zayd had known of the Prophet's ﷺ character what made him prefer him over his family.",
      "The Prophet ﷺ rejoiced at this choice. He freed him at once. He took him to the Ka'bah and said: 'O whoever is present, bear witness that Zayd is my son; he inherits from me and I inherit from him.' From that day he became Zayd ibn Muhammad. He was attributed to the Prophet ﷺ by adoption. The Prophet ﷺ loved him deeply.",
      "When the Prophet ﷺ was sent, Zayd was among the first to believe in him. He was the fourth to embrace Islam — after Khadijah, Ali, and Abu Bakr. He emigrated to Madinah. He participated in every campaign of the Prophet ﷺ.",
      "The Prophet ﷺ would appoint him over every expedition he sent out. He was the most military commander whom the Prophet ﷺ appointed in campaigns and expeditions. He was a successful commander. Brave, firm, obeyed. He was not defeated in a battle he led.",
      "Zayd married several times. He first married Umm Ayman — the Prophet's ﷺ nurse — and bore Usamah ibn Zayd from her. Usamah was among the most beloved of people to the Prophet ﷺ. Zayd then married Zaynab bint Jahsh — the Prophet's ﷺ cousin — by the Prophet's order. The marriage did not last, and he divorced her. The Prophet ﷺ then married her by Allah's command directly from above seven heavens.",
      "In the Qur'an, Zayd was mentioned by name. The only Companion Allah mentioned in the Qur'an by his explicit name. The verse: 'When Zayd had no further need of her, We married her to you, so that there should be no difficulty for the believers concerning the wives of their adopted sons.' This is a unique honour — that a servant's name should be mentioned in the Book of the Lord of the Worlds.",
      "In the fifth year of the Hijrah, the verse was revealed: 'Call them by their fathers; that is more just with Allah.' The custom in the Jahiliyyah was the adoption of sons, and Zayd was called Zayd ibn Muhammad. When the verse was revealed, he returned to his real father's name: Zayd ibn Harithah. Zayd's acceptance of this change was evidence of his faith — he did not grieve at losing the title 'son of Muhammad.'",
      "In the eighth year of the Hijrah, the Prophet ﷺ prepared the Mu'tah army. He appointed Zayd ibn Harithah over it. Three commanders in succession: Zayd; if killed, Ja'far ibn Abi Talib; if killed, Abdullah ibn Rawahah. Zayd was the first commander.",
      "At the Battle of Mu'tah, Zayd fought with great valour. He was the Muslims' standard-bearer. The Roman army was 200,000, the Muslims only 3,000. Zayd was struck with many wounds. He fell a martyr. He was the first of the Muslims killed in that battle. Ja'far ibn Abi Talib took the banner after him.",
      "When the Prophet ﷺ learned of Zayd's martyrdom, he grieved deeply. He wept. He said: 'Seek forgiveness for Zayd.' Then he said: 'Zayd was among the most beloved of people to me.' The Prophet ﷺ grieved for Zayd as he grieved for his family — and Zayd had been of his household by the previous adoption.",
      "After Zayd's martyrdom, the Prophet ﷺ honoured his son Usamah ibn Zayd. He appointed him commander of an army going out to fight the Romans in Sham while he was 18 years old. Some Companions objected to Usamah's young age. The Prophet ﷺ became severely angry and said: 'If you criticise his appointment, you criticised his father's appointment before.' It was a defense of Zayd after his death.",
      "Zayd's lessons are great. First: faith may enter the heart before Islam. Zayd chose the Prophet ﷺ over his father before the mission, because he had known of the Prophet's character what attracts hearts. Whoever's character is beautiful, people love him before they know his religion.",
      "Second: true lineage is by heart, not by blood. Zayd was a slave, and the Prophet ﷺ made him his son. Then when the command came to attribute him to his real father, he accepted. Lineages are a divine matter, but love is not bounded by lineages.",
      "Third: martyrdom is the ending of heroes. Zayd lived a life full of command and jihad; Allah chose for him the ending of martyrdom at Mu'tah. Everyone who fights in Allah's cause sincerely hopes to be sealed with a good ending.",
      "Zayd ibn Harithah remains in the history of Islam the freed slave of the Messenger of Allah ﷺ, the only Companion named in the Qur'an, the fourth to embrace Islam, the commander of the Mu'tah army and its martyr. O Allah, be pleased with Zayd, and gather us with him in the Gardens of Bliss.",
    ]),
  },
};

